const GRAMMAR_VOCAB_ITEMS = [{"id":"gv-kc-01-1","level":"kc","focus":"tense","q":"Look at those dark clouds over the school gate! It ______ very soon.","options":["rains","is going to rain","has rained","rained"],"correct":1,"answer":"is going to rain","vi":"Nhìn mấy đám mây đen trên cổng trường kìa! Trời sắp mưa rồi.","explanation":"A prediction from present evidence (<b>Look at those dark clouds</b>) takes <b>be going to</b>: is going to rain. ✗ <b>rains</b> — present simple is for habits or timetables, not a prediction; ✗ <b>has rained</b> — present perfect is a past action with a present result, but <b>very soon</b> points to the future; ✗ <b>rained</b> — past simple, but the rain has not happened yet."},{"id":"gv-kc-01-2","level":"kc","focus":"word-choice","q":"Nam paid the taxi ______ with the coins he had left in his pocket.","options":["fare","fee","fine","tip"],"correct":0,"answer":"fare","vi":"Nam trả tiền taxi bằng mấy đồng xu còn lại trong túi.","explanation":"Money paid for a journey by taxi, bus or train is a <b>fare</b> (clue: <b>paid the taxi</b>). ✗ <b>fee</b> — money for a professional service or a course, not for a ride; ✗ <b>fine</b> — money paid as a punishment for breaking a rule; ✗ <b>tip</b> — extra money given as thanks, not the price of the trip itself."},{"id":"gv-kc-01-3","level":"kc","focus":"collocation","q":"There was ______ rain all afternoon, so the football match was cancelled.","options":["strong","hard","heavy","big"],"correct":2,"answer":"heavy","vi":"Mưa to suốt cả buổi chiều nên trận bóng đá đã bị hủy.","explanation":"Rain in large amounts is <b>heavy rain</b> — the adjective that collocates with <b>rain</b> to mean 'a lot' (clue: the match was cancelled). ✗ <b>strong</b> — goes with wind or current, not rain; ✗ <b>hard</b> — works as an adverb (it rained hard) but 'hard rain' is not the standard noun phrase; ✗ <b>big</b> — describes the size of objects, never rain."},{"id":"gv-kc-01-4","level":"kc","focus":"idiom","q":"Lan: Did you buy the new maths workbook? / Nam: Yes, but I had to ______ for it at the shop near school.","options":["pay lip service","pay my way","pay my respects","pay through the nose"],"correct":3,"answer":"pay through the nose","vi":"Lan: Cậu mua cuốn bài tập toán mới chưa? / Nam: Rồi, nhưng tớ phải trả giá cắt cổ ở tiệm gần trường.","explanation":"<b>Pay through the nose</b> = pay far too much (<b>but I had to</b> signals a complaint about the price). ✗ <b>pay lip service</b> — support something only in words, and it takes 'to', not 'for'; ✗ <b>pay my way</b> — pay my own costs, nothing about an overpriced item; ✗ <b>pay my respects</b> — greet or honour someone politely, not buy a book."},{"id":"gv-kc-01-5","level":"kc","focus":"phrasal-verb","q":"Lan: Who ______ your little brother when your parents are at work? / Nam: My grandmother does.","options":["looks after","looks up","looks into","looks for"],"correct":0,"answer":"looks after","vi":"Lan: Ai trông em trai cậu khi bố mẹ cậu đi làm? / Nam: Bà tớ.","explanation":"<b>Look after</b> = take care of someone; the reply <b>My grandmother does</b> (while the parents are at work) shows childcare. ✗ <b>looks up</b> — find information in a book or online; ✗ <b>looks into</b> — investigate a problem; ✗ <b>looks for</b> — search for something or someone lost."},{"id":"gv-kc-01-6","level":"kc","focus":"modal","q":"Nam ______ have taken my umbrella — he wasn't even at school today.","options":["must","can't","should","needn't"],"correct":1,"answer":"can't","vi":"Nam không thể nào lấy ô của tớ được — hôm nay cậu ấy thậm chí còn không đi học.","explanation":"<b>Can't have + past participle</b> = it was impossible in the past; the clue <b>he wasn't even at school today</b> proves it. ✗ <b>must</b> — must have means 'I am sure he did it', the opposite of the evidence; ✗ <b>should</b> — should have means he was expected to do it but didn't (advice or regret), not impossibility; ✗ <b>needn't</b> — needn't have means he did it but it was unnecessary."},{"id":"gv-kc-01-7","level":"kc","focus":"relative","q":"The teacher ______ class we have on Monday mornings is going to retire next year.","options":["who","which","whose","whom"],"correct":2,"answer":"whose","vi":"Cô giáo mà chúng tôi có tiết học vào các sáng thứ Hai sẽ nghỉ hưu vào năm sau.","explanation":"A noun (<b>class</b>) follows the blank, so the relative pronoun must show possession: <b>whose</b> (= the teacher's class). ✗ <b>who</b> — a subject pronoun, must be followed by a verb, not a noun; ✗ <b>which</b> — used for things, and it cannot show possession; ✗ <b>whom</b> — an object pronoun for people, cannot show possession either."},{"id":"gv-kc-01-8","level":"kc","focus":"article-quantifier","q":"Lan: Do you want to play badminton? / Nam: Sorry, I have too ______ homework to finish before nine.","options":["many","few","a lot","much"],"correct":3,"answer":"much","vi":"Lan: Cậu có muốn chơi cầu lông không? / Nam: Xin lỗi, tớ có quá nhiều bài tập về nhà phải làm xong trước chín giờ.","explanation":"<b>Homework</b> is uncountable, so 'too + quantity' is <b>too much</b>. ✗ <b>many</b> — only with plural countable nouns (too many books); ✗ <b>few</b> — countable, and it means 'not enough', the wrong meaning; ✗ <b>a lot</b> — cannot follow <b>too</b> (you say 'a lot of homework' but never 'too a lot')."},{"id":"gv-kc-01-9","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your project to school tomorrow — the teacher is going to collect it.","options":["bringing","to bring","bring","brought"],"correct":1,"answer":"to bring","vi":"Nhớ mang dự án đến trường ngày mai nhé — cô giáo sẽ thu đấy.","explanation":"<b>Remember + to-infinitive</b> = don't forget a task still to do; the clue is <b>tomorrow</b> (future). ✗ <b>bringing</b> — remember + -ing means having a memory of something already done; ✗ <b>bring</b> — a bare infinitive cannot follow remember; ✗ <b>brought</b> — a past form has no auxiliary here and the action is in the future."},{"id":"gv-kc-01-10","level":"kc","focus":"linking","q":"It rained all day on Saturday; ______, the school picnic was put off until next week.","options":["however","whereas","consequently","otherwise"],"correct":2,"answer":"consequently","vi":"Thứ Bảy trời mưa cả ngày; do đó, buổi dã ngoại của trường bị hoãn sang tuần sau.","explanation":"The second clause is the <b>result</b> of the first (rain → picnic put off), so the linker is <b>consequently</b>. ✗ <b>however</b> — shows contrast, but there is none; ✗ <b>whereas</b> — a conjunction joining two contrasting facts, not a sentence adverb after a semicolon; ✗ <b>otherwise</b> — means 'if not', which would say the picnic was put off because it did NOT rain."},{"id":"gv-kc-01-11","level":"kc","focus":"conditional","q":"If it ______ tomorrow, we will have PE in the gym instead of on the field.","options":["rains","will rain","rained","would rain"],"correct":0,"answer":"rains","vi":"Nếu ngày mai trời mưa, chúng tôi sẽ học thể dục trong nhà thi đấu thay vì ngoài sân.","explanation":"A real future possibility is the <b>first conditional</b>: if + present simple, <b>will</b> in the main clause (<b>we will have PE</b>). ✗ <b>will rain</b> — will never goes in the if-clause; ✗ <b>rained</b> — past simple makes a second (unreal) conditional, which needs 'would', not 'will', in the main clause; ✗ <b>would rain</b> — would does not go in an if-clause."},{"id":"gv-kc-01-12","level":"kc","focus":"passive","q":"The final exam results ______ on the school website next Friday.","options":["will announce","are announcing","have announced","will be announced"],"correct":3,"answer":"will be announced","vi":"Kết quả kỳ thi cuối kỳ sẽ được công bố trên trang web của trường vào thứ Sáu tới.","explanation":"The subject <b>results</b> cannot announce anything — they are announced by the school — so the verb is passive, and <b>next Friday</b> makes it future: <b>will be announced</b>. ✗ <b>will announce</b> — active, so the results would be doing the announcing; ✗ <b>are announcing</b> — active, and present continuous for a fixed future date is odd; ✗ <b>have announced</b> — active and present perfect, but the announcement is still to come."},{"id":"gv-kc-01-13","level":"kc","focus":"reported","q":"Lan said that she ______ a doctor when she grew up.","options":["will be","would be","is","has been"],"correct":1,"answer":"would be","vi":"Lan nói rằng khi lớn lên cô ấy sẽ trở thành bác sĩ.","explanation":"After a past reporting verb (<b>said</b>) tenses shift back: will → <b>would</b>; the clause <b>when she grew up</b> is already in the shifted past form. ✗ <b>will be</b> — no backshift after said; ✗ <b>is</b> — present tense clashes with said and with 'when she grew up'; ✗ <b>has been</b> — present perfect says she has already been a doctor, which contradicts a childhood ambition."},{"id":"gv-kc-01-14","level":"kc","focus":"preposition","q":"Our maths teacher is strict, but she is always patient ______ slow learners.","options":["to","for","with","at"],"correct":2,"answer":"with","vi":"Cô giáo toán của chúng tôi nghiêm khắc, nhưng cô luôn kiên nhẫn với những học sinh tiếp thu chậm.","explanation":"The adjective <b>patient</b> takes <b>with</b> before the person you are patient towards: patient with slow learners. ✗ <b>to</b> — follows kind/rude/polite (kind to), not patient; ✗ <b>for</b> — 'patient for' is not a phrase (you wait patiently for something); ✗ <b>at</b> — follows good/bad/clever (good at maths), not patient."},{"id":"gv-kc-01-15","level":"kc","focus":"comparison","q":"This winter is much ______ than last winter — I have to wear two jumpers to school.","options":["colder","cold","coldest","the coldest"],"correct":0,"answer":"colder","vi":"Mùa đông năm nay lạnh hơn nhiều so với mùa đông năm ngoái — tôi phải mặc hai cái áo len đi học.","explanation":"<b>Than</b> signals a comparison of two winters, so a comparative is needed: much <b>colder</b>. ✗ <b>cold</b> — the base form cannot be followed by than; ✗ <b>coldest</b> — a superlative compares three or more and needs 'the'; ✗ <b>the coldest</b> — a superlative, and superlatives never take than."},{"id":"gv-kc-01-16","level":"kc","focus":"idiom","q":"Whenever I show my brother an essay, he ______ it and tells me everything that is wrong.","options":["turns a blind eye to","picks holes in","makes light of","pulls strings for"],"correct":1,"answer":"picks holes in","vi":"Mỗi lần tôi đưa anh trai xem bài luận, anh ấy lại bới lông tìm vết và chỉ ra mọi lỗi sai.","explanation":"<b>Pick holes in</b> = find faults in; the clue is <b>tells me everything that is wrong</b>. ✗ <b>turns a blind eye to</b> — deliberately ignores, the opposite of criticising; ✗ <b>makes light of</b> — treats as unimportant; ✗ <b>pulls strings for</b> — uses influence to help someone get something."},{"id":"gv-kc-01-17","level":"kc","focus":"phrasal-verb","q":"Lan: Do you ______ your new classmates? / Nam: Yes, they are really friendly.","options":["get over","get away with","get through","get on with"],"correct":3,"answer":"get on with","vi":"Lan: Cậu có hòa hợp với các bạn cùng lớp mới không? / Nam: Có, các bạn ấy rất thân thiện.","explanation":"<b>Get on with</b> someone = have a friendly relationship; the reply <b>they are really friendly</b> confirms it. ✗ <b>get over</b> — recover from an illness or a shock; ✗ <b>get away with</b> — escape punishment for something; ✗ <b>get through</b> — finish or survive something difficult (an exam, a hard week)."},{"id":"gv-kc-01-18","level":"kc","focus":"tense","q":"I ______ my old primary school report while I was tidying my desk last night.","options":["came across","was coming across","have come across","had come across"],"correct":0,"answer":"came across","vi":"Tối qua tôi tình cờ thấy học bạ tiểu học cũ của mình khi đang dọn bàn học.","explanation":"A short action inside a longer one (<b>while I was tidying</b>) takes the past simple: <b>came across</b>. ✗ <b>was coming across</b> — the continuous is for the background action, and finding by chance is a sudden event, not a process; ✗ <b>have come across</b> — present perfect cannot go with the finished time <b>last night</b>; ✗ <b>had come across</b> — past perfect would put the finding BEFORE the tidying, but it happened during it."},{"id":"gv-kc-01-19","level":"kc","focus":"word-choice","q":"Please check the new class ______ — chemistry has moved to Thursday afternoon.","options":["calendar","diary","timetable","menu"],"correct":2,"answer":"timetable","vi":"Hãy kiểm tra thời khóa biểu mới của lớp — môn hóa đã chuyển sang chiều thứ Năm.","explanation":"A list of the times of school lessons is a <b>timetable</b>; the clue is <b>chemistry has moved to Thursday afternoon</b>. ✗ <b>calendar</b> — shows the days and months of the year, not lesson times; ✗ <b>diary</b> — a personal book of daily events or plans; ✗ <b>menu</b> — a list of dishes in a restaurant."},{"id":"gv-kc-01-20","level":"kc","focus":"word-choice","q":"Keep the ______ in case the calculator stops working and you need to take it back to the shop.","options":["recipe","receipt","bill","ticket"],"correct":1,"answer":"receipt","vi":"Hãy giữ hóa đơn phòng khi máy tính bỏ túi bị hỏng và bạn cần mang ra trả lại cửa hàng.","explanation":"A <b>receipt</b> is the paper proving you paid — what a shop asks for when you <b>take it back</b>. ✗ <b>recipe</b> — instructions for cooking a dish (a common spelling mix-up); ✗ <b>bill</b> — a paper asking you to pay, given before payment; ✗ <b>ticket</b> — lets you travel or enter an event."},{"id":"gv-kc-01-21","level":"kc","focus":"word-choice","q":"The weather ______ says it will be sunny and 32 degrees in Ho Chi Minh City tomorrow.","options":["prediction","estimate","guess","forecast"],"correct":3,"answer":"forecast","vi":"Dự báo thời tiết nói ngày mai ở Thành phố Hồ Chí Minh trời nắng và 32 độ.","explanation":"The fixed compound is <b>weather forecast</b> — a report of what the weather will probably be (<b>says it will be sunny ... tomorrow</b>). ✗ <b>prediction</b> — similar meaning, but not the noun that collocates with weather; ✗ <b>estimate</b> — a rough calculation of a number or cost; ✗ <b>guess</b> — an answer without evidence, not an official report."},{"id":"gv-kc-01-22","level":"kc","focus":"word-choice","q":"To get a part-time job at the café, you have to fill in an ______ form first.","options":["application","appointment","advertisement","interview"],"correct":0,"answer":"application","vi":"Để xin làm thêm ở quán cà phê, trước tiên bạn phải điền vào đơn xin việc.","explanation":"The form you fill in to ask for a job is an <b>application form</b> (clue: <b>to get a part-time job</b>). ✗ <b>appointment</b> — a fixed time for a meeting; ✗ <b>advertisement</b> — the notice announcing that a job is available; ✗ <b>interview</b> — the meeting that comes after you apply, not a form."},{"id":"gv-kc-01-23","level":"kc","focus":"collocation","q":"Nam wants to be a pilot, so he is ______ a lot of effort into his English lessons.","options":["making","taking","putting","giving"],"correct":2,"answer":"putting","vi":"Nam muốn trở thành phi công nên cậu ấy đang dồn rất nhiều công sức vào các tiết tiếng Anh.","explanation":"The collocation is <b>put effort into</b> something (clue: <b>into his English lessons</b>). ✗ <b>making</b> — 'make an effort' exists, but it is followed by a to-infinitive, not into; ✗ <b>taking</b> — only a task 'takes effort' (it takes effort to ...); a person does not take effort into something; ✗ <b>giving</b> — 'give effort' is not an English collocation."},{"id":"gv-kc-01-24","level":"kc","focus":"collocation","q":"Lan: Can you come out and play? / Nam: Sorry, I haven't ______ my homework yet.","options":["made","taken","given","done"],"correct":3,"answer":"done","vi":"Lan: Cậu ra ngoài chơi được không? / Nam: Xin lỗi, tớ chưa làm xong bài tập về nhà.","explanation":"The verb that collocates with <b>homework</b> is <b>do</b>; with <b>haven't ... yet</b> (present perfect) it is <b>done</b>. ✗ <b>made</b> — make is for creating something new (make a cake, make a decision), never homework; ✗ <b>taken</b> — you take an exam or a test, not homework; ✗ <b>given</b> — a teacher gives homework; the student does it."},{"id":"gv-kc-01-25","level":"kc","focus":"tense","q":"My uncle ______ as a chef in a hotel in Da Nang since 2019.","options":["works","has worked","is working","worked"],"correct":1,"answer":"has worked","vi":"Chú tôi đã làm đầu bếp ở một khách sạn tại Đà Nẵng từ năm 2019.","explanation":"<b>Since + starting point</b> (since 2019) marks an action that began in the past and continues now: present perfect <b>has worked</b>. ✗ <b>works</b> — present simple describes a habit but cannot go with since + a date; ✗ <b>is working</b> — present continuous is a temporary action now, with no link back to 2019; ✗ <b>worked</b> — past simple means the job has finished, but since shows it still continues."},{"id":"gv-kc-02-1","level":"kc","focus":"tense","q":"I ______ this novel since Monday, and I still haven't reached the last chapter.","options":["am reading","have been reading","read","was reading"],"correct":1,"answer":"have been reading","vi":"Tôi đọc cuốn tiểu thuyết này từ thứ Hai mà vẫn chưa tới chương cuối.","explanation":"An action that began in the past and is still going on (<b>since Monday</b> + <b>still haven't reached</b>) takes the present perfect continuous: <b>have been reading</b>. ✗ <b>am reading</b> — present continuous is only for now, it cannot take <b>since</b> + a starting point; ✗ <b>read</b> — past simple means the reading is finished, but it is still going on; ✗ <b>was reading</b> — past continuous puts the action in the past, not reaching up to now."},{"id":"gv-kc-02-2","level":"kc","focus":"word-choice","q":"Lan: How much is the bus ______ to the cinema? / Nam: Only seven thousand dong each way.","options":["fare","fee","price","charge"],"correct":0,"answer":"fare","vi":"Lan: Vé xe buýt tới rạp chiếu phim bao nhiêu tiền? / Nam: Chỉ bảy nghìn đồng một chiều thôi.","explanation":"The money for a <b>bus</b>, taxi or train ride is a <b>fare</b> — the clue is <b>bus</b> + <b>each way</b>. ✗ <b>fee</b> — money for a professional service (doctor, school, lawyer); ✗ <b>price</b> — the cost of goods in a shop, not of a journey; ✗ <b>charge</b> — a general amount a company asks for a service, not the fixed word for transport."},{"id":"gv-kc-02-3","level":"kc","focus":"idiom","q":"My parents ______ for my sister's wedding party: a live band, fireworks and a five-tier cake.","options":["pulled some strings","pulled their socks up","pulled out all the stops","pulled our legs"],"correct":2,"answer":"pulled out all the stops","vi":"Bố mẹ tôi đã dốc toàn lực cho tiệc cưới của chị tôi: ban nhạc sống, pháo hoa và chiếc bánh cưới năm tầng.","explanation":"The list <b>a live band, fireworks and a five-tier cake</b> shows every possible effort, which is <b>pull out all the stops</b> = do everything possible to make something a success. ✗ <b>pulled some strings</b> — used secret influence to get a favour; ✗ <b>pulled their socks up</b> — started to work harder; ✗ <b>pulled our legs</b> — joked with us, made us believe something untrue."},{"id":"gv-kc-02-4","level":"kc","focus":"collocation","q":"My brother ______ the housework on Saturdays while I cook lunch.","options":["makes","does","takes","gives"],"correct":1,"answer":"does","vi":"Anh tôi làm việc nhà vào thứ Bảy còn tôi nấu bữa trưa.","explanation":"<b>Housework</b> collocates with <b>do</b>: we do the housework, the shopping, the washing-up (routine tasks). ✗ <b>makes</b> — <b>make</b> goes with things you create (a cake, a decision, a mess), not routine chores; ✗ <b>takes</b> — <b>take</b> pairs with a photo, a break, a bus, never housework; ✗ <b>gives</b> — <b>give</b> pairs with a hand, a speech, a present, never housework."},{"id":"gv-kc-02-5","level":"kc","focus":"relative","q":"That's the singer ______ concert we went to last month.","options":["whose","who","whom","which"],"correct":0,"answer":"whose","vi":"Đó là ca sĩ mà tháng trước chúng tôi đã đi xem buổi hòa nhạc của cô ấy.","explanation":"The <b>concert</b> belongs to the <b>singer</b>, so the blank needs the possessive relative <b>whose</b> + noun (<b>whose concert</b>). ✗ <b>who</b> — a subject pronoun for a person, but the clause already has its subject <b>we</b>; ✗ <b>whom</b> — an object pronoun for a person, and it cannot stand before the noun <b>concert</b>; ✗ <b>which</b> — refers to a thing, but here the antecedent is the person <b>singer</b>."},{"id":"gv-kc-02-6","level":"kc","focus":"phrasal-verb","q":"Minh's birthday party has been ______ until next Saturday because his mother is ill.","options":["put out","put off","put up","set off"],"correct":1,"answer":"put off","vi":"Tiệc sinh nhật của Minh đã bị hoãn đến thứ Bảy tuần sau vì mẹ cậu ấy bị ốm.","explanation":"<b>Put off</b> = postpone, which is what <b>until next Saturday</b> + <b>his mother is ill</b> describe. ✗ <b>put out</b> — extinguish a fire or a light; ✗ <b>put up</b> — build (a tent), raise (prices) or give someone a bed for the night; ✗ <b>set off</b> — start a journey, and a party cannot set off."},{"id":"gv-kc-02-7","level":"kc","focus":"word-choice","q":"To save money, my friends and I stayed at a cheap ______ where we shared a room with six other travellers.","options":["hostel","hotel","resort","campsite"],"correct":0,"answer":"hostel","vi":"Để tiết kiệm tiền, tôi và bạn bè ở một nhà nghỉ tập thể giá rẻ, chung phòng với sáu du khách khác.","explanation":"A <b>hostel</b> is cheap accommodation where travellers share big rooms — the clues are <b>cheap</b> and <b>shared a room with six other travellers</b>. ✗ <b>hotel</b> — you get your own room, and it is not typically cheap; ✗ <b>resort</b> — an expensive holiday complex with private rooms; ✗ <b>campsite</b> — you sleep in a tent, not in a room."},{"id":"gv-kc-02-8","level":"kc","focus":"modal","q":"Nam ______ the film last night — he was at my house until midnight.","options":["must have seen","might have seen","should have seen","can't have seen"],"correct":3,"answer":"can't have seen","vi":"Nam không thể nào đã xem bộ phim tối qua được — cậu ấy ở nhà tôi đến tận nửa đêm.","explanation":"<b>Can't have</b> + past participle = it was impossible in the past; the clue <b>he was at my house until midnight</b> makes seeing the film impossible. ✗ <b>must have seen</b> — near certainty that it DID happen, the opposite of the evidence; ✗ <b>might have seen</b> — a possibility, but the evidence rules it out; ✗ <b>should have seen</b> — an action that was expected but not done, a regret, not a deduction."},{"id":"gv-kc-02-9","level":"kc","focus":"article-quantifier","q":"There were only ______ guests at the party, so we all sat around one table.","options":["few","a few","little","a little"],"correct":1,"answer":"a few","vi":"Bữa tiệc chỉ có vài vị khách, nên tất cả chúng tôi ngồi quanh một bàn.","explanation":"<b>Guests</b> is a countable plural and <b>only</b> + <b>a few</b> = a small number, which explains <b>one table</b>. ✗ <b>few</b> — already means \"almost none\" (negative), so it is not used after <b>only</b>; ✗ <b>little</b> — goes with uncountable nouns (little time), not with <b>guests</b>; ✗ <b>a little</b> — also uncountable only (a little sugar), not for people you can count."},{"id":"gv-kc-02-10","level":"kc","focus":"tense","q":"By the time we found our seats, the film ______.","options":["has already started","already starts","is already starting","had already started"],"correct":3,"answer":"had already started","vi":"Lúc chúng tôi tìm được chỗ ngồi thì bộ phim đã bắt đầu rồi.","explanation":"<b>By the time</b> + past simple (<b>found</b>) needs the past perfect for the action that happened first: <b>had already started</b>. ✗ <b>has already started</b> — present perfect links to now, but the story is in the past; ✗ <b>already starts</b> — present simple cannot follow a past-time clause; ✗ <b>is already starting</b> — present continuous describes now, not an earlier past moment."},{"id":"gv-kc-02-11","level":"kc","focus":"gerund-infinitive","q":"After the doctor's visit, my father decided ______ smoking for good.","options":["giving up","give up","to give up","to giving up"],"correct":2,"answer":"to give up","vi":"Sau khi đi khám bác sĩ, bố tôi quyết định bỏ hẳn thuốc lá.","explanation":"<b>Decide</b> is followed by a to-infinitive: <b>decided to give up</b>. ✗ <b>giving up</b> — a gerund, but <b>decide</b> is not a gerund verb (unlike <b>stop / enjoy</b>); ✗ <b>give up</b> — a bare infinitive only follows modals or <b>make / let</b>, not <b>decide</b>; ✗ <b>to giving up</b> — <b>to</b> + -ing exists only after set phrases like <b>look forward to</b>, never after <b>decide</b>."},{"id":"gv-kc-02-12","level":"kc","focus":"word-choice","q":"From our hotel balcony we had a wonderful ______ of the harbour.","options":["sight","view","scene","scenery"],"correct":1,"answer":"view","vi":"Từ ban công khách sạn, chúng tôi ngắm được toàn cảnh bến cảng thật tuyệt.","explanation":"<b>Have a view of</b> is the pattern for what you can see from a place, and <b>from our hotel balcony</b> gives the viewpoint. ✗ <b>sight</b> — the ability to see, or a place tourists visit (the sights), not what a balcony offers; ✗ <b>scene</b> — a part of a film or play, or the place where something happens; ✗ <b>scenery</b> — uncountable, so it can never take <b>a</b>."},{"id":"gv-kc-02-13","level":"kc","focus":"linking","q":"______ the film was three hours long, nobody left the cinema early.","options":["Although","Despite","However","Because"],"correct":0,"answer":"Although","vi":"Mặc dù bộ phim dài ba tiếng, không ai rời rạp sớm cả.","explanation":"The blank introduces a full clause (<b>the film was three hours long</b>) that contrasts with <b>nobody left early</b>, so the conjunction is <b>although</b>. ✗ <b>Despite</b> — a preposition, it needs a noun or -ing (<b>despite the film being long</b>), not subject + verb; ✗ <b>However</b> — an adverb that starts a new sentence, it cannot join two clauses with a comma; ✗ <b>Because</b> — gives a reason, but a long film is not a reason for staying."},{"id":"gv-kc-02-14","level":"kc","focus":"collocation","q":"The picnic was cancelled because of the ______ rain on Sunday morning.","options":["strong","hard","big","heavy"],"correct":3,"answer":"heavy","vi":"Buổi dã ngoại bị hủy vì trận mưa lớn sáng Chủ nhật.","explanation":"<b>Rain</b>, traffic and snow are described as <b>heavy</b> = falling in large amounts. ✗ <b>strong</b> — collocates with wind, coffee or a smell, not rain; ✗ <b>hard</b> — \"it rained hard\" is an adverb, but <b>hard rain</b> before the noun is not the standard collocation; ✗ <b>big</b> — used for size (a big storm), never for rain."},{"id":"gv-kc-02-15","level":"kc","focus":"idiom","q":"Dad finally ______ and said that nobody could use a phone at the dinner table.","options":["put his feet up","put his foot down","put his back into it","put his cards on the table"],"correct":1,"answer":"put his foot down","vi":"Cuối cùng bố cũng cương quyết ra lệnh rằng không ai được dùng điện thoại trong bữa tối.","explanation":"<b>Put your foot down</b> = be firm and refuse to allow something, which matches the strict rule <b>nobody could use a phone</b>. ✗ <b>put his feet up</b> — relax, rest; ✗ <b>put his back into it</b> — work very hard at a task; ✗ <b>put his cards on the table</b> — be honest and open about your plans."},{"id":"gv-kc-02-16","level":"kc","focus":"conditional","q":"If my brother ______ so much noise every evening, I could finish my book in a week.","options":["doesn't make","hadn't made","didn't make","won't make"],"correct":2,"answer":"didn't make","vi":"Nếu em trai tôi không làm ồn như vậy mỗi tối thì tôi có thể đọc xong cuốn sách trong một tuần.","explanation":"A second conditional describes a present situation that is not true — <b>every evening</b> + <b>could finish</b> — so the if-clause takes the past simple: <b>didn't make</b>. ✗ <b>doesn't make</b> — present simple belongs to the first conditional with <b>will / can</b>, not <b>could</b>; ✗ <b>hadn't made</b> — past perfect is the third conditional about a finished past event, which clashes with <b>every evening</b>; ✗ <b>won't make</b> — <b>will</b> is not used in an if-clause."},{"id":"gv-kc-02-17","level":"kc","focus":"word-choice","q":"Our ______ was a quiet village by the sea, but the bus dropped us in the wrong town.","options":["direction","distance","arrival","destination"],"correct":3,"answer":"destination","vi":"Điểm đến của chúng tôi là một ngôi làng yên tĩnh ven biển, nhưng xe buýt lại thả chúng tôi ở nhầm thị trấn.","explanation":"The place you are travelling to is your <b>destination</b>; the clue is the contrast with <b>the wrong town</b>. ✗ <b>direction</b> — the way you go (north, left), not a place; ✗ <b>distance</b> — how far it is, a length, not a village; ✗ <b>arrival</b> — the act of getting somewhere, not the place itself."},{"id":"gv-kc-02-18","level":"kc","focus":"agreement","q":"Neither my parents nor my little sister ______ horror films.","options":["like","likes","are liking","have liked"],"correct":1,"answer":"likes","vi":"Cả bố mẹ tôi lẫn em gái tôi đều không thích phim kinh dị.","explanation":"With <b>neither … nor</b>, the verb agrees with the subject nearest to it: singular <b>my little sister</b> → <b>likes</b>. ✗ <b>like</b> — plural, it would agree with <b>parents</b>, which is further from the verb; ✗ <b>are liking</b> — plural AND a continuous form, but <b>like</b> is a state verb not used in the continuous; ✗ <b>have liked</b> — plural, and the present perfect makes no sense for a general preference."},{"id":"gv-kc-02-19","level":"kc","focus":"phrasal-verb","q":"My cousin has ______ the piano and practises every evening after dinner.","options":["taken over","taken in","taken off","taken up"],"correct":3,"answer":"taken up","vi":"Em họ tôi mới bắt đầu học đàn piano và luyện tập mỗi tối sau bữa ăn.","explanation":"<b>Take up</b> = start a new hobby or activity, which fits <b>practises every evening</b>. ✗ <b>taken over</b> — take control of a company or a job; ✗ <b>taken in</b> — understand something, or give someone a home; ✗ <b>taken off</b> — remove clothes, or leave the ground (a plane)."},{"id":"gv-kc-02-20","level":"kc","focus":"participle","q":"The chocolate cake ______ by my grandmother was the best thing at the party.","options":["making","was made","made","had made"],"correct":2,"answer":"made","vi":"Chiếc bánh sô-cô-la do bà tôi làm là món ngon nhất trong bữa tiệc.","explanation":"A past participle shortens the passive relative clause <b>which was made by my grandmother</b> to <b>the cake made by</b>; the clue is the passive agent <b>by my grandmother</b>. ✗ <b>making</b> — a present participle would mean the cake did the making, which is impossible; ✗ <b>was made</b> — a full verb here would give the sentence two main verbs (<b>was made … was</b>); ✗ <b>had made</b> — active past perfect, it also makes a second main verb and says the cake made something."},{"id":"gv-kc-02-21","level":"kc","focus":"tense","q":"This time next week we ______ on the beach in Nha Trang with all our cousins.","options":["will be lying","lie","have lain","were lying"],"correct":0,"answer":"will be lying","vi":"Giờ này tuần sau chúng tôi sẽ đang nằm trên bãi biển Nha Trang cùng tất cả anh chị em họ.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, which takes the future continuous: <b>will be lying</b>. ✗ <b>lie</b> — present simple is for habits or timetables, not a picture of one future moment; ✗ <b>have lain</b> — present perfect links the past to now, not to next week; ✗ <b>were lying</b> — past continuous describes a past moment, but the time marker is future."},{"id":"gv-kc-02-22","level":"kc","focus":"word-choice","q":"On the first day in Hue, my family went ______ and took photos of every old palace.","options":["watching","viewing","sightseeing","looking"],"correct":2,"answer":"sightseeing","vi":"Ngày đầu tiên ở Huế, gia đình tôi đi tham quan và chụp ảnh mọi cung điện cổ.","explanation":"<b>Go sightseeing</b> is the set expression for visiting the famous places of a town, and <b>took photos of every old palace</b> confirms it. ✗ <b>watching</b> — needs an object (watching a film), and <b>go watching</b> is not a set phrase; ✗ <b>viewing</b> — also needs an object, and it is used for houses or exhibitions, not tours; ✗ <b>looking</b> — <b>go looking</b> must be followed by <b>for</b> something."},{"id":"gv-kc-02-23","level":"kc","focus":"pronoun","q":"My brother and I often cook dinner ______ when our parents work late.","options":["ourself","themselves","each other","ourselves"],"correct":3,"answer":"ourselves","vi":"Anh em tôi thường tự nấu bữa tối khi bố mẹ đi làm về muộn.","explanation":"<b>My brother and I</b> = <b>we</b>, so the reflexive is <b>ourselves</b>, here meaning \"without our parents' help\". ✗ <b>ourself</b> — not a standard English form; the plural is always <b>ourselves</b>; ✗ <b>themselves</b> — refers to <b>they</b>, not to <b>we</b>; ✗ <b>each other</b> — a reciprocal pronoun, it would mean we cook one another, which makes no sense."},{"id":"gv-kc-02-24","level":"kc","focus":"collocation","q":"Could you ______ a photo of us in front of the cinema, please?","options":["make","do","take","catch"],"correct":2,"answer":"take","vi":"Bạn chụp giúp bọn mình một tấm ảnh trước rạp chiếu phim được không?","explanation":"<b>Photo</b> collocates with <b>take</b>: you take a photo / a picture. ✗ <b>make</b> — a direct translation from many languages, but English uses <b>make</b> for creating things (a cake, a film), not photos; ✗ <b>do</b> — pairs with tasks (homework, housework), never with a photo; ✗ <b>catch</b> — goes with a bus, a ball or a cold, not a photo."},{"id":"gv-kc-02-25","level":"kc","focus":"question-tag","q":"Let's watch a comedy tonight, ______?","options":["shall we","will we","do we","don't we"],"correct":0,"answer":"shall we","vi":"Tối nay chúng ta xem phim hài nhé?","explanation":"A suggestion with <b>Let's</b> always takes the tag <b>shall we?</b>. ✗ <b>will we</b> — <b>will you?</b> is the tag after an imperative (Open the door, will you?), not after <b>Let's</b>; ✗ <b>do we</b> — follows a negative present simple statement (We don't …, do we?); ✗ <b>don't we</b> — follows a positive present simple statement (We watch …, don't we?), but <b>Let's</b> is not a statement."},{"id":"gv-kc-03-1","level":"kc","focus":"word-choice","q":"At the checkout, the ______ scanned my items and asked if I wanted a bag.","options":["cashier","customer","accountant","banker"],"correct":0,"answer":"cashier","vi":"Ở quầy tính tiền, nhân viên thu ngân quét các món hàng của tôi và hỏi tôi có cần túi không.","explanation":"The clue is <b>at the checkout ... scanned my items</b> — the job of taking payment in a shop, so <b>cashier</b>. ✗ <b>customer</b> — the person buying, not scanning; ✗ <b>accountant</b> — keeps a company's financial records; ✗ <b>banker</b> — works in a bank, not at a shop till."},{"id":"gv-kc-03-2","level":"kc","focus":"word-choice","q":"Thousands of ______ cheered when the striker scored in the last minute.","options":["witnesses","spectators","observers","audiences"],"correct":1,"answer":"spectators","vi":"Hàng nghìn khán giả reo hò khi tiền đạo ghi bàn ở phút cuối.","explanation":"People watching a sports event are <b>spectators</b>; the clue is <b>cheered when the striker scored</b>. ✗ <b>witnesses</b> — people who see a crime or accident; ✗ <b>observers</b> — people who watch officially to check or report; ✗ <b>audiences</b> — 'audience' is a group noun for one crowd at a show, so 'thousands of audiences' would mean thousands of separate crowds."},{"id":"gv-kc-03-3","level":"kc","focus":"word-choice","q":"My sister's ______ in the chess final was a boy who had never lost a game.","options":["partner","colleague","opponent","teammate"],"correct":2,"answer":"opponent","vi":"Đối thủ của chị tôi trong trận chung kết cờ vua là một cậu bé chưa từng thua ván nào.","explanation":"The person you play <b>against</b> is your <b>opponent</b>; the clue is <b>in the chess final ... a boy who had never lost</b>. ✗ <b>partner</b> — someone on your side in a pair; ✗ <b>colleague</b> — someone you work with; ✗ <b>teammate</b> — a member of your own team, not the person you face."},{"id":"gv-kc-03-4","level":"kc","focus":"word-choice","q":"The ______ blew her whistle and told the children to get out of the pool.","options":["bodyguard","doorman","guardian","lifeguard"],"correct":3,"answer":"lifeguard","vi":"Nhân viên cứu hộ thổi còi và bảo bọn trẻ ra khỏi hồ bơi.","explanation":"The clue is <b>blew her whistle ... out of the pool</b>: a <b>lifeguard</b> watches swimmers and keeps them safe. ✗ <b>bodyguard</b> — protects one person from attack; ✗ <b>doorman</b> — stands at a building's entrance; ✗ <b>guardian</b> — the adult legally responsible for a child."},{"id":"gv-kc-03-5","level":"kc","focus":"word-choice","q":"A famous ______ with two million subscribers reviews new phones on her video channel every week.","options":["vlogger","blogger","editor","reporter"],"correct":0,"answer":"vlogger","vi":"Một vlogger nổi tiếng với hai triệu người đăng ký đánh giá điện thoại mới trên kênh video của cô ấy mỗi tuần.","explanation":"The clues are <b>video channel</b> and <b>subscribers</b>: a <b>vlogger</b> (video + blogger) makes videos. ✗ <b>blogger</b> — writes text posts on a website; ✗ <b>editor</b> — checks and corrects other people's writing; ✗ <b>reporter</b> — collects and writes news for a newspaper or TV."},{"id":"gv-kc-03-6","level":"kc","focus":"collocation","q":"Before buying the phone, Nam ______ a lot of research online.","options":["made","did","took","gave"],"correct":1,"answer":"did","vi":"Trước khi mua điện thoại, Nam đã tìm hiểu rất nhiều trên mạng.","explanation":"<b>Research</b> collocates with <b>do</b>: <b>do research</b> (like do homework, do an experiment). ✗ <b>made</b> — 'make' goes with creating something (make a decision, make a mistake), never research; ✗ <b>took</b> — 'take' goes with time, a test or a photo, not research; ✗ <b>gave</b> — 'give' goes with a talk or a presentation, not research."},{"id":"gv-kc-03-7","level":"kc","focus":"collocation","q":"Choose a ______ password so that nobody can get into your account.","options":["heavy","hard","strong","powerful"],"correct":2,"answer":"strong","vi":"Hãy chọn một mật khẩu mạnh để không ai vào được tài khoản của bạn.","explanation":"A password that is hard to guess is a <b>strong password</b>; the clue is <b>so that nobody can get into your account</b>. ✗ <b>heavy</b> — describes weight, rain or traffic, not passwords; ✗ <b>hard</b> — means difficult, but 'hard password' is not the collocation; ✗ <b>powerful</b> — describes engines, leaders or arguments, not passwords."},{"id":"gv-kc-03-8","level":"kc","focus":"collocation","q":"Please ______ attention when the referee explains the rules of the game.","options":["give","take","make","pay"],"correct":3,"answer":"pay","vi":"Hãy chú ý khi trọng tài giải thích luật của trận đấu.","explanation":"The fixed collocation is <b>pay attention</b> = listen or watch carefully; the clue is <b>when the referee explains the rules</b>. ✗ <b>give</b> — you give someone a present or a hand; 'give attention' is not the idiom for listening carefully; ✗ <b>take</b> — 'take' does not pair with 'attention' at all; ✗ <b>make</b> — 'make' goes with an effort or a decision, not attention."},{"id":"gv-kc-03-9","level":"kc","focus":"tense","q":"Even though it started to rain, the players ______ with the match until the referee stopped it.","options":["carried on","have carried on","carry on","had carried on"],"correct":0,"answer":"carried on","vi":"Dù trời bắt đầu mưa, các cầu thủ vẫn tiếp tục trận đấu cho đến khi trọng tài dừng lại.","explanation":"A finished past story told in order — <b>it started to rain</b>, they carried on, <b>the referee stopped it</b> — uses the past simple: <b>carried on</b>. ✗ <b>have carried on</b> — present perfect cannot sit in a story told with past-simple 'started' and 'stopped'; ✗ <b>carry on</b> — present simple for a past event; ✗ <b>had carried on</b> — past perfect is for an action BEFORE another past action, but carrying on came after the rain started."},{"id":"gv-kc-03-10","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Nam's mum: He ______ football in the park at the moment.","options":["plays","is playing","has played","played"],"correct":1,"answer":"is playing","vi":"Lan: Nam đâu ạ? / Mẹ Nam: Nó đang đá bóng trong công viên.","explanation":"<b>At the moment</b> means right now, so the present continuous <b>is playing</b> is needed. ✗ <b>plays</b> — present simple is for habits and facts, not an action in progress; ✗ <b>has played</b> — present perfect links past to present but does not describe what is happening now; ✗ <b>played</b> — past simple is for a finished action, but the game is still going on."},{"id":"gv-kc-03-11","level":"kc","focus":"tense","q":"I ______ this phone for three years, so it's time to buy a new one.","options":["had","am having","have had","have"],"correct":2,"answer":"have had","vi":"Tôi đã dùng chiếc điện thoại này ba năm rồi, nên đã đến lúc mua cái mới.","explanation":"A situation that began in the past and continues to now, with <b>for three years</b>, takes the present perfect: <b>have had</b>. ✗ <b>had</b> — past simple would mean I no longer have it, but I still do (<b>it's time to buy a new one</b>); ✗ <b>am having</b> — 'have' meaning own is a state verb, not used in the continuous; ✗ <b>have</b> — present simple cannot carry 'for three years' back into the past."},{"id":"gv-kc-03-12","level":"kc","focus":"tense","q":"By the time the shop opened, dozens of people ______ outside for hours.","options":["waited","have waited","were waiting","had been waiting"],"correct":3,"answer":"had been waiting","vi":"Đến lúc cửa hàng mở cửa, hàng chục người đã đứng chờ bên ngoài suốt mấy tiếng.","explanation":"An activity that continued up to a past moment (<b>by the time the shop opened</b>) with a duration (<b>for hours</b>) takes the past perfect continuous: <b>had been waiting</b>. ✗ <b>waited</b> — past simple does not show the waiting happened before the opening; ✗ <b>have waited</b> — present perfect cannot combine with the past event 'opened'; ✗ <b>were waiting</b> — past continuous shows an action at that moment but does not carry 'for hours' up to it."},{"id":"gv-kc-03-13","level":"kc","focus":"idiom","q":"Lan: Do you know a shop called Phone World? / Nam: The name ______, but I can't remember where it is.","options":["breaks the ice","rings a bell","hits the nail on the head","gets on my nerves"],"correct":1,"answer":"rings a bell","vi":"Lan: Cậu biết cửa hàng tên Phone World không? / Nam: Cái tên nghe quen quen, nhưng tớ không nhớ nó ở đâu.","explanation":"<b>Ring a bell</b> = sound familiar; the clue is <b>but I can't remember where it is</b>. ✗ <b>breaks the ice</b> — makes people relax when they first meet; ✗ <b>hits the nail on the head</b> — says exactly the right thing; ✗ <b>gets on my nerves</b> — annoys me."},{"id":"gv-kc-03-14","level":"kc","focus":"idiom","q":"Our team played well in the first half but ______ after the break and lost 3-1.","options":["ran out of steam","hit the roof","missed the boat","made ends meet"],"correct":0,"answer":"ran out of steam","vi":"Đội chúng tôi chơi tốt ở hiệp một nhưng đuối sức sau giờ nghỉ và thua 3-1.","explanation":"<b>Run out of steam</b> = lose energy and stop trying hard; the clue is <b>played well in the first half but ... lost</b>. ✗ <b>hit the roof</b> — got very angry; ✗ <b>missed the boat</b> — lost a chance by being too late; ✗ <b>made ends meet</b> — had just enough money to live on."},{"id":"gv-kc-03-15","level":"kc","focus":"phrasal-verb","q":"The shop ______ my request for a refund because I had lost the receipt.","options":["turned up","turned over","turned off","turned down"],"correct":3,"answer":"turned down","vi":"Cửa hàng đã từ chối yêu cầu hoàn tiền của tôi vì tôi làm mất hóa đơn.","explanation":"<b>Turn down</b> = refuse a request or offer; the clue is <b>because I had lost the receipt</b>, a reason for refusing. ✗ <b>turned up</b> — arrived, or increased the volume; ✗ <b>turned over</b> — flipped something to the other side; ✗ <b>turned off</b> — switched off a machine or light."},{"id":"gv-kc-03-16","level":"kc","focus":"phrasal-verb","q":"Please don't ______ the money I owe you in front of my parents.","options":["bring back","bring about","bring up","bring in"],"correct":2,"answer":"bring up","vi":"Làm ơn đừng nhắc đến số tiền tớ nợ cậu trước mặt bố mẹ tớ.","explanation":"<b>Bring up</b> = mention a subject; the clue is <b>in front of my parents</b> — the speaker doesn't want the debt mentioned. ✗ <b>bring back</b> — return something, or make you remember; ✗ <b>bring about</b> — cause a change to happen; ✗ <b>bring in</b> — introduce a rule, or earn money."},{"id":"gv-kc-03-17","level":"kc","focus":"modal","q":"Nam paid full price in the shop. He ______ have bought the phone online, where the same model is much cheaper.","options":["must","should","can't","needn't"],"correct":1,"answer":"should","vi":"Nam đã trả nguyên giá ở cửa hàng. Lẽ ra cậu ấy nên mua điện thoại trên mạng, nơi cùng mẫu đó rẻ hơn nhiều.","explanation":"<b>Should have + past participle</b> criticises a past choice: it was a good idea but he didn't do it. The clue is <b>paid full price</b> although online is <b>much cheaper</b>. ✗ <b>must have</b> — a confident guess that something DID happen, but he did not buy online; ✗ <b>can't have</b> — a confident guess that something did NOT happen, not advice; ✗ <b>needn't have</b> — he did it but it wasn't necessary, yet he never bought online at all."},{"id":"gv-kc-03-18","level":"kc","focus":"modal","q":"Lan ______ have spent much money at the market - she only bought a keyring.","options":["can't","must","should","needn't"],"correct":0,"answer":"can't","vi":"Lan không thể nào tiêu nhiều tiền ở chợ được - cô ấy chỉ mua một cái móc khóa.","explanation":"<b>Can't have + past participle</b> = the speaker is sure something did NOT happen; the clue is <b>she only bought a keyring</b>. ✗ <b>must have</b> — sure it DID happen, the opposite of the evidence; ✗ <b>should have</b> — criticism that she ought to have spent much money, which makes no sense; ✗ <b>needn't have</b> — she spent a lot but didn't need to, yet she spent almost nothing."},{"id":"gv-kc-03-19","level":"kc","focus":"relative","q":"The girl ______ phone was stolen on the bus reported it to the police.","options":["who","which","whom","whose"],"correct":3,"answer":"whose","vi":"Cô gái có điện thoại bị lấy cắp trên xe buýt đã báo cảnh sát.","explanation":"<b>Whose</b> shows possession — the girl's phone — and is followed directly by the noun <b>phone</b>. ✗ <b>who</b> — a subject pronoun for a person; it cannot stand before a noun ('who phone'); ✗ <b>which</b> — refers to a thing and also cannot stand before a noun here; ✗ <b>whom</b> — an object pronoun (the girl whom I saw), not a possessive."},{"id":"gv-kc-03-20","level":"kc","focus":"relative","q":"The shop ______ I bought my headphones has closed down.","options":["which","that","where","whose"],"correct":2,"answer":"where","vi":"Cửa hàng nơi tôi mua tai nghe đã đóng cửa rồi.","explanation":"<b>Where</b> replaces 'in the shop' — a place — and is followed by a complete clause, <b>I bought my headphones</b>. ✗ <b>which</b> — needs a preposition for a place ('the shop from which I bought them'); ✗ <b>that</b> — also needs a preposition ('the shop that I bought them from'); ✗ <b>whose</b> — shows possession, but the shop owns nothing here."},{"id":"gv-kc-03-21","level":"kc","focus":"article-quantifier","q":"There isn't ______ time left before the sale ends, so hurry up.","options":["many","much","a few","few"],"correct":1,"answer":"much","vi":"Không còn nhiều thời gian trước khi đợt giảm giá kết thúc, nên nhanh lên.","explanation":"<b>Time</b> (hours and minutes) is uncountable, and the sentence is negative (<b>isn't</b>), so it takes <b>much</b>. ✗ <b>many</b> — only with plural countable nouns (many days); ✗ <b>a few</b> — plural countable only, and 'a few' is not used after 'isn't'; ✗ <b>few</b> — plural countable only (few days)."},{"id":"gv-kc-03-22","level":"kc","focus":"gerund-infinitive","q":"Don't forget ______ your phone before the match; you'll want to take photos.","options":["to charge","charging","charge","to charging"],"correct":0,"answer":"to charge","vi":"Đừng quên sạc điện thoại trước trận đấu; cậu sẽ muốn chụp ảnh đấy.","explanation":"<b>Forget + to-infinitive</b> = forget to do a task that is still to be done; the clue is <b>before the match</b>, a future job. ✗ <b>charging</b> — 'forget doing' means having no memory of something already done; ✗ <b>charge</b> — 'forget' is never followed by a bare infinitive; ✗ <b>to charging</b> — 'to' + -ing does not follow 'forget'."},{"id":"gv-kc-03-23","level":"kc","focus":"linking","q":"The tickets were quite expensive; ______, the stadium was completely full.","options":["therefore","because","although","however"],"correct":3,"answer":"however","vi":"Vé khá đắt; tuy nhiên, sân vận động vẫn chật kín.","explanation":"Two contrasting ideas (<b>expensive</b> but <b>completely full</b>) joined by <b>a semicolon and a comma</b> need the linking adverb <b>however</b>. ✗ <b>therefore</b> — an adverb, but it shows a result, and a full stadium is not the result of expensive tickets; ✗ <b>because</b> — a conjunction giving a reason; it cannot sit between ';' and ','; ✗ <b>although</b> — shows contrast but is a conjunction that must start a clause ('although the tickets were expensive'), not stand alone between ';' and ','."},{"id":"gv-kc-03-24","level":"kc","focus":"conditional","q":"If I ______ so much on clothes last month, I could buy those trainers now.","options":["didn't spend","haven't spent","hadn't spent","wouldn't spend"],"correct":2,"answer":"hadn't spent","vi":"Nếu tháng trước tôi không tiêu quá nhiều vào quần áo thì bây giờ tôi đã có thể mua đôi giày thể thao đó.","explanation":"A mixed conditional: an unreal past condition (<b>last month</b>) takes the past perfect <b>hadn't spent</b>, and its present result uses could + verb (<b>could buy ... now</b>). ✗ <b>didn't spend</b> — past simple after 'if' makes a second conditional about the present, but 'last month' is finished; ✗ <b>haven't spent</b> — present perfect cannot be used with 'last month' and does not form an unreal condition; ✗ <b>wouldn't spend</b> — 'would' belongs in the result clause, not after 'if'."},{"id":"gv-kc-03-25","level":"kc","focus":"inversion","q":"Only after the final whistle ______ how tired he was.","options":["Nam realised","did Nam realise","Nam did realise","realised Nam"],"correct":1,"answer":"did Nam realise","vi":"Chỉ sau tiếng còi kết thúc Nam mới nhận ra mình mệt đến thế nào.","explanation":"When a sentence starts with the limiting phrase <b>Only after ...</b>, the auxiliary and subject are inverted like a question: <b>did Nam realise</b>. ✗ <b>Nam realised</b> — normal word order, but 'Only after' at the front forces inversion; ✗ <b>Nam did realise</b> — 'did' after the subject is emphasis, not inversion; ✗ <b>realised Nam</b> — inverts the main verb instead of the auxiliary 'did'."},{"id":"gv-kc-04-1","level":"kc","focus":"tense","q":"Grandma ______ in this village since she was a little girl.","options":["lives","has lived","lived","is living"],"correct":1,"answer":"has lived","vi":"Bà nội đã sống ở ngôi làng này từ khi còn là một cô bé.","explanation":"<b>Since she was a little girl</b> gives the starting point of an action that continues to now, so the present perfect <b>has lived</b> is needed.<br>✗ <b>lives</b> — present simple cannot combine with 'since' + a past point; ✗ <b>lived</b> — past simple would mean the living is finished, but she still lives there; ✗ <b>is living</b> — present continuous describes a temporary action now, not one lasting since childhood."},{"id":"gv-kc-04-2","level":"kc","focus":"word-choice","q":"Although she had made lots of new friends at the summer camp, Lan still felt ______ and kept talking about her mum’s cooking and her own little bedroom.","options":["homesick","lonely","nostalgic","bored"],"correct":0,"answer":"homesick","vi":"Dù đã có nhiều bạn mới ở trại hè, Lan vẫn thấy nhớ nhà và cứ nhắc mãi về món mẹ nấu và căn phòng nhỏ của mình.","explanation":"<b>Homesick</b> = sad because you are away from home and miss it; the clue is that she <b>kept talking about her mum's cooking and her own little bedroom</b>.<br>✗ <b>lonely</b> — sad because you have no company, but she had made lots of new friends; ✗ <b>nostalgic</b> — missing a time in the past, not a place; ✗ <b>bored</b> — having nothing interesting to do, which does not explain missing home."},{"id":"gv-kc-04-3","level":"kc","focus":"collocation","q":"The forecast says there will be ______ rain all weekend, so the picnic in the forest is cancelled.","options":["strong","hard","heavy","big"],"correct":2,"answer":"heavy","vi":"Dự báo nói cuối tuần sẽ mưa to suốt, nên buổi dã ngoại trong rừng bị hủy.","explanation":"Rain is described by amount, and the fixed collocation is <b>heavy rain</b> (also heavy snow, heavy traffic); <b>all weekend</b> and the cancelled picnic show it is a lot of rain.<br>✗ <b>strong</b> — collocates with wind or currents, not rain; ✗ <b>hard</b> — used as an adverb ('it rained hard'), not before the noun 'rain'; ✗ <b>big</b> — describes the size of objects, never rain."},{"id":"gv-kc-04-4","level":"kc","focus":"phrasal-verb","q":"We ______ for the mountains at five in the morning to avoid the traffic.","options":["set up","set about","set down","set off"],"correct":3,"answer":"set off","vi":"Chúng tôi lên đường đi lên núi lúc năm giờ sáng để tránh kẹt xe.","explanation":"<b>Set off</b> = start a journey; the clue is <b>for the mountains at five in the morning</b>, a departure towards a destination.<br>✗ <b>set up</b> — establish or arrange (a company, a tent); ✗ <b>set about</b> — begin doing a task (set about cleaning); ✗ <b>set down</b> — put something down or write it down. None of these can take 'for' + a place."},{"id":"gv-kc-04-5","level":"kc","focus":"modal","q":"Nam: I saw Lan at the hospital yesterday. / Hoa: You ______ her — she has been in Hà Nội all week.","options":["can't have seen","mustn't have seen","shouldn't have seen","needn't have seen"],"correct":0,"answer":"can't have seen","vi":"Nam: Hôm qua tớ thấy Lan ở bệnh viện. / Hoa: Cậu không thể nào thấy cô ấy được — cả tuần nay cô ấy ở Hà Nội mà.","explanation":"<b>Can't have + past participle</b> = a confident deduction that something in the past was impossible; the clue is <b>she has been in Hà Nội all week</b>.<br>✗ <b>mustn't have seen</b> — 'must' makes positive deductions only ('must have seen'); its negative for deduction is 'can't have'; ✗ <b>shouldn't have seen</b> — criticism: it was wrong to see her; ✗ <b>needn't have seen</b> — it was unnecessary to see her."},{"id":"gv-kc-04-6","level":"kc","focus":"idiom","q":"Tickets for the island boat tour are ______ — book now or you will miss out.","options":["burning the midnight oil","selling like hot cakes","raining cats and dogs","going the extra mile"],"correct":1,"answer":"selling like hot cakes","vi":"Vé tour thuyền ra đảo đang bán đắt như tôm tươi — đặt ngay kẻo hết.","explanation":"<b>Sell like hot cakes</b> = sell very quickly in large numbers; the clue is <b>book now or you will miss out</b>.<br>✗ <b>burning the midnight oil</b> — working or studying late into the night; ✗ <b>raining cats and dogs</b> — raining very heavily; ✗ <b>going the extra mile</b> — making more effort than is expected. Only 'selling like hot cakes' can describe tickets."},{"id":"gv-kc-04-7","level":"kc","focus":"relative","q":"The dentist to ______ my mother goes has moved her clinic to District 3.","options":["who","whose","whom","which"],"correct":2,"answer":"whom","vi":"Nha sĩ mà mẹ tôi hay đến khám đã chuyển phòng khám sang Quận 3.","explanation":"After a preposition (<b>to</b>) the relative pronoun must be the object form <b>whom</b>: 'the dentist to whom my mother goes'.<br>✗ <b>who</b> — subject form, not used directly after a preposition; ✗ <b>whose</b> — possessive, must be followed by a noun ('whose clinic'); ✗ <b>which</b> — refers to things, but the dentist is a person."},{"id":"gv-kc-04-8","level":"kc","focus":"word-choice","q":"Mum was ______ to hear that it was only a cold and not the flu.","options":["relaxed","comfortable","peaceful","relieved"],"correct":3,"answer":"relieved","vi":"Mẹ nhẹ cả người khi nghe đó chỉ là cảm lạnh chứ không phải cúm.","explanation":"<b>Relieved</b> = glad because a worry has gone; the clue is the good news <b>only a cold and not the flu</b>.<br>✗ <b>relaxed</b> — calm and not stressed, a general state rather than a reaction to news; ✗ <b>comfortable</b> — physically at ease or not worried, not used with 'to hear that'; ✗ <b>peaceful</b> — quiet and calm, describes places or moods, not a sudden feeling about news."},{"id":"gv-kc-04-9","level":"kc","focus":"preposition","q":"My uncle has suffered ______ back pain for years, so he sees a doctor every month.","options":["from","of","with","by"],"correct":0,"answer":"from","vi":"Chú tôi bị đau lưng nhiều năm nay nên tháng nào cũng đi khám bác sĩ.","explanation":"The verb <b>suffer</b> takes <b>from</b> when it means to have an illness or pain: <b>suffer from back pain</b>.<br>✗ <b>of</b> — 'suffer of' is not English (compare 'die of'); ✗ <b>with</b> — heard informally, but the standard pattern for an illness is 'suffer from'; ✗ <b>by</b> — 'by' introduces the agent of a passive verb, and 'has suffered' is active."},{"id":"gv-kc-04-10","level":"kc","focus":"tense","q":"This time next week we ______ on a beach in Phú Quốc.","options":["lie","are lying","will be lying","have been lying"],"correct":2,"answer":"will be lying","vi":"Giờ này tuần sau chúng tôi sẽ đang nằm dài trên bãi biển ở Phú Quốc.","explanation":"<b>This time next week</b> marks an action in progress at a moment in the future, so the future continuous <b>will be lying</b> is needed.<br>✗ <b>lie</b> — present simple states facts or habits, not a future moment; ✗ <b>are lying</b> — present continuous means now or a fixed arrangement, not an action pictured in progress then; ✗ <b>have been lying</b> — present perfect continuous runs from the past up to now."},{"id":"gv-kc-04-11","level":"kc","focus":"article-quantifier","q":"There's ______ time before the flight, so let's have a coffee.","options":["a few","a little","few","many"],"correct":1,"answer":"a little","vi":"Còn một chút thời gian trước chuyến bay, nên mình đi uống cà phê đi.","explanation":"<b>Time</b> here is an uncountable noun, and the tone is positive (enough for a coffee), so <b>a little</b> = some.<br>✗ <b>a few</b> — only with plural countable nouns (a few minutes); ✗ <b>many</b> — only with plural countable nouns, so 'many time' is impossible; ✗ <b>few</b> — countable and negative ('almost none'), which would clash with 'let's have a coffee'."},{"id":"gv-kc-04-12","level":"kc","focus":"collocation","q":"I would like to ______ an appointment with Dr Hùng for tomorrow morning, please.","options":["do","take","put","make"],"correct":3,"answer":"make","vi":"Tôi muốn đặt lịch hẹn với bác sĩ Hùng vào sáng mai ạ.","explanation":"The fixed collocation is <b>make an appointment</b> (also make a booking, make a reservation); the clue is <b>with Dr Hùng for tomorrow morning</b>, i.e. arranging a time.<br>✗ <b>do</b> — used for tasks and activities (do homework), not for arranging; ✗ <b>take</b> — 'take an appointment' is not English (you can keep or miss one); ✗ <b>put</b> — needs a place ('put it in the diary') and has no collocation with 'appointment'."},{"id":"gv-kc-04-13","level":"kc","focus":"word-choice","q":"Minh was ______ when the doctor told him he could not play football for a month.","options":["disappointed","ashamed","amused","grateful"],"correct":0,"answer":"disappointed","vi":"Minh thất vọng khi bác sĩ bảo cậu không được đá bóng trong một tháng.","explanation":"<b>Disappointed</b> = sad because something you hoped for will not happen; the clue is that he <b>could not play football for a month</b>.<br>✗ <b>ashamed</b> — feeling guilty about something bad you did, but Minh did nothing wrong; ✗ <b>amused</b> — finding something funny, the opposite of a reaction to bad news; ✗ <b>grateful</b> — thankful for help, which nobody gave here."},{"id":"gv-kc-04-14","level":"kc","focus":"conditional","q":"If I ______ you, I would see a doctor about that cough.","options":["am","were","had been","would be"],"correct":1,"answer":"were","vi":"Nếu tớ là cậu, tớ sẽ đi khám bác sĩ về cơn ho đó.","explanation":"Second conditional (imaginary present, used for advice): <b>if + past simple, would + verb</b>; the clue is <b>would see</b> in the main clause, and 'If I <b>were</b> you' is the fixed form.<br>✗ <b>am</b> — present simple makes a first conditional, which needs 'will', not 'would'; ✗ <b>had been</b> — past perfect makes a third conditional about the past (would have + p.p.); ✗ <b>would be</b> — 'would' belongs in the main clause, not the if-clause."},{"id":"gv-kc-04-15","level":"kc","focus":"phrasal-verb","q":"We ______ petrol halfway to the beach and had to push the car to a garage.","options":["ran into","ran after","ran out of","ran over"],"correct":2,"answer":"ran out of","vi":"Chúng tôi hết xăng giữa đường ra biển và phải đẩy xe đến tiệm sửa.","explanation":"<b>Run out of</b> = use all of something so none is left; the clue is that they <b>had to push the car</b>, so there was no petrol.<br>✗ <b>ran into</b> — met by chance, or crashed into; ✗ <b>ran after</b> — chased; ✗ <b>ran over</b> — hit and drove over with a vehicle. None of these can be done to petrol."},{"id":"gv-kc-04-16","level":"kc","focus":"linking","q":"The weather in Sa Pa was terrible all week; ______, we still had a wonderful holiday.","options":["therefore","moreover","otherwise","however"],"correct":3,"answer":"however","vi":"Thời tiết ở Sa Pa tệ suốt cả tuần; tuy nhiên, chúng tôi vẫn có một kỳ nghỉ tuyệt vời.","explanation":"The two halves contrast (<b>terrible weather</b> / <b>still a wonderful holiday</b>), so the linker of contrast <b>however</b> is needed; the word <b>still</b> confirms it.<br>✗ <b>therefore</b> — introduces a result, but a great holiday is not the result of bad weather; ✗ <b>moreover</b> — adds a point of the same kind, not an opposite one; ✗ <b>otherwise</b> — means 'if not', which makes no sense here."},{"id":"gv-kc-04-17","level":"kc","focus":"word-choice","q":"Hoa felt ______ when she realised she had been following the wrong tour group for ten minutes.","options":["frightened","embarrassed","delighted","proud"],"correct":1,"answer":"embarrassed","vi":"Hoa thấy xấu hổ khi nhận ra mình đã đi theo nhầm đoàn du lịch suốt mười phút.","explanation":"<b>Embarrassed</b> = feeling silly and uncomfortable because of a mistake others may have noticed; the clue is <b>following the wrong tour group for ten minutes</b>.<br>✗ <b>frightened</b> — scared of danger, but nothing dangerous happened; ✗ <b>delighted</b> — very pleased, the wrong reaction to a mistake; ✗ <b>proud</b> — pleased with an achievement, not with a silly error."},{"id":"gv-kc-04-18","level":"kc","focus":"passive","q":"Thousands of young trees ______ in the national park every year by student volunteers.","options":["are planted","are planting","plant","have planted"],"correct":0,"answer":"are planted","vi":"Hàng nghìn cây non được trồng trong vườn quốc gia mỗi năm bởi các tình nguyện viên học sinh.","explanation":"The trees do not plant; they <b>are planted</b>, and the agent follows <b>by student volunteers</b>, so the sentence is passive — present simple passive because <b>every year</b> describes a repeated fact.<br>✗ <b>are planting</b> — active continuous: the trees would be doing the planting; ✗ <b>plant</b> — active present simple, same problem, and 'by' would have no role; ✗ <b>have planted</b> — active present perfect, again making the trees the planters."},{"id":"gv-kc-04-19","level":"kc","focus":"idiom","q":"The doctor went on television to ______ about the rumours that the new vaccine was dangerous.","options":["hit the nail on the head","turn over a new leaf","break the ice","set the record straight"],"correct":3,"answer":"set the record straight","vi":"Bác sĩ lên truyền hình để làm rõ sự thật về những tin đồn rằng vắc-xin mới nguy hiểm.","explanation":"<b>Set the record straight</b> = give the true facts after false ones have spread; the clue is <b>the rumours that the new vaccine was dangerous</b>.<br>✗ <b>hit the nail on the head</b> — say exactly the right thing about a problem; ✗ <b>turn over a new leaf</b> — start behaving better; ✗ <b>break the ice</b> — say something to make strangers feel relaxed. None of these means correcting false information."},{"id":"gv-kc-04-20","level":"kc","focus":"gerund-infinitive","q":"I am really looking forward to ______ my cousins in Huế this summer.","options":["see","to see","seeing","to seeing"],"correct":2,"answer":"seeing","vi":"Tớ rất mong được gặp các anh chị em họ ở Huế hè này.","explanation":"In <b>look forward to</b>, 'to' is a preposition, not an infinitive marker, so the verb after it must be a gerund: <b>seeing</b>.<br>✗ <b>see</b> — a bare infinitive cannot follow a preposition; ✗ <b>to see</b> — repeats 'to' and wrongly treats it as an infinitive marker; ✗ <b>to seeing</b> — doubles the preposition ('forward to to seeing')."},{"id":"gv-kc-04-21","level":"kc","focus":"reported","q":"Lan asked me ______ on holiday that summer.","options":["where I was going","where was I going","where am I going","where I am going"],"correct":0,"answer":"where I was going","vi":"Lan hỏi tôi sẽ đi nghỉ ở đâu vào mùa hè năm đó.","explanation":"A reported question keeps statement word order (<b>subject before verb</b>) and, after the past reporting verb <b>asked</b>, shifts the tense back: <b>where I was going</b>.<br>✗ <b>where was I going</b> — question word order (verb before subject) belongs only in direct questions; ✗ <b>where am I going</b> — question order and no backshift; ✗ <b>where I am going</b> — right order, but present tense does not match 'asked' and 'that summer'."},{"id":"gv-kc-04-22","level":"kc","focus":"collocation","q":"The doctor asked me to ______ a deep breath and hold it for five seconds.","options":["make","take","do","give"],"correct":1,"answer":"take","vi":"Bác sĩ bảo tôi hít một hơi thật sâu và giữ trong năm giây.","explanation":"The fixed collocation is <b>take a (deep) breath</b>; the clue is <b>hold it for five seconds</b>, a single act of breathing in.<br>✗ <b>make</b> — not used with 'breath' (you make a noise or a decision); ✗ <b>do</b> — used for activities and tasks, not for breathing; ✗ <b>give</b> — you give a sigh or a shout, but not a breath."},{"id":"gv-kc-04-23","level":"kc","focus":"word-choice","q":"Our tour guide stayed ______ even when the bus broke down in the rain, joking with everyone until help came.","options":["anxious","jealous","cheerful","hopeless"],"correct":2,"answer":"cheerful","vi":"Hướng dẫn viên của chúng tôi vẫn vui vẻ ngay cả khi xe buýt hỏng giữa trời mưa, đùa với mọi người cho tới khi có người tới giúp.","explanation":"<b>Cheerful</b> = happy and in a good mood; the clue is <b>joking with everyone</b> even when the bus broke down.<br>✗ <b>anxious</b> — worried and nervous, the opposite of joking; ✗ <b>jealous</b> — wanting what someone else has, and there is nothing here to envy; ✗ <b>hopeless</b> — feeling that nothing will get better, which does not match keeping people laughing 'until help came'."},{"id":"gv-kc-04-24","level":"kc","focus":"comparison","q":"The mountains were ______ than we expected, so we bought warm jackets at the market.","options":["as cold","far coldest","more cold","far colder"],"correct":3,"answer":"far colder","vi":"Trên núi lạnh hơn nhiều so với chúng tôi tưởng, nên chúng tôi mua áo khoác ấm ở chợ.","explanation":"<b>Than</b> after the blank needs a comparative, and <b>far</b> (= much) strengthens it: <b>far colder</b>.<br>✗ <b>as cold</b> — the equal comparison needs 'as cold as', not 'than'; ✗ <b>far coldest</b> — a superlative compares three or more and never goes with 'than'; ✗ <b>more cold</b> — 'cold' is one syllable, so it takes '-er', not 'more'."},{"id":"gv-kc-04-25","level":"kc","focus":"tense","q":"Lan: You look exhausted! / Nam: Yes, I ______ back from Đà Lạt — the bus took eight hours.","options":["have just come","had just come","just come","am just coming"],"correct":0,"answer":"have just come","vi":"Lan: Trông cậu mệt quá! / Nam: Ừ, tớ vừa mới về từ Đà Lạt — xe buýt đi mất tám tiếng.","explanation":"<b>Just</b> + a recent action whose result is visible now (<b>you look exhausted</b>) takes the present perfect: <b>have just come</b>.<br>✗ <b>had just come</b> — past perfect needs an earlier past event to be 'before', but the conversation is now; ✗ <b>just come</b> — no auxiliary, so it is not a correct tense (the informal past would be 'just came'); ✗ <b>am just coming</b> — present continuous means he is still on the way, but he is already here."},{"id":"gv-kc-05-1","level":"kc","focus":"tense","q":"Grandma ______ the sticky rice for Tết right now, so the kitchen is full of steam.","options":["steams","is steaming","has steamed","steamed"],"correct":1,"answer":"is steaming","vi":"Bà đang đồ xôi cho Tết ngay lúc này nên bếp đầy hơi nước.","explanation":"<b>Right now</b> marks an action in progress at the moment of speaking, so the present continuous <b>is steaming</b> is needed.<br>✗ <b>steams</b> — present simple is for habits and routines, not what is happening now; ✗ <b>has steamed</b> — present perfect means the cooking is finished, but the kitchen is still full of steam; ✗ <b>steamed</b> — past simple puts the action in the past, clashing with <b>right now</b>."},{"id":"gv-kc-05-2","level":"kc","focus":"word-choice","q":"Vegetables are cheap at the village market; a whole basket of tomatoes only ______ 20,000 dong.","options":["costs","pays","spends","charges"],"correct":0,"answer":"costs","vi":"Rau ở chợ làng rất rẻ; cả một rổ cà chua chỉ có giá 20.000 đồng.","explanation":"Word choice: the subject is a thing (<b>a basket of tomatoes</b>) and the object is a sum of money, so the verb is <b>costs</b> = has a price of.<br>✗ <b>pays</b> — a person pays money; tomatoes cannot pay; ✗ <b>spends</b> — a person spends money on something; ✗ <b>charges</b> — a seller charges a customer a price; a basket cannot charge anyone."},{"id":"gv-kc-05-3","level":"kc","focus":"idiom","q":"Lan: The recipe says 200 grams of sugar, but you used 210. / Nam: Let's not ______ — ten grams won't change the taste.","options":["pull strings","cut corners","split hairs","beat around the bush"],"correct":2,"answer":"split hairs","vi":"Lan: Công thức ghi 200 gam đường mà cậu cho 210. / Nam: Đừng bắt bẻ từng li từng tí — mười gam chẳng làm đổi vị đâu.","explanation":"Idiom: Nam refuses to argue over a tiny <b>ten-gram</b> difference, so <b>split hairs</b> = argue about small, unimportant details.<br>✗ <b>pull strings</b> — use influence to get a favour; ✗ <b>cut corners</b> — do a job cheaply or carelessly; ✗ <b>beat around the bush</b> — avoid saying the main point directly. None of these describes fussing over a small difference."},{"id":"gv-kc-05-4","level":"kc","focus":"collocation","q":"Could you ______ the table before the guests arrive for the New Year dinner?","options":["make","put","do","lay"],"correct":3,"answer":"lay","vi":"Con dọn bàn ăn trước khi khách đến dự bữa tối năm mới được không?","explanation":"Collocation: putting out plates and cutlery <b>before the guests arrive</b> is <b>lay the table</b> (also <b>set the table</b>).<br>✗ <b>make</b> — you make a bed or a cake, not a table for dinner; ✗ <b>put</b> — needs a place (put it on the table) and has no sense of preparing; ✗ <b>do</b> — 'do the table' is not an English expression for preparing it."},{"id":"gv-kc-05-5","level":"kc","focus":"relative","q":"Our class won the school football final, ______ everyone because we had lost every practice match.","options":["that surprised","which surprised","what surprised","it surprised"],"correct":1,"answer":"which surprised","vi":"Lớp mình đã thắng trận chung kết bóng đá của trường, điều đó làm mọi người bất ngờ vì bọn mình thua hết các trận giao hữu.","explanation":"Relative clause: after a <b>comma</b>, <b>which</b> can refer back to the whole previous clause (winning the final) — that is what surprised everyone.<br>✗ <b>that surprised</b> — <b>that</b> cannot begin a non-defining clause after a comma; ✗ <b>what surprised</b> — <b>what</b> = 'the thing that' and cannot add a comment to a clause; ✗ <b>it surprised</b> — starts a new independent clause, so a comma alone cannot join it (comma splice)."},{"id":"gv-kc-05-6","level":"kc","focus":"phrasal-verb","q":"I can't ______ the barking from the neighbours' dogs any longer; it goes on all night.","options":["put off","put up with","put out","put away"],"correct":1,"answer":"put up with","vi":"Tôi không thể chịu đựng tiếng sủa của mấy con chó nhà hàng xóm thêm nữa; nó kéo dài suốt đêm.","explanation":"Phrasal verb: the speaker can no longer tolerate the barking (<b>can't … any longer</b>), so <b>put up with</b> = accept something unpleasant without complaining.<br>✗ <b>put off</b> — postpone, or make someone dislike something; ✗ <b>put out</b> — extinguish a fire or light; ✗ <b>put away</b> — store something in its place. Only <b>put up with</b> takes 'the barking' as something to bear."},{"id":"gv-kc-05-7","level":"kc","focus":"word-choice","q":"The restaurant added a ten per cent service ______ to our bill, so the meal cost more than we expected.","options":["price","fare","cost","charge"],"correct":3,"answer":"charge","vi":"Nhà hàng cộng thêm 10% phí phục vụ vào hóa đơn nên bữa ăn đắt hơn chúng tôi tưởng.","explanation":"Word choice: a percentage <b>added to a bill</b> for a service is a <b>service charge</b>; a <b>charge</b> is the amount a business asks for a service.<br>✗ <b>price</b> — what goods are sold for, not an extra added to a bill; ✗ <b>fare</b> — the money paid for a bus, taxi or train journey; ✗ <b>cost</b> — what something costs you overall; 'service cost' is not the fixed term."},{"id":"gv-kc-05-8","level":"kc","focus":"tense","q":"By the time we reached the market, the fishmonger ______ every last prawn.","options":["has sold","sold","had sold","was selling"],"correct":2,"answer":"had sold","vi":"Lúc chúng tôi tới chợ thì người bán cá đã bán hết sạch tôm.","explanation":"Tense: <b>By the time we reached</b> is a past point, and the selling was already complete before it, so the past perfect <b>had sold</b> is needed.<br>✗ <b>has sold</b> — present perfect links to now, not to a past moment; ✗ <b>sold</b> — past simple would make the selling happen at the same time as our arrival; ✗ <b>was selling</b> — past continuous means the sale was still going on, but <b>every last prawn</b> shows it was finished."},{"id":"gv-kc-05-9","level":"kc","focus":"article-quantifier","q":"There's only ______ milk left in the fridge, so I can't make pancakes for everyone.","options":["a little","a few","many","few"],"correct":0,"answer":"a little","vi":"Trong tủ lạnh chỉ còn một ít sữa nên mình không làm bánh kếp cho cả nhà được.","explanation":"Quantifier: <b>milk</b> is an uncountable noun, so it needs <b>a little</b> = a small amount.<br>✗ <b>a few</b> — used only with plural countable nouns (a few eggs); ✗ <b>few</b> — also plural countable, and means 'almost none'; ✗ <b>many</b> — plural countable, and 'many' contradicts <b>only … left</b>."},{"id":"gv-kc-05-10","level":"kc","focus":"modal","q":"You ______ feed the goldfish more than once a day, or it will get sick.","options":["needn't","mustn't","don't have to","might not"],"correct":1,"answer":"mustn't","vi":"Con không được cho cá vàng ăn quá một lần mỗi ngày, nếu không nó sẽ bị bệnh.","explanation":"Modal: the warning <b>or it will get sick</b> shows that feeding more than once a day is forbidden, so <b>mustn't</b> = it is prohibited.<br>✗ <b>needn't</b> — means 'it is not necessary', not 'it is harmful'; ✗ <b>don't have to</b> — same as needn't, no prohibition; ✗ <b>might not</b> — expresses possibility ('perhaps you won't'), not a rule."},{"id":"gv-kc-05-11","level":"kc","focus":"word-choice","q":"We ______ nearly all our pocket money on snacks at the Mid-Autumn fair.","options":["paid","bought","spent","cost"],"correct":2,"answer":"spent","vi":"Chúng tôi tiêu gần hết tiền tiêu vặt vào đồ ăn vặt ở hội chợ Trung thu.","explanation":"Word choice: the object is money (<b>pocket money</b>) and the pattern is <b>spend money on something</b>, so <b>spent</b> is correct.<br>✗ <b>paid</b> — you pay a person or pay for something; 'pay money on' is wrong; ✗ <b>bought</b> — you buy goods, not money; ✗ <b>cost</b> — things cost money; people are not the subject of <b>cost</b>."},{"id":"gv-kc-05-12","level":"kc","focus":"question-tag","q":"Lan: Your parrot can say a few words, ______? / Nam: Yes, it says 'hello' every morning.","options":["can it","isn't it","doesn't it","can't it"],"correct":3,"answer":"can't it","vi":"Lan: Con vẹt của cậu nói được vài từ, phải không? / Nam: Ừ, sáng nào nó cũng nói 'hello'.","explanation":"Question tag: a positive statement takes a negative tag with the same auxiliary. The verb here is the modal <b>can</b>, so the tag is <b>can't it</b>.<br>✗ <b>can it</b> — a positive tag after a positive statement; ✗ <b>isn't it</b> — repeats <b>be</b>, but the sentence has no <b>is</b>; ✗ <b>doesn't it</b> — <b>do</b> is used only when there is no auxiliary, and here <b>can</b> is the auxiliary."},{"id":"gv-kc-05-13","level":"kc","focus":"collocation","q":"The vet told us to ______ the puppy a bath every two weeks, not every day.","options":["give","take","make","do"],"correct":0,"answer":"give","vi":"Bác sĩ thú y dặn chúng tôi tắm cho chó con hai tuần một lần, chứ không phải mỗi ngày.","explanation":"Collocation: when you wash a pet or a child, you <b>give</b> it a bath; the bath is something done to <b>the puppy</b>.<br>✗ <b>take</b> — you take (or have) a bath yourself; you cannot 'take someone a bath'; ✗ <b>make</b> — 'make a bath' is not a collocation; ✗ <b>do</b> — 'do a bath' does not exist in English."},{"id":"gv-kc-05-14","level":"kc","focus":"conditional","q":"If it ______ so heavily, the village wouldn't have called off the boat race.","options":["didn't rain","hadn't rained","wouldn't rain","doesn't rain"],"correct":1,"answer":"hadn't rained","vi":"Nếu trời không mưa to như vậy thì làng đã không hủy cuộc đua thuyền.","explanation":"Third conditional: the main clause <b>wouldn't have called off</b> (would have + past participle) shows an unreal past, so the if-clause needs the past perfect <b>hadn't rained</b>.<br>✗ <b>didn't rain</b> — past simple builds a second conditional (would + verb) about the present; ✗ <b>wouldn't rain</b> — <b>would</b> belongs in the main clause, not after <b>if</b>; ✗ <b>doesn't rain</b> — present simple makes a first conditional about a real future."},{"id":"gv-kc-05-15","level":"kc","focus":"linking","q":"The soup smelt wonderful; ______, it was far too salty to eat.","options":["therefore","moreover","however","because"],"correct":2,"answer":"however","vi":"Món canh thơm tuyệt; tuy nhiên, nó mặn quá không ăn nổi.","explanation":"Linking word: the soup <b>smelt wonderful</b> but was <b>too salty</b> — two opposite ideas — so <b>however</b> is needed.<br>✗ <b>therefore</b> — introduces a result, but being salty is not caused by smelling good; ✗ <b>moreover</b> — adds a similar point, not an opposite one; ✗ <b>because</b> — gives a reason, and a conjunction cannot sit between a semicolon and a comma like this."},{"id":"gv-kc-05-16","level":"kc","focus":"word-choice","q":"The pet shop gave us a small ______ because the cage had a scratch on one side.","options":["bargain","sale","bonus","discount"],"correct":3,"answer":"discount","vi":"Cửa hàng thú cưng giảm giá một chút cho chúng tôi vì cái lồng bị xước một bên.","explanation":"Word choice: money taken off the price <b>because the cage had a scratch</b> is a <b>discount</b>.<br>✗ <b>bargain</b> — something bought at a good price, not the amount taken off; a shop does not 'give a bargain'; ✗ <b>sale</b> — a period when a shop lowers all its prices; ✗ <b>bonus</b> — extra money paid to a worker or an added benefit, not a price cut."},{"id":"gv-kc-05-17","level":"kc","focus":"gerund-infinitive","q":"Don't forget ______ the hamster's cage before we leave for the festival.","options":["to clean","cleaning","clean","to cleaning"],"correct":0,"answer":"to clean","vi":"Đừng quên dọn lồng chuột hamster trước khi chúng ta đi lễ hội nhé.","explanation":"Gerund vs infinitive: <b>forget + to-infinitive</b> = forget a task you still need to do. The cage has not been cleaned yet (<b>before we leave</b>), so <b>to clean</b> is right.<br>✗ <b>cleaning</b> — <b>forget doing</b> = have no memory of something already done; ✗ <b>clean</b> — a bare infinitive cannot follow <b>forget</b>; ✗ <b>to cleaning</b> — <b>to</b> + -ing is not a form <b>forget</b> takes."},{"id":"gv-kc-05-18","level":"kc","focus":"phrasal-verb","q":"It took Mai several weeks to ______ the loss of her old cat.","options":["get by","get along","get over","get up"],"correct":2,"answer":"get over","vi":"Mai phải mất mấy tuần mới nguôi ngoai nỗi mất con mèo già của mình.","explanation":"Phrasal verb: recovering from a sad experience (<b>the loss of her old cat</b>) is <b>get over</b> = recover from.<br>✗ <b>get by</b> — manage to live with little money; ✗ <b>get along</b> — have a friendly relationship with someone; ✗ <b>get up</b> — rise from bed. Only <b>get over</b> takes 'the loss' as its object."},{"id":"gv-kc-05-19","level":"kc","focus":"agreement","q":"Neither the dog nor the cats ______ allowed in the kitchen while Mum is cooking.","options":["is","are","was","has been"],"correct":1,"answer":"are","vi":"Cả con chó lẫn mấy con mèo đều không được vào bếp khi mẹ đang nấu ăn.","explanation":"Agreement: with <b>neither … nor</b> the verb agrees with the nearer subject, <b>the cats</b> (plural), and <b>while Mum is cooking</b> keeps it in the present, so <b>are</b>.<br>✗ <b>is</b> — singular, would agree with the far subject <b>the dog</b>; ✗ <b>was</b> — singular and past, but the rule is present; ✗ <b>has been</b> — singular present perfect; neither the number nor the tense fits."},{"id":"gv-kc-05-20","level":"kc","focus":"idiom","q":"You should ______ if the butcher tries to charge more than the price on the sign.","options":["stand your ground","hold your tongue","pull your weight","mind your step"],"correct":0,"answer":"stand your ground","vi":"Bạn nên giữ vững lập trường nếu người bán thịt cố tính giá cao hơn giá ghi trên bảng.","explanation":"Idiom: refusing to accept a price higher than <b>the price on the sign</b> is <b>stand your ground</b> = refuse to give in.<br>✗ <b>hold your tongue</b> — stay silent, the opposite of arguing back; ✗ <b>pull your weight</b> — do your fair share of the work; ✗ <b>mind your step</b> — be careful where you walk. Only <b>stand your ground</b> fits a price dispute."},{"id":"gv-kc-05-21","level":"kc","focus":"tense","q":"My uncle ______ dogs since he was a little boy, and he still has three.","options":["keeps","kept","is keeping","has kept"],"correct":3,"answer":"has kept","vi":"Chú tôi nuôi chó từ hồi còn bé, và giờ chú vẫn nuôi ba con.","explanation":"Tense: <b>since he was a little boy</b> gives a starting point and <b>he still has three</b> shows the situation continues to now, so the present perfect <b>has kept</b> is needed.<br>✗ <b>keeps</b> — present simple cannot combine with <b>since</b> + past time; ✗ <b>kept</b> — past simple would mean he stopped keeping dogs; ✗ <b>is keeping</b> — present continuous describes only now, not a period from the past."},{"id":"gv-kc-05-22","level":"kc","focus":"participle","q":"______ the mooncakes, Mai carried a plate of them next door for the neighbours.","options":["Baking","Having baked","Baked","To bake"],"correct":1,"answer":"Having baked","vi":"Nướng xong bánh trung thu, Mai bưng một đĩa sang nhà hàng xóm.","explanation":"Participle clause: Mai finished baking <b>before</b> carrying the plate, so the perfect participle <b>Having baked</b> shows the earlier, completed action.<br>✗ <b>Baking</b> — present participle means both actions happen at the same time; she cannot carry a plate of finished cakes while still baking them; ✗ <b>Baked</b> — past participle is passive and would make Mai the thing that was baked; ✗ <b>To bake</b> — an infinitive of purpose ('in order to bake') makes no sense here."},{"id":"gv-kc-05-23","level":"kc","focus":"pronoun","q":"The two puppies love chasing ______ around the garden all afternoon.","options":["themselves","itself","each other","another"],"correct":2,"answer":"each other","vi":"Hai chú chó con thích rượt đuổi nhau quanh vườn suốt buổi chiều.","explanation":"Pronoun: <b>the two puppies</b> chase one another — an action going both ways — so the reciprocal pronoun <b>each other</b> is needed.<br>✗ <b>themselves</b> — reflexive: each puppy would be chasing its own self; ✗ <b>itself</b> — singular reflexive, but the subject is plural; ✗ <b>another</b> — means 'a different one', and there is no third puppy."},{"id":"gv-kc-05-24","level":"kc","focus":"word-choice","q":"My aunt ______ about 500,000 dong a month by selling homemade fish sauce online.","options":["earns","wins","gains","charges"],"correct":0,"answer":"earns","vi":"Dì tôi kiếm được khoảng 500.000 đồng một tháng nhờ bán nước mắm nhà làm trên mạng.","explanation":"Word choice: getting money by working or <b>selling</b> is <b>earn</b>, so <b>earns</b> about 500,000 dong a month.<br>✗ <b>wins</b> — you win a prize, a race or a game, not a monthly income; ✗ <b>gains</b> — you gain weight, experience or confidence, not a sum of money from work; ✗ <b>charges</b> — a seller charges a customer a price for an item, not 'charges 500,000 dong a month'."},{"id":"gv-kc-05-25","level":"kc","focus":"collocation","q":"The whole village ______ part in the lantern parade every autumn.","options":["makes","does","gets","takes"],"correct":3,"answer":"takes","vi":"Cả làng đều tham gia rước đèn mỗi mùa thu.","explanation":"Collocation: the fixed expression for joining an activity is <b>take part in</b>, so the village <b>takes</b> part in the parade.<br>✗ <b>makes</b> — 'make part in' is not an expression; ✗ <b>does</b> — 'do part in' does not exist; ✗ <b>gets</b> — 'get part in' is wrong; you can only 'get a part' in a play, which is a role, a different meaning."},{"id":"gv-kc-06-1","level":"kc","focus":"tense","q":"We ______ football in the park when it suddenly started to pour.","options":["played","were playing","have played","had played"],"correct":1,"answer":"were playing","vi":"Chúng tôi đang chơi bóng đá trong công viên thì trời bỗng đổ mưa như trút.","explanation":"Past continuous for a longer action in progress that a shorter past action interrupts — the clue is <b>when it suddenly started</b>: <b>were playing</b>.<br>✗ <b>played</b> — past simple would make the two events a sequence, not one cutting into the other; ✗ <b>have played</b> — present perfect cannot sit with a finished past time (when it started); ✗ <b>had played</b> — past perfect would mean the game was already over before the rain."},{"id":"gv-kc-06-2","level":"kc","focus":"word-choice","q":"We moved to a quiet ______ near the river, where all the neighbours know each other.","options":["region","territory","neighbourhood","zone"],"correct":2,"answer":"neighbourhood","vi":"Chúng tôi chuyển đến một khu dân cư yên tĩnh gần bờ sông, nơi hàng xóm đều quen biết nhau.","explanation":"Word choice for a small residential area: <b>neighbourhood</b> — the clue is <b>all the neighbours know each other</b>, so it is the streets where people live close together.<br>✗ <b>region</b> — a large part of a country (the Mekong region); ✗ <b>territory</b> — land owned or controlled by a country or an animal; ✗ <b>zone</b> — an area marked off for a purpose (a no-parking zone), not somewhere you move to live."},{"id":"gv-kc-06-3","level":"kc","focus":"collocation","q":"Please ______ attention to the safety rules before you start the chemistry experiment.","options":["give","take","pay","put"],"correct":2,"answer":"pay","vi":"Hãy chú ý đến các quy tắc an toàn trước khi bạn bắt đầu thí nghiệm hóa học.","explanation":"Collocation: the fixed verb with <b>attention</b> is <b>pay attention to</b>, here to the <b>safety rules</b>.<br>✗ <b>give</b> — you give advice, help or a hand; 'give attention' is not the set phrase; ✗ <b>take</b> — you take notes, care or a break, never attention; ✗ <b>put</b> — you put effort into something; 'put attention' is a direct translation English does not use."},{"id":"gv-kc-06-4","level":"kc","focus":"idiom","q":"Now that Mr Ba is retiring, he wants to ______ and let the younger teachers run the football club.","options":["take a rain check","take the floor","take a stand","take a back seat"],"correct":3,"answer":"take a back seat","vi":"Giờ sắp nghỉ hưu, thầy Ba muốn lui về phía sau và để các giáo viên trẻ điều hành câu lạc bộ bóng đá.","explanation":"Idiom: <b>take a back seat</b> = stop leading and let others take charge — the clue is <b>retiring</b> and <b>let the younger teachers run</b> the club.<br>✗ <b>take a rain check</b> — decline an invitation now, accept it later; ✗ <b>take the floor</b> — begin speaking to a group; ✗ <b>take a stand</b> — declare and defend a firm opinion."},{"id":"gv-kc-06-5","level":"kc","focus":"relative","q":"My grandparents still live in the small town ______ my father grew up.","options":["which","whose","who","where"],"correct":3,"answer":"where","vi":"Ông bà tôi vẫn sống ở thị trấn nhỏ nơi bố tôi lớn lên.","explanation":"Relative adverb of place: <b>where</b> stands for 'in the town' and is followed by a complete clause — <b>my father grew up</b> already has its subject and verb and needs no object.<br>✗ <b>which</b> — a pronoun that must be subject or object of the clause; it would need 'in which'; ✗ <b>whose</b> — shows possession and must be followed by a noun (whose streets); ✗ <b>who</b> — refers to a person, not a town."},{"id":"gv-kc-06-6","level":"kc","focus":"phrasal-verb","q":"Lan: How did you ______ that the test was cancelled? / Nam: Our teacher posted it in the class group.","options":["look out","find out","make out","turn out"],"correct":1,"answer":"find out","vi":"Lan: Sao cậu biết được là bài kiểm tra bị hủy? / Nam: Cô giáo đăng trong nhóm lớp.","explanation":"Phrasal verb: <b>find out</b> = discover a fact — the clue is that Nam answers <b>how</b> he learned the news (the class group).<br>✗ <b>look out</b> — be careful, watch out; ✗ <b>make out</b> — see or hear something with difficulty; ✗ <b>turn out</b> — prove to be in the end; it is used with 'it' (it turned out that…), not with 'you' + 'that'."},{"id":"gv-kc-06-7","level":"kc","focus":"modal","q":"The streets are all wet this morning. It ______ have rained during the night.","options":["can't","should","must","needn't"],"correct":2,"answer":"must","vi":"Sáng nay đường phố ướt hết cả. Chắc hẳn đêm qua trời đã mưa.","explanation":"Modal deduction: <b>must have</b> + past participle = a confident conclusion about the past drawn from evidence — the clue is <b>the streets are all wet</b>.<br>✗ <b>can't have</b> — the opposite deduction, 'I'm sure it didn't'; ✗ <b>should have</b> — says what was right but was not done (you should have studied), not a guess; ✗ <b>needn't have</b> — says something was done but was unnecessary, not a guess about what happened."},{"id":"gv-kc-06-8","level":"kc","focus":"word-choice","q":"The little shelter at the bus ______ outside our school keeps us dry when it rains.","options":["station","terminal","harbour","stop"],"correct":3,"answer":"stop","vi":"Mái che nhỏ ở trạm xe buýt trước cổng trường giúp chúng tôi khỏi bị ướt khi trời mưa.","explanation":"Word choice: a bus <b>stop</b> is the small roadside point where a bus picks passengers up — the clue is a <b>little shelter outside our school</b>.<br>✗ <b>station</b> — a large building where trains or many bus routes start and end; ✗ <b>terminal</b> — the main building at the end of a route or at an airport; ✗ <b>harbour</b> — a sheltered port for ships, not buses."},{"id":"gv-kc-06-9","level":"kc","focus":"tense","q":"By the time the bus finally came, we ______ for over half an hour.","options":["had waited","waited","have waited","are waiting"],"correct":0,"answer":"had waited","vi":"Đến lúc xe buýt cuối cùng cũng tới, chúng tôi đã đợi hơn nửa tiếng.","explanation":"Past perfect for an action completed before a past moment — the clue is <b>By the time</b> + past simple (<b>came</b>) with the duration <b>for over half an hour</b>: <b>had waited</b>.<br>✗ <b>waited</b> — past simple puts the waiting at the same time as the bus's arrival, not before it; ✗ <b>have waited</b> — present perfect cannot combine with a past-time clause ('came'); ✗ <b>are waiting</b> — present continuous clashes with a past narrative."},{"id":"gv-kc-06-10","level":"kc","focus":"article-quantifier","q":"There is ______ traffic on this road in the early morning, so we usually get to school on time.","options":["few","little","a few","many"],"correct":1,"answer":"little","vi":"Sáng sớm đường này rất ít xe cộ, nên chúng tôi thường đến trường đúng giờ.","explanation":"Quantifier with an uncountable noun: <b>traffic</b> has no plural, so it takes <b>little</b> (= not much) — and little traffic is why they get to school <b>on time</b>.<br>✗ <b>few</b> — only with plural countable nouns (few cars); ✗ <b>a few</b> — also countable-only, and 'some' traffic would not explain arriving on time; ✗ <b>many</b> — countable-only, and heavy traffic would make them late."},{"id":"gv-kc-06-11","level":"kc","focus":"collocation","q":"Nam usually ______ his homework right after dinner so he can watch TV later.","options":["makes","writes","does","works"],"correct":2,"answer":"does","vi":"Nam thường làm bài tập về nhà ngay sau bữa tối để lát nữa được xem tivi.","explanation":"Collocation: <b>do homework</b> is the fixed pair — <b>do</b> goes with tasks and duties (do the dishes, do an exercise).<br>✗ <b>makes</b> — make is for producing something (make a cake, make a decision), never homework; ✗ <b>writes</b> — you write an essay or a letter; 'write homework' is not the English collocation; ✗ <b>works</b> — has no object here; it would need a preposition (work on his homework)."},{"id":"gv-kc-06-12","level":"kc","focus":"conditional","q":"If it ______ so cold today, we would go for a walk along the river.","options":["isn't","hadn't been","wouldn't be","weren't"],"correct":3,"answer":"weren't","vi":"Nếu hôm nay trời không lạnh thế này thì chúng tôi sẽ đi dạo dọc bờ sông.","explanation":"Second conditional for an unreal present — the clues are <b>today</b> and <b>would go</b> in the main clause (it really is cold): if + past subjunctive <b>weren't</b>.<br>✗ <b>isn't</b> — present simple makes a first conditional, which pairs with 'will', not 'would'; ✗ <b>hadn't been</b> — past perfect belongs to the third conditional about the past (would have gone); ✗ <b>wouldn't be</b> — 'would' never goes inside the if-clause."},{"id":"gv-kc-06-13","level":"kc","focus":"word-choice","q":"There is a small ______ in the middle of town where people sit and feed the pigeons.","options":["corner","square","yard","block"],"correct":1,"answer":"square","vi":"Có một quảng trường nhỏ ở giữa thị trấn, nơi mọi người ngồi cho bồ câu ăn.","explanation":"Word choice: a <b>square</b> is an open public space in a town — the clue is <b>in the middle of town where people sit</b> and feed pigeons.<br>✗ <b>corner</b> — the point where two streets meet, not a space to sit in; ✗ <b>yard</b> — an enclosed area beside a house or school, not public; ✗ <b>block</b> — a group of buildings between streets, which you walk around, not sit in."},{"id":"gv-kc-06-14","level":"kc","focus":"phrasal-verb","q":"Our old school bus ______ on the way to the museum, so we arrived an hour late.","options":["broke down","broke up","broke out","made up"],"correct":0,"answer":"broke down","vi":"Chiếc xe buýt cũ của trường bị hỏng giữa đường đến bảo tàng, nên chúng tôi tới muộn một tiếng.","explanation":"Phrasal verb: a vehicle or machine <b>breaks down</b> when it stops working — the clue is the bus stopped and <b>we arrived an hour late</b>.<br>✗ <b>broke up</b> — end a relationship, or (of school) close for the holidays; ✗ <b>broke out</b> — start suddenly (a fire, a war, a fight); ✗ <b>made up</b> — invent a story, or make peace after a quarrel."},{"id":"gv-kc-06-15","level":"kc","focus":"linking","q":"Lan has practised the piano every day for months; ______, she played beautifully at the school concert.","options":["therefore","however","otherwise","meanwhile"],"correct":0,"answer":"therefore","vi":"Lan đã luyện đàn piano mỗi ngày suốt nhiều tháng; vì vậy, cô ấy chơi rất hay trong buổi hòa nhạc của trường.","explanation":"Linking word of result: <b>therefore</b> = as a result — the clue is cause (<b>months of practice</b>) followed by effect (<b>played beautifully</b>).<br>✗ <b>however</b> — introduces a contrast, but practising and playing well do not contradict; ✗ <b>otherwise</b> — means 'if not', which would need a warning about what happens without practice; ✗ <b>meanwhile</b> — 'at the same time', but the concert came after the months of practice."},{"id":"gv-kc-06-16","level":"kc","focus":"tense","q":"Lan: Have you finished your maths homework? / Nam: Not yet. I ______ the last two problems.","options":["don't do","didn't do","hadn't done","haven't done"],"correct":3,"answer":"haven't done","vi":"Lan: Cậu làm xong bài tập toán chưa? / Nam: Chưa. Tớ vẫn chưa làm hai bài cuối.","explanation":"Present perfect for an action not completed up to now — the clues are <b>Not yet</b> and the question <b>Have you finished</b>: <b>haven't done</b>.<br>✗ <b>don't do</b> — present simple describes a habit, not the state of one piece of homework; ✗ <b>didn't do</b> — past simple needs a finished past time (yesterday) and would mean he is not going to do them; ✗ <b>hadn't done</b> — past perfect needs an earlier past reference point, but the time here is now."},{"id":"gv-kc-06-17","level":"kc","focus":"idiom","q":"Before opening a second shop, Mrs Hoa decided to ______ by selling her cakes at the weekend market.","options":["break the ice","test the waters","hit the road","clear the air"],"correct":1,"answer":"test the waters","vi":"Trước khi mở cửa hàng thứ hai, cô Hoa quyết định thăm dò thị trường bằng cách bán bánh ở chợ cuối tuần.","explanation":"Idiom: <b>test the waters</b> = try something in a small way before committing — the clue is <b>Before opening a second shop</b> she sells at a market first.<br>✗ <b>break the ice</b> — make people relax when they first meet; ✗ <b>hit the road</b> — leave, set off on a journey; ✗ <b>clear the air</b> — settle a misunderstanding or bad feeling between people."},{"id":"gv-kc-06-18","level":"kc","focus":"word-choice","q":"Turn left at the ______ where Nguyen Trai Street meets Le Loi Street, and the school is on your right.","options":["junction","lane","pavement","bridge"],"correct":0,"answer":"junction","vi":"Rẽ trái ở ngã tư nơi đường Nguyễn Trãi giao với đường Lê Lợi, trường ở bên tay phải.","explanation":"Word choice: a <b>junction</b> is the place where two roads meet — the clue is <b>where Nguyen Trai Street meets Le Loi Street</b>.<br>✗ <b>lane</b> — a narrow road, or one strip of a wide road; ✗ <b>pavement</b> — the path beside the road for walking on; ✗ <b>bridge</b> — a structure carrying a road over a river or another road."},{"id":"gv-kc-06-19","level":"kc","focus":"modal","q":"Lan: ______ I borrow your ruler for a minute? / Nam: Sure, here you are.","options":["Must","Should","Could","Would"],"correct":2,"answer":"Could","vi":"Lan: Tớ mượn thước của cậu một lát được không? / Nam: Được chứ, đây này.","explanation":"Modal for permission: <b>Could I…?</b> is a polite request — the clue is Nam's reply <b>Sure, here you are</b>, which grants it.<br>✗ <b>Must</b> — 'Must I borrow?' asks whether I am obliged to, which makes no sense here; ✗ <b>Should</b> — asks for advice about the right thing to do; ✗ <b>Would</b> — 'Would I borrow?' asks about my own future action; a request with would is 'Would you lend me…?'."},{"id":"gv-kc-06-20","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your raincoat tomorrow; it looks like a storm is coming.","options":["taking","take","to taking","to take"],"correct":3,"answer":"to take","vi":"Nhớ mang áo mưa ngày mai nhé; có vẻ bão sắp đến rồi.","explanation":"Gerund vs infinitive: <b>remember + to-infinitive</b> = not forget a task still to come — the clue is <b>tomorrow</b>: <b>to take</b>.<br>✗ <b>taking</b> — 'remember doing' is a memory of something already done, impossible for tomorrow; ✗ <b>take</b> — a bare infinitive never follows 'remember'; ✗ <b>to taking</b> — 'to' + -ing only follows a few phrases (look forward to, be used to), not remember."},{"id":"gv-kc-06-21","level":"kc","focus":"relative","q":"The new bridge, ______ opened last month, has cut my journey to school in half.","options":["that","which","where","what"],"correct":1,"answer":"which","vi":"Cây cầu mới, mới thông xe tháng trước, đã rút ngắn quãng đường đến trường của tôi một nửa.","explanation":"Non-defining relative clause (between commas) about a thing: <b>which</b> is the subject of <b>opened</b>.<br>✗ <b>that</b> — cannot be used after a comma in a non-defining clause; ✗ <b>where</b> — a relative adverb, so it needs a full clause with its own subject after it (where I cross the river); ✗ <b>what</b> — not a relative pronoun; it means 'the thing that' and cannot follow a noun."},{"id":"gv-kc-06-22","level":"kc","focus":"collocation","q":"Hurry up, or we'll ______ the school bus again and have to walk!","options":["miss","lose","drop","fail"],"correct":0,"answer":"miss","vi":"Nhanh lên, không thì chúng ta lại lỡ xe buýt của trường và phải đi bộ đấy!","explanation":"Collocation: you <b>miss</b> a bus, train or plane when you arrive too late to catch it — the clue is <b>Hurry up</b> and <b>have to walk</b>.<br>✗ <b>lose</b> — you lose an object or a game; 'lose the bus' is a translation from Vietnamese, not English; ✗ <b>drop</b> — let something fall, or stop doing it; ✗ <b>fail</b> — not succeed at an exam or a task; it does not take a bus as its object."},{"id":"gv-kc-06-23","level":"kc","focus":"inversion","q":"______ had we left the house when it began to snow.","options":["No sooner","Not until","Hardly","Only"],"correct":2,"answer":"Hardly","vi":"Chúng tôi vừa mới ra khỏi nhà thì tuyết bắt đầu rơi.","explanation":"Inversion: <b>Hardly</b> + had + subject + past participle… <b>when</b> — the clue is <b>when</b> after the inverted clause.<br>✗ <b>No sooner</b> — the same inversion but must pair with <b>than</b>, not 'when'; ✗ <b>Not until</b> — must be followed by a time phrase or clause before the inverted main verb (Not until midnight did we leave); ✗ <b>Only</b> — needs a phrase after it first (Only then / Only when) to trigger inversion; on its own it cannot start 'had we left'."},{"id":"gv-kc-06-24","level":"kc","focus":"word-choice","q":"Sa Pa is a favourite ______ for tourists who want to see snow in winter.","options":["direction","journey","arrival","destination"],"correct":3,"answer":"destination","vi":"Sa Pa là điểm đến yêu thích của du khách muốn ngắm tuyết vào mùa đông.","explanation":"Word choice: a <b>destination</b> is the place you travel to — the clue is <b>for tourists who want to see snow</b>, Sa Pa is where they go.<br>✗ <b>direction</b> — the way you head (north, left), not a place; ✗ <b>journey</b> — the act of travelling, not the place you reach; ✗ <b>arrival</b> — the act of reaching a place (an arrivals hall), not a location."},{"id":"gv-kc-06-25","level":"kc","focus":"tense","q":"This time next week, we ______ on the beach in Nha Trang instead of sitting in class.","options":["lie","will be lying","are lying","have lain"],"correct":1,"answer":"will be lying","vi":"Giờ này tuần sau, chúng tôi sẽ đang nằm trên bãi biển Nha Trang thay vì ngồi trong lớp.","explanation":"Future continuous for an action in progress at a fixed future moment — the clue is <b>This time next week</b>: <b>will be lying</b>.<br>✗ <b>lie</b> — present simple is for habits or timetables, not a picture of one future moment; ✗ <b>are lying</b> — present continuous means happening now or a fixed arrangement, not being in the middle of an action at a future time; ✗ <b>have lain</b> — present perfect looks back at a finished action, not forward."},{"id":"gv-kc-07-1","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Minh: He ______ for a job interview at the moment, so don't disturb him.","options":["prepares","is preparing","has prepared","prepared"],"correct":1,"answer":"is preparing","vi":"Lan: Nam đâu rồi? / Minh: Bạn ấy đang chuẩn bị cho buổi phỏng vấn xin việc lúc này, nên đừng làm phiền.","explanation":"<b>At the moment</b> means right now, so the present continuous <b>is preparing</b> describes an action in progress at the time of speaking.<br>✗ <b>prepares</b> — simple present is for habits and facts, not what is happening now; ✗ <b>has prepared</b> — present perfect means the preparing is finished, but he is still busy; ✗ <b>prepared</b> — past simple puts it in the past, yet 'don't disturb him' shows it is happening now."},{"id":"gv-kc-07-2","level":"kc","focus":"word-choice","q":"Our garden party was cancelled because of a sudden ______ that flooded the lawn in minutes.","options":["downpour","drizzle","mist","frost"],"correct":0,"answer":"downpour","vi":"Bữa tiệc ngoài vườn của chúng tôi bị hủy vì một trận mưa như trút bất ngờ làm ngập bãi cỏ chỉ trong vài phút.","explanation":"A <b>downpour</b> is a sudden, very heavy fall of rain — the only option that could <b>flood the lawn in minutes</b>.<br>✗ <b>drizzle</b> — very light, fine rain; it could not flood anything; ✗ <b>mist</b> — thin fog hanging in the air, not falling rain; ✗ <b>frost</b> — a layer of ice on cold surfaces; no water to flood a lawn."},{"id":"gv-kc-07-3","level":"kc","focus":"collocation","q":"My brother has to ______ a decision about which career to follow before he finishes school.","options":["do","have","make","get"],"correct":2,"answer":"make","vi":"Anh trai tôi phải đưa ra quyết định về nghề nghiệp sẽ theo đuổi trước khi học xong.","explanation":"<b>Make a decision</b> is the fixed verb + noun collocation (= decide), and <b>which career to follow</b> shows a choice being made.<br>✗ <b>do</b> — 'do' goes with tasks and activities (do homework, do the dishes), never with 'decision'; ✗ <b>have</b> — 'have' collocates with a meal, a shower, a look, not with 'decision'; ✗ <b>get</b> — 'get' means receive or obtain; you cannot receive a decision you are making yourself."},{"id":"gv-kc-07-4","level":"kc","focus":"idiom","q":"Nam: Should I take the job in Da Nang or stay here? / Lan: ______ is that you need a steady income, so take it.","options":["The last straw","The tip of the iceberg","The eleventh hour","The bottom line"],"correct":3,"answer":"The bottom line","vi":"Nam: Mình nên nhận việc ở Đà Nẵng hay ở lại đây? / Lan: Điều cốt lõi là cậu cần một nguồn thu nhập ổn định, nên nhận đi.","explanation":"<b>The bottom line</b> is the most important fact that decides a matter — here <b>you need a steady income, so take it</b>.<br>✗ <b>the last straw</b> — the final problem that makes you lose patience; ✗ <b>the tip of the iceberg</b> — a small visible part of a much bigger problem; ✗ <b>the eleventh hour</b> — the last possible moment before something happens. None of these states a deciding reason."},{"id":"gv-kc-07-5","level":"kc","focus":"phrasal-verb","q":"Lan: Why isn't Minh at school anymore? / Nam: He decided to ______ of school to help his father at the shop.","options":["drop out","drop off","drop in","drop by"],"correct":0,"answer":"drop out","vi":"Lan: Sao Minh không còn đi học nữa? / Nam: Cậu ấy quyết định bỏ học để phụ bố ở cửa hàng.","explanation":"<b>Drop out of school</b> means to leave school before finishing — the reason <b>Minh isn't at school anymore</b> — and it is the only option that takes <b>of</b>.<br>✗ <b>drop off</b> — fall asleep, or deliver someone somewhere; ✗ <b>drop in</b> — pay a short, casual visit (drop in on someone); ✗ <b>drop by</b> — call round briefly at a place; none combines with 'of school'."},{"id":"gv-kc-07-6","level":"kc","focus":"modal","q":"You ______ such an expensive present; just coming to my birthday party was enough.","options":["mustn't have bought","can't have bought","needn't have bought","won't have bought"],"correct":2,"answer":"needn't have bought","vi":"Bạn không cần phải mua món quà đắt tiền như vậy đâu; chỉ cần đến dự sinh nhật mình là đủ rồi.","explanation":"<b>Needn't have + past participle</b> means something was done but was not necessary: the present <b>was</b> bought, and <b>just coming was enough</b> shows it wasn't needed.<br>✗ <b>mustn't have bought</b> — 'must have' only makes deductions, and its negative is 'can't have'; it never means 'it was unnecessary'; ✗ <b>can't have bought</b> — a deduction that something did NOT happen, but the present clearly exists; ✗ <b>won't have bought</b> — future perfect, for something finished by a future time."},{"id":"gv-kc-07-7","level":"kc","focus":"relative","q":"Do you remember the year ______ our family first moved to Ho Chi Minh City?","options":["where","whom","which","when"],"correct":3,"answer":"when","vi":"Bạn có nhớ năm mà gia đình chúng ta lần đầu chuyển đến Thành phố Hồ Chí Minh không?","explanation":"<b>When</b> is the relative adverb used after a time noun such as <b>the year</b> (= in which).<br>✗ <b>where</b> — refers to places, not times; ✗ <b>whom</b> — refers to people as an object; ✗ <b>which</b> — a pronoun that would need a preposition here: 'the year in which our family moved'."},{"id":"gv-kc-07-8","level":"kc","focus":"word-choice","q":"Dad drove to work very slowly because of the thick ______ on the road this morning.","options":["hail","thunder","drought","fog"],"correct":3,"answer":"fog","vi":"Sáng nay bố lái xe đi làm rất chậm vì sương mù dày đặc trên đường.","explanation":"<b>Fog</b> is thick cloud near the ground that blocks a driver's view — the clue is <b>thick … on the road</b> making Dad drive slowly.<br>✗ <b>hail</b> — small balls of ice falling from the sky; it is not 'thick on the road'; ✗ <b>thunder</b> — the loud sound in a storm; it cannot be seen or be 'thick'; ✗ <b>drought</b> — a long period without rain, not something lying on a road."},{"id":"gv-kc-07-9","level":"kc","focus":"tense","q":"By the time we got to Hoa's house, the party ______.","options":["has already started","had already started","was already starting","already starts"],"correct":1,"answer":"had already started","vi":"Lúc chúng tôi đến nhà Hoa thì bữa tiệc đã bắt đầu rồi.","explanation":"<b>By the time + past simple (got)</b> marks a point in the past, and an action already complete before that point takes the past perfect: <b>had already started</b>.<br>✗ <b>has already started</b> — present perfect links to now, but the story is set in the past; ✗ <b>was already starting</b> — past continuous means it was only just beginning as we arrived, which clashes with 'already'; ✗ <b>already starts</b> — simple present cannot follow a past-time clause."},{"id":"gv-kc-07-10","level":"kc","focus":"article-quantifier","q":"There isn't ______ milk left in the fridge, so could you buy some on the way home?","options":["much","many","a few","few"],"correct":0,"answer":"much","vi":"Trong tủ lạnh không còn nhiều sữa, nên bạn mua thêm trên đường về nhà được không?","explanation":"<b>Milk</b> is an uncountable noun, and in a negative sentence (<b>isn't</b>) an uncountable noun takes <b>much</b>.<br>✗ <b>many</b> — only with plural countable nouns (many bottles); ✗ <b>a few</b> — plural countable nouns only, and 'isn't a few' is not used; ✗ <b>few</b> — also plural countable (few bottles) and already negative, so it cannot follow 'isn't'."},{"id":"gv-kc-07-11","level":"kc","focus":"collocation","q":"Put on your coat, or you will ______ a cold waiting for the bus in this wind.","options":["catch","take","hold","bring"],"correct":0,"answer":"catch","vi":"Mặc áo khoác vào đi, không thì bạn sẽ bị cảm lạnh khi đứng đợi xe buýt trong gió này.","explanation":"<b>Catch a cold</b> is the fixed collocation for becoming ill with a cold — the clue is the cold <b>wind</b> that makes you ill.<br>✗ <b>take</b> — 'take' collocates with medicine or a rest, not with an illness you get; ✗ <b>hold</b> — means keep something in your hand or position; nothing to do with getting ill; ✗ <b>bring</b> — means carry something to a place; you do not 'bring a cold'."},{"id":"gv-kc-07-12","level":"kc","focus":"gerund-infinitive","q":"My aunt is used to ______ up early because she runs a stall at the market.","options":["get","to get","got","getting"],"correct":3,"answer":"getting","vi":"Dì tôi đã quen với việc dậy sớm vì dì bán hàng ở chợ.","explanation":"<b>Be used to</b> (= be accustomed to) ends in the preposition 'to', so it takes a noun or -ing form: <b>is used to getting up</b>; the clue is <b>is</b> before 'used to'.<br>✗ <b>get</b> — a bare infinitive never follows a preposition; ✗ <b>to get</b> — the to-infinitive only follows 'used to' WITHOUT 'be', meaning a past habit (She used to get up early); ✗ <b>got</b> — a past form cannot follow 'to'."},{"id":"gv-kc-07-13","level":"kc","focus":"word-choice","q":"My uncle's farm lost most of its rice this year because of the long ______.","options":["flood","drought","hail","lightning"],"correct":1,"answer":"drought","vi":"Nông trại của chú tôi mất gần hết lúa năm nay vì đợt hạn hán kéo dài.","explanation":"A <b>drought</b> is a long period without rain, which dries up crops — the clue is <b>long</b> plus a lost <b>rice</b> harvest.<br>✗ <b>flood</b> — too much water covering the land; it damages crops but is not described as 'long'; ✗ <b>hail</b> — balls of ice in a brief storm, not a long event; ✗ <b>lightning</b> — a sudden flash lasting a second; it cannot be 'long'."},{"id":"gv-kc-07-14","level":"kc","focus":"linking","q":"Nam wants to become a doctor, ______ his twin brother dreams of opening a restaurant.","options":["whereas","however","therefore","so that"],"correct":0,"answer":"whereas","vi":"Nam muốn trở thành bác sĩ, trong khi người anh sinh đôi của cậu ấy lại mơ mở một nhà hàng.","explanation":"<b>Whereas</b> is a conjunction that joins two contrasting clauses inside one sentence — Nam's plan versus <b>his twin brother's</b> different dream.<br>✗ <b>however</b> — an adverb, not a conjunction; it needs a full stop or semicolon before it ('…doctor. However, his…'); ✗ <b>therefore</b> — shows a result, but the second clause is a contrast, not a consequence; ✗ <b>so that</b> — shows purpose, but the brother's dream is not the purpose of Nam's plan."},{"id":"gv-kc-07-15","level":"kc","focus":"phrasal-verb","q":"Could you ______ my little sister from school today? I have a job interview at three.","options":["drop off","take up","pick up","bring up"],"correct":2,"answer":"pick up","vi":"Hôm nay bạn đón em gái mình ở trường giúp được không? Mình có buổi phỏng vấn xin việc lúc ba giờ.","explanation":"<b>Pick up</b> someone <b>from</b> a place means to collect them, usually by car — the clue is <b>from school</b>.<br>✗ <b>drop off</b> — the opposite: leave someone AT a place; it goes with 'at', not 'from'; ✗ <b>take up</b> — start a hobby or activity (take up tennis); ✗ <b>bring up</b> — raise a child, or mention a topic in conversation."},{"id":"gv-kc-07-16","level":"kc","focus":"conditional","q":"If I ______ you, I would apply for the job at the new hotel before somebody else does.","options":["am","had been","will be","were"],"correct":3,"answer":"were","vi":"Nếu tôi là bạn, tôi sẽ nộp đơn xin việc ở khách sạn mới trước khi người khác nộp.","explanation":"The second conditional gives advice about an unreal present situation; <b>would apply</b> in the main clause tells you the if-clause needs a past form: <b>If I were you</b>, the fixed advice phrase.<br>✗ <b>am</b> — present simple belongs to the first conditional (If I am…, I will…), and 'I am you' is impossible; ✗ <b>will be</b> — 'will' is not used in the if-clause of a conditional; ✗ <b>had been</b> — third conditional, which would need 'would have applied'."},{"id":"gv-kc-07-17","level":"kc","focus":"idiom","q":"Lan: I want to save up for a new laptop. / Nam: Then you'll have to ______ and stop buying bubble tea every day.","options":["hold your horses","tighten your belt","keep your chin up","bite your tongue"],"correct":1,"answer":"tighten your belt","vi":"Lan: Mình muốn để dành tiền mua laptop mới. / Nam: Vậy thì cậu phải thắt lưng buộc bụng và ngừng mua trà sữa mỗi ngày.","explanation":"<b>Tighten your belt</b> means to spend less money because you have less to spend — the clue is <b>save up</b> and <b>stop buying bubble tea</b>.<br>✗ <b>hold your horses</b> — wait, slow down, don't rush; ✗ <b>keep your chin up</b> — stay cheerful in a difficult time; ✗ <b>bite your tongue</b> — stop yourself from saying something. None of these is about money."},{"id":"gv-kc-07-18","level":"kc","focus":"passive","q":"The invitations for the party ______ to all our classmates yesterday.","options":["sent","have been sent","were sent","are sent"],"correct":2,"answer":"were sent","vi":"Thiệp mời dự tiệc đã được gửi tới tất cả các bạn cùng lớp hôm qua.","explanation":"<b>The invitations</b> cannot send themselves, so the passive is needed, and <b>yesterday</b> fixes the past simple: <b>were sent</b>.<br>✗ <b>sent</b> — active past simple, which would make the invitations the sender; ✗ <b>have been sent</b> — present perfect passive cannot combine with a finished past time like 'yesterday'; ✗ <b>are sent</b> — present simple passive describes a habit or general fact, not one completed event yesterday."},{"id":"gv-kc-07-19","level":"kc","focus":"word-choice","q":"After the rain stopped, a bright ______ stretched across the sky above our house.","options":["thunder","lightning","hail","rainbow"],"correct":3,"answer":"rainbow","vi":"Sau khi mưa tạnh, một chiếc cầu vồng rực rỡ trải dài trên bầu trời phía trên nhà chúng tôi.","explanation":"A <b>rainbow</b> is the coloured arc that appears when the sun comes out <b>after the rain</b> — the only option that <b>stretches across the sky</b>.<br>✗ <b>thunder</b> — the loud noise in a storm; it is heard, not seen; ✗ <b>lightning</b> — a sudden flash DURING a storm, not after the rain stops; ✗ <b>hail</b> — small balls of ice that fall, not something stretched across the sky."},{"id":"gv-kc-07-20","level":"kc","focus":"reported","q":"Mai said that she ______ her grandparents in the countryside the following weekend.","options":["would visit","will visit","visits","has visited"],"correct":0,"answer":"would visit","vi":"Mai nói rằng cô ấy sẽ về thăm ông bà ở quê vào cuối tuần sau đó.","explanation":"After a past reporting verb (<b>said</b>) the tense shifts back, so 'will visit' becomes <b>would visit</b>; <b>the following weekend</b> (the reported form of 'next weekend') confirms it.<br>✗ <b>will visit</b> — 'will' stays only after a present reporting verb (says); ✗ <b>visits</b> — present simple describes a habit, not a plan for one future weekend; ✗ <b>has visited</b> — present perfect means the visit is already done, but 'the following weekend' is still to come."},{"id":"gv-kc-07-21","level":"kc","focus":"collocation","q":"My cousins are going to ______ a party for Grandma's seventieth birthday next month.","options":["make","do","throw","put"],"correct":2,"answer":"throw","vi":"Các anh chị họ của tôi sẽ tổ chức một bữa tiệc mừng sinh nhật lần thứ bảy mươi của bà vào tháng sau.","explanation":"<b>Throw a party</b> (also have/hold/give a party) is the collocation for organising a celebration, and <b>for Grandma's birthday</b> shows one being organised.<br>✗ <b>make</b> — 'make' is for producing things (make a cake), not events; ✗ <b>do</b> — 'do' is for tasks and chores (do the shopping), not for parties; ✗ <b>put</b> — needs 'on' to mean organise (put on a show); alone it is meaningless here."},{"id":"gv-kc-07-22","level":"kc","focus":"tense","q":"My father ______ at the same bank since he left college, and he still enjoys it.","options":["works","has worked","is working","worked"],"correct":1,"answer":"has worked","vi":"Bố tôi đã làm việc ở cùng một ngân hàng kể từ khi rời trường cao đẳng, và bố vẫn thích công việc đó.","explanation":"<b>Since + a past starting point</b> (<b>since he left college</b>) with a situation that continues now (<b>still enjoys it</b>) takes the present perfect: <b>has worked</b>.<br>✗ <b>works</b> — simple present describes the habit but cannot go with 'since'; ✗ <b>is working</b> — present continuous describes a temporary action now, not a period running from the past; ✗ <b>worked</b> — past simple means the job is over, but he still enjoys it."},{"id":"gv-kc-07-23","level":"kc","focus":"preposition","q":"At the class reunion, I finally had time to catch up ______ my old friends.","options":["on","to","at","with"],"correct":3,"answer":"with","vi":"Ở buổi họp lớp, cuối cùng tôi cũng có thời gian hàn huyên với bạn bè cũ.","explanation":"<b>Catch up with</b> someone means to meet them and exchange news — the clue is <b>my old friends</b> at a <b>reunion</b>.<br>✗ <b>on</b> — 'catch up on' goes with things you missed (catch up on sleep, homework), not people; ✗ <b>to</b> — 'catch up to' means physically reach someone ahead of you, not chat; ✗ <b>at</b> — 'catch up at' is not a phrasal verb in English."},{"id":"gv-kc-07-24","level":"kc","focus":"word-choice","q":"Check the weather ______ before you invite everyone to the beach on Sunday.","options":["forecast","climate","temperature","season"],"correct":0,"answer":"forecast","vi":"Hãy xem dự báo thời tiết trước khi mời mọi người đi biển vào Chủ nhật.","explanation":"A <b>weather forecast</b> is a prediction of the coming weather — what you <b>check before</b> planning a beach trip <b>on Sunday</b>.<br>✗ <b>climate</b> — the usual weather of a region over many years; it cannot be 'checked' for one Sunday; ✗ <b>temperature</b> — only how hot or cold it is, and 'weather temperature' is not a phrase; ✗ <b>season</b> — a part of the year (summer, winter), not something you check for a day."},{"id":"gv-kc-07-25","level":"kc","focus":"comparison","q":"Living in the city is ______ more expensive than living in our hometown, so I might move back after graduation.","options":["very","too","far","so"],"correct":2,"answer":"far","vi":"Sống ở thành phố đắt đỏ hơn nhiều so với sống ở quê, nên có lẽ tôi sẽ chuyển về sau khi tốt nghiệp.","explanation":"A comparative (<b>more expensive</b>) is strengthened with <b>far</b>, much or a lot; the clue is <b>more … than</b> around the adjective.<br>✗ <b>very</b> — modifies a plain adjective (very expensive), never a comparative; ✗ <b>too</b> — means 'more than enough' with a plain adjective (too expensive); ✗ <b>so</b> — goes with a plain adjective (so expensive) or 'so … that', not with 'more … than'."},{"id":"gv-kc-08-1","level":"kc","focus":"word-choice","q":"Our class ______ shows that we have PE right after lunch on Mondays.","options":["timetable","register","diary","agenda"],"correct":0,"answer":"timetable","vi":"Thời khóa biểu của lớp mình cho thấy thứ Hai có tiết Thể dục ngay sau giờ ăn trưa.","explanation":"Word choice: the thing that <b>shows we have PE right after lunch on Mondays</b> is the list of lesson times, so <b>timetable</b> fits. ✗ <b>register</b> — a list of names used to record who is present; ✗ <b>diary</b> — a personal book where you write your own plans or thoughts; ✗ <b>agenda</b> — the list of points to discuss at a meeting."},{"id":"gv-kc-08-2","level":"kc","focus":"collocation","q":"Lan ______ most of her pocket money on comic books and film magazines.","options":["pays","spends","costs","uses"],"correct":1,"answer":"spends","vi":"Lan tiêu phần lớn tiền tiêu vặt vào truyện tranh và tạp chí điện ảnh.","explanation":"Collocation: the pattern is <b>spend money on something</b>, and the clue is <b>her pocket money on comic books</b>. ✗ <b>pays</b> — you pay <b>for</b> something, not pay money on it; ✗ <b>costs</b> — the thing bought is the subject (comics cost money), not the person; ✗ <b>uses</b> — <i>use money on</i> is not a natural collocation for buying."},{"id":"gv-kc-08-3","level":"kc","focus":"tense","q":"By next Friday, Lan ______ all her exam revision, so she can join the camping trip.","options":["finishes","will finish","will have finished","has finished"],"correct":2,"answer":"will have finished","vi":"Đến thứ Sáu tuần sau, Lan sẽ ôn thi xong hết nên có thể tham gia chuyến cắm trại.","explanation":"Future perfect: <b>by next Friday</b> marks a deadline before which the action will be complete, so we need <b>will have finished</b>. ✗ <b>will finish</b> — future simple only says it happens some time in the future, not that it is done before the deadline; ✗ <b>finishes</b> — present simple cannot describe a future deadline here; ✗ <b>has finished</b> — present perfect is for something already done now, not by a future time."},{"id":"gv-kc-08-4","level":"kc","focus":"idiom","q":"The new coach is strict: any player who refuses to ______ will be dropped from the team.","options":["cross the line","draw the line","hold the line","toe the line"],"correct":3,"answer":"toe the line","vi":"Huấn luyện viên mới rất nghiêm: cầu thủ nào không chịu tuân thủ kỷ luật sẽ bị loại khỏi đội.","explanation":"Idiom: a strict coach drops players who refuse to obey, so <b>toe the line</b> (= obey the rules) fits. ✗ <b>cross the line</b> — go too far, behave unacceptably; ✗ <b>draw the line</b> — set a limit on what you will accept; ✗ <b>hold the line</b> — keep your position or refuse to change."},{"id":"gv-kc-08-5","level":"kc","focus":"phrasal-verb","q":"The doctor told Nam to ______ sweets and fizzy drinks before the big race.","options":["cut down on","cut off","cut up","cut across"],"correct":0,"answer":"cut down on","vi":"Bác sĩ bảo Nam giảm bớt kẹo và nước ngọt có ga trước cuộc đua lớn.","explanation":"Phrasal verb: a doctor wants Nam to eat fewer sweets, so <b>cut down on</b> (= reduce the amount of) fits <b>sweets and fizzy drinks</b>. ✗ <b>cut off</b> — disconnect or remove completely; ✗ <b>cut up</b> — chop into pieces; ✗ <b>cut across</b> — take a short way through a place."},{"id":"gv-kc-08-6","level":"kc","focus":"word-choice","q":"Lan got full ______ in the music quiz because she knew every song.","options":["degrees","grades","marks","levels"],"correct":2,"answer":"marks","vi":"Lan được điểm tối đa trong cuộc thi đố vui âm nhạc vì bạn ấy biết hết mọi bài hát.","explanation":"Word choice: <b>full marks</b> is the fixed phrase for the highest possible score, and <b>knew every song</b> in a quiz confirms it. ✗ <b>grades</b> — letters like A or B for a course, not a quiz score; ✗ <b>degrees</b> — university qualifications, or units of temperature; ✗ <b>levels</b> — stages of difficulty, not a score."},{"id":"gv-kc-08-7","level":"kc","focus":"modal","q":"Nam ______ have bought the concert tickets yet — the box office doesn't open until ten.","options":["mustn't","can't","needn't","shouldn't"],"correct":1,"answer":"can't","vi":"Nam không thể nào đã mua vé buổi hòa nhạc được — quầy vé mười giờ mới mở cửa mà.","explanation":"Modal of deduction: <b>can't have + past participle</b> says a past action was impossible, and the clue is <b>the box office doesn't open until ten</b>. ✗ <b>mustn't</b> — <i>mustn't have</i> is not used for deduction (we say <i>can't have</i>); ✗ <b>needn't</b> — <i>needn't have</i> means he did it but it wasn't necessary; ✗ <b>shouldn't</b> — <i>shouldn't have</i> criticises something he actually did."},{"id":"gv-kc-08-8","level":"kc","focus":"collocation","q":"Nam ______ two goals in the final, so his team won the school cup.","options":["made","hit","won","scored"],"correct":3,"answer":"scored","vi":"Nam ghi hai bàn trong trận chung kết nên đội của cậu ấy giành cúp của trường.","explanation":"Collocation: in football you <b>score a goal</b>, and the clue is <b>two goals in the final</b>. ✗ <b>made</b> — <i>make a goal</i> is not the football collocation; ✗ <b>hit</b> — you hit a ball or the post, not a goal; ✗ <b>won</b> — you win a match or a cup, not a goal."},{"id":"gv-kc-08-9","level":"kc","focus":"relative","q":"Nam told his mother everything ______ had happened at the football match.","options":["who","which","that","what"],"correct":2,"answer":"that","vi":"Nam kể cho mẹ nghe mọi chuyện đã xảy ra ở trận bóng đá.","explanation":"Relative pronoun: after <b>everything</b> (also <i>all, nothing</i>, superlatives) the relative pronoun is <b>that</b>. ✗ <b>what</b> — means 'the thing which' and cannot follow a noun like <i>everything</i>; ✗ <b>who</b> — refers to people, not things; ✗ <b>which</b> — not used after <i>everything / all / nothing</i>."},{"id":"gv-kc-08-10","level":"kc","focus":"word-choice","q":"Lan has to ______ two chapters of history tonight, so she can't come to the cinema.","options":["rehearse","remind","revise","repeat"],"correct":2,"answer":"revise","vi":"Tối nay Lan phải ôn lại hai chương lịch sử nên không đi xem phim được.","explanation":"Word choice: studying <b>two chapters of history</b> again before a test is to <b>revise</b>. ✗ <b>rehearse</b> — practise a play or performance; ✗ <b>remind</b> — make a person remember, so it needs a person as its object; ✗ <b>repeat</b> — say or do something again, not study it."},{"id":"gv-kc-08-11","level":"kc","focus":"article-quantifier","q":"There were very ______ people at the early screening, so we got the best seats.","options":["few","little","a few","a little"],"correct":0,"answer":"few","vi":"Có rất ít người ở suất chiếu sớm nên bọn mình được ngồi chỗ đẹp nhất.","explanation":"Quantifiers: <b>people</b> is countable and <b>very</b> makes the amount negative ('almost none'), so <b>few</b> fits. ✗ <b>little</b> — used with uncountable nouns; ✗ <b>a few</b> — positive ('some') and cannot follow <i>very</i>; ✗ <b>a little</b> — uncountable and cannot follow <i>very</i>."},{"id":"gv-kc-08-12","level":"kc","focus":"tense","q":"Since Nam started spending every evening at the game arcade, he ______ in maths.","options":["falls behind","fell behind","has fallen behind","had fallen behind"],"correct":2,"answer":"has fallen behind","vi":"Từ khi Nam bắt đầu tối nào cũng ở tiệm game, cậu ấy đã bị tụt lại môn toán.","explanation":"Present perfect: <b>since + past starting point</b> describes a situation that began then and continues now, so we use <b>has fallen behind</b>. ✗ <b>falls behind</b> — present simple is for habits, not a change since a point in the past; ✗ <b>fell behind</b> — past simple would cut the link to now that <i>since</i> creates; ✗ <b>had fallen behind</b> — past perfect needs a later past event to be earlier than."},{"id":"gv-kc-08-13","level":"kc","focus":"gerund-infinitive","q":"Nam remembers ______ his wallet on the shop counter, but now it isn't there.","options":["to leave","leaving","leave","left"],"correct":1,"answer":"leaving","vi":"Nam nhớ là đã để ví trên quầy cửa hàng, nhưng giờ nó không còn ở đó nữa.","explanation":"Gerund vs infinitive: <b>remember + -ing</b> is a memory of something already done, and the clue <b>now it isn't there</b> shows he is recalling leaving it. ✗ <b>to leave</b> — <i>remember to do</i> means not forgetting a future task; ✗ <b>leave</b> — <i>remember</i> is not followed by a bare infinitive; ✗ <b>left</b> — a past form cannot follow <i>remember</i> without <i>that he had</i>."},{"id":"gv-kc-08-14","level":"kc","focus":"idiom","q":"I didn't want to go to the concert, but Lan ______ and I ended up buying a ticket.","options":["pulled my leg","caught my eye","twisted my arm","held my hand"],"correct":2,"answer":"twisted my arm","vi":"Tôi không muốn đi xem hòa nhạc, nhưng Lan cứ nài ép nên cuối cùng tôi cũng mua vé.","explanation":"Idiom: I didn't want to go but <b>ended up buying a ticket</b>, so Lan persuaded me against my will: <b>twisted my arm</b>. ✗ <b>pulled my leg</b> — joked with me, teased me; ✗ <b>caught my eye</b> — attracted my attention; ✗ <b>held my hand</b> — supported me closely through something."},{"id":"gv-kc-08-15","level":"kc","focus":"linking","q":"Set your alarm tonight; ______, you will miss the early bus to the museum.","options":["otherwise","therefore","besides","although"],"correct":0,"answer":"otherwise","vi":"Tối nay nhớ đặt báo thức, nếu không bạn sẽ lỡ chuyến xe buýt sớm đi bảo tàng.","explanation":"Linking word: <b>otherwise</b> means 'if you don't do that', so no alarm → <b>you will miss the bus</b>. ✗ <b>therefore</b> — shows a result of the first sentence, but missing the bus is not the result of setting an alarm; ✗ <b>besides</b> — adds an extra point, not a warning; ✗ <b>although</b> — introduces a contrast clause and cannot stand after a semicolon and comma."},{"id":"gv-kc-08-16","level":"kc","focus":"word-choice","q":"The school ______ ends next week, so the swimming pool will be full of students.","options":["period","break","lesson","term"],"correct":3,"answer":"term","vi":"Học kỳ sắp kết thúc vào tuần tới nên bể bơi sẽ đầy học sinh.","explanation":"Word choice: the part of the school year that <b>ends next week</b> before a holiday is the <b>term</b>. ✗ <b>period</b> — one lesson slot in the timetable, under an hour; ✗ <b>break</b> — the short rest between lessons; ✗ <b>lesson</b> — a single class, not a part of the year."},{"id":"gv-kc-08-17","level":"kc","focus":"phrasal-verb","q":"The bookshop has ______ plastic bags, so remember to bring your own.","options":["done up","done away with","done without","done in"],"correct":1,"answer":"done away with","vi":"Hiệu sách đã bỏ hẳn túi ni lông, nên nhớ mang túi của mình theo.","explanation":"Phrasal verb: the shop has stopped using plastic bags, so <b>remember to bring your own</b>; <b>do away with</b> = get rid of, abolish. ✗ <b>done up</b> — fasten, or repair and decorate; ✗ <b>done without</b> — manage without something (the shop is not managing without bags, it has removed them); ✗ <b>done in</b> — exhaust or tire someone out."},{"id":"gv-kc-08-18","level":"kc","focus":"conditional","q":"If I ______ more pocket money, I would buy that second-hand guitar.","options":["have","had","would have","have had"],"correct":1,"answer":"had","vi":"Nếu tôi có nhiều tiền tiêu vặt hơn, tôi sẽ mua cây đàn ghi-ta cũ đó.","explanation":"Second conditional: <b>would buy</b> in the main clause signals an unreal present, so the if-clause takes past simple <b>had</b>. ✗ <b>have</b> — present simple makes a first conditional, which needs <i>will buy</i>; ✗ <b>would have</b> — <i>would</i> does not go in the if-clause; ✗ <b>have had</b> — present perfect is not used in conditional if-clauses of this type."},{"id":"gv-kc-08-19","level":"kc","focus":"collocation","q":"Lan ______ chess with her grandfather every Sunday afternoon.","options":["plays","does","goes","makes"],"correct":0,"answer":"plays","vi":"Chiều Chủ nhật nào Lan cũng chơi cờ vua với ông.","explanation":"Collocation: games with rules and a winner take <b>play</b>: <b>play chess</b>. ✗ <b>does</b> — <i>do</i> goes with activities like homework, yoga or karate; ✗ <b>goes</b> — <i>go</i> goes with -ing sports like swimming or cycling; ✗ <b>makes</b> — <i>make</i> does not collocate with games."},{"id":"gv-kc-08-20","level":"kc","focus":"agreement","q":"Either Nam or his sister ______ going to buy the tickets this afternoon.","options":["are","am","be","is"],"correct":3,"answer":"is","vi":"Hoặc Nam hoặc chị của cậu ấy sẽ đi mua vé chiều nay.","explanation":"Subject–verb agreement: with <b>either… or</b> the verb agrees with the nearer subject, <b>his sister</b> (singular), so <b>is</b>. ✗ <b>are</b> — plural, but <i>either… or</i> does not add the subjects together; ✗ <b>am</b> — only for <i>I</i>; ✗ <b>be</b> — a bare infinitive cannot be the main verb of the sentence."},{"id":"gv-kc-08-21","level":"kc","focus":"participle","q":"The novel ______ by our English teacher turned out to be much funnier than I expected.","options":["recommending","to recommend","recommend","recommended"],"correct":3,"answer":"recommended","vi":"Cuốn tiểu thuyết được cô giáo tiếng Anh giới thiệu hóa ra vui hơn tôi tưởng nhiều.","explanation":"Reduced relative clause: the novel <b>(which was) recommended by our English teacher</b> is passive, so the past participle <b>recommended</b> fits; <b>by</b> is the clue. ✗ <b>recommending</b> — active, would mean the novel itself recommends something; ✗ <b>to recommend</b> — an infinitive here would mean 'to be recommended in the future'; ✗ <b>recommend</b> — a bare verb cannot follow a noun as a modifier."},{"id":"gv-kc-08-22","level":"kc","focus":"word-choice","q":"Nam can't go to football practice tonight because he has too much ______ to finish.","options":["classwork","housework","homework","paperwork"],"correct":2,"answer":"homework","vi":"Tối nay Nam không đi tập bóng đá được vì có quá nhiều bài tập về nhà phải làm.","explanation":"Word choice: school work Nam must <b>finish tonight</b> at home is <b>homework</b>. ✗ <b>classwork</b> — work done during lessons in class; ✗ <b>housework</b> — cleaning, washing and cooking at home; ✗ <b>paperwork</b> — office forms and documents."},{"id":"gv-kc-08-23","level":"kc","focus":"pronoun","q":"Nam and Lan often lend ______ their favourite comic books.","options":["each other","themselves","ourselves","yourselves"],"correct":0,"answer":"each other","vi":"Nam và Lan thường cho nhau mượn những cuốn truyện tranh yêu thích.","explanation":"Reciprocal pronoun: <b>Nam and Lan</b> lend to one another, so <b>each other</b>. ✗ <b>themselves</b> — reflexive, would mean each lends to himself or herself; ✗ <b>ourselves</b> — refers to <i>we</i>, not the third-person subject; ✗ <b>yourselves</b> — refers to <i>you</i>, not <i>Nam and Lan</i>."},{"id":"gv-kc-08-24","level":"kc","focus":"question-tag","q":"Let's watch the new animated film on Saturday, ______?","options":["will we","do we","don't we","shall we"],"correct":3,"answer":"shall we","vi":"Thứ Bảy mình đi xem bộ phim hoạt hình mới nhé?","explanation":"Question tag: a suggestion with <b>Let's</b> always takes <b>shall we</b>. ✗ <b>will we</b> — <i>will you</i> is the tag for an imperative, and <i>will we</i> fits no pattern; ✗ <b>do we</b> — tags a present simple statement, and <i>Let's</i> is not a statement; ✗ <b>don't we</b> — the same, and positive statements take negative tags anyway."},{"id":"gv-kc-08-25","level":"kc","focus":"tense","q":"Nam ______ a comic book in bed when the lights suddenly went out.","options":["has read","was reading","reads","has been reading"],"correct":1,"answer":"was reading","vi":"Nam đang đọc truyện tranh trên giường thì đèn bỗng nhiên tắt.","explanation":"Past continuous: a longer action in progress (<b>was reading</b>) is interrupted by a short past action, <b>the lights suddenly went out</b>. ✗ <b>has read</b> — present perfect cannot combine with a finished past event marked by <i>when</i>; ✗ <b>reads</b> — present simple is for habits, not a scene in the past; ✗ <b>has been reading</b> — present perfect continuous links to now, but the story is in the past."},{"id":"gv-kc-09-1","level":"kc","focus":"tense","q":"Lan ______ the road when a motorbike suddenly pulled out in front of her.","options":["crossed","was crossing","has crossed","had been crossing"],"correct":1,"answer":"was crossing","vi":"Lan đang băng qua đường thì một chiếc xe máy bất ngờ lao ra trước mặt cô.","explanation":"Past continuous <b>was crossing</b>: a longer action in progress is interrupted by a short past-simple action after <b>when</b> (<b>suddenly pulled out</b>). ✗ <b>crossed</b> — past simple would make the crossing finish before the motorbike appeared, so nothing is interrupted; ✗ <b>has crossed</b> — present perfect cannot sit in a story told in the past (<i>pulled out</i>); ✗ <b>had been crossing</b> — past perfect continuous puts the crossing before an earlier past point, but the two events happen at the same moment."},{"id":"gv-kc-09-2","level":"kc","focus":"word-choice","q":"The doctor said Nam should eat smaller ______ at dinner if he wants to lose weight.","options":["ingredients","flavours","portions","recipes"],"correct":2,"answer":"portions","vi":"Bác sĩ nói Nam nên ăn những khẩu phần nhỏ hơn vào bữa tối nếu muốn giảm cân.","explanation":"A <b>portion</b> is the amount of food served to one person, so eating <b>smaller portions</b> is how you <b>lose weight</b>. ✗ <b>ingredients</b> — the things a dish is made from; you don't eat 'smaller' ones; ✗ <b>flavours</b> — tastes, not amounts of food; ✗ <b>recipes</b> — sets of cooking instructions, which you follow, not eat."},{"id":"gv-kc-09-3","level":"kc","focus":"collocation","q":"You should ______ an appointment with the dentist before the holiday starts.","options":["make","do","take","put"],"correct":0,"answer":"make","vi":"Bạn nên đặt lịch hẹn với nha sĩ trước khi kỳ nghỉ bắt đầu.","explanation":"Collocation: you <b>make an appointment</b> (arrange a fixed time to see someone). ✗ <b>do</b> — <i>do</i> goes with tasks (<i>do homework</i>), never with <i>appointment</i>; ✗ <b>take</b> — you <i>take</i> a test or a photo, not an appointment; ✗ <b>put</b> — needs a place or an object (<i>put it down</i>) and has no meaning with <i>appointment</i>."},{"id":"gv-kc-09-4","level":"kc","focus":"phrasal-verb","q":"The forum's rules are strict, so nobody can ______ posting rude comments for long.","options":["get on with","get round to","get down to","get away with"],"correct":3,"answer":"get away with","vi":"Quy định của diễn đàn rất nghiêm, nên không ai có thể đăng bình luận thô lỗ mà thoát được lâu.","explanation":"<b>Get away with</b> = do something wrong without being punished; the clue is <b>strict rules</b> and <b>rude comments</b>. ✗ <b>get on with</b> — continue doing (or have a good relationship with); ✗ <b>get round to</b> — finally find time to do; ✗ <b>get down to</b> — start working seriously on. None of these involves escaping punishment."},{"id":"gv-kc-09-5","level":"kc","focus":"relative","q":"The doctor ______ treated my brother has just moved to a hospital in Hue.","options":["which","who","whose","whom"],"correct":1,"answer":"who","vi":"Vị bác sĩ đã chữa cho anh tôi vừa chuyển đến một bệnh viện ở Huế.","explanation":"The relative pronoun is the <b>subject</b> of <b>treated</b> (no other subject follows it) and refers to a person, <b>the doctor</b>, so it must be <b>who</b>. ✗ <b>whom</b> — object form only; here the pronoun does the treating; ✗ <b>whose</b> — shows possession and needs a noun after it (<i>whose patient</i>); ✗ <b>which</b> — for things, not people."},{"id":"gv-kc-09-6","level":"kc","focus":"idiom","q":"Since Grandma came home from hospital, everyone has been ______ around her so as not to upset her.","options":["walking on eggshells","walking on air","walking on thin ice","walking on water"],"correct":0,"answer":"walking on eggshells","vi":"Từ khi bà đi viện về, cả nhà ai cũng phải rón rén giữ ý quanh bà để không làm bà buồn.","explanation":"<b>Walk on eggshells</b> = be very careful not to upset someone; the clue is <b>so as not to upset her</b>. ✗ <b>walking on air</b> — feeling extremely happy; ✗ <b>walking on thin ice</b> — being in a risky situation yourself; ✗ <b>walking on water</b> — doing the impossible. Only <i>eggshells</i> is about handling another person gently."},{"id":"gv-kc-09-7","level":"kc","focus":"modal","q":"You ______ a taxi from the airport; the hotel bus was free for all guests.","options":["mustn't have taken","can't have taken","needn't have taken","must have taken"],"correct":2,"answer":"needn't have taken","vi":"Bạn đã không cần phải đi taxi từ sân bay; xe buýt của khách sạn miễn phí cho mọi khách.","explanation":"<b>Needn't have + past participle</b> = you did it, but it was not necessary; the clue is <b>the hotel bus was free</b>, so the taxi was a waste. ✗ <b>must have taken</b> — a confident guess that you did take one, not a comment on necessity; ✗ <b>can't have taken</b> — a guess that you did not take one, which contradicts the sentence; ✗ <b>mustn't have taken</b> — <i>mustn't</i> is not used for past deduction or past necessity."},{"id":"gv-kc-09-8","level":"kc","focus":"word-choice","q":"The waiter brought us the ______ so that we could choose what to order.","options":["dish","dessert","snack","menu"],"correct":3,"answer":"menu","vi":"Người phục vụ mang thực đơn ra để chúng tôi chọn món.","explanation":"The <b>menu</b> is the list you <b>choose</b> from before you <b>order</b>. ✗ <b>dish</b> — one prepared food item, something you order, not choose from; ✗ <b>dessert</b> — the sweet course at the end of a meal; ✗ <b>snack</b> — a small quick bite between meals. All three are food, not a list of food."},{"id":"gv-kc-09-9","level":"kc","focus":"tense","q":"Nam looks tired because he ______ on the phone since eight o'clock this morning.","options":["has been talking","is talking","was talking","talks"],"correct":0,"answer":"has been talking","vi":"Nam trông mệt mỏi vì cậu ấy nói chuyện điện thoại từ tám giờ sáng đến giờ.","explanation":"Present perfect continuous <b>has been talking</b>: an action that began in the past (<b>since eight o'clock</b>) and continues to now, with a visible present result (<b>looks tired</b>). ✗ <b>is talking</b> — present continuous describes only now and cannot take <i>since</i>; ✗ <b>was talking</b> — past continuous means the call is over, but he is still tired from an ongoing one; ✗ <b>talks</b> — present simple is for habits, not an action lasting since a specific time."},{"id":"gv-kc-09-10","level":"kc","focus":"article-quantifier","q":"There were very ______ tourists on the beach in the early morning, so it was wonderfully peaceful.","options":["a few","few","little","a little"],"correct":1,"answer":"few","vi":"Sáng sớm trên bãi biển có rất ít khách du lịch, nên nơi đó yên bình tuyệt vời.","explanation":"<b>Tourists</b> is plural countable, and the meaning is 'almost none' (it was <b>peaceful</b>), so <b>few</b>; <b>very</b> also confirms it, since <i>very</i> goes only before <i>few</i>. ✗ <b>a few</b> — means 'some' and cannot follow <i>very</i>; ✗ <b>little</b> — for uncountable nouns (<i>little time</i>); ✗ <b>a little</b> — uncountable and positive ('some'), both wrong here."},{"id":"gv-kc-09-11","level":"kc","focus":"collocation","q":"Remember to ______ a photo of your passport before you travel abroad.","options":["make","do","catch","take"],"correct":3,"answer":"take","vi":"Nhớ chụp một tấm ảnh hộ chiếu của bạn trước khi đi nước ngoài nhé.","explanation":"Collocation: you <b>take a photo</b>. ✗ <b>make</b> — you <i>make</i> a copy or a film, but not a photo; ✗ <b>do</b> — goes with tasks (<i>do the shopping</i>), not with <i>photo</i>; ✗ <b>catch</b> — you <i>catch</i> a bus or a cold; with a photo it would mean nothing."},{"id":"gv-kc-09-12","level":"kc","focus":"word-choice","q":"Bún bò Huế is a famous ______ of central Vietnam, which every visitor should try.","options":["ingredient","diet","speciality","flavour"],"correct":2,"answer":"speciality","vi":"Bún bò Huế là một đặc sản nổi tiếng của miền Trung Việt Nam mà du khách nào cũng nên thử.","explanation":"A <b>speciality</b> is a food a place is <b>famous</b> for, which fits <b>of central Vietnam</b> and <b>every visitor should try</b>. ✗ <b>ingredient</b> — one component of a dish, but bún bò Huế is a whole dish; ✗ <b>diet</b> — what a person regularly eats, not a named dish; ✗ <b>flavour</b> — a taste, not something a region is famous for making."},{"id":"gv-kc-09-13","level":"kc","focus":"conditional","q":"If I ______ my phone charger at home, I could show you the holiday photos now.","options":["hadn't left","didn't leave","haven't left","wouldn't leave"],"correct":0,"answer":"hadn't left","vi":"Nếu tôi không để quên sạc điện thoại ở nhà thì giờ tôi có thể cho bạn xem ảnh kỳ nghỉ rồi.","explanation":"<b>Mixed conditional</b>: a past condition (leaving the charger at home) with a present result (<b>could show you … now</b>), so the if-clause takes the past perfect <b>hadn't left</b>. ✗ <b>didn't leave</b> — past simple would make a second conditional about a present or future situation, but the leaving already happened; ✗ <b>haven't left</b> — present perfect does not appear in unreal conditions; ✗ <b>wouldn't leave</b> — <i>would</i> belongs in the result clause, never after <i>if</i>."},{"id":"gv-kc-09-14","level":"kc","focus":"phrasal-verb","q":"Grandpa finds it hard to ______ all the new apps his grandchildren use.","options":["keep on with","keep up with","keep out of","keep away from"],"correct":1,"answer":"keep up with","vi":"Ông thấy khó theo kịp tất cả những ứng dụng mới mà các cháu dùng.","explanation":"<b>Keep up with</b> = stay at the same level as something changing fast, the clue being <b>all the new apps</b>. ✗ <b>keep on with</b> — continue doing something you have started; ✗ <b>keep out of</b> — stay away from trouble or a place; ✗ <b>keep away from</b> — avoid going near. Only <i>keep up with</i> is about following change."},{"id":"gv-kc-09-15","level":"kc","focus":"tense","q":"While I ______ the hotel website, the internet connection suddenly dropped.","options":["checked","have checked","was checking","am checking"],"correct":2,"answer":"was checking","vi":"Trong lúc tôi đang xem trang web của khách sạn thì kết nối mạng bỗng nhiên bị mất.","explanation":"Past continuous <b>was checking</b>: <b>while</b> introduces a longer action in progress that is interrupted by a short past-simple event (<b>suddenly dropped</b>). ✗ <b>checked</b> — past simple makes two finished actions in sequence, not one interrupting the other; ✗ <b>have checked</b> — present perfect cannot combine with a past-simple main clause; ✗ <b>am checking</b> — present continuous clashes with the past time of <i>dropped</i>."},{"id":"gv-kc-09-16","level":"kc","focus":"relative","q":"The hotel, the rooms ______ all face the sea, is fully booked until August.","options":["whose","of whom","in which","of which"],"correct":3,"answer":"of which","vi":"Khách sạn đó, với các phòng đều hướng ra biển, đã kín chỗ cho đến tận tháng Tám.","explanation":"Possession placed after the noun for a thing takes <b>of which</b>: <i>the rooms of which</i> = <i>whose rooms</i> (the hotel's rooms). ✗ <b>whose</b> — must come <b>before</b> the noun (<i>whose rooms all face</i>), not after it; ✗ <b>of whom</b> — for people, but a hotel is a thing; ✗ <b>in which</b> — would mean the rooms are inside something, not that they belong to the hotel."},{"id":"gv-kc-09-17","level":"kc","focus":"gerund-infinitive","q":"The receptionist reminded us ______ our room keys before we left the hotel.","options":["handing in","to hand in","hand in","to handing in"],"correct":1,"answer":"to hand in","vi":"Lễ tân nhắc chúng tôi nộp lại chìa khóa phòng trước khi rời khách sạn.","explanation":"<b>Remind somebody to do</b> something takes an object + <b>to-infinitive</b>: <b>reminded us to hand in</b>. ✗ <b>handing in</b> — the -ing form follows verbs like <i>suggest</i> or <i>avoid</i>, not <i>remind + object</i>; ✗ <b>hand in</b> — the bare infinitive follows <i>make</i>/<i>let</i>, not <i>remind</i>; ✗ <b>to handing in</b> — <i>to</i> + -ing only works when <i>to</i> is a preposition (<i>look forward to</i>), which it is not here."},{"id":"gv-kc-09-18","level":"kc","focus":"idiom","q":"My patience is beginning to ______ — the hostel Wi-Fi has stopped working for the third time today.","options":["wear thin","fall flat","go blank","run wild"],"correct":0,"answer":"wear thin","vi":"Tôi bắt đầu hết kiên nhẫn rồi — Wi-Fi ở nhà nghỉ đã hỏng lần thứ ba trong ngày hôm nay.","explanation":"When your patience <b>wears thin</b>, you gradually lose it; the clue is <b>for the third time today</b>. ✗ <b>fall flat</b> — a joke or plan fails to get the effect wanted; ✗ <b>go blank</b> — your mind suddenly remembers nothing; ✗ <b>run wild</b> — your imagination or children get out of control. None of these goes with <i>patience</i>."},{"id":"gv-kc-09-19","level":"kc","focus":"word-choice","q":"The soup had a strong ______ of ginger, which really helped my sore throat.","options":["texture","appetite","portion","flavour"],"correct":3,"answer":"flavour","vi":"Món súp có vị gừng rất đậm, và điều đó thực sự giúp cổ họng đau của tôi dễ chịu hơn.","explanation":"The <b>flavour</b> of a food is its particular taste, so a soup can have a <b>strong flavour of ginger</b>. ✗ <b>texture</b> — how food feels in the mouth (smooth, crunchy), not what it tastes of; ✗ <b>appetite</b> — a person's desire to eat, not a quality of soup; ✗ <b>portion</b> — the amount served, not the taste."},{"id":"gv-kc-09-20","level":"kc","focus":"linking","q":"My sister loves crowded night markets, ______ I prefer quiet cafés by the river.","options":["despite","so that","whereas","otherwise"],"correct":2,"answer":"whereas","vi":"Chị tôi thích những khu chợ đêm đông đúc, trong khi tôi lại thích những quán cà phê yên tĩnh bên sông.","explanation":"<b>Whereas</b> links two full clauses that <b>contrast</b> two people: sister loves crowded markets vs. I prefer quiet cafés. ✗ <b>despite</b> — a preposition, so it cannot be followed by a clause with a subject and verb; ✗ <b>so that</b> — gives a purpose, but my preference is not the purpose of hers; ✗ <b>otherwise</b> — means 'if not', which makes no sense between two likes."},{"id":"gv-kc-09-21","level":"kc","focus":"modal","q":"Passengers ______ switch their phones to flight mode before the plane takes off; it is an airline rule.","options":["must","might","could","would"],"correct":0,"answer":"must","vi":"Hành khách phải chuyển điện thoại sang chế độ máy bay trước khi máy bay cất cánh; đó là quy định của hãng.","explanation":"A rule or strong obligation takes <b>must</b>; the clue is <b>it is an airline rule</b>. ✗ <b>might</b> — only a possibility, not an obligation; ✗ <b>could</b> — ability or possibility, not something required; ✗ <b>would</b> — hypothetical or past habit, not a present rule."},{"id":"gv-kc-09-22","level":"kc","focus":"collocation","q":"Lan ______ a bad cold on the plane and spent the first two days of the holiday in bed.","options":["took","caught","made","held"],"correct":1,"answer":"caught","vi":"Lan bị cảm nặng trên máy bay và nằm giường suốt hai ngày đầu của kỳ nghỉ.","explanation":"Collocation: you <b>catch a cold</b> (become ill with one). ✗ <b>took</b> — you <i>take</i> medicine or a break, not an illness; ✗ <b>made</b> — you <i>make</i> things, and a cold is not something you create; ✗ <b>held</b> — you <i>hold</i> objects or meetings, not illnesses."},{"id":"gv-kc-09-23","level":"kc","focus":"inversion","q":"______ had we boarded the plane when the baby behind us started crying.","options":["No sooner","Not until","Hardly","Only when"],"correct":2,"answer":"Hardly","vi":"Chúng tôi vừa mới lên máy bay thì em bé ngồi sau bắt đầu khóc.","explanation":"Inversion <b>Hardly had we boarded … when …</b>: <b>Hardly</b> + past perfect pairs with <b>when</b> for an event that happened almost immediately. ✗ <b>No sooner</b> — must pair with <b>than</b>, not <i>when</i>; ✗ <b>Not until</b> — needs a time clause first (<i>Not until we boarded did …</i>), and the inversion comes in the main clause; ✗ <b>Only when</b> — likewise needs a clause before the inversion, not <i>had we</i> directly."},{"id":"gv-kc-09-24","level":"kc","focus":"word-choice","q":"The doctor put Grandpa on a low-salt ______ after his blood pressure test.","options":["meal","dish","menu","diet"],"correct":3,"answer":"diet","vi":"Sau khi đo huyết áp, bác sĩ cho ông theo chế độ ăn ít muối.","explanation":"A <b>diet</b> is the food a person regularly eats, often for health, so a doctor puts a patient <b>on a low-salt diet</b> after a <b>blood pressure test</b>. ✗ <b>meal</b> — one occasion of eating, not a long-term plan; ✗ <b>dish</b> — one prepared food item; ✗ <b>menu</b> — a restaurant's list of food, not a health plan."},{"id":"gv-kc-09-25","level":"kc","focus":"tense","q":"When we finally reached the gate, the plane ______ already.","options":["left","had left","has left","was leaving"],"correct":1,"answer":"had left","vi":"Khi cuối cùng chúng tôi tới được cửa ra máy bay thì máy bay đã cất cánh rồi.","explanation":"Past perfect <b>had left</b>: the plane's departure happened <b>before</b> the past moment of <b>reached the gate</b>, and <b>already</b> confirms the earlier action. ✗ <b>left</b> — past simple would make the two events happen at the same time or in order, but the plane was gone first; ✗ <b>has left</b> — present perfect clashes with the past-simple <i>reached</i>; ✗ <b>was leaving</b> — past continuous means it was still leaving as we arrived, but <i>already</i> says it was gone."},{"id":"gv-kc-10-1","level":"kc","focus":"tense","q":"Look! The cat ______ on the kitchen table again.","options":["sleeps","is sleeping","slept","has slept"],"correct":1,"answer":"is sleeping","vi":"Nhìn kìa! Con mèo lại đang ngủ trên bàn bếp.","explanation":"Present continuous for an action happening now: <b>Look!</b> tells us the cat is on the table at this moment, so <b>is sleeping</b> fits. ✗ <b>sleeps</b> — present simple is for habits, not what we can see as we speak; ✗ <b>slept</b> — past simple puts the action in the finished past; ✗ <b>has slept</b> — present perfect reports a completed action, not one in progress."},{"id":"gv-kc-10-2","level":"kc","focus":"word-choice","q":"The kitten ______ its paw on a piece of broken glass in the garden.","options":["bruised","sprained","cut","strained"],"correct":2,"answer":"cut","vi":"Con mèo con bị đứt chân vì một mảnh thủy tinh vỡ trong vườn.","explanation":"Word choice for injuries: <b>broken glass</b> has a sharp edge, so it makes a <b>cut</b> (an opening in the skin). ✗ <b>bruised</b> — a bruise is a dark mark from a knock, not from a sharp edge; ✗ <b>sprained</b> — you sprain a joint by twisting it; ✗ <b>strained</b> — you strain a muscle by overusing it. Neither comes from glass."},{"id":"gv-kc-10-3","level":"kc","focus":"idiom","q":"Everyone expects Tuan's dog to ______ at Sunday's race because it is much faster than the others.","options":["run out of steam","win by a whisker","lose its way","win hands down"],"correct":3,"answer":"win hands down","vi":"Ai cũng nghĩ chó của Tuấn sẽ thắng dễ dàng ở cuộc đua hôm Chủ nhật vì nó nhanh hơn hẳn những con khác.","explanation":"Idiom for winning: <b>much faster than the others</b> means an easy victory, so <b>win hands down</b> (win very easily) fits. ✗ <b>run out of steam</b> — lose energy and slow down; ✗ <b>win by a whisker</b> — win by a tiny margin, the opposite of an easy win; ✗ <b>lose its way</b> — go in the wrong direction, so no win at all."},{"id":"gv-kc-10-4","level":"kc","focus":"collocation","q":"You should ______ your promise to visit Grandma this weekend, or she will be very upset.","options":["hold","stay","keep","save"],"correct":2,"answer":"keep","vi":"Con nên giữ lời hứa đi thăm bà vào cuối tuần này, không thì bà sẽ buồn lắm.","explanation":"Collocation with <b>promise</b>: the fixed verb is <b>keep a promise</b> (do what you said you would), and <b>or she will be very upset</b> shows that breaking it is the danger. ✗ <b>hold</b> — you hold a meeting or hold on, not a promise; ✗ <b>stay</b> — cannot take 'promise' as an object; ✗ <b>save</b> — you save money or time, not a promise."},{"id":"gv-kc-10-5","level":"kc","focus":"phrasal-verb","q":"Don't ______ your teammates by missing the school cooking contest on Saturday.","options":["turn down","let off","let down","put down"],"correct":2,"answer":"let down","vi":"Đừng làm đồng đội thất vọng bằng cách bỏ lỡ cuộc thi nấu ăn của trường vào thứ Bảy.","explanation":"Phrasal verb: <b>let somebody down</b> = disappoint someone, which is what <b>missing the contest</b> would do to teammates. ✗ <b>turn down</b> — refuse an offer or request, not something you do to people who rely on you; ✗ <b>let off</b> — not punish someone; ✗ <b>put down</b> — criticise someone, or place something on a surface."},{"id":"gv-kc-10-6","level":"kc","focus":"relative","q":"Nobody could explain the reason ______ the school swimming pool stayed closed all summer.","options":["which","where","when","why"],"correct":3,"answer":"why","vi":"Không ai giải thích được lý do vì sao bể bơi của trường đóng cửa suốt cả mùa hè.","explanation":"Relative adverb after <b>the reason</b>: the fixed pattern is <b>the reason why</b> + clause. ✗ <b>which</b> — a relative pronoun must be the subject or object of its clause, but 'the pool stayed closed' already has its subject and needs no object; ✗ <b>where</b> — follows a place noun; ✗ <b>when</b> — follows a time noun."},{"id":"gv-kc-10-7","level":"kc","focus":"word-choice","q":"After eating the fish that had been left out in the sun, Nam felt ______ and had to lie down.","options":["sore","bruised","hurt","sick"],"correct":3,"answer":"sick","vi":"Sau khi ăn con cá bị để ngoài nắng, Nam thấy buồn nôn và phải nằm nghỉ.","explanation":"Word choice for illness: <b>fish left out in the sun</b> gives you food poisoning, so Nam felt <b>sick</b> (ill, wanting to vomit). ✗ <b>sore</b> — a body part is sore (painful), not the whole person after bad food; ✗ <b>bruised</b> — marked by a knock; ✗ <b>hurt</b> — injured, or emotionally upset, not ill."},{"id":"gv-kc-10-8","level":"kc","focus":"modal","q":"The bowl is empty — the cat ______ all the fish while we were out.","options":["must have eaten","should have eaten","needn't have eaten","can't have eaten"],"correct":0,"answer":"must have eaten","vi":"Cái bát trống không — chắc chắn con mèo đã ăn hết cá lúc chúng ta đi vắng.","explanation":"Modal of past deduction: <b>the bowl is empty</b> is the evidence, so <b>must have eaten</b> (I'm sure it happened) fits. ✗ <b>can't have eaten</b> — the opposite deduction (I'm sure it didn't), contradicted by the empty bowl; ✗ <b>should have eaten</b> — criticises something that did not happen; ✗ <b>needn't have eaten</b> — it happened but was unnecessary; neither is a guess from evidence."},{"id":"gv-kc-10-9","level":"kc","focus":"preposition","q":"Parrots are famous ______ copying the sounds of human speech.","options":["of","about","for","with"],"correct":2,"answer":"for","vi":"Vẹt nổi tiếng vì bắt chước được âm thanh tiếng người.","explanation":"Adjective + preposition: <b>famous for</b> + the thing someone is known for (<b>copying human speech</b>). ✗ <b>of</b> — 'famous of' does not exist (compare 'proud of'); ✗ <b>about</b> — 'famous about' does not exist (compare 'worried about'); ✗ <b>with</b> — 'famous with' is not used (compare 'popular with')."},{"id":"gv-kc-10-10","level":"kc","focus":"tense","q":"My grandmother ______ the same soup recipe since she was a little girl.","options":["uses","used","is using","has used"],"correct":3,"answer":"has used","vi":"Bà tôi đã dùng cùng một công thức nấu canh này từ khi bà còn là một cô bé.","explanation":"Present perfect with <b>since</b>: <b>since she was a little girl</b> marks the start of a period that continues to now, so <b>has used</b> fits. ✗ <b>uses</b> — present simple gives a habit but cannot combine with a 'since' starting point; ✗ <b>used</b> — past simple would mean she has stopped; ✗ <b>is using</b> — present continuous is for right now, not a period from childhood."},{"id":"gv-kc-10-11","level":"kc","focus":"word-choice","q":"Lan's ankle became ______ after she twisted it on the mountain trail.","options":["dizzy","swollen","hoarse","feverish"],"correct":1,"answer":"swollen","vi":"Cổ chân của Lan bị sưng lên sau khi cô ấy bị trẹo chân trên đường mòn lên núi.","explanation":"Word choice for a body part: a <b>twisted ankle</b> becomes <b>swollen</b> (bigger than normal). ✗ <b>dizzy</b> — a person feels dizzy (the room spins), not an ankle; ✗ <b>hoarse</b> — describes a rough, tired voice; ✗ <b>feverish</b> — describes a person with a high temperature."},{"id":"gv-kc-10-12","level":"kc","focus":"collocation","q":"Could you ______ the table while I finish the spring rolls?","options":["put","make","lay","do"],"correct":2,"answer":"lay","vi":"Con dọn bàn ăn giúp mẹ trong lúc mẹ làm nốt chả giò được không?","explanation":"Collocation: <b>lay the table</b> = put out the plates and chopsticks before a meal, the clue being <b>while I finish the spring rolls</b>. ✗ <b>put</b> — needs a place ('put the plates on the table'); ✗ <b>make</b> — you make a table only if you build it; ✗ <b>do</b> — 'do the table' is not a collocation (we do the dishes, the washing-up)."},{"id":"gv-kc-10-13","level":"kc","focus":"conditional","q":"Lan: Are we going to the beach tomorrow? / Nam: If the weather ______ fine, we'll take the dog with us.","options":["will be","is","was","would be"],"correct":1,"answer":"is","vi":"Lan: Mai mình đi biển chứ? / Nam: Nếu trời đẹp, mình sẽ dắt chó theo.","explanation":"First conditional: <b>tomorrow</b> and <b>we'll take</b> in the main clause show a real future condition, so the <b>if</b>-clause takes the present simple <b>is</b>. ✗ <b>will be</b> — 'will' is not used in the if-clause of a first conditional; ✗ <b>was</b> — past simple makes an unreal second conditional, which needs 'would' in the main clause; ✗ <b>would be</b> — 'would' belongs in the main clause, not after 'if'."},{"id":"gv-kc-10-14","level":"kc","focus":"idiom","q":"Planting ten trees is only ______ when a whole forest has been cut down.","options":["a drop in the ocean","a piece of cake","a storm in a teacup","a breath of fresh air"],"correct":0,"answer":"a drop in the ocean","vi":"Trồng mười cái cây chỉ như muối bỏ biển khi cả một khu rừng đã bị chặt.","explanation":"Idiom: <b>ten trees</b> against <b>a whole forest</b> is a tiny amount compared with what is needed — <b>a drop in the ocean</b>. ✗ <b>a piece of cake</b> — something very easy; ✗ <b>a storm in a teacup</b> — a big fuss about something unimportant; ✗ <b>a breath of fresh air</b> — something pleasantly new and different."},{"id":"gv-kc-10-15","level":"kc","focus":"article-quantifier","q":"There is only ______ rice left in the pot, so I'll cook some noodles as well.","options":["a few","many","a little","several"],"correct":2,"answer":"a little","vi":"Trong nồi chỉ còn một ít cơm, nên mình sẽ nấu thêm mì.","explanation":"Quantifier with an uncountable noun: <b>rice</b> has no plural, so <b>a little</b> (a small amount) fits, and <b>only</b> confirms it is a small amount. ✗ <b>a few</b> — only with plural countable nouns (a few grains); ✗ <b>many</b> — plural countable only, and means a lot, clashing with 'only'; ✗ <b>several</b> — plural countable only."},{"id":"gv-kc-10-16","level":"kc","focus":"word-choice","q":"Mai has a bad ______, so she keeps coughing and sneezing in class.","options":["cold","ache","bruise","rash"],"correct":0,"answer":"cold","vi":"Mai bị cảm nặng nên cứ ho và hắt hơi liên tục trong lớp.","explanation":"Word choice for illness: <b>coughing and sneezing</b> are the symptoms of a <b>cold</b>. ✗ <b>ache</b> — a dull continuous pain, as in backache; ✗ <b>bruise</b> — a dark mark on the skin after a knock; ✗ <b>rash</b> — a patch of red spots on the skin. None of these makes you cough or sneeze."},{"id":"gv-kc-10-17","level":"kc","focus":"phrasal-verb","q":"Our old dog ______ peacefully last winter, and we buried him under the mango tree.","options":["passed out","gave away","passed by","passed away"],"correct":3,"answer":"passed away","vi":"Con chó già của chúng tôi đã qua đời thanh thản vào mùa đông năm ngoái, và chúng tôi chôn nó dưới gốc xoài.","explanation":"Phrasal verb: <b>passed away</b> is the gentle word for died, matching <b>we buried him</b>. ✗ <b>passed out</b> — fainted, lost consciousness; ✗ <b>gave away</b> — gave something to someone for free, and needs an object; ✗ <b>passed by</b> — went past a place."},{"id":"gv-kc-10-18","level":"kc","focus":"reported","q":"The vet said she ______ the problem with our rabbit's teeth the next day.","options":["will look into","looks into","would look into","has looked into"],"correct":2,"answer":"would look into","vi":"Bác sĩ thú y nói rằng hôm sau cô ấy sẽ xem xét vấn đề về răng của con thỏ nhà chúng tôi.","explanation":"Reported speech backshift: after <b>said</b>, and with <b>the next day</b> (reported 'tomorrow'), <b>will</b> becomes <b>would look into</b>. ✗ <b>will look into</b> — no backshift after a past reporting verb; ✗ <b>looks into</b> — present simple does not report a future plan; ✗ <b>has looked into</b> — present perfect clashes with 'said' and with 'the next day'."},{"id":"gv-kc-10-19","level":"kc","focus":"gerund-infinitive","q":"Nam: Shall we eat out tonight? / Lan: I'd rather ______ at home; I've bought some fresh prawns.","options":["cook","cooking","to cook","cooked"],"correct":0,"answer":"cook","vi":"Nam: Tối nay mình ra ngoài ăn nhé? / Lan: Tớ thích nấu ở nhà hơn; tớ mới mua ít tôm tươi.","explanation":"Verb form after <b>would rather</b>: it takes the bare infinitive, so <b>I'd rather cook</b>. ✗ <b>cooking</b> — the -ing form follows 'prefer', not 'would rather'; ✗ <b>to cook</b> — 'to' follows 'would prefer', not 'would rather'; ✗ <b>cooked</b> — a past form makes no sense after 'rather' for tonight's plan."},{"id":"gv-kc-10-20","level":"kc","focus":"tense","q":"When I got home from school, my dog ______ my new slippers to pieces.","options":["chews","has chewed","is chewing","had chewed"],"correct":3,"answer":"had chewed","vi":"Khi tôi đi học về thì con chó đã cắn nát đôi dép mới của tôi.","explanation":"Past perfect for the earlier of two past actions: <b>When I got home</b> is past simple, and the chewing happened <b>before</b> that, so <b>had chewed</b>. ✗ <b>chews</b> — present simple cannot follow a past time clause; ✗ <b>has chewed</b> — present perfect links to now, not to a past moment; ✗ <b>is chewing</b> — present continuous is for right now, not last afternoon."},{"id":"gv-kc-10-21","level":"kc","focus":"word-choice","q":"Minh has a terrible ______, so he can't chew the sticky rice cake his mother made.","options":["headache","toothache","earache","stomachache"],"correct":1,"answer":"toothache","vi":"Minh bị đau răng dữ dội nên không nhai được bánh chưng mẹ làm.","explanation":"Word choice for pains: <b>can't chew</b> points to the mouth, so <b>toothache</b>. ✗ <b>headache</b> — pain in the head, which does not stop you chewing; ✗ <b>earache</b> — pain in the ear; ✗ <b>stomachache</b> — pain in the stomach, which might stop you eating but not chewing."},{"id":"gv-kc-10-22","level":"kc","focus":"linking","q":"Nam loves spicy food, ______ his sister cannot eat even a little chilli.","options":["therefore","whereas","so that","because"],"correct":1,"answer":"whereas","vi":"Nam rất thích đồ ăn cay, trong khi chị của cậu ấy không ăn nổi dù chỉ một chút ớt.","explanation":"Linking word of contrast: <b>loves spicy food</b> and <b>cannot eat even a little chilli</b> are opposites, so <b>whereas</b>. ✗ <b>therefore</b> — introduces a result, and needs a full stop or semicolon before it; ✗ <b>so that</b> — introduces a purpose; ✗ <b>because</b> — gives a reason, but her dislike is not the cause of his love."},{"id":"gv-kc-10-23","level":"kc","focus":"passive","q":"Fresh vegetables ______ to the market every morning by farmers from the countryside.","options":["bring","brought","are bringing","are brought"],"correct":3,"answer":"are brought","vi":"Rau tươi được nông dân từ vùng quê chở đến chợ mỗi sáng.","explanation":"Present simple passive: the subject <b>vegetables</b> receives the action and <b>by farmers</b> names the agent, so <b>are brought</b>; <b>every morning</b> makes it present simple. ✗ <b>bring</b> — active, but vegetables cannot bring themselves; ✗ <b>brought</b> — past simple active, wrong voice and clashes with 'every morning'; ✗ <b>are bringing</b> — active continuous, wrong voice."},{"id":"gv-kc-10-24","level":"kc","focus":"comparison","q":"Lan: Why don't you buy frozen fish? It's cheaper. / Nam: Fresh fish tastes far ______ than frozen fish.","options":["best","better","good","well"],"correct":1,"answer":"better","vi":"Lan: Sao cậu không mua cá đông lạnh? Rẻ hơn mà. / Nam: Cá tươi ăn ngon hơn cá đông lạnh nhiều.","explanation":"Comparative: <b>than</b> requires a comparative, and the irregular comparative of <b>good</b> is <b>better</b>; <b>far</b> strengthens it. ✗ <b>best</b> — superlative, used with 'the', not 'than'; ✗ <b>good</b> — base form cannot go with 'than'; ✗ <b>well</b> — an adverb, but 'tastes' is a linking verb that takes an adjective, and it is not comparative anyway."},{"id":"gv-kc-10-25","level":"kc","focus":"collocation","q":"After dinner, Nam always ______ the washing-up so that his mother can rest.","options":["does","makes","takes","gets"],"correct":0,"answer":"does","vi":"Sau bữa tối, Nam luôn rửa bát để mẹ được nghỉ ngơi.","explanation":"Collocation: <b>do the washing-up</b> (wash the dishes), like do the cooking or do the dishes. ✗ <b>makes</b> — 'make' creates something (make a cake), not a chore; ✗ <b>takes</b> — you take a shower or a break, not the washing-up; ✗ <b>gets</b> — 'get the washing-up' would mean fetch it, not do it."},{"id":"gv-kc-11-1","level":"kc","focus":"tense","q":"Look! The lion dance team ______ down our street right now.","options":["comes","is coming","has come","came"],"correct":1,"answer":"is coming","vi":"Nhìn kìa! Đội múa lân đang đi xuống phố nhà mình ngay lúc này.","explanation":"<b>Look!</b> and <b>right now</b> mark an action in progress at the moment of speaking, so the present continuous <b>is coming</b> is needed. ✗ <b>comes</b> — present simple is for habits and facts, not what is happening now; ✗ <b>has come</b> — present perfect says the arrival is already finished, which clashes with <b>right now</b>; ✗ <b>came</b> — past simple puts the action in the past, not now."},{"id":"gv-kc-11-2","level":"kc","focus":"word-choice","q":"In the south of Viet Nam, the rainy ______ usually lasts from May to November.","options":["season","term","era","decade"],"correct":0,"answer":"season","vi":"Ở miền Nam Việt Nam, mùa mưa thường kéo dài từ tháng Năm đến tháng Mười Một.","explanation":"A <b>season</b> is a part of the year with its own weather — the rainy one here runs <b>from May to November</b>. ✗ <b>term</b> — a division of the school year, not of the weather; ✗ <b>era</b> — a long period of history; ✗ <b>decade</b> — a period of ten years, far longer than six months."},{"id":"gv-kc-11-3","level":"kc","focus":"collocation","q":"The forecast says a ______ wind will blow from the north tonight, so bring a jacket.","options":["heavy","thick","strong","large"],"correct":2,"answer":"strong","vi":"Dự báo nói tối nay sẽ có gió mạnh thổi từ phía bắc, nên hãy mang theo áo khoác.","explanation":"The collocation is a <b>strong wind</b> (or a light wind); the clue is <b>wind will blow</b>. ✗ <b>heavy</b> — goes with rain, snow and traffic, not wind; ✗ <b>thick</b> — describes fog, smoke or hair; ✗ <b>large</b> — describes size, and wind has no size."},{"id":"gv-kc-11-4","level":"kc","focus":"idiom","q":"Since Mai joined the school drama club, she has really ______ — she chats with everyone now.","options":["come to her senses","come down to earth","come full circle","come out of her shell"],"correct":3,"answer":"come out of her shell","vi":"Từ khi Mai vào câu lạc bộ kịch của trường, bạn ấy thật sự đã cởi mở hơn hẳn — giờ bạn ấy trò chuyện với tất cả mọi người.","explanation":"The clue <b>she chats with everyone now</b> shows Mai has stopped being shy: to <b>come out of your shell</b> is to become confident and sociable. ✗ <b>come to her senses</b> — to start thinking sensibly again; ✗ <b>come down to earth</b> — to become realistic after dreaming; ✗ <b>come full circle</b> — to return to where something started."},{"id":"gv-kc-11-5","level":"kc","focus":"phrasal-verb","q":"The tour guide ______ that the old market had been rebuilt after the fire.","options":["pointed out","pointed at","turned out","left out"],"correct":0,"answer":"pointed out","vi":"Hướng dẫn viên chỉ ra rằng khu chợ cũ đã được xây lại sau vụ cháy.","explanation":"<b>Pointed out that</b> + clause: to <b>point out</b> is to tell people a fact they may not have noticed. ✗ <b>pointed at</b> — to aim your finger at a thing, so it needs a noun, not a <b>that</b>-clause; ✗ <b>turned out</b> — 'proved to be', used with <b>it</b> (it turned out that…), not with a person as subject; ✗ <b>left out</b> — to omit; the guide is giving information, not leaving it out."},{"id":"gv-kc-11-6","level":"kc","focus":"modal","q":"The streets are completely dry this morning, so it ______ last night.","options":["must have rained","can't have rained","should have rained","might rain"],"correct":1,"answer":"can't have rained","vi":"Sáng nay đường phố khô ráo hoàn toàn, nên tối qua chắc chắn là không mưa.","explanation":"The evidence <b>completely dry</b> leads to a confident conclusion that something did NOT happen in the past: <b>can't have</b> + past participle. ✗ <b>must have rained</b> — a confident conclusion that it DID rain, the opposite of the evidence; ✗ <b>should have rained</b> — means rain was expected or desirable, not a deduction from evidence; ✗ <b>might rain</b> — refers to the future, but <b>last night</b> is past."},{"id":"gv-kc-11-7","level":"kc","focus":"word-choice","q":"There will be a fifteen-minute ______ between the two water-puppet shows, so you can buy some snacks.","options":["delay","recess","interval","era"],"correct":2,"answer":"interval","vi":"Sẽ có mười lăm phút giải lao giữa hai suất múa rối nước, nên bạn có thể mua chút đồ ăn vặt.","explanation":"A planned break <b>between the two shows</b> is an <b>interval</b>. ✗ <b>delay</b> — unplanned lateness, not a scheduled pause; ✗ <b>recess</b> — a break at school or in court, not in a theatre programme; ✗ <b>era</b> — a long period of history, not fifteen minutes."},{"id":"gv-kc-11-8","level":"kc","focus":"relative","q":"The bus ______ Nam takes to school every morning was twenty minutes late again today.","options":["who","whose","where","which"],"correct":3,"answer":"which","vi":"Chiếc xe buýt mà Nam đi học mỗi sáng hôm nay lại trễ hai mươi phút.","explanation":"The pronoun stands for a thing, <b>the bus</b>, and is the object of <b>takes</b> (Nam takes the bus), so <b>which</b> (or <b>that</b>) is used. ✗ <b>who</b> — only for people; ✗ <b>whose</b> — shows possession and must be followed by a noun (whose driver…); ✗ <b>where</b> — a relative adverb, so <b>takes</b> would be left without an object."},{"id":"gv-kc-11-9","level":"kc","focus":"article-quantifier","q":"Very ______ pupils remembered to bring their raincoats, so most of them got soaked on the way home.","options":["a few","little","few","a little"],"correct":2,"answer":"few","vi":"Rất ít học sinh nhớ mang áo mưa, nên hầu hết các em bị ướt sũng trên đường về nhà.","explanation":"<b>Few</b> + plural noun means 'almost no', stressing the small number — which is why <b>most of them got soaked</b> — and it is the only option that can follow <b>very</b>. ✗ <b>a few</b> — means 'some', a positive idea, and 'very a few' is impossible; ✗ <b>little</b> — for uncountable nouns, but <b>pupils</b> is plural countable; ✗ <b>a little</b> — also uncountable, and 'very a little' is impossible."},{"id":"gv-kc-11-10","level":"kc","focus":"tense","q":"Lan ______ the lantern festival three times since she moved to Hoi An.","options":["visited","had visited","has visited","visits"],"correct":2,"answer":"has visited","vi":"Từ khi chuyển đến Hội An, Lan đã đi lễ hội đèn lồng ba lần.","explanation":"<b>Since she moved</b> and <b>three times</b> count experience from a past point up to now, so the present perfect <b>has visited</b> is needed. ✗ <b>visited</b> — past simple needs a finished time (last year), not <b>since</b>; ✗ <b>had visited</b> — past perfect needs a later past event to be 'before', and there is none; ✗ <b>visits</b> — present simple describes a habit, not a total 'so far'."},{"id":"gv-kc-11-11","level":"kc","focus":"gerund-infinitive","q":"On the way to the beach, Dad stopped ______ some petrol at the station near the bridge.","options":["to buy","buying","buy","bought"],"correct":0,"answer":"to buy","vi":"Trên đường ra biển, bố dừng lại để mua xăng ở cây xăng gần cầu.","explanation":"<b>Stop to do</b> = pause in order to do something else: Dad stopped the car so that he could buy petrol (<b>on the way</b>, <b>at the station</b>). ✗ <b>buying</b> — <b>stop doing</b> means to give up an activity, so he would have quit buying petrol; ✗ <b>buy</b> — a bare infinitive cannot follow <b>stop</b>; ✗ <b>bought</b> — two past verbs cannot stand together without <b>and</b>."},{"id":"gv-kc-11-12","level":"kc","focus":"collocation","q":"Please ______ your seat belt before the coach pulls out of the station.","options":["tie","close","fix","fasten"],"correct":3,"answer":"fasten","vi":"Vui lòng thắt dây an toàn trước khi xe khách rời bến.","explanation":"The collocation is <b>fasten</b> (or do up) a <b>seat belt</b>, which has a buckle. ✗ <b>tie</b> — for shoelaces, ropes and knots, not a belt with a buckle; ✗ <b>close</b> — for doors, windows and lids; ✗ <b>fix</b> — means to repair or to attach firmly, not to buckle."},{"id":"gv-kc-11-13","level":"kc","focus":"word-choice","q":"Uncle Tam is always ______: his bus leaves the depot at exactly six every morning.","options":["temporary","punctual","recent","urgent"],"correct":1,"answer":"punctual","vi":"Bác Tâm lúc nào cũng đúng giờ: xe buýt của bác rời bến đúng sáu giờ mỗi sáng.","explanation":"The clue <b>at exactly six every morning</b> describes someone who is always on time: <b>punctual</b>. ✗ <b>temporary</b> — lasting only a short time; ✗ <b>recent</b> — happening not long ago; ✗ <b>urgent</b> — needing action at once."},{"id":"gv-kc-11-14","level":"kc","focus":"linking","q":"There was a thunderstorm last night; ______, the morning market opened as usual.","options":["nevertheless","therefore","moreover","otherwise"],"correct":0,"answer":"nevertheless","vi":"Tối qua có giông bão; tuy vậy, chợ sáng vẫn mở cửa như thường lệ.","explanation":"A storm at night, yet the market <b>opened as usual</b>: the second clause contrasts with the first, so the adverb of contrast <b>nevertheless</b> is needed. ✗ <b>therefore</b> — shows a result, but opening normally is not a result of a storm; ✗ <b>moreover</b> — adds a similar point, not an opposite one; ✗ <b>otherwise</b> — means 'if not', which makes no sense after a stated fact."},{"id":"gv-kc-11-15","level":"kc","focus":"idiom","q":"Somehow the whole class ______ Nam's surprise party, so it wasn't a surprise at all.","options":["got the hang of","got the better of","got wind of","got rid of"],"correct":2,"answer":"got wind of","vi":"Không hiểu sao cả lớp đã nghe phong thanh về bữa tiệc bất ngờ của Nam, nên nó chẳng còn bất ngờ chút nào.","explanation":"The clue <b>it wasn't a surprise at all</b> shows the class had heard about the party in advance: to <b>get wind of</b> something is to hear about it, often before it is meant to be known. ✗ <b>got the hang of</b> — learned how to do something; ✗ <b>got the better of</b> — defeated or overcame; ✗ <b>got rid of</b> — threw away or removed."},{"id":"gv-kc-11-16","level":"kc","focus":"conditional","q":"If the weather office hadn't ruled out a storm, the boat race on the river ______.","options":["would be cancelled","will be cancelled","was cancelled","would have been cancelled"],"correct":3,"answer":"would have been cancelled","vi":"Nếu cơ quan khí tượng không loại trừ khả năng có bão thì cuộc đua thuyền trên sông đã bị hủy rồi.","explanation":"The <b>if</b>-clause is past perfect (<b>hadn't ruled out</b>), so this is a third conditional about an unreal past, and the main clause takes <b>would have</b> + past participle: <b>would have been cancelled</b>. ✗ <b>would be cancelled</b> — second conditional, for an unreal present or future; ✗ <b>will be cancelled</b> — first conditional, for a real future possibility; ✗ <b>was cancelled</b> — a plain past fact, but the cancellation never happened."},{"id":"gv-kc-11-17","level":"kc","focus":"word-choice","q":"We reached the station ten minutes ______, so we had time for a coffee before the train left.","options":["soon","early","lately","quickly"],"correct":1,"answer":"early","vi":"Chúng tôi đến ga sớm mười phút, nên có thời gian uống cà phê trước khi tàu chạy.","explanation":"<b>Ten minutes early</b> = before the planned time, which is why there was <b>time for a coffee</b>. ✗ <b>soon</b> — 'in a short time from now'; 'ten minutes soon' is not English; ✗ <b>lately</b> — means 'recently' and cannot measure a time difference; ✗ <b>quickly</b> — describes speed of movement, not arriving before a time."},{"id":"gv-kc-11-18","level":"kc","focus":"agreement","q":"A number of lanterns ______ hung along the river every full-moon night in Hoi An.","options":["are","is","has","was"],"correct":0,"answer":"are","vi":"Nhiều chiếc đèn lồng được treo dọc bờ sông vào mỗi đêm rằm ở Hội An.","explanation":"<b>A number of</b> + plural noun means 'many' and takes a plural verb (only <b>the number of</b> is singular), and <b>every full-moon night</b> calls for the present simple, so <b>are</b> hung. ✗ <b>is</b> — singular, breaks agreement with <b>lanterns</b>; ✗ <b>has</b> — singular, and <b>has hung</b> would be active, not the passive 'are hung' the sentence needs; ✗ <b>was</b> — singular and past, clashing with <b>every</b> night."},{"id":"gv-kc-11-19","level":"kc","focus":"phrasal-verb","q":"At the meeting, the head girl ______ a plan for a greener school festival.","options":["put off","put away","put forward","put up"],"correct":2,"answer":"put forward","vi":"Tại cuộc họp, bạn nữ đại diện học sinh đã đề xuất một kế hoạch cho lễ hội trường xanh hơn.","explanation":"<b>Put forward</b> a plan or idea = suggest it for discussion, which is what happens <b>at the meeting</b>. ✗ <b>put off</b> — postpone; ✗ <b>put away</b> — store something in its place; ✗ <b>put up</b> — build a tent or building, or display a poster."},{"id":"gv-kc-11-20","level":"kc","focus":"participle","q":"______ from the top of the hill, the whole town looks like a toy model.","options":["Seeing","Seen","To see","Having seen"],"correct":1,"answer":"Seen","vi":"Nhìn từ đỉnh đồi, cả thị trấn trông như một mô hình đồ chơi.","explanation":"The town does not do the seeing — it is <b>seen</b> — so the past participle gives a passive meaning (When it is seen from the top…). ✗ <b>Seeing</b> — active present participle, which would make <b>the whole town</b> the one who looks (a dangling participle); ✗ <b>Having seen</b> — active perfect participle, the same problem; ✗ <b>To see</b> — an infinitive of purpose ('in order to see'), not the meaning here."},{"id":"gv-kc-11-21","level":"kc","focus":"tense","q":"By next Tet, my family ______ in this town for exactly ten years.","options":["will live","has lived","lived","will have lived"],"correct":3,"answer":"will have lived","vi":"Đến Tết sang năm, gia đình tôi sẽ sống ở thị trấn này tròn mười năm.","explanation":"<b>By next Tet</b> (a future point) + <b>for exactly ten years</b> describe a period completed up to a point in the future, so the future perfect <b>will have lived</b> is needed. ✗ <b>will live</b> — future simple gives no sense of 'completed by then'; ✗ <b>has lived</b> — present perfect measures up to now, not up to next Tet; ✗ <b>lived</b> — past simple is for a finished past period."},{"id":"gv-kc-11-22","level":"kc","focus":"word-choice","q":"The old tram line closed years ago; ______ most people in the city take the metro.","options":["nowadays","lately","formerly","previously"],"correct":0,"answer":"nowadays","vi":"Tuyến tàu điện cũ đã đóng cửa nhiều năm trước; ngày nay hầu hết người dân thành phố đi tàu điện ngầm.","explanation":"<b>Nowadays</b> = at the present time, in contrast with the past (<b>closed years ago</b> … now the metro). ✗ <b>lately</b> — 'recently', and it goes with the present perfect, not present simple <b>take</b>; ✗ <b>formerly</b> — 'in the past', the opposite of the contrast needed; ✗ <b>previously</b> — also 'before', so it would put the metro in the past too."},{"id":"gv-kc-11-23","level":"kc","focus":"pronoun","q":"______ gets to the bus stop first should save seats for the rest of the group.","options":["Whatever","Whichever","Whoever","Whom"],"correct":2,"answer":"Whoever","vi":"Ai đến trạm xe buýt trước thì nên giữ chỗ cho cả nhóm.","explanation":"<b>Whoever</b> = 'the person who' and is the subject of <b>gets</b>; the sentence is about a person who <b>should save seats</b>. ✗ <b>Whatever</b> — 'anything that', refers to things; ✗ <b>Whichever</b> — 'any one of a set', and on its own it needs a noun or 'of you' after it (whichever of you gets…); ✗ <b>Whom</b> — an object form, so it cannot be the subject of <b>gets</b>."},{"id":"gv-kc-11-24","level":"kc","focus":"collocation","q":"Tet ______ on a different date each year because it follows the lunar calendar.","options":["drops","falls","sets","lies"],"correct":1,"answer":"falls","vi":"Tết rơi vào một ngày khác nhau mỗi năm vì nó theo lịch âm.","explanation":"A festival or holiday <b>falls on</b> a date — the clue is <b>on a different date</b>. ✗ <b>drops</b> — means goes down or lets fall, not used with dates; ✗ <b>sets</b> — the sun sets; a date is set (fixed) by people, only in the passive; ✗ <b>lies</b> — a place lies somewhere (the town lies on the river), not a day."},{"id":"gv-kc-11-25","level":"kc","focus":"question-tag","q":"Let's go to the flower market on Sunday morning, ______?","options":["will we","do we","don't we","shall we"],"correct":3,"answer":"shall we","vi":"Sáng Chủ nhật mình đi chợ hoa nhé?","explanation":"The tag for <b>Let's</b> (a suggestion) is always <b>shall we</b>. ✗ <b>will we</b> — <b>will you</b> is the tag for an imperative (Open the door, will you?), and 'will we' matches nothing here; ✗ <b>do we</b> — tags a negative present simple statement (We don't go…, do we?); ✗ <b>don't we</b> — tags a positive present simple statement (We go…, don't we?), and <b>Let's</b> has no <b>do</b> to echo."},{"id":"gv-kc-12-1","level":"kc","focus":"tense","q":"By the time Lan gets home from school, her little brother ______ all the birthday cake.","options":["has eaten","ate","will have eaten","is eating"],"correct":2,"answer":"will have eaten","vi":"Đến lúc Lan đi học về thì em trai cô ấy sẽ ăn hết cả cái bánh sinh nhật rồi.","explanation":"<b>By the time + present simple</b> (gets home) marks a future point, and an action finished <b>before</b> that point takes the future perfect: <b>will have eaten</b>. ✗ <b>has eaten</b> — present perfect, links a past action to now, not to a future deadline; ✗ <b>ate</b> — past simple, but the cake-eating has not happened yet; ✗ <b>is eating</b> — present continuous, an action in progress now, not one completed before she arrives."},{"id":"gv-kc-12-2","level":"kc","focus":"word-choice","q":"Could you ______ the kitchen floor? There are crumbs everywhere after the party.","options":["sweep","dust","fold","hang"],"correct":0,"answer":"sweep","vi":"Bạn quét sàn bếp giúp mình được không? Sau bữa tiệc, vụn bánh rơi khắp nơi.","explanation":"The clue is <b>the kitchen floor</b> and <b>crumbs</b>: you <b>sweep</b> a floor with a broom. ✗ <b>dust</b> — wipe dust off shelves or furniture, not crumbs off a floor; ✗ <b>fold</b> — bend clothes or paper neatly; ✗ <b>hang</b> — put clothes or pictures up on a line or wall."},{"id":"gv-kc-12-3","level":"kc","focus":"idiom","q":"Nam's parents ______ when they found out he had skipped school to go to a party.","options":["went round in circles","went through the roof","went down the drain","went off the rails"],"correct":1,"answer":"went through the roof","vi":"Bố mẹ Nam nổi giận đùng đùng khi phát hiện cậu ấy trốn học đi dự tiệc.","explanation":"The clue is <b>found out he had skipped school</b>: parents react with anger, and <b>go through the roof</b> means to become extremely angry. ✗ <b>went round in circles</b> — made no progress; ✗ <b>went down the drain</b> — was wasted (money, effort); ✗ <b>went off the rails</b> — started behaving badly, which fits Nam, not his parents."},{"id":"gv-kc-12-4","level":"kc","focus":"modal","q":"Lan: Shall I bring some snacks tonight? / Nam: No, you ______ — my mum has made enough for everyone.","options":["mustn't","can't","won't","needn't"],"correct":3,"answer":"needn't","vi":"Lan: Tối nay mình mang chút đồ ăn vặt tới nhé? / Nam: Không, cậu không cần đâu — mẹ mình đã làm đủ cho mọi người rồi.","explanation":"<b>Needn't</b> = it is not necessary, matching the reason <b>my mum has made enough for everyone</b>. ✗ <b>mustn't</b> — forbids (\"you are not allowed to\"), too strong for an offer of snacks; ✗ <b>can't</b> — denies ability or permission, not necessity; ✗ <b>won't</b> — a refusal or a prediction, not an answer to \"Shall I?\"."},{"id":"gv-kc-12-5","level":"kc","focus":"relative","q":"The letters on our badge, ______ stand for the school's name, were designed by a student.","options":["which","that","who","whose"],"correct":0,"answer":"which","vi":"Các chữ cái trên huy hiệu của chúng tôi, vốn là viết tắt của tên trường, do một học sinh thiết kế.","explanation":"The commas mark a non-defining clause about a thing (<b>the letters</b>), so <b>which</b> is needed. ✗ <b>that</b> — cannot introduce a non-defining clause after a comma; ✗ <b>who</b> — for people, not letters; ✗ <b>whose</b> — possessive, needs a noun after it (<b>whose colours</b>)."},{"id":"gv-kc-12-6","level":"kc","focus":"collocation","q":"Minh is ______ a real effort to finish his homework before the party starts.","options":["doing","making","taking","having"],"correct":1,"answer":"making","vi":"Minh đang thực sự cố gắng làm xong bài tập về nhà trước khi bữa tiệc bắt đầu.","explanation":"The fixed collocation is <b>make an effort</b>, and the object <b>a real effort</b> decides it. ✗ <b>doing</b> — we do homework or the dishes, not an effort; ✗ <b>taking</b> — we take a break or a photo; ✗ <b>having</b> — we have a party or a rest; none of these pair with <b>effort</b>."},{"id":"gv-kc-12-7","level":"kc","focus":"word-choice","q":"It's your turn to ______ the dishes tonight; I did them yesterday.","options":["mop","sweep","wash","dust"],"correct":2,"answer":"wash","vi":"Tối nay đến lượt cậu rửa bát; hôm qua mình rửa rồi.","explanation":"The object <b>the dishes</b> decides it: we <b>wash</b> the dishes (= wash up). ✗ <b>mop</b> — clean a floor with a wet mop; ✗ <b>sweep</b> — clean a floor with a broom; ✗ <b>dust</b> — wipe dust off furniture and shelves."},{"id":"gv-kc-12-8","level":"kc","focus":"phrasal-verb","q":"Hung only bought that expensive phone to ______ in front of his classmates.","options":["show off","show up","put off","take off"],"correct":0,"answer":"show off","vi":"Hùng mua cái điện thoại đắt tiền đó chỉ để khoe khoang trước mặt các bạn cùng lớp.","explanation":"The clue is <b>expensive phone ... in front of his classmates</b>: <b>show off</b> = try to impress people with what you have. ✗ <b>show up</b> — arrive, appear; ✗ <b>put off</b> — postpone, or make someone dislike something; ✗ <b>take off</b> — remove clothes, or leave the ground (a plane)."},{"id":"gv-kc-12-9","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Hoa: He ______ his homework in the library — he'll be back at six.","options":["does","has done","did","is doing"],"correct":3,"answer":"is doing","vi":"Lan: Nam đâu rồi? / Hoa: Cậu ấy đang làm bài tập trong thư viện — sáu giờ sẽ về.","explanation":"Hoa is saying where Nam is <b>at this moment</b> (<b>Where's Nam?</b> ... <b>he'll be back at six</b>), so the present continuous <b>is doing</b> is needed. ✗ <b>does</b> — present simple, a habit or routine, not what is happening now; ✗ <b>has done</b> — present perfect, would mean the homework is finished; ✗ <b>did</b> — past simple, a finished past action, but he is still in the library."},{"id":"gv-kc-12-10","level":"kc","focus":"word-choice","q":"Before the party, we had to ______ the living room so there was space to dance.","options":["mend","tidy","polish","iron"],"correct":1,"answer":"tidy","vi":"Trước bữa tiệc, chúng tôi phải dọn gọn phòng khách để có chỗ nhảy.","explanation":"The clue is <b>so there was space to dance</b>: to <b>tidy</b> a room is to put things in order and clear space. ✗ <b>mend</b> — repair something broken; ✗ <b>polish</b> — rub shoes or furniture to make them shine; ✗ <b>iron</b> — press clothes flat with a hot iron."},{"id":"gv-kc-12-11","level":"kc","focus":"article-quantifier","q":"I have very ______ homework tonight, so I can come to Hoa's party after all.","options":["few","a few","little","a little"],"correct":2,"answer":"little","vi":"Tối nay mình có rất ít bài tập, nên rốt cuộc mình có thể đến dự tiệc của Hoa.","explanation":"<b>Homework</b> is uncountable, and the meaning (<b>so I can come</b>) is \"almost none\", so <b>little</b> fits; it is also the only option that can follow <b>very</b>. ✗ <b>few</b> — for plural countable nouns (few books); ✗ <b>a few</b> — countable, and \"very a few\" is impossible; ✗ <b>a little</b> — uncountable but positive (\"some\"), and <b>very a little</b> does not exist."},{"id":"gv-kc-12-12","level":"kc","focus":"conditional","q":"If I ______ more free time after school, I would join the school band.","options":["had","have","had had","would have"],"correct":0,"answer":"had","vi":"Nếu mình có nhiều thời gian rảnh sau giờ học hơn, mình sẽ tham gia ban nhạc của trường.","explanation":"<b>Would join</b> in the main clause marks a second conditional (unreal present), so the if-clause takes the past simple: <b>If I had</b>. ✗ <b>have</b> — first conditional, would need <b>will join</b>; ✗ <b>had had</b> — past perfect belongs to the third conditional (<b>would have joined</b>); ✗ <b>would have</b> — <b>would</b> never goes in the if-clause."},{"id":"gv-kc-12-13","level":"kc","focus":"collocation","q":"Hurry up, or we will ______ the last bus home and have to call a taxi.","options":["lose","fail","miss","drop"],"correct":2,"answer":"miss","vi":"Nhanh lên, không thì chúng ta sẽ lỡ chuyến xe buýt cuối cùng về nhà và phải gọi taxi đấy.","explanation":"The clue is <b>the last bus</b> and <b>have to call a taxi</b>: you <b>miss</b> a bus, train or flight when you arrive too late for it. ✗ <b>lose</b> — be unable to find something, or be beaten in a game; ✗ <b>fail</b> — not pass a test or exam; ✗ <b>drop</b> — let something fall."},{"id":"gv-kc-12-14","level":"kc","focus":"word-choice","q":"Dad ______ the bookshelves every weekend because the dust makes my brother sneeze.","options":["rinses","dusts","peels","stirs"],"correct":1,"answer":"dusts","vi":"Cuối tuần nào bố cũng lau bụi giá sách vì bụi làm em trai tôi hắt hơi.","explanation":"The clue is <b>bookshelves</b> and <b>the dust</b>: to <b>dust</b> is to wipe dust off furniture. ✗ <b>rinses</b> — washes with clean water to remove soap; ✗ <b>peels</b> — removes the skin of fruit or vegetables; ✗ <b>stirs</b> — mixes food or drink with a spoon."},{"id":"gv-kc-12-15","level":"kc","focus":"modal","q":"Hoa ______ the party yet — her bag and jacket are still on the chair.","options":["must have left","should have left","can't have left","needn't have left"],"correct":2,"answer":"can't have left","vi":"Hoa không thể nào đã rời bữa tiệc được — túi và áo khoác của cô ấy vẫn còn trên ghế.","explanation":"The evidence <b>her bag and jacket are still on the chair</b> calls for a negative deduction: <b>can't have left</b> = it is impossible that she left. ✗ <b>must have left</b> — the opposite deduction (\"I'm sure she left\"), which the evidence contradicts; ✗ <b>should have left</b> — she was expected to leave but didn't, a criticism, not a deduction; ✗ <b>needn't have left</b> — she did leave but it was unnecessary, which contradicts <b>yet</b>."},{"id":"gv-kc-12-16","level":"kc","focus":"idiom","q":"Studying a little every day feels hard now, but it will pay off ______.","options":["in the nick of time","on the spur of the moment","at the drop of a hat","in the long run"],"correct":3,"answer":"in the long run","vi":"Mỗi ngày học một chút bây giờ thấy vất vả, nhưng về lâu dài sẽ có kết quả.","explanation":"The contrast <b>hard now</b> ... <b>will pay off</b> points to a distant result: <b>in the long run</b> = over a long period, eventually. ✗ <b>in the nick of time</b> — just before it is too late; ✗ <b>on the spur of the moment</b> — suddenly, without planning; ✗ <b>at the drop of a hat</b> — immediately, without hesitation."},{"id":"gv-kc-12-17","level":"kc","focus":"tense","q":"Mr Tran ______ maths at our school since 2015, and he still loves the job.","options":["taught","has taught","is teaching","had taught"],"correct":1,"answer":"has taught","vi":"Thầy Trần đã dạy toán ở trường chúng tôi từ năm 2015, và thầy vẫn yêu công việc này.","explanation":"<b>Since 2015</b> links a past starting point to now, and <b>he still loves the job</b> confirms it continues, so the present perfect <b>has taught</b> is needed. ✗ <b>taught</b> — past simple, a finished period, would mean he no longer teaches there; ✗ <b>is teaching</b> — present continuous cannot be used with <b>since</b> + a starting point; ✗ <b>had taught</b> — past perfect, needs a later past point to be \"before\"."},{"id":"gv-kc-12-18","level":"kc","focus":"relative","q":"The café ______ we usually meet at after school is closed for repairs this week.","options":["where","whom","whose","that"],"correct":3,"answer":"that","vi":"Quán cà phê mà bọn mình hay gặp nhau sau giờ học tuần này đóng cửa để sửa chữa.","explanation":"The clause is defining (no commas) and keeps its preposition at the end (<b>meet at</b>), so a place-thing takes <b>that</b> (or which). ✗ <b>where</b> — already means \"at which\", so it cannot combine with <b>at</b>; ✗ <b>whom</b> — for people only; ✗ <b>whose</b> — possessive, needs a noun after it."},{"id":"gv-kc-12-19","level":"kc","focus":"phrasal-verb","q":"Everyone says Mai ______ her mother — they have the same laugh and the same smile.","options":["takes up","looks after","takes after","takes off"],"correct":2,"answer":"takes after","vi":"Ai cũng bảo Mai giống mẹ — hai mẹ con có cùng tiếng cười và nụ cười.","explanation":"The clue is <b>the same laugh and the same smile</b> as her mother: <b>take after</b> = resemble an older relative. ✗ <b>takes up</b> — start a hobby or activity; ✗ <b>looks after</b> — care for someone; ✗ <b>takes off</b> — remove clothes, or leave the ground."},{"id":"gv-kc-12-20","level":"kc","focus":"word-choice","q":"Hang the ______ on the line outside; it won't dry indoors in this weather.","options":["rubbish","dishes","groceries","laundry"],"correct":3,"answer":"laundry","vi":"Phơi quần áo giặt lên dây ngoài trời đi; thời tiết này để trong nhà sẽ không khô đâu.","explanation":"The clue is <b>hang ... on the line</b> and <b>dry</b>: <b>laundry</b> is washed clothes, which you hang out to dry. ✗ <b>rubbish</b> — waste, which you take out; ✗ <b>dishes</b> — plates and bowls, which you wash and dry with a cloth; ✗ <b>groceries</b> — food shopping, which you put away."},{"id":"gv-kc-12-21","level":"kc","focus":"linking","q":"______ the bad weather, the school football match went ahead on Sunday afternoon.","options":["Despite","Although","In spite","Even though"],"correct":0,"answer":"Despite","vi":"Dù thời tiết xấu, trận bóng đá của trường vẫn diễn ra vào chiều Chủ nhật.","explanation":"The blank is followed by a noun phrase (<b>the bad weather</b>), so it needs a preposition: <b>Despite</b>. ✗ <b>Although</b> — a conjunction, needs a clause with subject and verb (although the weather was bad); ✗ <b>In spite</b> — incomplete, must be <b>in spite of</b>; ✗ <b>Even though</b> — also a conjunction, needs a full clause."},{"id":"gv-kc-12-22","level":"kc","focus":"gerund-infinitive","q":"Remember ______ the lights before you leave the classroom this afternoon.","options":["to turn off","turning off","turn off","to turning off"],"correct":0,"answer":"to turn off","vi":"Nhớ tắt đèn trước khi rời lớp chiều nay nhé.","explanation":"<b>Remember + to-infinitive</b> = don't forget to do something in the future, and <b>before you leave</b> shows the action is still to come: <b>to turn off</b>. ✗ <b>turning off</b> — remember + -ing is a memory of something already done, which makes no sense as a reminder; ✗ <b>turn off</b> — remember cannot take a bare infinitive; ✗ <b>to turning off</b> — <b>to</b> + -ing does not follow remember."},{"id":"gv-kc-12-23","level":"kc","focus":"tense","q":"When I called at seven, my friends ______ for the party, so nobody answered the phone.","options":["got ready","have got ready","are getting ready","were getting ready"],"correct":3,"answer":"were getting ready","vi":"Lúc mình gọi vào bảy giờ, các bạn mình đang chuẩn bị cho bữa tiệc, nên không ai nghe máy.","explanation":"A longer action in progress when a shorter past action interrupted it (<b>When I called at seven</b>) takes the past continuous: <b>were getting ready</b>. ✗ <b>got ready</b> — past simple, a completed action, but they were in the middle of it, which is why nobody answered; ✗ <b>have got ready</b> — present perfect cannot combine with the past time <b>at seven</b>; ✗ <b>are getting ready</b> — present continuous, but the story is in the past."},{"id":"gv-kc-12-24","level":"kc","focus":"collocation","q":"We're ______ a party on Saturday to celebrate the end of the exams — can you come?","options":["making","doing","throwing","taking"],"correct":2,"answer":"throwing","vi":"Thứ Bảy này bọn mình tổ chức một bữa tiệc mừng thi xong — cậu đến được không?","explanation":"The object <b>a party</b> decides it: we <b>throw</b> (or have / hold) a party. ✗ <b>making</b> — we make a cake or an effort, not a party; ✗ <b>doing</b> — we do homework or the dishes; ✗ <b>taking</b> — we take a break or a photo; none of these collocate with <b>party</b>."},{"id":"gv-kc-12-25","level":"kc","focus":"inversion","q":"______ does Lan miss a homework deadline; she is the most organised student in the class.","options":["Not until","Rarely","No sooner","Only after"],"correct":1,"answer":"Rarely","vi":"Hiếm khi Lan trễ hạn nộp bài tập; cô ấy là học sinh ngăn nắp nhất lớp.","explanation":"The inverted verb <b>does Lan miss</b> shows a negative adverb starts the sentence, and the meaning (<b>the most organised student</b>) needs \"almost never\": <b>Rarely</b>. ✗ <b>No sooner</b> — needs a past perfect verb and <b>than</b> (no sooner had she ... than); ✗ <b>Not until</b> — needs a time phrase or clause before the inversion (not until Friday does she ...); ✗ <b>Only after</b> — also needs a time phrase or clause first (only after lunch does she ...)."},{"id":"gv-kc-13-1","level":"kc","focus":"tense","q":"Mai ______ three novels by that author since January.","options":["read","is reading","has read","had read"],"correct":2,"answer":"has read","vi":"Từ tháng Một đến giờ Mai đã đọc ba cuốn tiểu thuyết của tác giả đó.","explanation":"<b>Since January</b> marks a period running from a past starting point up to now, so the present perfect <b>has read</b> is required. ✗ <b>read</b> — past simple describes a finished time, but the period is still open; ✗ <b>is reading</b> — present continuous is for an action happening right now, not a total of three finished books; ✗ <b>had read</b> — past perfect needs a later past event to be earlier than, and there is none."},{"id":"gv-kc-13-2","level":"kc","focus":"word-choice","q":"My sister ______ the ending of the film in my ear so that nobody else in the cinema could hear.","options":["shouted","announced","whispered","declared"],"correct":2,"answer":"whispered","vi":"Chị tôi thì thầm vào tai tôi đoạn kết của bộ phim để không ai khác trong rạp nghe thấy.","explanation":"<b>So that nobody else could hear</b> means the words were said very quietly, and <b>in my ear</b> confirms it: <b>whispered</b> = spoke very softly. ✗ <b>shouted</b> — spoke very loudly, the opposite; ✗ <b>announced</b> — told everyone publicly; ✗ <b>declared</b> — stated openly and firmly, not secretly."},{"id":"gv-kc-13-3","level":"kc","focus":"collocation","q":"We ______ a lot of money on new furniture for the living room.","options":["paid","spent","cost","took"],"correct":1,"answer":"spent","vi":"Chúng tôi đã tiêu rất nhiều tiền vào đồ nội thất mới cho phòng khách.","explanation":"Money is the object and <b>on new furniture</b> names what it was used for, so the collocation is <b>spend money on</b> something. ✗ <b>paid</b> — you pay a person or pay <b>for</b> a thing, never pay money <b>on</b> it; ✗ <b>cost</b> — the thing costs money (the furniture cost us a lot), the buyer does not; ✗ <b>took</b> — take money = pick it up or accept it, not use it to buy."},{"id":"gv-kc-13-4","level":"kc","focus":"idiom","q":"Relax – it is only a tiny scratch on the car door. Don't ______.","options":["put all your eggs in one basket","bite off more than you can chew","kill two birds with one stone","make a mountain out of a molehill"],"correct":3,"answer":"make a mountain out of a molehill","vi":"Bình tĩnh đi, chỉ là một vết xước nhỏ xíu trên cửa xe thôi. Đừng có chuyện bé xé ra to.","explanation":"<b>Only a tiny scratch</b> plus <b>relax</b> means a small problem is being treated as a huge one: <b>make a mountain out of a molehill</b> = exaggerate a small problem. ✗ <b>put all your eggs in one basket</b> — risk everything on one plan; ✗ <b>bite off more than you can chew</b> — take on more than you can manage; ✗ <b>kill two birds with one stone</b> — achieve two things with one action."},{"id":"gv-kc-13-5","level":"kc","focus":"phrasal-verb","q":"We waited an hour outside the cinema, but Nam never ______.","options":["put up","turned down","turned up","turned off"],"correct":2,"answer":"turned up","vi":"Chúng tôi đợi cả tiếng ngoài rạp chiếu phim, nhưng Nam chẳng bao giờ xuất hiện.","explanation":"<b>Waited an hour ... but never</b> means Nam did not arrive: <b>turned up</b> = appeared, arrived. ✗ <b>put up</b> — needs an object (put up a poster) or with (put up with = tolerate); ✗ <b>turned down</b> — refused, or lowered the volume; ✗ <b>turned off</b> — switched off a device."},{"id":"gv-kc-13-6","level":"kc","focus":"modal","q":"Nam ______ at the concert last night – I saw him at home at nine o'clock.","options":["mustn't have been","can't have been","needn't have been","shouldn't have been"],"correct":1,"answer":"can't have been","vi":"Tối qua Nam không thể nào ở buổi hòa nhạc được – lúc chín giờ tôi thấy cậu ấy ở nhà mà.","explanation":"<b>I saw him at home at nine</b> is proof that his being at the concert was impossible, so the negative past deduction <b>can't have been</b> is needed. ✗ <b>mustn't have been</b> — must have is only for positive deduction; its negative is can't have; ✗ <b>needn't have been</b> — it was not necessary, but he did it anyway; ✗ <b>shouldn't have been</b> — it was wrong of him to be there, a criticism, not a conclusion about facts."},{"id":"gv-kc-13-7","level":"kc","focus":"relative","q":"The coach with ______ we trained for the swimming competition has moved to another club.","options":["who","whose","which","whom"],"correct":3,"answer":"whom","vi":"Huấn luyện viên mà chúng tôi đã tập luyện cùng cho giải bơi đã chuyển sang câu lạc bộ khác.","explanation":"The pronoun directly follows the preposition <b>with</b> and refers to a person (<b>the coach</b>), so the object form <b>whom</b> is required: <b>with whom we trained</b>. ✗ <b>who</b> — subject form, not used straight after a preposition; ✗ <b>whose</b> — possessive, must be followed by a noun; ✗ <b>which</b> — for things, not people."},{"id":"gv-kc-13-8","level":"kc","focus":"article-quantifier","q":"Linh has visited ______ countries in Asia, but she has never been to Japan.","options":["several","much","a little","every"],"correct":0,"answer":"several","vi":"Linh đã đi thăm vài nước ở châu Á, nhưng cô ấy chưa từng đến Nhật Bản.","explanation":"<b>Countries</b> is plural countable, and <b>but never Japan</b> shows some, not all, were visited, so <b>several</b> (= a few, more than two) fits. ✗ <b>much</b> — only with uncountable nouns (much money); ✗ <b>a little</b> — only with uncountable nouns (a little time); ✗ <b>every</b> — takes a singular noun (every country) and would contradict never having been to Japan."},{"id":"gv-kc-13-9","level":"kc","focus":"word-choice","q":"Could you ______ the last scene to me? I didn't understand why the hero left.","options":["complain","explain","persuade","argue"],"correct":1,"answer":"explain","vi":"Bạn giải thích cảnh cuối cho mình được không? Mình không hiểu tại sao nhân vật chính lại bỏ đi.","explanation":"<b>I didn't understand</b> shows the speaker wants the scene made clear: <b>explain</b> something <b>to</b> someone = make it clear. ✗ <b>complain</b> — say you are unhappy (complain about something), not clarify; ✗ <b>persuade</b> — make a person agree to do something, so its object is a person, not a scene; ✗ <b>argue</b> — disagree in words (argue with someone), not make something clear."},{"id":"gv-kc-13-10","level":"kc","focus":"gerund-infinitive","q":"Remember ______ the front door when you go out this evening.","options":["locking","lock","to locking","to lock"],"correct":3,"answer":"to lock","vi":"Nhớ khóa cửa trước khi con ra ngoài tối nay nhé.","explanation":"<b>When you go out this evening</b> puts the locking in the future, so it is a task still to do: <b>remember to do</b> = don't forget to do it. ✗ <b>locking</b> — remember doing = recall something already done, a memory not an instruction; ✗ <b>lock</b> — remember is never followed by a bare infinitive; ✗ <b>to locking</b> — to + -ing is not a form remember takes."},{"id":"gv-kc-13-11","level":"kc","focus":"linking","q":"Nam still went to school ______ he had a bad cold and a sore throat.","options":["despite","in spite of","although","however"],"correct":2,"answer":"although","vi":"Nam vẫn đi học mặc dù cậu ấy bị cảm nặng và đau họng.","explanation":"The blank is followed by a full clause with subject and verb (<b>he had</b>), so the contrast word must be a conjunction: <b>although</b>. ✗ <b>despite</b> — preposition, followed by a noun or -ing (despite his cold), not a clause; ✗ <b>in spite of</b> — same, needs a noun or -ing; ✗ <b>however</b> — adverb that starts a new sentence (However, he ...), it cannot join two clauses inside one sentence."},{"id":"gv-kc-13-12","level":"kc","focus":"word-choice","q":"Could you ______ me to call Grandma tonight? I always forget.","options":["suggest","recommend","remind","mention"],"correct":2,"answer":"remind","vi":"Bạn nhắc mình gọi cho bà tối nay nhé? Mình lúc nào cũng quên.","explanation":"<b>I always forget</b> means the speaker needs someone to make them remember, and the pattern is <b>remind someone to do</b> something. ✗ <b>suggest</b> — takes suggest doing / suggest that, never suggest someone to do; ✗ <b>recommend</b> — takes recommend doing / recommend that, not recommend someone to do; ✗ <b>mention</b> — speak briefly about something; mention someone to do does not exist."},{"id":"gv-kc-13-13","level":"kc","focus":"conditional","q":"I wish I ______ the film last night – everyone at school is talking about it.","options":["saw","have seen","had seen","would see"],"correct":2,"answer":"had seen","vi":"Giá mà tối qua tôi đã xem bộ phim đó – ở trường ai cũng đang bàn về nó.","explanation":"<b>Last night</b> makes this a wish about the past, and past wishes take <b>wish + past perfect</b>: <b>had seen</b>. ✗ <b>saw</b> — past simple after wish is a wish about the present (I wish I saw him more often); ✗ <b>have seen</b> — present perfect is never used after wish; ✗ <b>would see</b> — wish + would is for wanting a future change or complaining about someone's behaviour."},{"id":"gv-kc-13-14","level":"kc","focus":"collocation","q":"Could you ______ me a favour and return this book to the library?","options":["do","make","give","take"],"correct":0,"answer":"do","vi":"Bạn giúp mình một việc, trả cuốn sách này về thư viện được không?","explanation":"<b>Favour</b> as a small act of help has one fixed verb: <b>do someone a favour</b>. ✗ <b>make</b> — make goes with a decision, a mistake, an effort, not a favour; ✗ <b>give</b> — you give help or advice, but not give a favour; ✗ <b>take</b> — take does not combine with favour at all."},{"id":"gv-kc-13-15","level":"kc","focus":"passive","q":"The film ______ in Da Lat last year, which is why the scenery looks so familiar.","options":["shot","has shot","is shot","was shot"],"correct":3,"answer":"was shot","vi":"Bộ phim được quay ở Đà Lạt năm ngoái, vì thế cảnh trong phim trông rất quen thuộc.","explanation":"A film is shot <b>by</b> people, so the verb must be passive, and <b>last year</b> fixes the past simple: <b>was shot</b>. ✗ <b>shot</b> — active past, meaning the film did the shooting; ✗ <b>has shot</b> — active, and present perfect cannot be used with a finished time like last year; ✗ <b>is shot</b> — passive but present, contradicting last year."},{"id":"gv-kc-13-16","level":"kc","focus":"tense","q":"This time next week, my family ______ in our new house on the other side of town.","options":["live","will live","are living","will be living"],"correct":3,"answer":"will be living","vi":"Vào giờ này tuần sau, gia đình tôi sẽ đang sống trong ngôi nhà mới ở phía bên kia thành phố.","explanation":"<b>This time next week</b> names an exact future moment, and an action that will be in progress at that moment takes the future continuous: <b>will be living</b>. ✗ <b>live</b> — present simple states a general fact, no future meaning here; ✗ <b>will live</b> — plain future prediction, does not show an action in progress at a point in time; ✗ <b>are living</b> — present continuous describes now, not next week."},{"id":"gv-kc-13-17","level":"kc","focus":"reported","q":"Mum asked me where ______ the TV remote after the film.","options":["had I put","I had put","did I put","have I put"],"correct":1,"answer":"I had put","vi":"Mẹ hỏi tôi đã để cái điều khiển ti vi ở đâu sau khi xem phim.","explanation":"<b>Asked me where</b> introduces a reported question, which keeps statement order <b>subject + verb</b> and shifts the past simple back one step after past <b>asked</b>: <b>where I had put</b>. ✗ <b>had I put</b> — inverted verb-subject order belongs only to direct questions; ✗ <b>did I put</b> — the question auxiliary did is dropped in reported questions; ✗ <b>have I put</b> — inverted, and present perfect is not the backshifted form of past simple."},{"id":"gv-kc-13-18","level":"kc","focus":"idiom","q":"After a long talk, my parents and I are finally ______ about my plan to study music.","options":["in the same boat","on the same page","under the weather","over the moon"],"correct":1,"answer":"on the same page","vi":"Sau một cuộc nói chuyện dài, cuối cùng bố mẹ và tôi cũng đã đồng quan điểm về kế hoạch học nhạc của tôi.","explanation":"<b>After a long talk ... finally</b> means they now agree about the plan: <b>on the same page</b> = sharing the same understanding. ✗ <b>in the same boat</b> — in the same difficult situation; ✗ <b>under the weather</b> — slightly ill; ✗ <b>over the moon</b> — extremely happy."},{"id":"gv-kc-13-19","level":"kc","focus":"preposition","q":"My sister is really keen ______ Korean pop music and knows every song by heart.","options":["in","of","at","on"],"correct":3,"answer":"on","vi":"Chị tôi rất mê nhạc pop Hàn Quốc và thuộc lòng mọi bài hát.","explanation":"<b>Keen</b> meaning very interested takes the fixed preposition <b>on</b>: <b>keen on</b> Korean pop music. ✗ <b>in</b> — goes with interested (interested in), not keen; ✗ <b>of</b> — goes with fond (fond of), not keen; ✗ <b>at</b> — goes with good / bad (good at), not keen."},{"id":"gv-kc-13-20","level":"kc","focus":"word-choice","q":"Please don't ______ while Grandma is telling her story – wait until she finishes.","options":["interrupt","repeat","describe","pronounce"],"correct":0,"answer":"interrupt","vi":"Đừng ngắt lời khi bà đang kể chuyện – hãy đợi bà kể xong đã.","explanation":"<b>While Grandma is telling her story – wait until she finishes</b> tells you the problem is speaking before she has finished: <b>interrupt</b> = break in while someone is talking. ✗ <b>repeat</b> — say again, and it needs an object (repeat the story); ✗ <b>describe</b> — say what something is like, needs an object; ✗ <b>pronounce</b> — say the sounds of a word, needs an object and has nothing to do with waiting."},{"id":"gv-kc-13-21","level":"kc","focus":"phrasal-verb","q":"My parents couldn't ______ how to use the new TV remote, so I showed them.","options":["work out","work up","carry out","set out"],"correct":0,"answer":"work out","vi":"Bố mẹ tôi không tìm ra cách dùng cái điều khiển ti vi mới, nên tôi chỉ cho họ.","explanation":"<b>Couldn't ... how to use</b> and <b>so I showed them</b> mean they failed to find the answer: <b>work out</b> = understand or solve by thinking. ✗ <b>work up</b> — build up an appetite, courage or energy; ✗ <b>carry out</b> — perform or complete a task or order; ✗ <b>set out</b> — start a journey, or lay out plans."},{"id":"gv-kc-13-22","level":"kc","focus":"comparison","q":"The more pocket money you save now, ______ you can spend on the school trip.","options":["more","the more","the most","most"],"correct":1,"answer":"the more","vi":"Bây giờ bạn càng để dành nhiều tiền tiêu vặt, thì bạn càng có nhiều tiền để chi cho chuyến đi của trường.","explanation":"The sentence opens with <b>The more ... you save</b>, and the double comparative pattern needs <b>the + comparative</b> in both halves: <b>the more</b>. ✗ <b>more</b> — comparative but missing the required the; ✗ <b>the most</b> — superlative, not a comparative; ✗ <b>most</b> — superlative and without the."},{"id":"gv-kc-13-23","level":"kc","focus":"tense","q":"By the time the film ended, the painkiller ______, and my tooth hurt again.","options":["wore off","had worn off","has worn off","wears off"],"correct":1,"answer":"had worn off","vi":"Đến lúc bộ phim kết thúc thì thuốc giảm đau đã hết tác dụng, và răng tôi lại đau.","explanation":"<b>By the time the film ended</b> (past simple) fixes a past moment, and the painkiller stopped working before it, so the earlier action takes the past perfect: <b>had worn off</b> (= stopped having an effect). ✗ <b>wore off</b> — past simple would make the two events happen together, not one before the other; ✗ <b>has worn off</b> — present perfect cannot follow a past-time clause; ✗ <b>wears off</b> — present simple, but the story is in the past."},{"id":"gv-kc-13-24","level":"kc","focus":"collocation","q":"The bookshop ______ a twenty per cent discount on all novels this week.","options":["offers","makes","does","brings"],"correct":0,"answer":"offers","vi":"Tuần này hiệu sách giảm giá hai mươi phần trăm cho tất cả tiểu thuyết.","explanation":"The subject is a shop and the object is <b>a ... discount</b>; the collocation is <b>offer</b> (or give) <b>a discount</b>. ✗ <b>makes</b> — make goes with a profit or a purchase, not a discount; ✗ <b>does</b> — do a deal exists, but do a discount is not English; ✗ <b>brings</b> — bring = carry something to a place, it does not go with discount."},{"id":"gv-kc-13-25","level":"kc","focus":"word-choice","q":"The shop assistant ______ that the phone was cheaper online, so we didn't buy it there.","options":["admitted","denied","refused","promised"],"correct":0,"answer":"admitted","vi":"Nhân viên cửa hàng thừa nhận rằng chiếc điện thoại mua trên mạng rẻ hơn, nên chúng tôi không mua ở đó.","explanation":"<b>So we didn't buy it there</b> shows the assistant agreed to an unwelcome truth about his own shop: <b>admitted that</b> = confessed something was true. ✗ <b>denied</b> — said it was not true, which would not make the buyers leave; ✗ <b>refused</b> — takes to + verb, not a that-clause; ✗ <b>promised that</b> — a promise makes no sense with a cheaper price elsewhere and would not lead to not buying."},{"id":"gv-kc-14-1","level":"kc","focus":"word-choice","q":"It was so dark in the clinic corridor that I had to ______ at the sign to read the doctor's name.","options":["glimpse","peer","notice","observe"],"correct":1,"answer":"peer","vi":"Hành lang phòng khám tối đến nỗi tôi phải nheo mắt nhìn kỹ tấm biển mới đọc được tên bác sĩ.","explanation":"Word choice: <b>peer at</b> = look closely and with difficulty, which fits <b>so dark</b> and having to read the sign. ✗ <b>glimpse</b> — see briefly by chance, and takes a direct object, not <b>at</b>; ✗ <b>notice</b> — become aware of something, no effort, no <b>at</b>; ✗ <b>observe</b> — watch carefully for a long time, takes a direct object, not <b>at</b>."},{"id":"gv-kc-14-2","level":"kc","focus":"word-choice","q":"Can you ______ any spelling mistakes in my post before I upload it?","options":["spot","glance","stare","gaze"],"correct":0,"answer":"spot","vi":"Bạn có thể phát hiện lỗi chính tả nào trong bài đăng của mình trước khi mình tải lên không?","explanation":"Word choice: <b>spot</b> = notice something that is hard to find, and it takes a direct object — <b>spot any spelling mistakes</b>. ✗ <b>glance</b> — take a quick look, needs <b>at</b>; ✗ <b>stare</b> — look fixedly, needs <b>at</b>; ✗ <b>gaze</b> — look steadily in admiration or wonder, needs <b>at</b>. None of the three can take 'mistakes' as its object."},{"id":"gv-kc-14-3","level":"kc","focus":"word-choice","q":"The little boy ______ at the goldfish in the doctor's waiting room for almost an hour.","options":["glimpsed","spotted","gazed","noticed"],"correct":2,"answer":"gazed","vi":"Cậu bé ngắm nhìn đàn cá vàng trong phòng chờ của bác sĩ gần cả tiếng đồng hồ.","explanation":"Word choice: <b>gaze at</b> = look steadily for a long time, which matches <b>for almost an hour</b> and the preposition <b>at</b>. ✗ <b>glimpsed</b> — saw for a moment, takes a direct object; ✗ <b>spotted</b> — noticed suddenly, takes a direct object; ✗ <b>noticed</b> — became aware of, takes a direct object. All three are momentary and never take <b>at</b>."},{"id":"gv-kc-14-4","level":"kc","focus":"word-choice","q":"I only caught a ______ of the famous striker before the crowd closed in around him.","options":["glance","view","stare","glimpse"],"correct":3,"answer":"glimpse","vi":"Tôi chỉ kịp thoáng thấy cầu thủ tiền đạo nổi tiếng trước khi đám đông vây quanh anh ấy.","explanation":"Fixed expression: <b>catch a glimpse of</b> = see something for a very short time, which fits <b>only ... before the crowd closed in</b>. ✗ <b>glance</b> — a quick look you <b>take</b> or <b>cast</b>, not catch; ✗ <b>view</b> — what you can see from a place, used with <b>have/get a view of</b>; ✗ <b>stare</b> — a long fixed look, used with <b>give a stare</b>, not catch."},{"id":"gv-kc-14-5","level":"kc","focus":"word-choice","q":"Lan spent the whole evening ______ the internet for a second-hand bicycle.","options":["browsing","peeking","glancing","staring"],"correct":0,"answer":"browsing","vi":"Lan dành cả buổi tối lướt mạng để tìm một chiếc xe đạp cũ.","explanation":"Word choice: <b>browse the internet</b> = look through websites without a fixed plan, which fits <b>the whole evening ... for a bicycle</b>; browse takes a direct object. ✗ <b>peeking</b> — take a quick secret look, needs <b>at</b>; ✗ <b>glancing</b> — take a quick look, needs <b>at</b>; ✗ <b>staring</b> — look fixedly, needs <b>at</b>. All three describe one short look, not searching online."},{"id":"gv-kc-14-6","level":"kc","focus":"collocation","q":"Please ______ attention to the road signs when you cycle through the city centre.","options":["pay","take","make","put"],"correct":0,"answer":"pay","vi":"Hãy chú ý các biển báo giao thông khi bạn đạp xe qua trung tâm thành phố.","explanation":"Collocation: the fixed verb with <b>attention</b> is <b>pay attention to</b>. ✗ <b>take</b> — take care / take notice, but never take attention; ✗ <b>make</b> — make an effort / make a note, not attention; ✗ <b>put</b> — put effort into, not attention. Only <b>pay</b> collocates with this noun."},{"id":"gv-kc-14-7","level":"kc","focus":"collocation","q":"When the teacher asked who had broken the window, Nam decided to ______ the truth.","options":["say","speak","tell","talk"],"correct":2,"answer":"tell","vi":"Khi cô giáo hỏi ai đã làm vỡ cửa sổ, Nam quyết định nói thật.","explanation":"Collocation: the fixed verb with <b>the truth</b> is <b>tell the truth</b> (like tell a lie, tell a story, tell a joke). ✗ <b>say</b> — reports the actual words spoken (say 'sorry'), not truth or lies; ✗ <b>speak</b> — a language or in a way (speak English, speak loudly), no object 'the truth'; ✗ <b>talk</b> — is intransitive: talk about / talk to, never talk the truth."},{"id":"gv-kc-14-8","level":"kc","focus":"collocation","q":"My grandfather cycles ten kilometres every morning to ______ fit.","options":["hold","make","go","keep"],"correct":3,"answer":"keep","vi":"Ông tôi đạp xe mười ki-lô-mét mỗi sáng để giữ gìn sức khỏe.","explanation":"Collocation: the verb before <b>fit</b> (= healthy through exercise) is <b>keep fit</b> or <b>stay fit</b>, and <b>cycles every morning</b> shows a continuing habit. ✗ <b>hold</b> — hold means grip or contain, never used before an adjective like fit; ✗ <b>make</b> — make + adjective needs an object (make him fit), and here there is none; ✗ <b>go</b> — go + adjective is for changes like go bad / go grey, not fit."},{"id":"gv-kc-14-9","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Minh: He ______ badminton at the sports centre. He'll be home by six.","options":["plays","is playing","has played","played"],"correct":1,"answer":"is playing","vi":"Lan: Nam đâu rồi? / Minh: Cậu ấy đang chơi cầu lông ở trung tâm thể thao. Sáu giờ cậu ấy sẽ về.","explanation":"Tense: an action in progress <b>at the moment of speaking</b> (Where's Nam? ... He'll be home by six) takes the present continuous: <b>is playing</b>. ✗ <b>plays</b> — present simple is for habits (plays every Friday), not what he is doing now; ✗ <b>has played</b> — present perfect means the game is over, but he is still out; ✗ <b>played</b> — past simple is a finished action, not something happening now."},{"id":"gv-kc-14-10","level":"kc","focus":"tense","q":"I ______ this phone for three years, and the battery still lasts all day.","options":["had","am having","have had","have"],"correct":2,"answer":"have had","vi":"Tôi đã dùng chiếc điện thoại này ba năm rồi mà pin vẫn dùng được cả ngày.","explanation":"Tense: <b>for three years</b> with a situation that still continues (the battery <b>still</b> lasts) takes the present perfect: <b>have had</b>. ✗ <b>had</b> — past simple would mean I no longer have the phone; ✗ <b>am having</b> — have meaning 'possess' is a state verb and is not used in the continuous; ✗ <b>have</b> — present simple cannot combine with a <b>for</b> + duration stretching back into the past."},{"id":"gv-kc-14-11","level":"kc","focus":"tense","q":"Lan: Are you free on Sunday? / Nam: No, I ______ my cousin in Da Lat. We booked the bus tickets last week.","options":["visit","visited","have visited","am visiting"],"correct":3,"answer":"am visiting","vi":"Lan: Chủ nhật bạn có rảnh không? / Nam: Không, mình đi thăm anh họ ở Đà Lạt. Bọn mình đặt vé xe từ tuần trước rồi.","explanation":"Tense: a personal arrangement already fixed for the future (<b>We booked the bus tickets last week</b>) takes the present continuous: <b>am visiting</b> on Sunday. ✗ <b>visit</b> — present simple is for timetables (the bus leaves at six), not personal plans; ✗ <b>visited</b> — past simple describes a finished visit, but Sunday is still to come; ✗ <b>have visited</b> — present perfect means the visit has already happened."},{"id":"gv-kc-14-12","level":"kc","focus":"idiom","q":"Mai was ______ when she found out she had won the chess tournament.","options":["under the weather","over the moon","on the fence","in the dark"],"correct":1,"answer":"over the moon","vi":"Mai vui sướng tột độ khi biết mình đã thắng giải cờ vua.","explanation":"Idiom: <b>over the moon</b> = extremely happy, which fits <b>she had won the tournament</b>. ✗ <b>under the weather</b> — slightly ill; ✗ <b>on the fence</b> — undecided between two choices; ✗ <b>in the dark</b> — not told about something. None of the three describes joy at winning."},{"id":"gv-kc-14-13","level":"kc","focus":"idiom","q":"After months of talking about it, my brother finally ______ and signed up for the marathon.","options":["took the plunge","took the biscuit","took the floor","took the hint"],"correct":0,"answer":"took the plunge","vi":"Sau nhiều tháng chỉ nói suông, cuối cùng anh tôi cũng quyết tâm dấn thân và đăng ký chạy marathon.","explanation":"Idiom: <b>take the plunge</b> = finally do something big or risky after hesitating, which fits <b>after months of talking about it ... finally</b>. ✗ <b>took the biscuit</b> — was the most annoying or surprising of all; ✗ <b>took the floor</b> — began to speak in a meeting; ✗ <b>took the hint</b> — understood an indirect message. Only the plunge fits signing up for a marathon."},{"id":"gv-kc-14-14","level":"kc","focus":"phrasal-verb","q":"Don't ______ our team just because we lost the first two matches of the season.","options":["write down","write up","write off","write out"],"correct":2,"answer":"write off","vi":"Đừng vội coi đội mình là vô vọng chỉ vì thua hai trận đầu mùa giải.","explanation":"Phrasal verb: <b>write off</b> = decide that someone or something is a failure and give up on them, which fits <b>just because we lost the first two matches</b>. ✗ <b>write down</b> — note on paper; ✗ <b>write up</b> — turn notes into a full report; ✗ <b>write out</b> — write in full, without abbreviations. A team cannot be noted, reported or written in full."},{"id":"gv-kc-14-15","level":"kc","focus":"phrasal-verb","q":"Nam refused to ______ in the argument about which phone is better, even when he was clearly wrong.","options":["back up","back out","back away","back down"],"correct":3,"answer":"back down","vi":"Nam nhất quyết không chịu nhượng bộ trong cuộc tranh cãi xem điện thoại nào tốt hơn, dù cậu ấy rõ ràng đã sai.","explanation":"Phrasal verb: <b>back down</b> = admit you are wrong and stop arguing, which fits <b>refused to ... in the argument ... even when he was clearly wrong</b>. ✗ <b>back up</b> — support someone, or copy computer data; ✗ <b>back out</b> — withdraw from a promise or agreement; ✗ <b>back away</b> — move backwards physically, away from danger."},{"id":"gv-kc-14-16","level":"kc","focus":"modal","q":"Lan: Nam isn't answering his phone. / Mai: He ______ be at the doctor's; he said he had an appointment at nine.","options":["can't","must","needn't","mustn't"],"correct":1,"answer":"must","vi":"Lan: Nam không nghe điện thoại. / Mai: Chắc chắn cậu ấy đang ở chỗ bác sĩ; cậu ấy nói có hẹn lúc chín giờ.","explanation":"Modal of deduction: <b>must</b> = the speaker is almost sure it is true, and the evidence is given — <b>he said he had an appointment at nine</b>. ✗ <b>can't</b> — deduction that it is impossible, the opposite of the evidence; ✗ <b>needn't</b> — no obligation to do something, not a guess about where he is; ✗ <b>mustn't</b> — prohibition (not allowed), never used for deduction."},{"id":"gv-kc-14-17","level":"kc","focus":"relative","q":"The doctor ______ treated my grandmother has just opened a clinic near our school.","options":["whom","whose","which","who"],"correct":3,"answer":"who","vi":"Vị bác sĩ đã chữa bệnh cho bà tôi vừa mở một phòng khám gần trường chúng tôi.","explanation":"Relative pronoun: the gap is the <b>subject</b> of <b>treated</b> and refers to a person (<b>the doctor</b>), so <b>who</b> is needed. ✗ <b>whom</b> — object form only (the doctor whom we saw); here the verb has no other subject; ✗ <b>whose</b> — possessive, must be followed by a noun (whose clinic); ✗ <b>which</b> — for things and animals, not people."},{"id":"gv-kc-14-18","level":"kc","focus":"article-quantifier","q":"Only ______ people in my class still use a phone without internet access.","options":["a little","a few","much","little"],"correct":1,"answer":"a few","vi":"Chỉ một vài bạn trong lớp tôi còn dùng điện thoại không có kết nối mạng.","explanation":"Quantifier: <b>people</b> is a plural countable noun, so it takes <b>a few</b> (= a small number). ✗ <b>a little</b> — only with uncountable nouns (a little time); ✗ <b>much</b> — only with uncountable nouns, and used mainly in negatives and questions; ✗ <b>little</b> — uncountable only, and would mean 'almost none', not a small group that still exists."},{"id":"gv-kc-14-19","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your phone before the exam starts, or the teacher will take it away.","options":["switching off","to switch off","switch off","to switching off"],"correct":1,"answer":"to switch off","vi":"Nhớ tắt điện thoại trước khi bài thi bắt đầu, nếu không cô giáo sẽ thu đấy.","explanation":"Gerund vs infinitive: <b>remember to do</b> = don't forget a duty still to be done, and <b>before the exam starts</b> shows the action is still ahead. ✗ <b>switching off</b> — remember doing = recall a memory of something already done; ✗ <b>switch off</b> — a bare infinitive never follows remember; ✗ <b>to switching off</b> — to + gerund is not a possible form after remember."},{"id":"gv-kc-14-20","level":"kc","focus":"linking","q":"Mai forgot to water the plants on the balcony for two weeks; ______, most of them died.","options":["as a result","even so","in addition","on the contrary"],"correct":0,"answer":"as a result","vi":"Mai quên tưới cây trên ban công suốt hai tuần; kết quả là phần lớn cây đều chết.","explanation":"Linking word: the second clause is the <b>consequence</b> of forgetting to water the plants, so <b>as a result</b> is needed. ✗ <b>even so</b> — contrast (despite that), but the plants dying is not surprising; ✗ <b>in addition</b> — adds a similar point, not an effect; ✗ <b>on the contrary</b> — denies the previous statement and says the opposite."},{"id":"gv-kc-14-21","level":"kc","focus":"conditional","q":"If my dad hadn't bailed me out, I ______ my phone bill last month.","options":["couldn't have paid","couldn't pay","can't pay","won't pay"],"correct":0,"answer":"couldn't have paid","vi":"Nếu bố không giúp tôi thoát khỏi cảnh túng thiếu, tháng trước tôi đã không thể trả nổi tiền cước điện thoại.","explanation":"Third conditional: <b>if + past perfect</b> (<b>hadn't bailed</b>) and <b>last month</b> mark an unreal past, so the result clause needs <b>could have + past participle</b>: <b>couldn't have paid</b>. ✗ <b>couldn't pay</b> — second conditional, for an unreal present, not last month; ✗ <b>can't pay</b> — present ability, cannot follow a past-perfect if-clause; ✗ <b>won't pay</b> — first conditional, a real future, not an imagined past."},{"id":"gv-kc-14-22","level":"kc","focus":"agreement","q":"Neither the coach nor the players ______ happy with the referee's decision.","options":["was","is","has been","were"],"correct":3,"answer":"were","vi":"Cả huấn luyện viên lẫn các cầu thủ đều không hài lòng với quyết định của trọng tài.","explanation":"Agreement: with <b>neither ... nor</b>, the verb agrees with the <b>nearer</b> subject, <b>the players</b> (plural), so <b>were</b> is correct; <b>the referee's decision</b> sets the sentence in the past. ✗ <b>was</b> — singular, agrees with 'the coach', the farther subject; ✗ <b>is</b> — singular and present; ✗ <b>has been</b> — singular and present perfect, wrong number and wrong time."},{"id":"gv-kc-14-23","level":"kc","focus":"participle","q":"______ by a virus from a free download site, my laptop stopped working completely.","options":["Infecting","Having infected","Infected","To infect"],"correct":2,"answer":"Infected","vi":"Bị nhiễm vi-rút từ một trang tải miễn phí, máy tính xách tay của tôi ngừng hoạt động hoàn toàn.","explanation":"Participle clause: the laptop <b>was infected</b> by the virus (it did not infect anything), and <b>by a virus</b> signals a passive, so a past participle opens the clause: <b>Infected by</b>. ✗ <b>Infecting</b> — active, would make the laptop the one infecting; ✗ <b>Having infected</b> — active perfect participle, same problem; ✗ <b>To infect</b> — an infinitive of purpose, and the laptop had no purpose to infect."},{"id":"gv-kc-14-24","level":"kc","focus":"pronoun","q":"______ finishes the crossword first will get a free ice cream from Dad.","options":["Whomever","Whom","Whose","Whoever"],"correct":3,"answer":"Whoever","vi":"Ai giải xong ô chữ trước sẽ được bố thưởng một cây kem miễn phí.","explanation":"Pronoun: the gap is the <b>subject</b> of <b>finishes</b>, and <b>whoever</b> = 'the person who' does that job. ✗ <b>Whomever</b> — object form, cannot be the subject of a verb; ✗ <b>Whom</b> — object form and a question/relative word, not 'the person who'; ✗ <b>Whose</b> — possessive, needs a noun after it (whose crossword)."},{"id":"gv-kc-14-25","level":"kc","focus":"question-tag","q":"You haven't been to the dentist for two years, ______?","options":["have you","haven't you","did you","do you"],"correct":0,"answer":"have you","vi":"Hai năm nay bạn chưa đi khám nha sĩ, đúng không?","explanation":"Question tag: the statement is negative present perfect (<b>haven't been</b>), so the tag is positive with the same auxiliary: <b>have you</b>. ✗ <b>haven't you</b> — negative tag after a negative statement; tags flip; ✗ <b>did you</b> — the auxiliary must match; the statement uses have, not did; ✗ <b>do you</b> — wrong auxiliary; do is only for present simple."},{"id":"gv-kc-15-1","level":"kc","focus":"tense","q":"Look! A whale ______ right next to our boat!","options":["swims","is swimming","swam","has swum"],"correct":1,"answer":"is swimming","vi":"Nhìn kìa! Một con cá voi đang bơi ngay cạnh thuyền của chúng ta!","explanation":"<b>Look!</b> means the action is happening at this very moment, so the present continuous <b>is swimming</b> is needed. ✗ <b>swims</b> — present simple is for habits and facts, not an action in progress now; ✗ <b>swam</b> — past simple puts the action in the finished past, but the whale is here now; ✗ <b>has swum</b> — present perfect gives a completed result, not something we are watching happen."},{"id":"gv-kc-15-2","level":"kc","focus":"word-choice","q":"Lan ______ the early bus to the beach because she woke up late.","options":["missed","lost","failed","dropped"],"correct":0,"answer":"missed","vi":"Lan lỡ chuyến xe buýt sớm ra biển vì cô ấy dậy muộn.","explanation":"You <b>miss</b> a bus, train or plane when you arrive too late to catch it, and <b>woke up late</b> is the clue. ✗ <b>lost</b> — you lose an object, a match or your way, not a vehicle you failed to catch; ✗ <b>failed</b> — you fail an exam or fail to do something; a bus cannot be its object; ✗ <b>dropped</b> — to let something fall from your hands."},{"id":"gv-kc-15-3","level":"kc","focus":"collocation","q":"The boat trip was cancelled because of ______ winds along the coast.","options":["heavy","hard","strong","big"],"correct":2,"answer":"strong","vi":"Chuyến đi thuyền bị hủy vì gió mạnh dọc bờ biển.","explanation":"Wind that blows with great force is <b>strong wind</b>; the clue is that it was powerful enough to <b>cancel the boat trip</b>. ✗ <b>heavy</b> — collocates with rain, snow and traffic, not wind; ✗ <b>hard</b> — describes work, questions or a hard frost, never wind; ✗ <b>big</b> — used for size (a big wave), not for the force of wind."},{"id":"gv-kc-15-4","level":"kc","focus":"idiom","q":"The hotel was lovely, and the free boat trip to the island was ______.","options":["the tip of the iceberg","a piece of cake","the last straw","the icing on the cake"],"correct":3,"answer":"the icing on the cake","vi":"Khách sạn rất đẹp, và chuyến đi thuyền miễn phí ra đảo là phần thưởng tuyệt vời thêm vào.","explanation":"<b>The icing on the cake</b> is an extra good thing that makes an already good situation (<b>the hotel was lovely</b>) even better. ✗ <b>the tip of the iceberg</b> — a small visible part of a much bigger problem; ✗ <b>a piece of cake</b> — something very easy to do; ✗ <b>the last straw</b> — the final problem that makes you lose patience, the opposite of good news."},{"id":"gv-kc-15-5","level":"kc","focus":"phrasal-verb","q":"Let's stay inside the tent until the storm ______.","options":["blows over","blows up","blows out","breaks down"],"correct":0,"answer":"blows over","vi":"Chúng ta hãy ở trong lều cho đến khi cơn bão qua đi.","explanation":"A storm or an argument <b>blows over</b> when it passes and things return to normal; <b>stay inside until</b> shows we are waiting for it to end. ✗ <b>blows up</b> — explodes, or suddenly loses its temper; ✗ <b>blows out</b> — puts out a candle or flame with a breath; ✗ <b>breaks down</b> — a car or machine stops working, or a person starts crying."},{"id":"gv-kc-15-6","level":"kc","focus":"modal","q":"The dog ______ the gate open by itself; it was locked all night.","options":["mustn't have pushed","can't have pushed","shouldn't have pushed","needn't have pushed"],"correct":1,"answer":"can't have pushed","vi":"Con chó không thể nào tự đẩy cổng mở được; cổng đã bị khóa suốt đêm.","explanation":"<b>Can't have + past participle</b> is a confident deduction that something did NOT happen; the clue <b>it was locked all night</b> makes it impossible. ✗ <b>mustn't have pushed</b> — 'must have' is for positive deductions only; its negative is 'can't have'; ✗ <b>shouldn't have pushed</b> — criticises something that really happened; ✗ <b>needn't have pushed</b> — says it was done but was unnecessary."},{"id":"gv-kc-15-7","level":"kc","focus":"relative","q":"The whole class passed the chemistry test, ______ the teacher very proud.","options":["that made","what made","which made","who made"],"correct":2,"answer":"which made","vi":"Cả lớp đều đậu bài kiểm tra Hóa, điều đó khiến cô giáo rất tự hào.","explanation":"After a comma, <b>which</b> can refer back to the WHOLE clause before it (the fact that everyone passed), so <b>, which made</b> is right. ✗ <b>that made</b> — 'that' cannot start a non-defining clause after a comma; ✗ <b>what made</b> — 'what' means 'the thing that' and cannot refer back to a clause; ✗ <b>who made</b> — 'who' is for people, and no person is the antecedent here."},{"id":"gv-kc-15-8","level":"kc","focus":"word-choice","q":"Our school team ______ the visitors 3–1 in the final of the eco-quiz.","options":["won","gained","achieved","beat"],"correct":3,"answer":"beat","vi":"Đội trường mình đã thắng đội khách 3–1 trong trận chung kết cuộc thi đố vui về môi trường.","explanation":"You <b>beat</b> an opponent, and the object here is <b>the visitors</b> (the other team). ✗ <b>won</b> — you win a match, a game or a prize, not the other team; ✗ <b>gained</b> — you gain experience, weight or confidence, never an opponent; ✗ <b>achieved</b> — you achieve a goal or success, never a team."},{"id":"gv-kc-15-9","level":"kc","focus":"tense","q":"By next summer, my family ______ every beach in Da Nang.","options":["will have visited","will visit","has visited","is visiting"],"correct":0,"answer":"will have visited","vi":"Đến mùa hè năm sau, gia đình tôi sẽ đi hết mọi bãi biển ở Đà Nẵng.","explanation":"<b>By next summer</b> marks a deadline in the future, and an action finished before that deadline takes the future perfect <b>will have visited</b>. ✗ <b>will visit</b> — simple future says only that it happens later, not that it is complete by then; ✗ <b>has visited</b> — present perfect links to now, not to a future point; ✗ <b>is visiting</b> — an action in progress, not one finished."},{"id":"gv-kc-15-10","level":"kc","focus":"article-quantifier","q":"Don't worry about lunch – Mum has packed ______ sandwiches for the whole group.","options":["much","plenty of","a great deal of","a large amount of"],"correct":1,"answer":"plenty of","vi":"Đừng lo về bữa trưa – mẹ đã gói rất nhiều bánh mì kẹp cho cả nhóm rồi.","explanation":"<b>Plenty of</b> (more than enough) is used with BOTH plural countable nouns like <b>sandwiches</b> and uncountable nouns. ✗ <b>much</b> — only with uncountable nouns (much food), and mainly in negatives and questions; ✗ <b>a great deal of</b> — only with uncountable nouns (a great deal of time); ✗ <b>a large amount of</b> — only with uncountable nouns; countable plurals take 'a large number of'."},{"id":"gv-kc-15-11","level":"kc","focus":"gerund-infinitive","q":"Before our trip to Australia, Dad spent every evening ______ his English.","options":["to brush up on","brush up on","brushing up on","brushed up on"],"correct":2,"answer":"brushing up on","vi":"Trước chuyến đi Úc, bố dành mỗi tối để ôn lại tiếng Anh.","explanation":"<b>Spend + time + -ing</b> is a fixed pattern, so <b>spent every evening brushing up on</b> (improving his rusty English) is right. ✗ <b>to brush up on</b> — 'spend time' never takes a to-infinitive; ✗ <b>brush up on</b> — a bare verb cannot follow the noun 'evening'; ✗ <b>brushed up on</b> — a second past tense would need 'and' to join it to 'spent'."},{"id":"gv-kc-15-12","level":"kc","focus":"collocation","q":"We ______ hundreds of photos of the elephants at the sanctuary.","options":["made","did","caught","took"],"correct":3,"answer":"took","vi":"Chúng tôi đã chụp hàng trăm bức ảnh về những con voi ở khu bảo tồn.","explanation":"The English collocation is <b>take a photo</b>, so <b>took hundreds of photos</b> is right. ✗ <b>made</b> — you make a cake or a decision; 'make a photo' is a direct-translation error; ✗ <b>did</b> — 'do' goes with homework, the shopping or a job, not photos; ✗ <b>caught</b> — you catch a ball, a bus or a cold, not a photo."},{"id":"gv-kc-15-13","level":"kc","focus":"word-choice","q":"The zoo's plan to breed rare parrots ended in ______ when none of the eggs hatched.","options":["failure","defeat","loss","mistake"],"correct":0,"answer":"failure","vi":"Kế hoạch nhân giống vẹt quý hiếm của sở thú đã thất bại khi không quả trứng nào nở.","explanation":"A plan that does not reach its aim <b>ends in failure</b>; the clue is <b>none of the eggs hatched</b>. ✗ <b>defeat</b> — being beaten by an opponent in a contest or war, but the zoo was not competing; ✗ <b>loss</b> — losing something you had (a loss of money), not a plan that did not work; ✗ <b>mistake</b> — a wrong action or choice, not the result of a plan."},{"id":"gv-kc-15-14","level":"kc","focus":"linking","q":"Living in the city centre is exciting; ______, the rent costs a fortune.","options":["in addition","on the other hand","as a result","for instance"],"correct":1,"answer":"on the other hand","vi":"Sống ở trung tâm thành phố rất thú vị; mặt khác, tiền thuê nhà thì đắt khủng khiếp.","explanation":"<b>On the other hand</b> introduces the opposite side of a situation: exciting BUT <b>the rent costs a fortune</b>. ✗ <b>in addition</b> — adds a similar point, but expensive rent is a contrast, not another plus; ✗ <b>as a result</b> — shows a consequence, and high rent is not caused by excitement; ✗ <b>for instance</b> — gives an example of the previous point, not a disadvantage."},{"id":"gv-kc-15-15","level":"kc","focus":"phrasal-verb","q":"Choosing where to go on holiday usually ______ how much money you have.","options":["boils over","breaks down","boils down to","puts up with"],"correct":2,"answer":"boils down to","vi":"Việc chọn đi nghỉ ở đâu thường quy về chuyện bạn có bao nhiêu tiền.","explanation":"Something <b>boils down to</b> one thing when that thing is the real deciding factor, here <b>how much money you have</b>. ✗ <b>boils over</b> — liquid rises and spills from a pan, or anger explodes; it also has no 'to' for the object; ✗ <b>breaks down</b> — stops working, or is divided into parts; ✗ <b>puts up with</b> — tolerates something unpleasant."},{"id":"gv-kc-15-16","level":"kc","focus":"modal","q":"You ______ bring a tent; the campsite lends them to visitors for free.","options":["mustn't","can't","shouldn't","needn't"],"correct":3,"answer":"needn't","vi":"Bạn không cần mang lều; khu cắm trại cho khách mượn miễn phí.","explanation":"<b>Needn't</b> means it is not necessary, and the reason <b>the campsite lends them for free</b> shows a tent is unnecessary, not forbidden. ✗ <b>mustn't</b> — a prohibition (you are not allowed to), which the sentence does not give; ✗ <b>can't</b> — impossibility or 'not allowed', but bringing a tent is possible; ✗ <b>shouldn't</b> — advice that it is a bad idea, not a lack of need."},{"id":"gv-kc-15-17","level":"kc","focus":"tense","q":"My family ______ in this fishing village since my grandfather was a boy.","options":["have lived","live","lived","are living"],"correct":0,"answer":"have lived","vi":"Gia đình tôi đã sống ở làng chài này từ khi ông tôi còn là một cậu bé.","explanation":"<b>Since + a past starting point</b> (my grandfather was a boy) for a situation still true now takes the present perfect <b>have lived</b>. ✗ <b>live</b> — present simple gives no link to the past starting point; ✗ <b>lived</b> — past simple would mean the family no longer lives there; ✗ <b>are living</b> — present continuous describes now only and does not go with 'since'."},{"id":"gv-kc-15-18","level":"kc","focus":"conditional","q":"Lan wishes she ______ her camera to the bird park yesterday.","options":["brought","had brought","has brought","would bring"],"correct":1,"answer":"had brought","vi":"Lan ước gì hôm qua cô ấy đã mang máy ảnh đến công viên chim.","explanation":"A regret about the past (<b>yesterday</b>) uses <b>wish + past perfect</b>, so <b>had brought</b> is right. ✗ <b>brought</b> — wish + past simple is for a present situation we want to be different, not a finished past event; ✗ <b>has brought</b> — the present perfect is never used after 'wish'; ✗ <b>would bring</b> — wish + would complains about someone else's future behaviour, not a past regret."},{"id":"gv-kc-15-19","level":"kc","focus":"word-choice","q":"It took the campers three ______ to light the fire in the wet forest.","options":["efforts","trials","attempts","tests"],"correct":2,"answer":"attempts","vi":"Những người cắm trại phải thử đến ba lần mới nhóm được lửa trong khu rừng ẩm ướt.","explanation":"An <b>attempt</b> is one act of trying, so you can count <b>three attempts</b> before success. ✗ <b>efforts</b> — effort is the energy you put in; 'three efforts' does not count tries; ✗ <b>trials</b> — a scientific experiment or a court case, not a try at lighting a fire; ✗ <b>tests</b> — a check of knowledge or quality, not an act of trying."},{"id":"gv-kc-15-20","level":"kc","focus":"relative","q":"The beach ______ we camped last year is now closed to protect the sea turtles.","options":["which","that","whom","where"],"correct":3,"answer":"where","vi":"Bãi biển nơi chúng tôi cắm trại năm ngoái nay đã đóng cửa để bảo vệ rùa biển.","explanation":"<b>Where</b> replaces a place adverb: we camped <b>there</b> (on the beach), so no preposition is needed. ✗ <b>which</b> — would need a preposition ('on which we camped') because 'camp' takes no object; ✗ <b>that</b> — same problem: 'that we camped' leaves the verb with nothing to do; ✗ <b>whom</b> — only for people as an object, never for a place."},{"id":"gv-kc-15-21","level":"kc","focus":"idiom","q":"The showers at the campsite were not ______, so we complained to the owner.","options":["up to scratch","up in the air","up in arms","under the weather"],"correct":0,"answer":"up to scratch","vi":"Nhà tắm ở khu cắm trại không đạt yêu cầu, nên chúng tôi đã phàn nàn với chủ khu.","explanation":"<b>Up to scratch</b> means of an acceptable standard; the clue is that the showers were bad enough to <b>complain</b> about. ✗ <b>up in the air</b> — still undecided (used of plans); ✗ <b>up in arms</b> — very angry and protesting; a person is up in arms, not a shower; ✗ <b>under the weather</b> — slightly ill, used of people."},{"id":"gv-kc-15-22","level":"kc","focus":"inversion","q":"______ had we reached the campsite when it began to pour with rain.","options":["No sooner","Hardly","Not until","Only when"],"correct":1,"answer":"Hardly","vi":"Chúng tôi vừa mới tới khu cắm trại thì trời bắt đầu mưa như trút nước.","explanation":"<b>Hardly + had + subject + past participle ... when</b> means the second event followed the first immediately; the clue is <b>when</b> after the comma. ✗ <b>No sooner</b> — also takes inversion but pairs with 'than', not 'when'; ✗ <b>Not until</b> — the inversion comes in the MAIN clause after the time clause ('Not until we arrived did it rain'), not straight after these words; ✗ <b>Only when</b> — same pattern: 'Only when we arrived did it rain'."},{"id":"gv-kc-15-23","level":"kc","focus":"collocation","q":"The guide told us to ______ a close eye on our bags at the night market.","options":["hold","take","keep","put"],"correct":2,"answer":"keep","vi":"Hướng dẫn viên bảo chúng tôi để mắt kỹ tới túi xách của mình ở chợ đêm.","explanation":"The fixed expression is <b>keep an eye on</b> something (watch it carefully), so <b>keep a close eye on our bags</b> is right. ✗ <b>hold</b> — you hold a bag or a hand, but there is no idiom 'hold an eye on'; ✗ <b>take</b> — 'take a look at' exists, but 'take an eye on' does not; ✗ <b>put</b> — you put something somewhere; there is no idiom with 'eye on'."},{"id":"gv-kc-15-24","level":"kc","focus":"tense","q":"Mai ______ her passport twice before she finally found it in her coat pocket.","options":["has checked","checks","is checking","had checked"],"correct":3,"answer":"had checked","vi":"Mai đã kiểm tra hộ chiếu hai lần trước khi cuối cùng tìm thấy nó trong túi áo khoác.","explanation":"The checking happened <b>before</b> another past action (<b>before she finally found it</b>), so the earlier action takes the past perfect <b>had checked</b>. ✗ <b>has checked</b> — present perfect links to now and cannot sit with a finished past clause; ✗ <b>checks</b> — present simple is for habits, not a past story; ✗ <b>is checking</b> — an action in progress now, not one before a past event."},{"id":"gv-kc-15-25","level":"kc","focus":"word-choice","q":"The baby turtle ______ to reach the sea before the seagulls noticed it.","options":["managed","succeeded","achieved","reached"],"correct":0,"answer":"managed","vi":"Chú rùa con đã tìm được cách ra tới biển trước khi lũ mòng biển phát hiện.","explanation":"<b>Manage to + verb</b> means to succeed in doing something difficult, and the to-infinitive <b>to reach</b> is the clue. ✗ <b>succeeded</b> — needs 'in + -ing' (succeeded in reaching), never a to-infinitive; ✗ <b>achieved</b> — takes a noun object (achieve a goal), not to + verb; ✗ <b>reached</b> — already means 'arrive at' and takes a place as object; 'reached to reach' repeats itself."},{"id":"gv-kc-16-1","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Mai: He ______ dumplings in the kitchen since noon.","options":["makes","is making","has been making","made"],"correct":2,"answer":"has been making","vi":"Lan: Nam đâu rồi? / Mai: Cậu ấy gói bánh trong bếp từ trưa tới giờ.","explanation":"<b>Since noon</b> + an action still going on now (\"Where's Nam?\" – he is still in the kitchen) calls for the present perfect continuous <b>has been making</b>.<br>✗ <b>makes</b> — present simple states a habit, not an action running from noon until now; ✗ <b>is making</b> — present continuous cannot take <b>since</b> + a starting point; ✗ <b>made</b> — past simple means the action is finished, but he is still there."},{"id":"gv-kc-16-2","level":"kc","focus":"word-choice","q":"I still ______ Nam fifty thousand dong for the bánh mì he bought me yesterday.","options":["owe","own","lend","keep"],"correct":0,"answer":"owe","vi":"Tôi vẫn còn nợ Nam năm mươi nghìn tiền ổ bánh mì cậu ấy mua cho tôi hôm qua.","explanation":"<b>Owe</b> someone money = still have to pay it back, which fits <b>still</b> and <b>for the bánh mì he bought me</b>.<br>✗ <b>own</b> — possess something (you cannot \"own Nam money\"); ✗ <b>lend</b> — give money OUT for a time, the opposite direction; ✗ <b>keep</b> — hold on to something; it does not take a person + a sum like this."},{"id":"gv-kc-16-3","level":"kc","focus":"idiom","q":"Lan: Sorry, I'm an hour late for the dumpling class! / Nam: Well, ______.","options":["better safe than sorry","better late than never","easier said than done","no pain, no gain"],"correct":1,"answer":"better late than never","vi":"Lan: Xin lỗi, mình đến lớp gói bánh trễ cả tiếng! / Nam: Thôi, trễ còn hơn không.","explanation":"Lan apologises for being <b>an hour late</b>, and Nam forgives her: <b>better late than never</b> = arriving late is still better than not coming at all.<br>✗ <b>better safe than sorry</b> — take precautions to avoid risk; ✗ <b>easier said than done</b> — a plan is harder to do than to talk about; ✗ <b>no pain, no gain</b> — you must work hard to get results. None of these answers an apology for lateness."},{"id":"gv-kc-16-4","level":"kc","focus":"collocation","q":"Lan ______ a photo of the lantern display and sent it to her cousin in Da Nang.","options":["made","did","got","took"],"correct":3,"answer":"took","vi":"Lan chụp một tấm ảnh gian trưng bày lồng đèn rồi gửi cho em họ ở Đà Nẵng.","explanation":"The fixed collocation is <b>take a photo</b>; the past tense <b>took</b> matches <b>sent</b>.<br>✗ <b>made</b> — you make a cake or a mistake, not a photo; ✗ <b>did</b> — do goes with homework, the dishes, not a photo; ✗ <b>got</b> — get a photo = receive one, but Lan is the one photographing the display and sending it."},{"id":"gv-kc-16-5","level":"kc","focus":"phrasal-verb","q":"Everyone in our street ______ to buy lanterns for the Mid-Autumn party.","options":["chipped in","dropped in","chipped away","gave in"],"correct":0,"answer":"chipped in","vi":"Cả xóm tôi góp tiền mua lồng đèn cho buổi tiệc Trung thu.","explanation":"<b>Everyone</b> paying towards <b>lanterns for the party</b> = a shared cost, so <b>chipped in</b> (each person gives some money).<br>✗ <b>dropped in</b> — make a short, casual visit; ✗ <b>chipped away</b> — remove something bit by bit, and it takes <b>at</b> not <b>to</b>; ✗ <b>gave in</b> — surrender or stop resisting."},{"id":"gv-kc-16-6","level":"kc","focus":"modal","q":"Lan: The bánh chưng is burnt! / Nam: You ______ the heat on so high.","options":["needn't have left","mustn't have left","shouldn't have left","couldn't have left"],"correct":2,"answer":"shouldn't have left","vi":"Lan: Bánh chưng bị khét rồi! / Nam: Đáng lẽ cậu không nên để lửa to như thế.","explanation":"The bánh chưng is <b>burnt</b>, so Nam criticises a past mistake: <b>shouldn't have + past participle</b> = you did it, and it was wrong.<br>✗ <b>needn't have left</b> — it was unnecessary, not a mistake; ✗ <b>couldn't have left</b> — a deduction that it was impossible, but she clearly did leave it high; ✗ <b>mustn't have left</b> — English uses <b>can't have</b> for a negative past deduction; <b>mustn't have</b> is not a standard form here."},{"id":"gv-kc-16-7","level":"kc","focus":"word-choice","q":"We can't ______ to eat out every night, so I cook at home most days.","options":["pay","afford","spend","cost"],"correct":1,"answer":"afford","vi":"Nhà tôi không đủ tiền ăn ngoài mỗi tối, nên hầu như ngày nào tôi cũng nấu ở nhà.","explanation":"<b>Can't afford to + verb</b> = not have enough money to do it, which explains <b>so I cook at home</b>.<br>✗ <b>pay</b> — pay needs an amount or a person (<b>pay $10 / pay the waiter</b>), not <b>to eat</b>; ✗ <b>spend</b> — spend money/time <b>on</b> something, not <b>spend to eat</b>; ✗ <b>cost</b> — a thing costs money; a person cannot be the subject of <b>cost</b> like this."},{"id":"gv-kc-16-8","level":"kc","focus":"relative","q":"The town ______ my grandparents live is famous for its floating market.","options":["which","who","that","where"],"correct":3,"answer":"where","vi":"Thị trấn nơi ông bà tôi sống nổi tiếng với chợ nổi.","explanation":"After the place noun <b>the town</b>, the clause <b>my grandparents live</b> is already complete (subject + verb), so it needs the relative adverb <b>where</b> (= in which).<br>✗ <b>which</b> — a relative pronoun must be the subject or object of the clause; here it would need <b>in which</b>; ✗ <b>that</b> — same problem, and <b>that</b> cannot follow a preposition; ✗ <b>who</b> — only for people, and <b>town</b> is a place."},{"id":"gv-kc-16-9","level":"kc","focus":"tense","q":"This time next week we ______ mooncakes at the Mid-Autumn fair.","options":["will be eating","are eating","will have eaten","eat"],"correct":0,"answer":"will be eating","vi":"Giờ này tuần sau chúng ta sẽ đang ăn bánh trung thu ở hội chợ Trung thu.","explanation":"<b>This time next week</b> pictures an action in progress at a future moment, so the future continuous <b>will be eating</b>.<br>✗ <b>are eating</b> — present continuous is for now or a fixed arrangement, not a scene at a future moment; ✗ <b>will have eaten</b> — future perfect means finished BEFORE that time, but we will be in the middle of eating; ✗ <b>eat</b> — present simple only works for timetables (<b>the fair opens at 6</b>)."},{"id":"gv-kc-16-10","level":"kc","focus":"collocation","q":"If we don't hurry, we'll ______ the last bus home.","options":["lose","miss","drop","fail"],"correct":1,"answer":"miss","vi":"Nếu không nhanh lên, chúng ta sẽ lỡ chuyến xe buýt cuối về nhà.","explanation":"You <b>miss</b> a bus, train or plane = arrive too late to catch it, which fits <b>if we don't hurry</b>.<br>✗ <b>lose</b> — you lose a thing you owned (keys, a match), not a bus you never boarded; ✗ <b>drop</b> — let something fall; ✗ <b>fail</b> — fail an exam or fail to do something; it takes <b>to</b> + verb, not <b>the bus</b>."},{"id":"gv-kc-16-11","level":"kc","focus":"preposition","q":"My mother is very proud ______ her recipe for fish sauce dressing.","options":["on","with","of","about"],"correct":2,"answer":"of","vi":"Mẹ tôi rất tự hào về công thức nước mắm chấm của bà.","explanation":"The adjective <b>proud</b> takes the fixed preposition <b>of</b>: <b>proud of</b> someone/something.<br>✗ <b>on</b> — not used after proud (<b>on</b> follows <b>keen, depend</b>); ✗ <b>with</b> — goes with <b>pleased / satisfied with</b>, not proud; ✗ <b>about</b> — goes with <b>happy / worried about</b>; <b>proud</b> never takes it."},{"id":"gv-kc-16-12","level":"kc","focus":"word-choice","q":"Remember to ______ the cookery book to the library by Friday.","options":["borrow","lend","rent","return"],"correct":3,"answer":"return","vi":"Nhớ trả cuốn sách nấu ăn cho thư viện trước thứ Sáu nhé.","explanation":"<b>To the library by Friday</b> means giving the book BACK: <b>return</b>.<br>✗ <b>borrow</b> — take something for a while (you borrow FROM the library); ✗ <b>lend</b> — give your OWN thing to someone temporarily, but the book belongs to the library; ✗ <b>rent</b> — pay money to use a room, car or bike; library books are not rented."},{"id":"gv-kc-16-13","level":"kc","focus":"phrasal-verb","q":"Half the class ______ flu after eating ice cream in the rain at the fair.","options":["came up with","came down with","put up with","came across"],"correct":1,"answer":"came down with","vi":"Nửa lớp bị cúm sau khi ăn kem dưới mưa ở hội chợ.","explanation":"<b>Flu</b> after ice cream in the rain = falling ill, so <b>came down with</b> (start to suffer from an illness).<br>✗ <b>came up with</b> — think of an idea or plan; ✗ <b>put up with</b> — tolerate something annoying; ✗ <b>came across</b> — find or meet by chance."},{"id":"gv-kc-16-14","level":"kc","focus":"article-quantifier","q":"Wrapping bánh chưng takes ______ patience, so my grandmother starts early in the morning.","options":["a great deal of","a large number of","a few","many"],"correct":0,"answer":"a great deal of","vi":"Gói bánh chưng cần rất nhiều kiên nhẫn, nên bà tôi bắt đầu từ sáng sớm.","explanation":"<b>Patience</b> is an uncountable noun, so the quantifier must be one for uncountables: <b>a great deal of</b> (= a lot of).<br>✗ <b>a large number of</b> — only with plural countables (<b>a large number of guests</b>); ✗ <b>a few</b> — plural countables only, and \"a few patience\" is impossible; ✗ <b>many</b> — plural countables only; uncountables take <b>much</b>."},{"id":"gv-kc-16-15","level":"kc","focus":"idiom","q":"Nam keeps promising to help clean up after the festival, but ______.","options":["practice makes perfect","every cloud has a silver lining","actions speak louder than words","two heads are better than one"],"correct":2,"answer":"actions speak louder than words","vi":"Nam cứ hứa sẽ giúp dọn dẹp sau lễ hội, nhưng hành động mới nói lên tất cả.","explanation":"<b>Keeps promising ... but</b> contrasts words with (missing) deeds, so <b>actions speak louder than words</b> = what you do matters more than what you say.<br>✗ <b>practice makes perfect</b> — repeating a skill makes you good at it; ✗ <b>every cloud has a silver lining</b> — something good comes out of bad luck; ✗ <b>two heads are better than one</b> — working together beats working alone."},{"id":"gv-kc-16-16","level":"kc","focus":"gerund-infinitive","q":"We're all looking forward ______ the lantern parade next week.","options":["to see","seeing","see","to seeing"],"correct":3,"answer":"to seeing","vi":"Tất cả chúng tôi đều mong được xem lễ rước đèn tuần tới.","explanation":"In <b>look forward to</b>, <b>to</b> is a preposition, not part of an infinitive, so it must be followed by a gerund: <b>to seeing</b>.<br>✗ <b>to see</b> — an infinitive after a preposition is impossible; ✗ <b>seeing</b> — drops the required <b>to</b> of the phrase <b>look forward TO</b>; ✗ <b>see</b> — a bare verb cannot follow <b>look forward</b> at all."},{"id":"gv-kc-16-17","level":"kc","focus":"word-choice","q":"The restaurant will ______ your phở to your door within thirty minutes.","options":["order","deliver","serve","receive"],"correct":1,"answer":"deliver","vi":"Nhà hàng sẽ giao phở tới tận cửa nhà bạn trong vòng ba mươi phút.","explanation":"<b>To your door within thirty minutes</b> describes bringing goods to a customer's home: <b>deliver</b>.<br>✗ <b>order</b> — ask for food; the customer orders, not the restaurant; ✗ <b>serve</b> — bring food to the table inside the restaurant, not to your door; ✗ <b>receive</b> — get something; the customer receives the phở, the restaurant does not."},{"id":"gv-kc-16-18","level":"kc","focus":"linking","q":"You won't find a seat at the night market food stalls ______ you get there before six.","options":["unless","if","although","so that"],"correct":0,"answer":"unless","vi":"Bạn sẽ không kiếm được chỗ ngồi ở các quầy ăn chợ đêm trừ khi bạn tới đó trước sáu giờ.","explanation":"<b>Unless</b> = if ... not: you won't find a seat if you do <b>not</b> get there before six, which is the logical warning.<br>✗ <b>if</b> — gives the reverse meaning (arriving early would cost you a seat); ✗ <b>although</b> — shows contrast between two facts, not a condition; ✗ <b>so that</b> — shows purpose and would need a modal (<b>so that you can...</b>)."},{"id":"gv-kc-16-19","level":"kc","focus":"tense","q":"Nam: Why weren't you at the parade? / Lan: Something ______ at home just as I was leaving.","options":["has cropped up","crops up","is cropping up","cropped up"],"correct":3,"answer":"cropped up","vi":"Nam: Sao cậu không đến xem diễu hành? / Lan: Có chuyện phát sinh ở nhà đúng lúc mình chuẩn bị đi.","explanation":"<b>Just as I was leaving</b> fixes the event at one finished moment in the past, so the past simple <b>cropped up</b> (= happened unexpectedly).<br>✗ <b>has cropped up</b> — present perfect cannot combine with a definite past moment like <b>as I was leaving</b>; ✗ <b>crops up</b> — present simple states a habit, not a single past event; ✗ <b>is cropping up</b> — present continuous is for something happening right now."},{"id":"gv-kc-16-20","level":"kc","focus":"conditional","q":"I wish I ______ how to make mooncakes as well as my grandmother does.","options":["know","had known","knew","would know"],"correct":2,"answer":"knew","vi":"Ước gì tôi biết làm bánh trung thu ngon như bà tôi.","explanation":"A wish about a PRESENT situation (<b>as well as my grandmother does</b>) uses <b>wish + past simple</b>: <b>I wish I knew</b>.<br>✗ <b>know</b> — a present form is never used after <b>wish</b>; ✗ <b>had known</b> — past perfect expresses regret about the PAST, but <b>does</b> shows the wish is about now; ✗ <b>would know</b> — <b>wish + would</b> is for someone else's annoying behaviour, not for the speaker's own knowledge."},{"id":"gv-kc-16-21","level":"kc","focus":"collocation","q":"Could you ______ the table while I fry the fish?","options":["put","lay","place","fix"],"correct":1,"answer":"lay","vi":"Con dọn bàn ăn giúp mẹ trong lúc mẹ chiên cá nhé?","explanation":"The fixed collocation is <b>lay the table</b> (also <b>set the table</b>) = put out plates and cutlery before a meal, which fits <b>while I fry the fish</b>.<br>✗ <b>put</b> — put needs a place (<b>put the table by the wall</b>); ✗ <b>place</b> — same as put: position an object somewhere; ✗ <b>fix</b> — repair or attach; nothing here is broken."},{"id":"gv-kc-16-22","level":"kc","focus":"passive","q":"Red envelopes ______ to children on the first morning of Tet.","options":["are given","give","are giving","given"],"correct":0,"answer":"are given","vi":"Bao lì xì được trao cho trẻ em vào sáng mùng Một Tết.","explanation":"<b>Red envelopes</b> do not give, they are given, and <b>on the first morning of Tet</b> is a yearly custom, so present simple passive: <b>are given</b> (be + past participle).<br>✗ <b>give</b> — active; the envelopes would be doing the giving; ✗ <b>are giving</b> — active continuous, same problem, and a custom is not in progress now; ✗ <b>given</b> — a past participle alone has no auxiliary, so the sentence has no verb."},{"id":"gv-kc-16-23","level":"kc","focus":"word-choice","q":"Can you ______ me a few minutes to explain the new bus route?","options":["share","save","spend","spare"],"correct":3,"answer":"spare","vi":"Bạn có thể dành cho mình vài phút để giải thích tuyến xe buýt mới không?","explanation":"<b>Spare someone a few minutes</b> = give them a little of your time; the pattern is <b>spare + person + time</b>.<br>✗ <b>share</b> — divide something between people; you share food, not \"share me a few minutes\"; ✗ <b>save</b> — keep something for later; \"save me a few minutes\" would mean reduce the time I need, not give me time; ✗ <b>spend</b> — use time yourself; it never takes a person as its object."},{"id":"gv-kc-16-24","level":"kc","focus":"reported","q":"Mai said she ______ the flower market the next morning to buy peach blossom.","options":["will visit","visits","would visit","has visited"],"correct":2,"answer":"would visit","vi":"Mai nói sáng hôm sau cô ấy sẽ đi chợ hoa mua cành đào.","explanation":"Reporting verb in the past (<b>said</b>) + <b>the next morning</b> (the reported form of \"tomorrow morning\") means the tense shifts back: <b>will visit</b> → <b>would visit</b>.<br>✗ <b>will visit</b> — no backshift after <b>said</b>; ✗ <b>visits</b> — present simple states a habit and ignores the backshift; ✗ <b>has visited</b> — present perfect means already done, but <b>the next morning</b> is still in the future from her viewpoint."},{"id":"gv-kc-16-25","level":"kc","focus":"comparison","q":"The traffic in the city centre is ______ than it was five years ago.","options":["more worse","far worse","much worst","worst"],"correct":1,"answer":"far worse","vi":"Giao thông ở trung tâm thành phố tệ hơn nhiều so với năm năm trước.","explanation":"<b>Than</b> needs a comparative; <b>bad</b> is irregular (<b>worse</b>), and <b>far</b> strengthens it: <b>far worse than</b>.<br>✗ <b>more worse</b> — a double comparative; <b>worse</b> already means <b>more bad</b>; ✗ <b>much worst</b> — <b>worst</b> is the superlative and cannot follow <b>much</b> or precede <b>than</b>; ✗ <b>worst</b> — superlative, used with <b>the</b> for three or more, not with <b>than</b>."},{"id":"gv-ch-17-1","level":"ch","focus":"tense","q":"By the end of this decade, the carmaker ______ more than half of its plants to fully automated lines.","options":["has converted","will convert","is converting","will have converted"],"correct":3,"answer":"will have converted","vi":"Đến cuối thập kỷ này, hãng xe sẽ chuyển đổi xong hơn một nửa số nhà máy của mình sang dây chuyền hoàn toàn tự động.","explanation":"<b>By the end of this decade</b> is a future deadline, and an action finished before a future point takes the future perfect: <b>will have converted</b>. ✗ <b>has converted</b> — present perfect reports what is already done now, not by a future date; ✗ <b>will convert</b> — simple future says the action happens, not that it is complete by the deadline; ✗ <b>is converting</b> — present continuous describes something in progress now."},{"id":"gv-ch-17-2","level":"ch","focus":"word-choice","q":"In an effort to curb obesity, the government has decided to ______ a levy on sugary drinks from next April.","options":["inflict","impose","impart","install"],"correct":1,"answer":"impose","vi":"Nhằm kiềm chế béo phì, chính phủ đã quyết định áp một khoản thuế lên đồ uống có đường từ tháng Tư năm sau.","explanation":"Governments <b>impose</b> a tax, levy, ban or fine — the verb that collocates with <b>a levy</b>. ✗ <b>inflict</b> — cause pain, damage or defeat on someone; ✗ <b>impart</b> — pass on knowledge, news or a flavour; ✗ <b>install</b> — fit equipment or software in place."},{"id":"gv-ch-17-3","level":"ch","focus":"idiom","q":"If the shares keep sliding, you may be wiser to ______ now than to wait years for a recovery that may never come.","options":["cut corners","cut a long story short","cut your losses","cut your teeth"],"correct":2,"answer":"cut your losses","vi":"Nếu cổ phiếu tiếp tục trượt giá, có lẽ bạn nên cắt lỗ ngay bây giờ thay vì chờ đợi nhiều năm cho một sự phục hồi có thể chẳng bao giờ đến.","explanation":"The clue <b>shares keep sliding … than wait years for a recovery</b> points to giving up before losing more: <b>cut your losses</b> = stop a failing venture early. ✗ <b>cut corners</b> — do a job cheaply or carelessly; ✗ <b>cut a long story short</b> — skip to the summary; ✗ <b>cut your teeth</b> — gain your first experience of something."},{"id":"gv-ch-17-4","level":"ch","focus":"collocation","q":"Regulators must ______ a balance between protecting consumers and leaving room for innovation in the fintech sector.","options":["strike","hit","beat","knock"],"correct":0,"answer":"strike","vi":"Các cơ quan quản lý phải tìm được sự cân bằng giữa việc bảo vệ người tiêu dùng và tạo dư địa cho đổi mới trong lĩnh vực công nghệ tài chính.","explanation":"The fixed collocation is <b>strike a balance</b> (also strike a deal, strike a chord); the clue is <b>a balance between</b>. ✗ <b>hit</b> — hit a target or a wall, never a balance; ✗ <b>beat</b> — beat an opponent or a record, not a balance; ✗ <b>knock</b> — knock on a door or knock something over, no link with balance."},{"id":"gv-ch-17-5","level":"ch","focus":"phrasal-verb","q":"Once the outcry over the product recall had ______, the company quietly relaunched the toy under a new name.","options":["died out","died away","died down","died off"],"correct":2,"answer":"died down","vi":"Khi làn sóng phẫn nộ về vụ thu hồi sản phẩm đã lắng xuống, công ty lặng lẽ tung lại món đồ chơi dưới một cái tên mới.","explanation":"Anger, noise or a controversy <b>dies down</b> = gradually becomes less intense, which fits an <b>outcry</b> that later lets the company relaunch. ✗ <b>died out</b> — disappear completely, used of species or customs; ✗ <b>died away</b> — fade to silence, used of a sound or wind; ✗ <b>died off</b> — die one after another, used of living things."},{"id":"gv-ch-17-6","level":"ch","focus":"relative","q":"The economist ______ forecasts the ministry relied on has admitted that her model ignored energy prices entirely.","options":["whom","which","whose","that"],"correct":2,"answer":"whose","vi":"Nhà kinh tế có các dự báo mà bộ đã dựa vào thừa nhận rằng mô hình của bà hoàn toàn bỏ qua giá năng lượng.","explanation":"The forecasts belong to the economist, so the possessive relative <b>whose</b> goes before the noun <b>forecasts</b> (= the economist's forecasts). ✗ <b>whom</b> — object pronoun for a person, cannot own a noun; ✗ <b>which</b> — refers to things and would leave <b>forecasts</b> without an owner; ✗ <b>that</b> — subject/object relative, shows no possession."},{"id":"gv-ch-17-7","level":"ch","focus":"word-choice","q":"Several hospitals have ______ a strict no-visitor policy during the flu season to protect vulnerable patients.","options":["adapted","adjusted","accommodated","adopted"],"correct":3,"answer":"adopted","vi":"Nhiều bệnh viện đã áp dụng chính sách cấm thăm bệnh nghiêm ngặt trong mùa cúm để bảo vệ những bệnh nhân dễ tổn thương.","explanation":"To <b>adopt</b> a policy is to start using it, and the clue <b>a strict no-visitor policy during the flu season</b> is something new the hospitals took up. ✗ <b>adapted</b> — change something to suit new conditions; ✗ <b>adjusted</b> — alter slightly, fine-tune; ✗ <b>accommodated</b> — provide room for or meet someone's needs."},{"id":"gv-ch-17-8","level":"ch","focus":"inversion","q":"______ had the central bank cut interest rates than the currency began to slide against the dollar.","options":["Hardly","No sooner","Scarcely","Not until"],"correct":1,"answer":"No sooner","vi":"Ngân hàng trung ương vừa mới cắt giảm lãi suất thì đồng nội tệ đã bắt đầu trượt giá so với đô la.","explanation":"The second clause opens with <b>than</b>, which pairs only with <b>No sooner</b> + inverted past perfect (No sooner had … than …). ✗ <b>Hardly</b> — needs <b>when</b>, not than; ✗ <b>Scarcely</b> — also needs <b>when</b>; ✗ <b>Not until</b> — must introduce a time clause first (Not until X did Y) and never takes than."},{"id":"gv-ch-17-9","level":"ch","focus":"idiom","q":"Before signing up for any 'free' trial, shoppers should always ______, since a monthly fee usually kicks in after thirty days.","options":["read between the lines","read the fine print","read the riot act","read them like a book"],"correct":1,"answer":"read the fine print","vi":"Trước khi đăng ký bất kỳ gói dùng thử 'miễn phí' nào, người mua nên luôn đọc kỹ các điều khoản in nhỏ, vì thường sau ba mươi ngày sẽ bắt đầu bị tính phí hằng tháng.","explanation":"The clue <b>a monthly fee usually kicks in after thirty days</b> is a hidden condition, so <b>read the fine print</b> = check the small, easily missed terms of a contract. ✗ <b>read between the lines</b> — work out a meaning that is not stated; ✗ <b>read the riot act</b> — scold someone severely; ✗ <b>read them like a book</b> — understand someone's thoughts easily."},{"id":"gv-ch-17-10","level":"ch","focus":"double-blank","q":"Tracking down the so-called miracle cure turned out to be a wild ______ chase that ______ the family thousands of dollars.","options":["duck / charged","fox / paid","goose / cost","hare / spent"],"correct":2,"answer":"goose / cost","vi":"Việc săn lùng cái gọi là thần dược hóa ra là một cuộc truy tìm vô vọng khiến gia đình tốn hàng nghìn đô la.","explanation":"The idiom for a hopeless search is <b>a wild goose chase</b>, and a thing that makes you lose money <b>costs</b> you that amount (the chase cost the family thousands). ✗ <b>duck / charged</b> — no 'wild duck chase'; charge needs a seller as subject; ✗ <b>fox / paid</b> — not the idiom; the family, not the chase, would pay; ✗ <b>hare / spent</b> — not the idiom; spend needs a person as subject."},{"id":"gv-ch-17-11","level":"ch","focus":"modal","q":"The patient ______ the medication as prescribed — his blood tests show no trace of it whatsoever.","options":["shouldn't have taken","needn't have taken","must have taken","can't have taken"],"correct":3,"answer":"can't have taken","vi":"Bệnh nhân không thể nào đã uống thuốc theo đơn — xét nghiệm máu của anh ta không cho thấy chút dấu vết nào của thuốc.","explanation":"The clue <b>no trace of it whatsoever</b> makes it impossible that he took the drug; a confident negative deduction about the past is <b>can't have</b> + past participle. ✗ <b>shouldn't have taken</b> — criticises a past action that did happen; ✗ <b>needn't have taken</b> — he took it but it was unnecessary; ✗ <b>must have taken</b> — positive deduction, the opposite of the evidence."},{"id":"gv-ch-17-12","level":"ch","focus":"word-choice","q":"Researchers ______ a large-scale trial across twelve countries to test whether the vaccine protects adults over seventy.","options":["conducted","directed","governed","steered"],"correct":0,"answer":"conducted","vi":"Các nhà nghiên cứu đã tiến hành một thử nghiệm quy mô lớn tại mười hai quốc gia để kiểm tra liệu vắc-xin có bảo vệ người trên bảy mươi tuổi hay không.","explanation":"You <b>conduct</b> a trial, survey, experiment or investigation — the verb that collocates with <b>a large-scale trial</b>. ✗ <b>directed</b> — direct a film, traffic or a company; ✗ <b>governed</b> — govern a country, or rules that govern behaviour; ✗ <b>steered</b> — steer a vehicle or a conversation."},{"id":"gv-ch-17-13","level":"ch","focus":"linking","q":"Sales of organic food have doubled in five years, ______ the number of certified organic farms has barely changed.","options":["despite","consequently","whereas","otherwise"],"correct":2,"answer":"whereas","vi":"Doanh số thực phẩm hữu cơ đã tăng gấp đôi trong năm năm, trong khi số trang trại được chứng nhận hữu cơ hầu như không thay đổi.","explanation":"Sales <b>doubled</b> while farms <b>barely changed</b> — two contrasting full clauses, joined by the conjunction <b>whereas</b>. ✗ <b>despite</b> — a preposition, must be followed by a noun or -ing, not a clause with a verb; ✗ <b>consequently</b> — signals a result, but the second fact is not caused by the first; ✗ <b>otherwise</b> — means 'if not', which makes no sense here."},{"id":"gv-ch-17-14","level":"ch","focus":"collocation","q":"Antibiotic resistance ______ a far greater threat to public health than most consumers realise.","options":["puts","poses","places","sets"],"correct":1,"answer":"poses","vi":"Tình trạng kháng kháng sinh đặt ra mối đe dọa với sức khỏe cộng đồng lớn hơn nhiều so với những gì hầu hết người tiêu dùng nhận thấy.","explanation":"The collocation is <b>pose a threat</b> (also pose a risk / a problem / a question); the clue is <b>a … threat to</b>. ✗ <b>puts</b> — you put someone at risk, but never put a threat; ✗ <b>places</b> — place a bet or an order, not a threat; ✗ <b>sets</b> — set a target or a record, not a threat."},{"id":"gv-ch-17-15","level":"ch","focus":"subjunctive","q":"The auditors recommended that every branch ______ its accounts to head office by the end of each quarter.","options":["submit","submits","submitted","will submit"],"correct":0,"answer":"submit","vi":"Các kiểm toán viên khuyến nghị rằng mỗi chi nhánh phải nộp sổ sách kế toán về trụ sở chính trước cuối mỗi quý.","explanation":"After <b>recommended that</b> (also suggest / insist / demand that) the verb takes the subjunctive base form: <b>every branch submit</b>. ✗ <b>submits</b> — the indicative -s form is not used in the subjunctive clause; ✗ <b>submitted</b> — past tense, but the recommendation is about what should happen; ✗ <b>will submit</b> — will is not used after recommend that; the base form already means 'should submit'."},{"id":"gv-ch-17-16","level":"ch","focus":"idiom","q":"Rather than admit that the failed product launch was his own doing, the manager ______ in front of the whole board.","options":["threw down the gauntlet","threw in the towel","threw caution to the wind","threw his assistant under the bus"],"correct":3,"answer":"threw his assistant under the bus","vi":"Thay vì thừa nhận vụ ra mắt sản phẩm thất bại là do chính mình, người quản lý đã đổ hết trách nhiệm lên trợ lý của mình trước toàn thể hội đồng quản trị.","explanation":"The clue <b>rather than admit … was his own doing</b> means he shifted the blame: <b>throw someone under the bus</b> = sacrifice a colleague to protect yourself. ✗ <b>threw down the gauntlet</b> — issue a challenge; ✗ <b>threw in the towel</b> — give up, admit defeat; ✗ <b>threw caution to the wind</b> — act recklessly, take a risk."},{"id":"gv-ch-17-17","level":"ch","focus":"gerund-infinitive","q":"Many retailers now regret ______ so heavily in city-centre stores just before online shopping took off.","options":["to invest","investing","invest","to have invested"],"correct":1,"answer":"investing","vi":"Nhiều nhà bán lẻ giờ đây hối tiếc vì đã đầu tư quá mạnh vào các cửa hàng ở trung tâm thành phố ngay trước khi mua sắm trực tuyến bùng nổ.","explanation":"<b>Regret + -ing</b> = feel sorry about something already done, and the clue <b>just before online shopping took off</b> places the investing in the past: <b>regret investing</b>. ✗ <b>to invest</b> — regret to + infinitive only introduces bad news you are about to give (we regret to inform you); ✗ <b>invest</b> — regret never takes a bare infinitive; ✗ <b>to have invested</b> — not a standard pattern after regret; the -ing form already refers to the past."},{"id":"gv-ch-17-18","level":"ch","focus":"word-choice","q":"Parliament ______ a law last month requiring supermarkets to print the unit price on every shelf label.","options":["enforced","entailed","enabled","enacted"],"correct":3,"answer":"enacted","vi":"Tháng trước, Quốc hội đã ban hành một đạo luật yêu cầu các siêu thị in đơn giá trên mọi nhãn kệ hàng.","explanation":"A legislature <b>enacts</b> (passes) a law — the clue is <b>Parliament … a law</b>. ✗ <b>enforced</b> — make people obey a law that already exists, the job of police or regulators; ✗ <b>entailed</b> — involve something as a necessary part; ✗ <b>enabled</b> — make something possible."},{"id":"gv-ch-17-19","level":"ch","focus":"phrasal-verb","q":"The trade talks ______ for almost three years, costing exporters billions in lost orders.","options":["dragged out","dragged in","dragged on","dragged along"],"correct":2,"answer":"dragged on","vi":"Các cuộc đàm phán thương mại kéo dài lê thê gần ba năm, khiến các nhà xuất khẩu mất hàng tỷ đô la đơn hàng.","explanation":"Something tedious that lasts far longer than it should <b>drags on</b>; the clue <b>for almost three years</b> and the missing object show the intransitive verb is needed. ✗ <b>dragged out</b> — transitive: someone drags the talks out, so it needs an object; ✗ <b>dragged in</b> — involve someone in a matter unnecessarily; ✗ <b>dragged along</b> — bring someone somewhere unwillingly."},{"id":"gv-ch-17-20","level":"ch","focus":"participle","q":"______ with last year's figures, the hospital's average waiting time has fallen by almost a third.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với số liệu năm ngoái, thời gian chờ trung bình của bệnh viện đã giảm gần một phần ba.","explanation":"The subject <b>the hospital's average waiting time</b> is the thing being compared, so the passive past participle <b>Compared with</b> is needed (= when it is compared with). ✗ <b>Comparing</b> — active -ing would make the waiting time do the comparing; ✗ <b>To compare</b> — infinitive of purpose ('in order to compare'), which the sentence does not express; ✗ <b>Having compared</b> — active perfect participle, again needs a person as subject."},{"id":"gv-ch-17-21","level":"ch","focus":"idiom","q":"Trying to work out why the price of eggs had doubled, the reporter ______ of feed costs, tariffs and bird flu.","options":["went off the deep end","went down a rabbit hole","went round in circles","went up the wall"],"correct":1,"answer":"went down a rabbit hole","vi":"Cố tìm hiểu vì sao giá trứng tăng gấp đôi, phóng viên đã sa vào mê cung của chi phí thức ăn chăn nuôi, thuế quan và cúm gia cầm.","explanation":"The clue <b>trying to work out why … of feed costs, tariffs and bird flu</b> shows the reporter got lost in an ever more complicated topic: <b>go down a rabbit hole</b> — the only option that takes <b>of</b> + the topic. ✗ <b>went off the deep end</b> — lose your temper suddenly; ✗ <b>went round in circles</b> — make no progress; ✗ <b>went up the wall</b> — become extremely annoyed."},{"id":"gv-ch-17-22","level":"ch","focus":"conditional","q":"The rural clinic ______ its doors last spring if the local council hadn't stepped in with an emergency grant.","options":["would close","had closed","would have closed","will have closed"],"correct":2,"answer":"would have closed","vi":"Phòng khám nông thôn hẳn đã phải đóng cửa vào mùa xuân năm ngoái nếu hội đồng địa phương không kịp thời hỗ trợ một khoản trợ cấp khẩn cấp.","explanation":"The if-clause <b>hadn't stepped in</b> plus the past time <b>last spring</b> make an unreal past condition — third conditional, so the result takes <b>would have closed</b>. ✗ <b>would close</b> — second conditional, for an unreal present or future; ✗ <b>had closed</b> — past perfect belongs in the if-clause, not the result clause; ✗ <b>will have closed</b> — future perfect, but the situation is past and did not happen."},{"id":"gv-ch-17-23","level":"ch","focus":"word-choice","q":"Only trained nurses are permitted to ______ the vaccine, which has to be injected slowly into the upper arm.","options":["prescribe","apply","undergo","administer"],"correct":3,"answer":"administer","vi":"Chỉ những y tá đã qua đào tạo mới được phép tiêm vắc-xin này, loại vắc-xin phải được tiêm chậm vào bắp tay.","explanation":"To <b>administer</b> a drug or vaccine is to give it to the patient, which fits <b>nurses … injected slowly into the upper arm</b>. ✗ <b>prescribe</b> — a doctor writes the order for a medicine; ✗ <b>apply</b> — put a cream or dressing on the skin; ✗ <b>undergo</b> — what the patient does: undergo surgery or a treatment."},{"id":"gv-ch-17-24","level":"ch","focus":"collocation","q":"Mask factories ran around the clock, yet they still could not ______ the demand during the first weeks of the outbreak.","options":["meet","reach","hit","catch"],"correct":0,"answer":"meet","vi":"Các nhà máy khẩu trang chạy suốt ngày đêm nhưng vẫn không thể đáp ứng nhu cầu trong những tuần đầu của đợt bùng phát dịch.","explanation":"Demand, a deadline, a target or a need is <b>met</b> = satisfied, and the clue <b>could not … the demand</b> points to this collocation. ✗ <b>reach</b> — reach a level, a target or an agreement, not demand; ✗ <b>hit</b> — hit a target or a record, not demand; ✗ <b>catch</b> — catch a bus, a cold or a ball, not demand."},{"id":"gv-ch-17-25","level":"ch","focus":"double-blank","q":"Lawyers were asked to ______ up a contract that would ______ either side from walking away before the merger was complete.","options":["set / avoid","draw / prevent","make / refuse","put / deny"],"correct":1,"answer":"draw / prevent","vi":"Các luật sư được yêu cầu soạn thảo một hợp đồng ngăn không cho bên nào rút lui trước khi vụ sáp nhập hoàn tất.","explanation":"A contract or plan is <b>drawn up</b> = written out in detail, and <b>prevent someone from</b> doing something is the verb that takes <b>from</b>. ✗ <b>set / avoid</b> — set up a company, not a contract; avoid takes an object or -ing, never 'someone from'; ✗ <b>make / refuse</b> — make up a story, not a contract; refuse to do, never 'someone from'; ✗ <b>put / deny</b> — put up a building or a price, not a contract; deny something, never 'someone from'."},{"id":"gv-ch-18-1","level":"ch","focus":"word-choice","q":"The laboratory's verdict was ______: the bone fragments were at least forty thousand years old.","options":["equivocal","unequivocal","equivalent","ambivalent"],"correct":1,"answer":"unequivocal","vi":"Kết luận của phòng thí nghiệm là không thể chối cãi: các mảnh xương có niên đại ít nhất bốn mươi nghìn năm.","explanation":"Word choice: the colon introduces a definite finding (<b>at least forty thousand years old</b>), so the verdict left no doubt — <b>unequivocal</b> = clear, leaving no room for doubt. ✗ <b>equivocal</b> — ambiguous, open to two readings, the opposite of the clue; ✗ <b>equivalent</b> — equal in value or amount, nothing to do with certainty; ✗ <b>ambivalent</b> — having mixed feelings, said of a person, not of a verdict."},{"id":"gv-ch-18-2","level":"ch","focus":"idiom","q":"For almost a decade the data broker operated ______, compiling profiles that most users never knew existed.","options":["under the radar","off the hook","on the fence","up in the air"],"correct":0,"answer":"under the radar","vi":"Trong gần một thập kỷ, công ty môi giới dữ liệu ấy hoạt động âm thầm ngoài tầm chú ý, lập những hồ sơ mà hầu hết người dùng chưa từng biết là có.","explanation":"Idiom: the clue is <b>profiles that most users never knew existed</b>, so the broker escaped notice — <b>under the radar</b> = unnoticed, without attracting attention. ✗ <b>off the hook</b> — freed from blame or a duty; ✗ <b>on the fence</b> — undecided between two sides; ✗ <b>up in the air</b> — not yet settled or decided. None describes working unnoticed for years."},{"id":"gv-ch-18-3","level":"ch","focus":"modal","q":"The builders of the tomb ______ have used wheeled carts, since no trace of a wheel has ever been found in the region.","options":["mustn't","needn't","can't","shouldn't"],"correct":2,"answer":"can't","vi":"Những người xây lăng mộ này không thể nào đã dùng xe có bánh, vì chưa từng tìm thấy dấu vết bánh xe nào trong vùng.","explanation":"Modal deduction about the past: <b>no trace of a wheel has ever been found</b> is evidence, so the speaker concludes it was impossible — <b>can't have + past participle</b> = \"I am sure this did not happen\". ✗ <b>mustn't have</b> — <i>must have</i> deduces that something DID happen; its negative is <i>can't have</i>; ✗ <b>needn't have</b> — it was unnecessary but they did it; ✗ <b>shouldn't have</b> — it was a mistake to do it; neither says what was possible."},{"id":"gv-ch-18-4","level":"ch","focus":"collocation","q":"Broadcasting your location in real time ______ a serious risk to your personal safety.","options":["puts","makes","does","poses"],"correct":3,"answer":"poses","vi":"Việc phát vị trí của bạn theo thời gian thực gây ra một rủi ro nghiêm trọng cho an toàn cá nhân.","explanation":"Collocation with <b>risk</b>: a danger <b>poses a risk/threat to</b> someone — <i>pose</i> = present, cause. ✗ <b>puts</b> — the pattern is <i>put someone at risk</i>, and here the object is <i>a risk</i>, not a person; ✗ <b>makes</b> — <i>make a risk</i> is not English (we <i>take</i> or <i>run</i> a risk); ✗ <b>does</b> — <i>do a risk</i> does not exist."},{"id":"gv-ch-18-5","level":"ch","focus":"word-choice","q":"With no witnesses and no fingerprints, the case against the hacker rested entirely on ______ evidence.","options":["circumstantial","coincidental","incidental","accidental"],"correct":0,"answer":"circumstantial","vi":"Không có nhân chứng và không có dấu vân tay, vụ án chống lại tin tặc ấy hoàn toàn dựa vào bằng chứng gián tiếp.","explanation":"Word choice: <b>no witnesses and no fingerprints</b> means the evidence is indirect — <b>circumstantial evidence</b> = facts that suggest guilt without proving it directly. ✗ <b>coincidental</b> — happening by chance at the same time; ✗ <b>incidental</b> — minor, secondary, by the way; ✗ <b>accidental</b> — unintended, by accident; none is a term used with <i>evidence</i> in court."},{"id":"gv-ch-18-6","level":"ch","focus":"phrasal-verb","q":"The deal to digitise the museum's entire archive ______ when the main sponsor withdrew at the last minute.","options":["fell out","fell through","fell behind","fell off"],"correct":1,"answer":"fell through","vi":"Thỏa thuận số hóa toàn bộ kho lưu trữ của bảo tàng đã đổ bể khi nhà tài trợ chính rút lui vào phút chót.","explanation":"Phrasal verb with <b>fall</b>: the clue <b>the main sponsor withdrew</b> tells you the deal failed — <b>fell through</b> = (of a plan or deal) failed to happen. ✗ <b>fell out</b> — quarrelled with someone; ✗ <b>fell behind</b> — failed to keep up, got behind schedule; ✗ <b>fell off</b> — declined in number or quality."},{"id":"gv-ch-18-7","level":"ch","focus":"inversion","q":"______ had the probe been launched than contact with it was lost.","options":["Hardly","Not until","No sooner","Only when"],"correct":2,"answer":"No sooner","vi":"Tàu thăm dò vừa mới được phóng lên thì đã mất liên lạc.","explanation":"Inversion: the clue is <b>than</b> later in the sentence, so the pattern is <b>No sooner had … than …</b> = \"as soon as\". ✗ <b>Hardly</b> — <i>Hardly had … when …</i> needs <i>when</i>, not <i>than</i>; ✗ <b>Not until</b> — inverts the MAIN clause (<i>Not until X was contact lost</i>), not the clause it introduces; ✗ <b>Only when</b> — same problem, and it never pairs with <i>than</i>."},{"id":"gv-ch-18-8","level":"ch","focus":"idiom","q":"Rather than cut down gradually, he decided to ______ and deleted every social media app from his phone in a single evening.","options":["go the extra mile","go with the flow","go through the roof","go cold turkey"],"correct":3,"answer":"go cold turkey","vi":"Thay vì giảm dần, anh ấy quyết định cai hẳn một lần và xóa toàn bộ ứng dụng mạng xã hội khỏi điện thoại chỉ trong một buổi tối.","explanation":"Idiom with <b>go</b>: <b>Rather than cut down gradually</b> and <b>in a single evening</b> show he stopped all at once — <b>go cold turkey</b> = quit a habit suddenly and completely. ✗ <b>go the extra mile</b> — make more effort than required; ✗ <b>go with the flow</b> — accept things as they come; ✗ <b>go through the roof</b> — (of prices) rise sharply, or (of a person) explode with anger."},{"id":"gv-ch-18-9","level":"ch","focus":"word-choice","q":"The privacy cost of a single photo upload may seem ______, but every post adds another data point to your profile.","options":["negligible","negligent","neglected","neglectful"],"correct":0,"answer":"negligible","vi":"Cái giá về quyền riêng tư của một lần tải ảnh lên có vẻ không đáng kể, nhưng mỗi bài đăng lại thêm một điểm dữ liệu vào hồ sơ của bạn.","explanation":"Word family of <i>neglect</i>: the contrast <b>may seem … but every post adds</b> means the cost looks tiny — <b>negligible</b> = too small to matter. ✗ <b>negligent</b> — (of a person) careless, failing in a duty; ✗ <b>neglected</b> — not looked after (a neglected garden); ✗ <b>neglectful</b> — habitually careless about someone or something. Only <i>negligible</i> describes size."},{"id":"gv-ch-18-10","level":"ch","focus":"double-blank","q":"Each new leak ______ the stakes, ______ regulators to act sooner than they had planned.","options":["rose / forced","raised / forcing","raised / forced","rose / forcing"],"correct":1,"answer":"raised / forcing","vi":"Mỗi vụ rò rỉ mới lại nâng cao mức độ rủi ro, buộc các cơ quan quản lý phải hành động sớm hơn dự kiến.","explanation":"Double blank: <b>the stakes</b> is an object, so the verb must be transitive <b>raised</b> (<i>rise</i> takes no object); the second blank has no conjunction before it, so the participle <b>forcing</b> shows the result. ✗ <b>rose / forced</b> — <i>rose</i> cannot take an object; ✗ <b>raised / forced</b> — two finite verbs (<i>raised … forced</i>) would need <i>and</i> between them; ✗ <b>rose / forcing</b> — <i>rose</i> is intransitive."},{"id":"gv-ch-18-11","level":"ch","focus":"subjunctive","q":"The regulator demanded that the company ______ fully transparent about which third parties receive users' data.","options":["is","was","be","were"],"correct":2,"answer":"be","vi":"Cơ quan quản lý yêu cầu công ty phải hoàn toàn minh bạch về việc những bên thứ ba nào nhận được dữ liệu của người dùng.","explanation":"Subjunctive: after <b>demanded that</b> (a verb of demand or suggestion) the verb is the base form <b>be</b>, whatever the subject or tense. ✗ <b>is</b> — present indicative, not used after <i>demand that</i>; ✗ <b>was</b> — past indicative, same problem; ✗ <b>were</b> — this is the <i>if I were</i> subjunctive for unreal conditions, not the form used after <i>demand</i>."},{"id":"gv-ch-18-12","level":"ch","focus":"collocation","q":"The pottery unearthed at the site ______ a striking resemblance to designs found five hundred kilometres away.","options":["holds","carries","keeps","bears"],"correct":3,"answer":"bears","vi":"Đồ gốm khai quật tại di chỉ này mang nét tương đồng đáng kinh ngạc với các hoa văn được tìm thấy cách đó năm trăm cây số.","explanation":"Collocation: <b>a striking resemblance to</b> takes the fixed verb <b>bear</b> — <i>bear a resemblance to</i> = look like. ✗ <b>holds</b> — you hold a view or a record, not a resemblance; ✗ <b>carries</b> — you carry weight or a risk; ✗ <b>keeps</b> — you keep a promise or a secret. None of these verbs collocates with <i>resemblance</i>."},{"id":"gv-ch-18-13","level":"ch","focus":"idiom","q":"The team had located the tomb in 2015 but, rather than dig at once, chose to ______ until better scanning technology became available.","options":["bide their time","cut their losses","pull their weight","mend their fences"],"correct":0,"answer":"bide their time","vi":"Nhóm nghiên cứu đã xác định được vị trí lăng mộ từ năm 2015 nhưng, thay vì đào ngay, họ chọn kiên nhẫn chờ thời cơ cho đến khi có công nghệ quét tốt hơn.","explanation":"Idiom: <b>rather than dig at once</b> and <b>until better scanning technology became available</b> show patient waiting — <b>bide your time</b> = wait calmly for the right moment. ✗ <b>cut your losses</b> — give up before losing even more; ✗ <b>pull your weight</b> — do your fair share of the work; ✗ <b>mend your fences</b> — repair a damaged relationship."},{"id":"gv-ch-18-14","level":"ch","focus":"word-choice","q":"The historian's claim that the city had a written language remained ______ until the clay tablets were finally deciphered.","options":["insubstantial","unsubstantiated","substantive","substantial"],"correct":1,"answer":"unsubstantiated","vi":"Luận điểm của nhà sử học rằng thành phố này từng có chữ viết vẫn chưa được chứng thực cho đến khi các phiến đất sét cuối cùng được giải mã.","explanation":"Word family of <i>substance</i>: <b>until the clay tablets were finally deciphered</b> tells you the claim lacked proof — <b>unsubstantiated</b> = not supported by evidence. ✗ <b>insubstantial</b> — flimsy, lacking solidity or importance; ✗ <b>substantive</b> — real, dealing with essentials; ✗ <b>substantial</b> — large in size or amount. Only <i>unsubstantiated</i> describes a claim without proof."},{"id":"gv-ch-18-15","level":"ch","focus":"gerund-infinitive","q":"The site's founders now openly regret ______ user data to advertisers in the company's early years.","options":["to sell","sell","selling","to have sold"],"correct":2,"answer":"selling","vi":"Những người sáng lập trang web giờ đây công khai hối tiếc vì đã bán dữ liệu người dùng cho các nhà quảng cáo trong những năm đầu của công ty.","explanation":"Gerund vs infinitive after <b>regret</b>: the selling happened <b>in the company's early years</b>, so they regret a past action — <b>regret + -ing</b> = feel sorry about something already done. ✗ <b>to sell</b> — <i>regret to + infinitive</i> announces bad news now (<i>we regret to inform you</i>); ✗ <b>sell</b> — <i>regret</i> never takes a bare infinitive; ✗ <b>to have sold</b> — the perfect infinitive is not used after <i>regret</i>; for a past action say <i>selling</i> or <i>having sold</i>."},{"id":"gv-ch-18-16","level":"ch","focus":"phrasal-verb","q":"Every day the site's servers must ______ thousands of automated login attempts from hijacked computers.","options":["fend for","put off","set off","fend off"],"correct":3,"answer":"fend off","vi":"Mỗi ngày, máy chủ của trang web phải chống đỡ hàng nghìn lượt đăng nhập tự động từ các máy tính bị chiếm quyền điều khiển.","explanation":"Phrasal verb: the servers face <b>automated login attempts</b> (an attack) and must repel them — <b>fend off</b> = drive away, keep off. ✗ <b>fend for</b> — only in <i>fend for yourself</i> = look after yourself; ✗ <b>put off</b> — postpone, or discourage someone; ✗ <b>set off</b> — trigger (an alarm) or start a journey."},{"id":"gv-ch-18-17","level":"ch","focus":"participle","q":"______ with the paper surveys of the 1990s, today's online census forms take barely ten minutes to complete.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với các phiếu khảo sát giấy của thập niên 1990, mẫu điều tra dân số trực tuyến ngày nay chỉ mất chưa đầy mười phút để hoàn thành.","explanation":"Participle clause: the subject <b>today's online census forms</b> is the thing being compared, so the past (passive) participle <b>Compared with</b> is needed. ✗ <b>Comparing</b> — an active participle would make the forms the ones doing the comparing; ✗ <b>To compare</b> — an infinitive of purpose (\"in order to compare\") makes no sense here; ✗ <b>Having compared</b> — also active, so the forms would again be the comparers."},{"id":"gv-ch-18-18","level":"ch","focus":"double-blank","q":"Once the researchers had ______ how the algorithm ranked posts, they ______ that outrage was being rewarded.","options":["figured in / realised","figured out / realised","figured on / to realise","worked out / realising"],"correct":1,"answer":"figured out / realised","vi":"Một khi các nhà nghiên cứu đã hiểu ra cách thuật toán xếp hạng bài đăng, họ nhận ra rằng sự phẫn nộ đang được tưởng thưởng.","explanation":"Double blank: <b>how the algorithm ranked posts</b> is something you understand or solve, so <b>figured out</b>; the main clause after <i>Once …</i> needs a finite past verb, <b>realised</b>. ✗ <b>figured in / realised</b> — <i>figure in</i> = include, play a part; ✗ <b>figured on / to realise</b> — <i>figure on</i> = expect, and an infinitive cannot be the main verb; ✗ <b>worked out / realising</b> — <i>worked out</i> fits, but the participle leaves no main verb."},{"id":"gv-ch-18-19","level":"ch","focus":"linking","q":"______ carefully a password is chosen, it is worthless once it has been reused on a dozen sites.","options":["However much","Whatever","No matter how","Even though"],"correct":2,"answer":"No matter how","vi":"Dù mật khẩu được chọn cẩn thận đến đâu, nó cũng trở nên vô giá trị một khi đã được dùng lại trên cả chục trang web.","explanation":"Concession of degree: the blank is followed directly by an adverb, <b>carefully</b>, so use <b>No matter how + adverb</b> (= however carefully). ✗ <b>However much</b> — <i>much</i> cannot sit in front of another adverb (<i>however carefully</i> works; <i>however much carefully</i> does not); ✗ <b>Whatever</b> — needs a noun (<i>whatever password</i>), not an adverb; ✗ <b>Even though</b> — a conjunction that needs a full clause, not <i>carefully</i> straight after it."},{"id":"gv-ch-18-20","level":"ch","focus":"idiom","q":"By selling the family farm to fund the expedition, the explorer had ______: there was simply no going back.","options":["burnt his fingers","burnt the midnight oil","burnt a hole in his pocket","burnt his boats"],"correct":3,"answer":"burnt his boats","vi":"Bằng việc bán nông trại của gia đình để tài trợ cho chuyến thám hiểm, nhà thám hiểm đã tự đốt thuyền chặt đứt đường lui: đơn giản là không còn đường quay về nữa.","explanation":"Idiom with <b>burn</b>: the colon explains it — <b>there was simply no going back</b> — so <b>burn your boats</b> (= burn your bridges) = act so that retreat is impossible. ✗ <b>burn your fingers</b> — get hurt by a risky venture; ✗ <b>burn the midnight oil</b> — work or study late into the night; ✗ <b>burn a hole in your pocket</b> — (of money) tempt you to spend it at once."},{"id":"gv-ch-18-21","level":"ch","focus":"word-choice","q":"Radiocarbon dating gave the team ______ grounds for redating the temple by three centuries.","options":["compelling","compulsive","compulsory","compelled"],"correct":0,"answer":"compelling","vi":"Phương pháp định tuổi bằng carbon phóng xạ đã cho nhóm nghiên cứu những cơ sở rất thuyết phục để xác định lại niên đại ngôi đền, chênh lệch tới ba thế kỷ.","explanation":"Word family of <i>compel</i>: <b>grounds for redating</b> must be convincing — <b>compelling</b> = very convincing (compelling evidence, reasons). ✗ <b>compulsive</b> — driven by an uncontrollable urge (a compulsive liar); ✗ <b>compulsory</b> — required by rule (compulsory education); ✗ <b>compelled</b> — forced to do something, said of a person, not of grounds."},{"id":"gv-ch-18-22","level":"ch","focus":"agreement","q":"Neither the archaeologists nor the museum director ______ willing to say when the sealed chamber will be opened.","options":["are","is","were","have been"],"correct":1,"answer":"is","vi":"Cả các nhà khảo cổ lẫn giám đốc bảo tàng đều không sẵn lòng cho biết khi nào căn phòng bị niêm phong sẽ được mở.","explanation":"Agreement with <b>neither … nor</b>: the verb agrees with the nearer subject, the singular <b>museum director</b>, and the sentence is about now (<i>will be opened</i>), so <b>is</b>. ✗ <b>are</b> — plural, but the nearer subject is singular; ✗ <b>were</b> — plural and past, while the situation is present; ✗ <b>have been</b> — plural present perfect, agreeing with <i>archaeologists</i>, the farther subject."},{"id":"gv-ch-18-23","level":"ch","focus":"comparison","q":"The more personal data a platform collects, ______ it becomes to advertisers.","options":["the most valuable","more valuable","the more valuable","the more valuably"],"correct":2,"answer":"the more valuable","vi":"Nền tảng càng thu thập nhiều dữ liệu cá nhân thì càng trở nên có giá trị đối với các nhà quảng cáo.","explanation":"Double comparative: <b>The more … a platform collects</b> must be balanced by <b>the more valuable</b> — both halves need <i>the</i> + comparative. ✗ <b>the most valuable</b> — a superlative, not a comparative; ✗ <b>more valuable</b> — the second half also needs <i>the</i>; ✗ <b>the more valuably</b> — <i>becomes</i> is a linking verb and takes an adjective, not an adverb."},{"id":"gv-ch-18-24","level":"ch","focus":"collocation","q":"After months of checks, the physicists ______ the conclusion that the signal was nothing more than noise from a nearby fridge.","options":["arrived","came","got","reached"],"correct":3,"answer":"reached","vi":"Sau nhiều tháng kiểm tra, các nhà vật lý đi đến kết luận rằng tín hiệu đó chẳng qua chỉ là nhiễu từ một chiếc tủ lạnh gần đó.","explanation":"Collocation with <b>conclusion</b>: there is no preposition before <b>the conclusion</b>, and only <b>reach</b> takes the noun directly — <i>reach the conclusion that</i>. ✗ <b>arrived</b> — needs <i>at</i> (<i>arrived at the conclusion</i>); ✗ <b>came</b> — needs <i>to</i> (<i>came to the conclusion</i>); ✗ <b>got</b> — needs <i>to</i> as well, and is informal."},{"id":"gv-ch-18-25","level":"ch","focus":"passive","q":"By the end of the decade, most routine scans ______ by algorithms rather than by radiologists.","options":["will have read","will have been read","will be reading","have been read"],"correct":1,"answer":"will have been read","vi":"Đến cuối thập kỷ này, hầu hết các ảnh chụp thường quy sẽ được thuật toán đọc thay vì bác sĩ chẩn đoán hình ảnh.","explanation":"Future perfect passive: <b>By the end of the decade</b> sets a future deadline, and <b>by algorithms</b> shows the scans receive the action — <b>will have been read</b>. ✗ <b>will have read</b> — active, making the scans the readers; ✗ <b>will be reading</b> — active and continuous, same problem, and no completion by the deadline; ✗ <b>have been read</b> — passive but present perfect, ignoring the future time marker."},{"id":"gv-ch-19-1","level":"ch","focus":"word-choice","q":"The prize-winning novel was ______ for the stage in 2019, with the narrator's fading memories performed by a chorus.","options":["adjusted","adapted","converted","altered"],"correct":1,"answer":"adapted","vi":"Cuốn tiểu thuyết đoạt giải được chuyển thể cho sân khấu năm 2019, với những ký ức phai nhạt của người kể chuyện do một dàn đồng ca thể hiện.","explanation":"<b>Adapted for the stage / screen</b> = rewritten in a new artistic form; the clue is <b>for the stage</b> plus memories being performed. ✗ <b>adjusted</b> — a small tweak or correction (adjust the volume), not a re-creation; ✗ <b>converted</b> — changed in use, units or belief (convert a barn, convert to metric), not an artistic reworking; ✗ <b>altered</b> — a vague general change; 'altered for the stage' is not the collocation."},{"id":"gv-ch-19-2","level":"ch","focus":"idiom","q":"Most of the mayor's promises about a second airport proved to be ______: no site was ever even surveyed.","options":["hot air","cold comfort","thin ice","sour grapes"],"correct":0,"answer":"hot air","vi":"Phần lớn lời hứa của thị trưởng về sân bay thứ hai hóa ra chỉ là lời nói suông: chưa từng có địa điểm nào được khảo sát.","explanation":"<b>Hot air</b> = empty talk with nothing behind it; the clue is <b>no site was ever even surveyed</b>. ✗ <b>cold comfort</b> — poor consolation after a loss; ✗ <b>thin ice</b> — a risky, dangerous position (be on thin ice); ✗ <b>sour grapes</b> — pretending not to want what you cannot have."},{"id":"gv-ch-19-3","level":"ch","focus":"collocation","q":"Two decades of touring had ______ a heavy toll on the conductor's hearing.","options":["paid","made","taken","done"],"correct":2,"answer":"taken","vi":"Hai thập kỷ lưu diễn đã gây tổn hại nặng nề cho thính giác của vị nhạc trưởng.","explanation":"The fixed collocation is <b>take a (heavy) toll on</b> = cause serious harm, which fits <b>touring … the conductor's hearing</b>. ✗ <b>paid</b> — you pay a toll (a fee) on a road, not on someone's hearing; ✗ <b>made</b> — 'make a toll' is not English; ✗ <b>done</b> — damage is done, but a toll is taken, never done."},{"id":"gv-ch-19-4","level":"ch","focus":"modal","q":"The coach ______ the nine o'clock ferry; it was still in the hotel car park at ten.","options":["mustn't have caught","needn't have caught","shouldn't have caught","can't have caught"],"correct":3,"answer":"can't have caught","vi":"Chiếc xe khách không thể nào đã kịp chuyến phà chín giờ; mười giờ nó vẫn còn nằm trong bãi đỗ của khách sạn.","explanation":"A confident deduction that something did <b>not</b> happen uses <b>can't have + past participle</b>; the clue is the evidence <b>still in the car park at ten</b>. ✗ <b>mustn't have caught</b> — in standard exam grammar 'must have' gives only positive deduction; its negative is can't have; ✗ <b>needn't have caught</b> — means it did catch it but did not need to; ✗ <b>shouldn't have caught</b> — criticises something it actually did."},{"id":"gv-ch-19-5","level":"ch","focus":"word-choice","q":"Researchers found that self-control tends to ______ across the day, sagging after lunch and recovering by early evening.","options":["fluctuate","mutate","convert","transform"],"correct":0,"answer":"fluctuate","vi":"Các nhà nghiên cứu nhận thấy khả năng tự chủ có xu hướng dao động trong ngày, sụt xuống sau bữa trưa rồi hồi phục vào đầu buổi tối.","explanation":"<b>Fluctuate</b> = rise and fall repeatedly, which the clue <b>sagging … recovering</b> describes. ✗ <b>mutate</b> — change into a different (usually genetic) form; ✗ <b>convert</b> — change into a different use or form, and needs 'into'; ✗ <b>transform</b> — change completely into something new, normally with an object; none describes up-and-down movement."},{"id":"gv-ch-19-6","level":"ch","focus":"phrasal-verb","q":"The campaign to reopen the town's only cinema ______ once its two loudest supporters moved away.","options":["wore out","broke out","passed out","fizzled out"],"correct":3,"answer":"fizzled out","vi":"Chiến dịch đòi mở lại rạp chiếu phim duy nhất của thị trấn lụi dần rồi tắt hẳn khi hai người ủng hộ nhiệt thành nhất chuyển đi nơi khác.","explanation":"<b>Fizzle out</b> = end weakly after a promising start; the clue is the campaign losing its <b>two loudest supporters</b>. ✗ <b>wore out</b> — became unusable through use (shoes, patience) or exhausted someone; ✗ <b>broke out</b> — started suddenly (a fire, a war, a rash), the opposite of ending; ✗ <b>passed out</b> — fainted, or handed out (which needs an object)."},{"id":"gv-ch-19-7","level":"ch","focus":"inversion","q":"______ had the curtain risen than a phone began ringing in the front row.","options":["Hardly","Scarcely","No sooner","Not until"],"correct":2,"answer":"No sooner","vi":"Màn vừa mới kéo lên thì một chiếc điện thoại đã đổ chuông ngay hàng ghế đầu.","explanation":"Inverted <b>No sooner had … than</b>: the <b>than</b> later in the sentence decides it. ✗ <b>Hardly</b> — pairs with <b>when</b> (Hardly had the curtain risen when …); ✗ <b>Scarcely</b> — also pairs with <b>when</b>, not than; ✗ <b>Not until</b> — must be followed by a time phrase or clause first (Not until the interval did …), not directly by the inverted main clause."},{"id":"gv-ch-19-8","level":"ch","focus":"idiom","q":"Trying to drum up interest in a third sequel after those reviews is ______; the studio would do better to move on.","options":["putting the cart before the horse","flogging a dead horse","beating around the bush","barking up the wrong tree"],"correct":1,"answer":"flogging a dead horse","vi":"Cố khơi lại sự quan tâm cho phần phim thứ ba sau những bài đánh giá như thế chẳng khác nào phí công vô ích; hãng phim nên chuyển hướng thì hơn.","explanation":"<b>Flog a dead horse</b> = waste effort on something already finished or hopeless; the clue is <b>the studio would do better to move on</b>. ✗ <b>putting the cart before the horse</b> — doing things in the wrong order; ✗ <b>beating around the bush</b> — avoiding saying something directly; ✗ <b>barking up the wrong tree</b> — pursuing the wrong person or idea, a mistake of target, not of hope."},{"id":"gv-ch-19-9","level":"ch","focus":"double-blank","q":"Having thrown ______ to the ______, the couple sold their flat and bought one-way tickets to Lisbon.","options":["caution / wind","care / winds","caution / air","fear / wind"],"correct":0,"answer":"caution / wind","vi":"Bất chấp mọi rủi ro, hai vợ chồng bán căn hộ và mua vé một chiều đi Lisbon.","explanation":"The fixed idiom is <b>throw caution to the wind(s)</b> = stop worrying about risk and act boldly, which <b>sold their flat … one-way tickets</b> shows. ✗ <b>care / winds</b> — the noun in the idiom is caution, not care; ✗ <b>caution / air</b> — the idiom needs wind, not air; ✗ <b>fear / wind</b> — 'throw fear to the wind' is not the expression."},{"id":"gv-ch-19-10","level":"ch","focus":"subjunctive","q":"The curator insisted that every painting on loan ______ insured before it left the building.","options":["was","be","is","were"],"correct":1,"answer":"be","vi":"Người phụ trách bảo tàng nhất quyết yêu cầu mọi bức tranh cho mượn phải được bảo hiểm trước khi rời khỏi tòa nhà.","explanation":"After <b>insist / demand / recommend that</b>, the verb takes the base-form subjunctive — <b>that every painting be insured</b> — whatever the tense of the main verb. ✗ <b>was</b> — indicative past would report a fact, not a demand; ✗ <b>is</b> — same problem, and clashes with the past 'insisted'; ✗ <b>were</b> — the past subjunctive belongs after 'if / wish' (if it were), not after insist that."},{"id":"gv-ch-19-11","level":"ch","focus":"word-choice","q":"After the trial of self-service kiosks ended in chaos, the airline ______ to its old check-in desks within a week.","options":["reversed","restored","reverted","retreated"],"correct":2,"answer":"reverted","vi":"Sau khi thử nghiệm quầy tự phục vụ kết thúc trong hỗn loạn, hãng hàng không quay lại dùng quầy làm thủ tục cũ chỉ trong một tuần.","explanation":"<b>Revert to</b> = go back to a former system or state, matching <b>to its old check-in desks</b>. ✗ <b>reversed</b> — undo or turn round; it needs an object (reverse a decision) and does not take 'to'; ✗ <b>restored</b> — bring back; also needs an object (restore the desks), never 'restore to' a system; ✗ <b>retreated</b> — physical or military withdrawal, not switching systems."},{"id":"gv-ch-19-12","level":"ch","focus":"collocation","q":"Good guides learn to ______ a balance between keeping to the timetable and letting the group linger where it wants.","options":["hit","draw","set","strike"],"correct":3,"answer":"strike","vi":"Hướng dẫn viên giỏi biết cách giữ được sự cân bằng giữa việc bám sát lịch trình và để đoàn nán lại nơi họ muốn.","explanation":"The fixed collocation is <b>strike a balance</b> = find a fair middle way, confirmed by <b>between … and …</b>. ✗ <b>hit</b> — hit a target or a record, never a balance; ✗ <b>draw</b> — draw a line or a conclusion, not a balance; ✗ <b>set</b> — set a limit or a standard, not a balance."},{"id":"gv-ch-19-13","level":"ch","focus":"gerund-infinitive","q":"After a decade in publishing, she has grown used to ______ manuscripts that are competent but unsellable.","options":["reject","have rejected","rejecting","being rejected"],"correct":2,"answer":"rejecting","vi":"Sau một thập kỷ làm xuất bản, cô đã quen với việc từ chối những bản thảo viết ổn nhưng không thể bán được.","explanation":"After <b>be / get / grow used to</b>, the <b>to</b> is a preposition, so a noun or -ing form follows: <b>used to rejecting</b>. ✗ <b>reject</b> — the bare infinitive follows 'used to' only for a past habit (she used to reject), which 'has grown' rules out; ✗ <b>have rejected</b> — an infinitive form, impossible after a preposition; ✗ <b>being rejected</b> — passive, so it cannot take the object 'manuscripts'; she is the one rejecting."},{"id":"gv-ch-19-14","level":"ch","focus":"idiom","q":"The review never calls the play a failure, but anyone able to ______ will sense the critic's disappointment.","options":["read the fine print","read between the lines","read the riot act","read it and weep"],"correct":1,"answer":"read between the lines","vi":"Bài phê bình không hề gọi vở kịch là thất bại, nhưng ai biết đọc ý tứ ẩn sau câu chữ sẽ cảm nhận được nỗi thất vọng của nhà phê bình.","explanation":"<b>Read between the lines</b> = understand what is implied but not stated; the clue is <b>never calls … but … will sense</b>. ✗ <b>read the fine print</b> — check the small conditions of a contract; ✗ <b>read the riot act</b> — scold someone severely; ✗ <b>read it and weep</b> — a taunt when showing someone a winning result."},{"id":"gv-ch-19-15","level":"ch","focus":"participle","q":"______ with the sprawling four-hour original, the director's new ninety-minute cut feels almost brisk.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với bản gốc dài lê thê bốn tiếng, bản dựng mới chín mươi phút của đạo diễn tạo cảm giác gần như gọn gàng, nhanh nhẹn.","explanation":"The new cut is the thing <b>being compared</b>, so the passive participle <b>Compared with</b> is needed; the clue is the subject <b>the director's new cut</b>. ✗ <b>Comparing</b> — active, would make the cut do the comparing (dangling participle); ✗ <b>To compare</b> — an infinitive of purpose, 'in order to compare', which makes no sense here; ✗ <b>Having compared</b> — active and perfect, again wrongly makes the cut the comparer."},{"id":"gv-ch-19-16","level":"ch","focus":"word-choice","q":"Rather than a few cosmetic changes, the museum's new director wants to ______ the entire visitor experience, from ticketing to the café.","options":["tweak","amend","modify","overhaul"],"correct":3,"answer":"overhaul","vi":"Thay vì vài thay đổi bề ngoài, giám đốc mới của bảo tàng muốn cải tổ toàn diện trải nghiệm của khách tham quan, từ khâu bán vé đến quán cà phê.","explanation":"<b>Overhaul</b> = examine and rebuild something completely; the clue is <b>rather than a few cosmetic changes … the entire experience</b>. ✗ <b>tweak</b> — make a tiny adjustment, exactly the cosmetic change rejected; ✗ <b>amend</b> — make minor corrections to a text or law; ✗ <b>modify</b> — change partly or slightly, not from top to bottom."},{"id":"gv-ch-19-17","level":"ch","focus":"linking","q":"______ the critics admired the film's ambition, few of them could sit through its four-hour running time.","options":["Much as","Despite","However","Nonetheless"],"correct":0,"answer":"Much as","vi":"Dù giới phê bình rất ngưỡng mộ tham vọng của bộ phim, ít ai trong số họ ngồi được hết bốn tiếng chiếu.","explanation":"<b>Much as</b> + clause = 'although … very much', and a full clause (<b>the critics admired</b>) follows the blank. ✗ <b>Despite</b> — a preposition, needs a noun or -ing (despite admiring), not subject + verb; ✗ <b>However</b> — an adverb; it cannot link two clauses with only a comma; ✗ <b>Nonetheless</b> — also an adverb, same comma-splice problem."},{"id":"gv-ch-19-18","level":"ch","focus":"phrasal-verb","q":"Managers who announce sweeping changes but never ______ soon lose the trust of their staff.","options":["follow suit","follow through","fall through","carry out"],"correct":1,"answer":"follow through","vi":"Những nhà quản lý tuyên bố cải cách lớn nhưng không bao giờ thực hiện đến nơi đến chốn sẽ sớm đánh mất lòng tin của nhân viên.","explanation":"<b>Follow through</b> = complete what you have started or promised; the clue is <b>announce sweeping changes but never …</b>. ✗ <b>follow suit</b> — copy what others have just done; ✗ <b>fall through</b> — (of a plan) collapse; managers cannot 'fall through'; ✗ <b>carry out</b> — perform, but it needs an object (carry out the changes) and the blank has none."},{"id":"gv-ch-19-19","level":"ch","focus":"collocation","q":"Fans who had queued overnight were ______ disappointed when the author cancelled her signing at the last minute.","options":["strongly","heavily","bitterly","highly"],"correct":2,"answer":"bitterly","vi":"Những người hâm mộ xếp hàng suốt đêm đã thất vọng cay đắng khi tác giả hủy buổi ký tặng vào phút chót.","explanation":"<b>Bitterly disappointed</b> is the standard collocation, intensified by <b>queued overnight</b>. ✗ <b>strongly</b> — goes with advise, oppose, recommend, not disappointed; ✗ <b>heavily</b> — goes with rain, traffic, rely, not disappointed; ✗ <b>highly</b> — goes with likely, recommended, successful, not disappointed."},{"id":"gv-ch-19-20","level":"ch","focus":"reported","q":"The interviewer asked the novelist ______ she had ever thought of abandoning the book halfway.","options":["that","did","how","whether"],"correct":3,"answer":"whether","vi":"Người phỏng vấn hỏi nữ tiểu thuyết gia liệu bà có bao giờ nghĩ đến chuyện bỏ dở cuốn sách giữa chừng không.","explanation":"A reported yes/no question is introduced by <b>whether</b> (or if) with statement word order; the clue is <b>asked … she had ever</b>. ✗ <b>that</b> — reports a statement, not a question; ✗ <b>did</b> — keeps direct-question order (did she …), which reported speech drops; ✗ <b>how</b> — asks about manner, but the original question was yes/no."},{"id":"gv-ch-19-21","level":"ch","focus":"idiom","q":"A seasoned tour guide knows how to ______: if the group is flagging, the lecture on Gothic arches can wait.","options":["read the room","call the shots","hold the floor","steal the show"],"correct":0,"answer":"read the room","vi":"Hướng dẫn viên dày dạn biết cách nắm bắt tâm trạng đoàn: nếu cả nhóm đã thấm mệt, bài giảng về vòm Gothic có thể để sau.","explanation":"<b>Read the room</b> = sense the mood of the people present and adjust; the clue is <b>if the group is flagging … can wait</b>. ✗ <b>call the shots</b> — be the one in charge; ✗ <b>hold the floor</b> — keep speaking while others listen, the opposite of pausing the lecture; ✗ <b>steal the show</b> — attract all the attention."},{"id":"gv-ch-19-22","level":"ch","focus":"pronoun","q":"The two novelists reviewed ______ books for thirty years without once meeting in person.","options":["each other","themselves","one another","each other's"],"correct":3,"answer":"each other's","vi":"Hai nhà tiểu thuyết đã bình sách của nhau suốt ba mươi năm mà chưa từng một lần gặp mặt.","explanation":"A possessive is needed before the noun <b>books</b>, so <b>each other's</b> = the other's books. ✗ <b>each other</b> — an object pronoun, cannot modify a noun; ✗ <b>one another</b> — same problem, no 's; ✗ <b>themselves</b> — reflexive, would mean each reviewed his own books, which contradicts 'without once meeting'."},{"id":"gv-ch-19-23","level":"ch","focus":"double-blank","q":"Before the festival put the town on the map, most families ______ by ______ fishing and a little farming.","options":["went / on","made / on","got / on","got / from"],"correct":2,"answer":"got / on","vi":"Trước khi lễ hội khiến thị trấn nổi tiếng, hầu hết các gia đình sống qua ngày nhờ đánh cá và làm nông chút ít.","explanation":"<b>Get by on</b> something = survive using only that (get by on a small income), matching <b>fishing and a little farming</b>. ✗ <b>went / on</b> — 'go by' means pass (the years went by), not survive; ✗ <b>made / on</b> — 'make by' is not a phrasal verb; ✗ <b>got / from</b> — get by takes on for the means, not from."},{"id":"gv-ch-19-24","level":"ch","focus":"word-choice","q":"Her editor asked her to ______ the manuscript one last time, cutting the second act and sharpening the dialogue.","options":["reverse","revise","rectify","revert"],"correct":1,"answer":"revise","vi":"Biên tập viên đề nghị cô sửa lại bản thảo lần cuối, cắt bỏ hồi hai và làm cho lời thoại sắc sảo hơn.","explanation":"<b>Revise</b> = rework and improve a text; the clue is <b>cutting the second act and sharpening the dialogue</b>. ✗ <b>reverse</b> — turn round or undo (reverse a decision); ✗ <b>rectify</b> — correct a specific error or fault, not reshape a whole manuscript; ✗ <b>revert</b> — go back to an earlier state, and takes 'to', not an object."},{"id":"gv-ch-19-25","level":"ch","focus":"question-tag","q":"Nobody on the coach tour actually read the itinerary before setting off, ______?","options":["did they","didn't they","did he","had they"],"correct":0,"answer":"did they","vi":"Chẳng ai trên chuyến xe du lịch thực sự đọc lịch trình trước khi khởi hành, phải không?","explanation":"<b>Nobody</b> makes the statement negative, so the tag is positive; nobody takes the pronoun <b>they</b>, and simple past <b>read</b> needs <b>did</b>. ✗ <b>didn't they</b> — a negative tag after an already-negative statement; ✗ <b>did he</b> — 'nobody' takes they, not he; ✗ <b>had they</b> — 'had' needs past perfect, but 'read' here is simple past (no 'had' before it)."},{"id":"gv-ch-20-1","level":"ch","focus":"word-choice","q":"Figures released by the grid operator on Monday comprehensively ______ the allegation that the country had been days away from rolling blackouts.","options":["argued","objected","refuted","disagreed"],"correct":2,"answer":"refuted","vi":"Số liệu do đơn vị vận hành lưới điện công bố hôm thứ Hai đã bác bỏ hoàn toàn cáo buộc rằng đất nước chỉ còn vài ngày nữa là phải cắt điện luân phiên.","explanation":"<b>Refute</b> = prove a claim false, and it takes a direct object: <b>refuted the allegation</b>. ✗ <b>argued</b> — you argue a case or argue that something is true; you cannot 'argue an allegation'; ✗ <b>objected</b> — needs <b>to</b> (object to a plan) and means protest, not disprove; ✗ <b>disagreed</b> — needs <b>with</b> and gives an opinion, not proof from figures."},{"id":"gv-ch-20-2","level":"ch","focus":"idiom","q":"The sponsor's late withdrawal threw ______ just weeks before the new stadium was due to open.","options":["a spanner in the works","a fly in the ointment","a bone of contention","a nail in the coffin"],"correct":0,"answer":"a spanner in the works","vi":"Việc nhà tài trợ rút lui vào phút chót đã phá hỏng kế hoạch chỉ vài tuần trước ngày sân vận động mới dự kiến khai trương.","explanation":"<b>Throw a spanner in the works</b> = suddenly wreck a plan; the clues are the verb <b>threw</b> and the stadium opening that is now at risk. ✗ <b>a fly in the ointment</b> — a small thing that spoils something; it <b>is</b> one, never thrown; ✗ <b>a bone of contention</b> — a subject people keep arguing over; ✗ <b>a nail in the coffin</b> — one more step towards failure; you <b>put</b> a nail in the coffin, not throw it."},{"id":"gv-ch-20-3","level":"ch","focus":"inversion","q":"______ had the vaccine trial's results been published when three rival laboratories announced they were abandoning their own programmes.","options":["No sooner","Hardly","Not only","Seldom"],"correct":1,"answer":"Hardly","vi":"Kết quả thử nghiệm vắc-xin vừa mới được công bố thì ba phòng thí nghiệm đối thủ đã tuyên bố từ bỏ chương trình của riêng họ.","explanation":"<b>Hardly … when</b>: the clue is <b>when</b> after the inverted past perfect (<b>had … been published when</b>). ✗ <b>No sooner</b> — pairs with <b>than</b>, not with when; ✗ <b>Not only</b> — pairs with <b>but (also)</b> and adds a second point, not a time sequence; ✗ <b>Seldom</b> — means 'rarely' and forms no pair with <b>when</b> at all."},{"id":"gv-ch-20-4","level":"ch","focus":"collocation","q":"Rolling blackouts ______ a serious threat to the region's hospitals, which cannot run their ventilators on generators for long.","options":["make","do","put","pose"],"correct":3,"answer":"pose","vi":"Cắt điện luân phiên gây ra mối đe dọa nghiêm trọng cho các bệnh viện trong vùng, vốn không thể chạy máy thở bằng máy phát điện lâu được.","explanation":"The fixed collocation is <b>pose a threat</b> (present a danger); the clue is the noun <b>threat</b> with a situation as subject. ✗ <b>make</b> — you make a threat only when a person threatens someone in words; blackouts cannot; ✗ <b>do</b> — never combines with <b>threat</b>; ✗ <b>put</b> — collocates with <b>at risk</b> (put hospitals at risk), not with <b>threat</b>."},{"id":"gv-ch-20-5","level":"ch","focus":"phrasal-verb","q":"Despite weeks of pressure from broadcasters, the league refused to ______ and kept every kick-off time unchanged.","options":["give in","give off","give out","give away"],"correct":0,"answer":"give in","vi":"Dù bị các đài truyền hình gây sức ép suốt nhiều tuần, giải đấu vẫn không chịu nhượng bộ và giữ nguyên mọi giờ thi đấu.","explanation":"<b>Give in</b> = yield to pressure, and it needs no object; the clues are <b>refused to</b> and <b>kept … unchanged</b>. ✗ <b>give off</b> — emit heat or a smell, and needs an object; ✗ <b>give out</b> — distribute (needs an object) or, on its own, stop working / run out — not yielding; ✗ <b>give away</b> — reveal a secret or donate, and needs an object."},{"id":"gv-ch-20-6","level":"ch","focus":"subjunctive","q":"The press commission recommended that the broadcaster ______ its correction on the front page of its website rather than bury it in a footnote.","options":["prints","printed","print","would print"],"correct":2,"answer":"print","vi":"Ủy ban báo chí khuyến nghị đài truyền hình đăng bản đính chính lên trang đầu của trang web thay vì giấu nó trong một ghi chú cuối trang.","explanation":"After <b>recommend that</b> the verb takes the bare subjunctive: <b>that the broadcaster print</b>; the clue is <b>recommended that</b>. ✗ <b>prints</b> — the ordinary present with <b>-s</b>; a subjunctive verb never agrees with its subject; ✗ <b>printed</b> — past tense, but the recommendation is about a future action; ✗ <b>would print</b> — a conditional, not used after verbs of demand, suggestion or recommendation."},{"id":"gv-ch-20-7","level":"ch","focus":"word-choice","q":"Once the replay had been shown on the big screen, the coach was forced to ______ that the goal had been perfectly legitimate.","options":["consent","concede","comply","conform"],"correct":1,"answer":"concede","vi":"Khi đoạn quay chậm được chiếu lên màn hình lớn, huấn luyện viên buộc phải thừa nhận rằng bàn thắng hoàn toàn hợp lệ.","explanation":"<b>Concede that</b> = reluctantly admit something is true; the clues are <b>was forced to</b> and the <b>that</b>-clause. ✗ <b>consent</b> — agree to a request, takes <b>to</b> + noun or infinitive, never <b>that</b>; ✗ <b>comply</b> — obey a rule, takes <b>with</b>; ✗ <b>conform</b> — follow accepted standards, takes <b>to / with</b>; none of the three can report a fact."},{"id":"gv-ch-20-8","level":"ch","focus":"idiom","q":"Aware that the drivers' union was losing patience, the ministry ______ by promising a review of shift patterns before the end of the year.","options":["threw in the towel","threw its weight around","threw caution to the wind","threw it a bone"],"correct":3,"answer":"threw it a bone","vi":"Biết công đoàn tài xế đang mất kiên nhẫn, bộ đã nhượng bộ chút ít bằng cách hứa xem xét lại lịch ca làm việc trước cuối năm.","explanation":"<b>Throw someone a bone</b> = give a small concession to keep them quiet; the clue is the modest promise of 'a review' to a union that is losing patience. ✗ <b>threw in the towel</b> — gave up completely, but the ministry did not surrender; ✗ <b>threw its weight around</b> — used its power to bully, the opposite of a soft promise; ✗ <b>threw caution to the wind</b> — acted recklessly, which a careful promise is not."},{"id":"gv-ch-20-9","level":"ch","focus":"modal","q":"Judging by the vibration recorded within an hour of start-up, the turbine ______ been installed correctly.","options":["can't have","must have","needn't have","should have"],"correct":0,"answer":"can't have","vi":"Căn cứ vào độ rung ghi nhận được chỉ trong vòng một giờ sau khi khởi động, tua-bin chắc chắn đã không được lắp đặt đúng cách.","explanation":"<b>Judging by</b> introduces a deduction, and the vibration is evidence that correct installation was impossible: <b>can't have been</b> (negative deduction about the past). ✗ <b>must have</b> — deduces the opposite, that it certainly <b>was</b> installed correctly; ✗ <b>needn't have</b> — says a past action was unnecessary, not a deduction; ✗ <b>should have</b> — criticises a past failure; the evidence here shows what is true, not what was advisable."},{"id":"gv-ch-20-10","level":"ch","focus":"double-blank","q":"Having sat on the ______ for months, the regulator finally came ______ in favour of a single national grid operator.","options":["wall / down","fence / down","fence / up","line / out"],"correct":1,"answer":"fence / down","vi":"Sau nhiều tháng lưỡng lự không chọn bên nào, cơ quan quản lý cuối cùng đã quyết định ủng hộ mô hình một đơn vị vận hành lưới điện quốc gia duy nhất.","explanation":"<b>Sit on the fence</b> = refuse to take sides, and <b>come down in favour of</b> = finally decide for; the clues are <b>for months</b> then <b>finally</b>. ✗ <b>wall / down</b> — 'sit on the wall' is not an idiom; ✗ <b>fence / up</b> — 'come up in favour of' does not exist; <b>come up</b> = arise; ✗ <b>line / out</b> — 'sit on the line' means nothing (<b>come out in favour of</b> alone would be fine)."},{"id":"gv-ch-20-11","level":"ch","focus":"linking","q":"______ the home side dominated possession for eighty minutes, it was the visitors who created the clearer chances.","options":["Despite","However","Although","Nevertheless"],"correct":2,"answer":"Although","vi":"Mặc dù đội chủ nhà kiểm soát bóng áp đảo suốt tám mươi phút, chính đội khách mới là bên tạo ra những cơ hội rõ rệt hơn.","explanation":"<b>Although</b> is a conjunction, and the blank is followed by a full clause (<b>the home side dominated</b>) that must be joined to the main clause. ✗ <b>Despite</b> — a preposition: takes a noun or <b>-ing</b> (despite dominating), not a clause; ✗ <b>However</b> — an adverb; it needs a full stop or semicolon before the second sentence; ✗ <b>Nevertheless</b> — also an adverb, so it cannot link two clauses in one sentence."},{"id":"gv-ch-20-12","level":"ch","focus":"word-choice","q":"The columnist stopped short of an outright accusation, merely ______ that the sprinter's sudden improvement owed more to chemistry than to training.","options":["proclaiming","pronouncing","announcing","insinuating"],"correct":3,"answer":"insinuating","vi":"Cây bút bình luận không đưa ra lời buộc tội thẳng thừng mà chỉ ám chỉ rằng sự tiến bộ đột ngột của vận động viên chạy nước rút là nhờ hóa chất nhiều hơn là nhờ tập luyện.","explanation":"<b>Insinuate</b> = suggest something unpleasant indirectly; the clues are <b>stopped short of an outright accusation</b> and <b>merely</b>. ✗ <b>proclaiming</b> — declaring openly and loudly, not hinting; ✗ <b>pronouncing</b> — declaring formally or officially (pronounce a verdict); ✗ <b>announcing</b> — making news publicly known; all three are open statements, the opposite of a hint."},{"id":"gv-ch-20-13","level":"ch","focus":"collocation","q":"The pipeline has been running at ______ capacity since the faulty compressor was replaced in March.","options":["whole","full","entire","complete"],"correct":1,"answer":"full","vi":"Đường ống đã vận hành hết công suất kể từ khi máy nén bị lỗi được thay thế hồi tháng Ba.","explanation":"The collocation is <b>at full capacity</b> (producing the maximum possible); the clue is <b>running at … capacity</b>. ✗ <b>whole</b> — describes a complete object (the whole pipeline), not a level of output; ✗ <b>entire</b> — the same, before countable nouns (the entire route); ✗ <b>complete</b> — finished or lacking nothing (a complete set); none pairs with <b>capacity</b>."},{"id":"gv-ch-20-14","level":"ch","focus":"participle","q":"______ its survey of the reef, the research vessel headed north to sample a second stretch of coastline before the monsoon arrived.","options":["Having finished","Finished","Being finished","To have finished"],"correct":0,"answer":"Having finished","vi":"Sau khi hoàn tất khảo sát rạn san hô, tàu nghiên cứu đi lên phía bắc để lấy mẫu ở một dải bờ biển thứ hai trước khi gió mùa tới.","explanation":"The vessel finished the survey <b>before</b> it headed north, and the vessel is the doer, so the perfect active participle <b>Having finished</b> marks the earlier action. ✗ <b>Finished</b> — a past participle here is passive: it would mean the vessel itself was finished; ✗ <b>Being finished</b> — also passive, and <b>being</b> gives no 'earlier action' sense; ✗ <b>To have finished</b> — an infinitive expresses purpose or result, not what happened first."},{"id":"gv-ch-20-15","level":"ch","focus":"idiom","q":"The night editor asked the reporter at the mine to ______ as the rescue unfolded, even if it meant calling at three in the morning.","options":["keep her at bay","keep her in the dark","keep her posted","keep her at arm's length"],"correct":2,"answer":"keep her posted","vi":"Biên tập viên ca đêm yêu cầu phóng viên tại hiện trường mỏ liên tục cập nhật tình hình khi cuộc giải cứu diễn ra, kể cả phải gọi lúc ba giờ sáng.","explanation":"<b>Keep someone posted</b> = keep sending them the latest news; the clues are <b>as the rescue unfolded</b> and calling at three in the morning. ✗ <b>keep her at bay</b> — hold an enemy or problem away; ✗ <b>keep her in the dark</b> — tell her nothing, the exact opposite; ✗ <b>keep her at arm's length</b> — avoid becoming close to someone."},{"id":"gv-ch-20-16","level":"ch","focus":"inversion","q":"______ the goalkeeper's save in stoppage time, the club would have been relegated on the final day of the season.","options":["Had not it been for","If it had not for","Were it not been for","Had it not been for"],"correct":3,"answer":"Had it not been for","vi":"Nếu không nhờ pha cứu thua của thủ môn ở phút bù giờ, câu lạc bộ đã xuống hạng ngay ngày thi đấu cuối cùng của mùa giải.","explanation":"The inverted third conditional is <b>Had it not been for</b> (= If it had not been for); the clue is <b>would have been relegated</b>. ✗ <b>Had not it been for</b> — in inversion <b>not</b> follows the subject (had it not), never the auxiliary; ✗ <b>If it had not for</b> — with <b>if</b> you need the full verb: had not <b>been</b>; ✗ <b>Were it not been for</b> — <b>were</b> (second conditional) cannot combine with <b>been</b>; it would be <b>were it not for</b>."},{"id":"gv-ch-20-17","level":"ch","focus":"word-choice","q":"Under threat of legal action, the newspaper agreed to ______ the story and print an apology in the following day's edition.","options":["retract","rescind","revoke","repeal"],"correct":0,"answer":"retract","vi":"Trước nguy cơ bị kiện, tờ báo đồng ý rút lại bài viết và đăng lời xin lỗi trong số báo ngày hôm sau.","explanation":"<b>Retract</b> = withdraw a statement as untrue; the clues are <b>the story</b> and <b>print an apology</b>. ✗ <b>rescind</b> — cancel an order, decision or contract; ✗ <b>revoke</b> — officially take back a licence, permit or right; ✗ <b>repeal</b> — abolish a law; none of these three is used with a news story."},{"id":"gv-ch-20-18","level":"ch","focus":"gerund-infinitive","q":"The club's owners would rather ______ a season in the second tier than sell the stadium to property developers.","options":["to endure","endure","enduring","endured"],"correct":1,"answer":"endure","vi":"Các ông chủ câu lạc bộ thà chịu đựng một mùa giải ở hạng hai còn hơn bán sân vận động cho các nhà phát triển bất động sản.","explanation":"<b>Would rather</b> + bare infinitive when the subject stays the same: <b>would rather endure … than sell</b>; the clue is the bare <b>sell</b> after <b>than</b>, which the blank must match. ✗ <b>to endure</b> — no <b>to</b> after <b>would rather</b>; ✗ <b>enduring</b> — <b>-ing</b> follows <b>prefer</b>, not <b>would rather</b>; ✗ <b>endured</b> — the past form is used only with a different subject (I'd rather <b>they</b> endured)."},{"id":"gv-ch-20-19","level":"ch","focus":"phrasal-verb","q":"Repairs to the transmission line were ______ for a month by a dispute over access to farmland along the route.","options":["held out","held on","set up","held up"],"correct":3,"answer":"held up","vi":"Việc sửa chữa đường dây truyền tải bị trì hoãn suốt một tháng vì tranh chấp về quyền đi qua đất nông nghiệp dọc tuyến.","explanation":"<b>Hold up</b> = delay; it is transitive, so it works in the passive <b>were held up for a month by</b>. ✗ <b>held out</b> — resist or last (the supplies held out), intransitive, so no passive; ✗ <b>held on</b> — wait or grip tightly, also intransitive; ✗ <b>set up</b> — establish or arrange; repairs are not 'established' by a dispute."},{"id":"gv-ch-20-20","level":"ch","focus":"subjunctive","q":"It's high time the federation ______ the anti-doping rules it wrote more than a decade ago.","options":["revise","revises","revised","has revised"],"correct":2,"answer":"revised","vi":"Đã đến lúc liên đoàn phải sửa đổi các quy định chống doping mà họ soạn ra từ hơn một thập kỷ trước.","explanation":"<b>It's high time</b> + past subjunctive: <b>It's high time the federation revised</b>; the past form refers to the present or future and stresses that it should already have happened. ✗ <b>revise</b> — the bare subjunctive follows <b>recommend / suggest that</b>, not <b>it's time</b>; ✗ <b>revises</b> — the present simple is not used after <b>it's (high) time</b>; ✗ <b>has revised</b> — the present perfect would say it has already happened, contradicting the complaint."},{"id":"gv-ch-20-21","level":"ch","focus":"idiom","q":"Missing the cup final through injury proved ______: the striker returned fully rested for the World Cup qualifiers.","options":["a shot in the dark","a blessing in disguise","a drop in the ocean","a storm in a teacup"],"correct":1,"answer":"a blessing in disguise","vi":"Việc lỡ trận chung kết cúp vì chấn thương hóa ra lại là trong cái rủi có cái may: tiền đạo trở lại với thể trạng sung sức cho vòng loại World Cup.","explanation":"<b>A blessing in disguise</b> = something that seems bad but turns out well; the clue is <b>proved</b> plus the colon: missing the final led to a well-rested return. ✗ <b>a shot in the dark</b> — a wild guess; ✗ <b>a drop in the ocean</b> — an amount too small to matter; ✗ <b>a storm in a teacup</b> — a big fuss about something unimportant."},{"id":"gv-ch-20-22","level":"ch","focus":"article-quantifier","q":"Only ______ of the stadium's eighty thousand seats were empty when the final kicked off.","options":["a few","few","a little","little"],"correct":0,"answer":"a few","vi":"Chỉ có một vài chỗ trong số tám mươi nghìn ghế của sân vận động là còn trống khi trận chung kết bắt đầu.","explanation":"<b>Seats</b> is plural countable, and <b>only a few</b> = a small number; <b>only</b> already carries the 'not many' meaning, so the positive <b>a few</b> is used. ✗ <b>few</b> — already means 'hardly any' (negative), so <b>only few</b> is not standard English; ✗ <b>a little</b> — used with uncountable nouns (a little water); ✗ <b>little</b> — uncountable and negative, so wrong twice."},{"id":"gv-ch-20-23","level":"ch","focus":"collocation","q":"The inquiry's report drew a ______ distinction between honest reporting and the paid content that had been dressed up as news.","options":["strong","hard","sharp","heavy"],"correct":2,"answer":"sharp","vi":"Báo cáo của cuộc điều tra phân biệt rõ ràng giữa đưa tin trung thực và nội dung được trả tiền nhưng được khoác vỏ tin tức.","explanation":"The collocation is <b>draw a sharp distinction</b> (= a very clear one); the clue is <b>distinction between</b>. ✗ <b>strong</b> — collocates with <b>argument / case / evidence</b>; the standard adjectives for a distinction are sharp, clear or fine; ✗ <b>hard</b> — describes a difficult decision or a hard line, not a distinction; ✗ <b>heavy</b> — collocates with <b>rain / traffic / losses</b>."},{"id":"gv-ch-20-24","level":"ch","focus":"word-choice","q":"Two independent engineers have since ______ the whistleblower's account of cracks in the dam's spillway.","options":["cooperated","coincided","conformed","corroborated"],"correct":3,"answer":"corroborated","vi":"Hai kỹ sư độc lập sau đó đã xác nhận lời kể của người tố giác về các vết nứt ở đập tràn của con đập.","explanation":"<b>Corroborate</b> = confirm an account with further evidence, and it takes a direct object: <b>corroborated the whistleblower's account</b>. ✗ <b>cooperated</b> — work together, needs <b>with</b>; ✗ <b>coincided</b> — happen at the same time or agree by chance, needs <b>with</b> and cannot take an account as its object; ✗ <b>conformed</b> — follow rules or standards, needs <b>to / with</b>."},{"id":"gv-ch-20-25","level":"ch","focus":"double-blank","q":"Once the last sticking points over image rights had been ______, the broadcasting deal was ______ by both boards on Monday.","options":["ironed off / sealed off","wiped out / signed off","ironed out / signed off","ironed out / sent off"],"correct":2,"answer":"ironed out / signed off","vi":"Khi những vướng mắc cuối cùng về bản quyền hình ảnh đã được giải quyết, thỏa thuận phát sóng được cả hai hội đồng quản trị phê duyệt hôm thứ Hai.","explanation":"<b>Iron out</b> = resolve small problems (the <b>sticking points</b>), and <b>sign off</b> = formally approve (<b>by both boards</b>). ✗ <b>ironed off / sealed off</b> — 'iron off' does not exist, and <b>seal off</b> = close an area; ✗ <b>wiped out / signed off</b> — <b>wipe out</b> = destroy completely, too violent for settling disagreements; ✗ <b>ironed out / sent off</b> — <b>send off</b> = order a player off the pitch or post a letter, not approve a deal."},{"id":"gv-ch-21-1","level":"ch","focus":"tense","q":"By the time the new metro line finally opens, the city ______ on it for eleven years.","options":["will work","will have been working","is working","has been working"],"correct":1,"answer":"will have been working","vi":"Đến lúc tuyến metro mới cuối cùng khánh thành, thành phố sẽ thi công tuyến này được mười một năm rồi.","explanation":"An action continuing up to a future point (<b>by the time … opens</b> + <b>for eleven years</b>) takes the future perfect continuous: <b>will have been working</b>. ✗ <b>will work</b> — simple future, cannot carry the duration <b>for eleven years</b>; ✗ <b>is working</b> — present continuous, no future perspective; ✗ <b>has been working</b> — present perfect measures up to now, not up to a future moment."},{"id":"gv-ch-21-2","level":"ch","focus":"word-choice","q":"The judge's ______ handling of the case was praised by both sides, neither of which felt it had been favoured.","options":["impartial","indifferent","apathetic","aloof"],"correct":0,"answer":"impartial","vi":"Cách xử lý vụ án công tâm của thẩm phán được cả hai bên khen ngợi, không bên nào cảm thấy mình được thiên vị.","explanation":"The clue <b>neither … felt it had been favoured</b> means the judge treated both sides equally: <b>impartial</b> (fair, not biased). ✗ <b>indifferent</b> — not caring either way; ✗ <b>apathetic</b> — lacking interest or energy; ✗ <b>aloof</b> — cold and distant in manner. None of those would be <b>praised by both sides</b>."},{"id":"gv-ch-21-3","level":"ch","focus":"idiom","q":"When the landlord raised the rent for the third time in a year, it was ______ for the tenants, who began organising a rent strike.","options":["the last word","the last resort","the last straw","the last laugh"],"correct":2,"answer":"the last straw","vi":"Khi chủ nhà tăng tiền thuê lần thứ ba trong một năm, đó là giọt nước tràn ly đối với người thuê, và họ bắt đầu tổ chức đình công tiền nhà.","explanation":"A <b>third</b> rise that finally triggers a <b>rent strike</b> is <b>the last straw</b> (the final small problem that makes things unbearable). ✗ <b>the last resort</b> — the only remaining option; ✗ <b>the last word</b> — the final say in an argument; ✗ <b>the last laugh</b> — winning in the end after seeming to lose."},{"id":"gv-ch-21-4","level":"ch","focus":"phrasal-verb","q":"The printing plant was forced to ______ a third of its workforce once the newspaper moved online.","options":["lay out","lay down","lay up","lay off"],"correct":3,"answer":"lay off","vi":"Nhà in buộc phải sa thải một phần ba nhân công khi tờ báo chuyển sang phát hành trực tuyến.","explanation":"Dismissing <b>a third of its workforce</b> because work has dried up is to <b>lay off</b> workers. ✗ <b>lay out</b> — arrange, or spend money; ✗ <b>lay down</b> — put down, or set rules; ✗ <b>lay up</b> — store away, or confine someone to bed with illness."},{"id":"gv-ch-21-5","level":"ch","focus":"inversion","q":"______ the laboratory had repeated the test three times did the researchers announce that the river's lead levels were safe.","options":["Until","As soon as","Not until","By the time"],"correct":2,"answer":"Not until","vi":"Mãi đến khi phòng thí nghiệm lặp lại xét nghiệm ba lần, các nhà nghiên cứu mới công bố rằng mức chì trong con sông đã ở ngưỡng an toàn.","explanation":"The inverted main clause <b>did the researchers announce</b> demands a negative opener: <b>Not until</b> + clause. ✗ <b>Until</b>, ✗ <b>As soon as</b>, ✗ <b>By the time</b> — all ordinary time conjunctions that would need normal word order (<i>the researchers announced</i>); only a negative/restrictive phrase fronted to the sentence triggers inversion."},{"id":"gv-ch-21-6","level":"ch","focus":"word-choice","q":"The minister sounded distinctly ______ about the bill, praising its aims in one breath and questioning its cost in the next.","options":["indifferent","apathetic","oblivious","ambivalent"],"correct":3,"answer":"ambivalent","vi":"Bộ trưởng tỏ ra rõ ràng là nước đôi về dự luật, vừa khen mục tiêu của nó ở câu trước lại vừa nghi ngờ chi phí ở câu sau.","explanation":"<b>Praising … in one breath and questioning … in the next</b> shows mixed feelings: <b>ambivalent</b> (about). ✗ <b>indifferent</b> — not caring at all; ✗ <b>apathetic</b> — lacking interest; ✗ <b>oblivious</b> — unaware, and takes <b>to/of</b>, not <b>about</b>."},{"id":"gv-ch-21-7","level":"ch","focus":"collocation","q":"The appeal court ______ the original ruling, rejecting every ground on which the developer had challenged it.","options":["upheld","held up","kept up","retained"],"correct":0,"answer":"upheld","vi":"Tòa phúc thẩm giữ nguyên phán quyết ban đầu, bác bỏ mọi căn cứ mà chủ đầu tư đã dùng để khiếu nại.","explanation":"A court that rejects every ground of appeal <b>upholds</b> the original ruling (confirms it). ✗ <b>held up</b> — delayed, or supported physically; ✗ <b>kept up</b> — maintained a pace or standard; ✗ <b>retained</b> — kept possession of, not used of confirming a decision."},{"id":"gv-ch-21-8","level":"ch","focus":"modal","q":"The mayor ______ the report before the press conference; she stumbled over even its most basic figures.","options":["needn't have read","shouldn't have read","can't have read","mustn't have read"],"correct":2,"answer":"can't have read","vi":"Thị trưởng chắc chắn đã không đọc bản báo cáo trước buổi họp báo; bà vấp ngay cả ở những con số cơ bản nhất.","explanation":"<b>Stumbled over even its most basic figures</b> is evidence she did not read it, so the speaker makes a confident negative deduction: <b>can't have + past participle</b>. ✗ <b>needn't have read</b> — she read it but it was unnecessary; ✗ <b>shouldn't have read</b> — she read it and was wrong to; ✗ <b>mustn't have read</b> — <b>must have</b> is for positive deduction only; the negative is <b>can't have</b>."},{"id":"gv-ch-21-9","level":"ch","focus":"idiom","q":"Rather than keep patching the leaking roof every winter, the housing association decided to ______ and replace it entirely.","options":["bite the bullet","bite the dust","bite its tongue","bite off more than it could chew"],"correct":0,"answer":"bite the bullet","vi":"Thay vì cứ vá mái nhà dột mỗi mùa đông, hiệp hội nhà ở quyết định cắn răng chịu đựng và thay toàn bộ mái.","explanation":"Replacing the roof <b>entirely</b> rather than <b>keep patching</b> is an unpleasant but necessary step: <b>bite the bullet</b>. ✗ <b>bite the dust</b> — fail, die or be defeated; ✗ <b>bite its tongue</b> — stay silent though tempted to speak; ✗ <b>bite off more than it could chew</b> — take on more than it can handle."},{"id":"gv-ch-21-10","level":"ch","focus":"relative","q":"The linguist ______ fieldwork on endangered dialects won last year's prize is now advising the ministry on language policy.","options":["whom","whose","which","that"],"correct":1,"answer":"whose","vi":"Nhà ngôn ngữ học mà công trình điền dã về các phương ngữ đang mai một đã đoạt giải năm ngoái hiện đang cố vấn cho bộ về chính sách ngôn ngữ.","explanation":"The blank sits before the noun <b>fieldwork</b>, which belongs to the linguist, so the possessive relative <b>whose</b> is needed. ✗ <b>whom</b> — object pronoun, cannot come before a noun; ✗ <b>which</b> — not used for a person; ✗ <b>that</b> — a subject/object relative, leaving <b>fieldwork</b> with no link to the linguist."},{"id":"gv-ch-21-11","level":"ch","focus":"double-blank","q":"The columnist ______ the nail on the head when she ______ that the city has plenty of homes, just not where people can afford to live.","options":["struck / observing","hit / observing","hit / observed","struck / observed"],"correct":2,"answer":"hit / observed","vi":"Nhà bình luận đã nói trúng phóc khi bà nhận xét rằng thành phố có thừa nhà ở, chỉ là không ở những nơi người dân đủ tiền sống.","explanation":"The idiom is <b>hit the nail on the head</b> (say exactly the right thing), and the <b>when</b>-clause needs a finite verb: <b>observed</b>. ✗ <b>struck / observing</b> — <b>strike</b> is not the verb of this idiom, and <b>observing</b> is a participle with no tense; ✗ <b>hit / observing</b> — <b>when she observing</b> has no finite verb; ✗ <b>struck / observed</b> — wrong verb for the idiom."},{"id":"gv-ch-21-12","level":"ch","focus":"word-choice","q":"Older residents are ______ to abandon the low-rise streets they grew up in, however generous the relocation package.","options":["averse","hostile","resistant","loath"],"correct":3,"answer":"loath","vi":"Những cư dân lớn tuổi không muốn rời bỏ những con phố nhà thấp tầng nơi họ lớn lên, dù gói tái định cư có hào phóng đến đâu.","explanation":"Only <b>loath</b> is followed by <b>to + infinitive</b>: <b>loath to abandon</b> (very unwilling). ✗ <b>averse</b> — takes <b>to + noun/-ing</b> (<i>averse to abandoning</i>); ✗ <b>hostile</b> — <b>hostile to</b> a person or idea, not <b>to</b> + verb; ✗ <b>resistant</b> — <b>resistant to change</b>, again <b>to</b> + noun, not infinitive."},{"id":"gv-ch-21-13","level":"ch","focus":"linking","q":"Rents in the capital have doubled in a decade; ______, wages have barely moved.","options":["meanwhile","therefore","otherwise","likewise"],"correct":0,"answer":"meanwhile","vi":"Tiền thuê nhà ở thủ đô đã tăng gấp đôi trong một thập kỷ; trong khi đó, tiền lương hầu như không nhúc nhích.","explanation":"Two things over <b>the same decade</b> are set side by side (rents up, wages flat), so <b>meanwhile</b>. ✗ <b>therefore</b> — gives a result, but flat wages are not caused by rising rents; ✗ <b>otherwise</b> — if not, the consequence of not doing something; ✗ <b>likewise</b> — signals similarity, but the two facts contrast."},{"id":"gv-ch-21-14","level":"ch","focus":"phrasal-verb","q":"Most junior reporters would ______ the chance to cover a general election, even if it meant weeks without a day off.","options":["jump through","jump at","jump over","jump off"],"correct":1,"answer":"jump at","vi":"Hầu hết phóng viên trẻ sẽ chớp ngay cơ hội đưa tin về một cuộc tổng tuyển cử, dù phải làm nhiều tuần không nghỉ.","explanation":"Eager acceptance of <b>the chance</b> (<b>even if it meant weeks without a day off</b>) is <b>jump at</b>. ✗ <b>jump through</b> — <i>jump through hoops</i>, go through tedious procedures; ✗ <b>jump over</b> — literally leap across; ✗ <b>jump off</b> — literally leap down from."},{"id":"gv-ch-21-15","level":"ch","focus":"subjunctive","q":"The committee recommended that the controversial clause ______ from the bill before its second reading.","options":["was removed","is removed","be removed","would be removed"],"correct":2,"answer":"be removed","vi":"Ủy ban đề nghị điều khoản gây tranh cãi được loại khỏi dự luật trước phiên đọc thứ hai.","explanation":"After <b>recommend that</b> (also suggest, insist, demand) the verb is subjunctive, the base form: <b>be removed</b>, whatever the tense of <b>recommended</b>. ✗ <b>was removed</b> — past tense, not the base form; ✗ <b>is removed</b> — present, not the base form; ✗ <b>would be removed</b> — modal, not used after recommend that."},{"id":"gv-ch-21-16","level":"ch","focus":"collocation","q":"The dictionary's editors keep a ______ eye on social media for words that are slipping into everyday use.","options":["tight","strict","near","close"],"correct":3,"answer":"close","vi":"Các biên tập viên từ điển theo dõi sát mạng xã hội để tìm những từ đang dần đi vào ngôn ngữ hằng ngày.","explanation":"Watching carefully is <b>keep a close eye on</b>, a fixed phrase. ✗ <b>tight</b> — goes with <i>grip</i>, <i>rein</i>, <i>budget</i>, not <i>eye</i>; ✗ <b>strict</b> — describes rules or people, not an eye; ✗ <b>near</b> — physical distance, never used with <i>eye on</i>."},{"id":"gv-ch-21-17","level":"ch","focus":"word-choice","q":"City officials were accused of being ______ about flood risk, insisting the century-old drains would cope as they always had.","options":["reluctant","complacent","apathetic","averse"],"correct":1,"answer":"complacent","vi":"Giới chức thành phố bị cáo buộc là chủ quan về nguy cơ ngập lụt, khăng khăng rằng hệ thống cống trăm năm tuổi vẫn sẽ chịu được như trước nay.","explanation":"<b>Insisting the drains would cope as they always had</b> is false confidence that ignores a danger: <b>complacent about</b>. ✗ <b>reluctant</b> — unwilling, and takes <b>to</b> + verb; ✗ <b>apathetic</b> — lacking interest, not over-confident, and takes <b>about/towards</b> only loosely; ✗ <b>averse</b> — opposed, and takes <b>to</b>."},{"id":"gv-ch-21-18","level":"ch","focus":"idiom","q":"The developer ______ at the last minute and withdrew its bid for the riverside site, citing 'market uncertainty'.","options":["got cold feet","got itchy feet","got the cold shoulder","got off on the wrong foot"],"correct":0,"answer":"got cold feet","vi":"Chủ đầu tư chùn bước vào phút chót và rút hồ sơ đấu thầu khu đất ven sông, viện lý do 'thị trường bất ổn'.","explanation":"Withdrawing <b>at the last minute</b> is losing your nerve: <b>get cold feet</b>. ✗ <b>got itchy feet</b> — a desire to travel or move on; ✗ <b>got the cold shoulder</b> — was deliberately ignored; ✗ <b>got off on the wrong foot</b> — made a bad start with someone."},{"id":"gv-ch-21-19","level":"ch","focus":"gerund-infinitive","q":"The tenants' association now regrets ______ the landlord's first offer, which looks generous beside the one on the table today.","options":["to reject","reject","rejecting","to be rejecting"],"correct":2,"answer":"rejecting","vi":"Hiệp hội người thuê nhà giờ hối tiếc vì đã từ chối đề nghị đầu tiên của chủ nhà, đề nghị ấy trông hào phóng hơn hẳn so với đề nghị đang bàn hôm nay.","explanation":"<b>Regret + -ing</b> looks back at something already done and wished undone: <b>regrets rejecting</b> the first offer. ✗ <b>to reject</b> — <b>regret + to-infinitive</b> only introduces bad news now (<i>we regret to inform you</i>); ✗ <b>reject</b> — regret never takes a bare infinitive; ✗ <b>to be rejecting</b> — continuous infinitive, and still the wrong pattern."},{"id":"gv-ch-21-20","level":"ch","focus":"conditional","q":"If the city ______ its drainage system a decade ago, last week's storm would not have flooded three metro stations.","options":["modernised","has modernised","would have modernised","had modernised"],"correct":3,"answer":"had modernised","vi":"Nếu thành phố đã hiện đại hóa hệ thống thoát nước từ một thập kỷ trước, cơn bão tuần rồi đã không làm ngập ba ga metro.","explanation":"An unreal past condition (<b>a decade ago</b>) with a past result (<b>would not have flooded</b>) is the third conditional: <b>if + past perfect</b>, <b>had modernised</b>. ✗ <b>modernised</b> — past simple gives a second conditional, needing <i>would not flood</i>; ✗ <b>has modernised</b> — present perfect cannot sit with <b>a decade ago</b>; ✗ <b>would have modernised</b> — <b>would</b> belongs in the result clause, not after <b>if</b>."},{"id":"gv-ch-21-21","level":"ch","focus":"word-choice","q":"Voters grew steadily ______ with a government that promised change every spring and delivered none by autumn.","options":["dismissive","disillusioned","disinclined","disapproving"],"correct":1,"answer":"disillusioned","vi":"Cử tri ngày càng vỡ mộng với một chính phủ cứ mỗi mùa xuân hứa đổi thay mà đến mùa thu chẳng làm được gì.","explanation":"Losing faith after being let down (<b>promised change … delivered none</b>) is <b>disillusioned with</b>. ✗ <b>dismissive</b> — treats something as unimportant, and takes <b>of</b>; ✗ <b>disinclined</b> — unwilling, and takes <b>to</b> + verb; ✗ <b>disapproving</b> — thinks something is wrong, and takes <b>of</b>."},{"id":"gv-ch-21-22","level":"ch","focus":"participle","q":"______ in plain language rather than legal jargon, the new tenancy contract can be understood without a lawyer.","options":["Written","Writing","Having written","To write"],"correct":0,"answer":"Written","vi":"Được viết bằng ngôn ngữ giản dị thay vì thuật ngữ pháp lý, hợp đồng thuê nhà mới có thể hiểu được mà không cần luật sư.","explanation":"The contract is written by someone, so the reduced clause is passive: past participle <b>Written</b>. ✗ <b>Writing</b> — active, would make the contract the writer; ✗ <b>Having written</b> — active perfect participle, same problem; ✗ <b>To write</b> — an infinitive of purpose, which makes no sense here."},{"id":"gv-ch-21-23","level":"ch","focus":"idiom","q":"After fourteen hours of talks on the budget, the two parties agreed to ______ and resume in the morning.","options":["call the shots","call a spade a spade","call it a day","call the tune"],"correct":2,"answer":"call it a day","vi":"Sau mười bốn giờ đàm phán về ngân sách, hai đảng đồng ý dừng lại ở đây và tiếp tục vào sáng hôm sau.","explanation":"Stopping <b>after fourteen hours</b> to <b>resume in the morning</b> is <b>call it a day</b>. ✗ <b>call the shots</b> — be in charge and make the decisions; ✗ <b>call the tune</b> — also be in control; ✗ <b>call a spade a spade</b> — speak bluntly and honestly."},{"id":"gv-ch-21-24","level":"ch","focus":"double-blank","q":"Had the council ______ with residents from the outset, far fewer of them would ______ opposed the scheme.","options":["squared / had","levelled / had","squared / have","levelled / have"],"correct":3,"answer":"levelled / have","vi":"Nếu hội đồng thành phố thẳng thắn với cư dân ngay từ đầu, thì đã có ít người phản đối dự án hơn nhiều.","explanation":"Being honest with residents is <b>level with</b> them, and the result clause of a past unreal condition (<b>Had the council …</b>) is <b>would have + past participle</b>. ✗ <b>squared / had</b> — <b>square with</b> means be consistent with, and <b>would had</b> is impossible; ✗ <b>levelled / had</b> — right verb, but <b>would had</b> is not a form; ✗ <b>squared / have</b> — wrong verb."},{"id":"gv-ch-21-25","level":"ch","focus":"collocation","q":"The new tram line is expected to ______ pressure on the city's overcrowded northern bus routes.","options":["release","relieve","loosen","lighten"],"correct":1,"answer":"relieve","vi":"Tuyến tàu điện mới được kỳ vọng sẽ giảm bớt áp lực cho các tuyến xe buýt quá tải ở phía bắc thành phố.","explanation":"Reducing strain on a service is <b>relieve pressure on</b>, the standard collocation. ✗ <b>release</b> — <i>release pressure</i> is physical, letting gas or steam out; ✗ <b>loosen</b> — goes with <i>grip</i>, <i>rules</i>, <i>a knot</i>, not <i>pressure on</i>; ✗ <b>lighten</b> — goes with <i>a load</i> or <i>the mood</i>, not <i>pressure on</i>."},{"id":"gv-ch-22-1","level":"ch","focus":"word-choice","q":"The reforestation fund is facing a ______ of nearly two million dollars between what donors pledged and what they actually paid.","options":["scarcity","shortfall","deficiency","dearth"],"correct":1,"answer":"shortfall","vi":"Quỹ trồng lại rừng đang đối mặt với mức thiếu hụt gần hai triệu đô la giữa số tiền các nhà tài trợ cam kết và số tiền họ thực sự chi trả.","explanation":"The clue <b>of nearly two million dollars between what donors pledged and what they actually paid</b> is a measured gap between an expected sum and a real one, which is a <b>shortfall</b>. ✗ <b>scarcity</b> — a general shortage of a resource (a scarcity of water), not a gap you can count; ✗ <b>deficiency</b> — a lack of something the body or system needs (a vitamin deficiency); ✗ <b>dearth</b> — an almost complete absence (a dearth of talent), never measured in dollars."},{"id":"gv-ch-22-2","level":"ch","focus":"idiom","q":"Once electric cars became fashionable, several oil companies were quick to ______, launching charging networks of their own.","options":["jump the gun","jump through hoops","jump on the bandwagon","jump ship"],"correct":2,"answer":"jump on the bandwagon","vi":"Khi xe điện trở nên thịnh hành, nhiều công ty dầu mỏ đã nhanh chóng chạy theo trào lưu, tự tung ra các mạng lưới trạm sạc của riêng mình.","explanation":"The clue <b>once electric cars became fashionable … quick to</b> describes joining a trend after it has become popular = <b>jump on the bandwagon</b>. ✗ <b>jump the gun</b> — act too early, before the proper time – the opposite of following others; ✗ <b>jump through hoops</b> — go through many tiresome steps to get something; ✗ <b>jump ship</b> — suddenly leave an organisation or cause, but here the companies are joining, not leaving."},{"id":"gv-ch-22-3","level":"ch","focus":"modal","q":"The burglars ______ in through the front door – it was still bolted from the inside when the police arrived.","options":["mightn't have come","needn't have come","shouldn't have come","can't have come"],"correct":3,"answer":"can't have come","vi":"Bọn trộm không thể nào đã vào bằng cửa trước – cửa vẫn còn cài then từ bên trong khi cảnh sát đến.","explanation":"The clue <b>it was still bolted from the inside</b> is proof that entry by the front door was impossible, so we need a confident past deduction: <b>can't have + past participle</b>. ✗ <b>mightn't have come</b> — only 'perhaps they didn't', far too weak with solid proof; ✗ <b>needn't have come</b> — 'they did come, but it was unnecessary', which makes no sense; ✗ <b>shouldn't have come</b> — criticises a past action as wrong, not a statement about what was possible."},{"id":"gv-ch-22-4","level":"ch","focus":"collocation","q":"Prosecutors decided to ______ charges against the chemical company after the spill was traced to its pipeline.","options":["bring","raise","put","make"],"correct":0,"answer":"bring","vi":"Các công tố viên quyết định khởi tố công ty hóa chất sau khi vụ rò rỉ được xác định bắt nguồn từ đường ống của công ty này.","explanation":"Charges are <b>brought</b> (or pressed) <b>against</b> someone – a fixed legal collocation, signalled by <b>prosecutors … charges against</b>. ✗ <b>raise</b> — collocates with objections, questions or concerns, not charges; ✗ <b>put</b> — you put a question or a case to someone; 'put charges' is not English; ✗ <b>make</b> — you make an accusation or a complaint, but charges are not 'made'."},{"id":"gv-ch-22-5","level":"ch","focus":"phrasal-verb","q":"The city's recycling scheme has failed to ______ the expectations of the residents who campaigned so hard for it.","options":["live down","live off","live through","live up to"],"correct":3,"answer":"live up to","vi":"Chương trình tái chế của thành phố đã không đáp ứng được kỳ vọng của những cư dân đã vận động hết mình cho nó.","explanation":"The clue <b>failed to ______ the expectations</b> needs the phrasal verb meaning 'be as good as what was hoped': <b>live up to</b>. ✗ <b>live down</b> — make people forget a past embarrassment (he never lived down that mistake); ✗ <b>live off</b> — depend on something or someone for money or food (live off his parents); ✗ <b>live through</b> — survive a difficult period (live through the war)."},{"id":"gv-ch-22-6","level":"ch","focus":"double-blank","q":"The council inspects its flood defences only once in a ______ moon, ______ neighbouring towns check theirs every spring.","options":["full / whereas","blue / whereas","blue / despite","new / while"],"correct":1,"answer":"blue / whereas","vi":"Hội đồng thành phố hiếm hoi lắm mới kiểm tra hệ thống đê chắn lũ, trong khi các thị trấn lân cận kiểm tra hàng năm vào mỗi mùa xuân.","explanation":"The idiom is <b>once in a blue moon</b> = very rarely, and the two clauses contrast (<b>only once … / every spring</b>), so the second blank needs the contrast conjunction <b>whereas</b>. ✗ <b>full / whereas</b> — 'once in a full moon' is not an idiom; ✗ <b>blue / despite</b> — despite must be followed by a noun or -ing, not a clause with a subject and verb; ✗ <b>new / while</b> — while could join the clauses, but 'once in a new moon' is not the idiom."},{"id":"gv-ch-22-7","level":"ch","focus":"word-choice","q":"The courts are still struggling to clear a ______ of more than sixty thousand cases that built up during the pandemic.","options":["stockpile","reserve","backlog","surplus"],"correct":2,"answer":"backlog","vi":"Các tòa án vẫn đang chật vật giải quyết lượng tồn đọng hơn sáu mươi nghìn vụ án tích tụ trong đại dịch.","explanation":"The clues <b>clear</b> and <b>cases that built up during the pandemic</b> point to overdue work that has piled up: a <b>backlog</b>. ✗ <b>stockpile</b> — a large supply deliberately stored for future use (a stockpile of weapons); ✗ <b>reserve</b> — a supply kept back until it is needed (oil reserves); ✗ <b>surplus</b> — an amount left over beyond what is needed (a budget surplus) – none of these means unfinished work."},{"id":"gv-ch-22-8","level":"ch","focus":"inversion","q":"______ the vaccine had been tested on ten thousand volunteers did the regulator agree to license it.","options":["Not only","Only after","Hardly","Seldom"],"correct":1,"answer":"Only after","vi":"Chỉ sau khi vắc-xin được thử nghiệm trên mười nghìn tình nguyện viên, cơ quan quản lý mới đồng ý cấp phép cho nó.","explanation":"The inverted main clause <b>did the regulator agree</b> comes after a full subordinate clause (<b>the vaccine had been tested …</b>), which is the pattern <b>Only after + clause + inverted main clause</b>. ✗ <b>Not only</b> — inversion must follow it immediately (Not only had the vaccine …) and it needs 'but also' later; ✗ <b>Hardly</b> — needs immediate inversion and a 'when' clause (Hardly had … when); ✗ <b>Seldom</b> — needs immediate inversion (Seldom did …) and gives no time sequence."},{"id":"gv-ch-22-9","level":"ch","focus":"idiom","q":"The minister meant to unveil the carbon tax in June, but a careless tweet from an aide ______ three weeks early.","options":["let the cat out of the bag","let sleeping dogs lie","let off steam","let the grass grow under his feet"],"correct":0,"answer":"let the cat out of the bag","vi":"Bộ trưởng định công bố thuế các-bon vào tháng Sáu, nhưng một dòng tweet bất cẩn của trợ lý đã để lộ bí mật sớm ba tuần.","explanation":"The clue <b>meant to unveil … in June, but a careless tweet … three weeks early</b> describes a secret revealed by accident = <b>let the cat out of the bag</b>. ✗ <b>let sleeping dogs lie</b> — avoid stirring up an old problem; ✗ <b>let off steam</b> — release anger or energy in a harmless way; ✗ <b>let the grass grow under his feet</b> — waste time by delaying – the opposite of acting early."},{"id":"gv-ch-22-10","level":"ch","focus":"subjunctive","q":"The union insisted that every worker ______ issued with protective clothing before entering the contaminated site.","options":["were","has been","be","will be"],"correct":2,"answer":"be","vi":"Công đoàn khăng khăng yêu cầu mọi công nhân phải được cấp quần áo bảo hộ trước khi vào khu vực bị ô nhiễm.","explanation":"<b>Insisted that</b> (like demand, suggest, recommend + that) is followed by the bare subjunctive, so the verb stays in its base form whatever the tense of the main clause: <b>(should) be issued</b>. ✗ <b>were</b> — the past subjunctive belongs after wish / if / as though, not after insist that; ✗ <b>has been</b> — an ordinary present perfect breaks the subjunctive pattern and clashes with past 'insisted'; ✗ <b>will be</b> — a future tense is not used in the that-clause after a verb of demand."},{"id":"gv-ch-22-11","level":"ch","focus":"collocation","q":"The evidence against the ringleader was ______ – fingerprints, CCTV footage and two eyewitnesses who picked him out of a line-up.","options":["overpowering","overwhelming","overriding","overbearing"],"correct":1,"answer":"overwhelming","vi":"Bằng chứng chống lại kẻ cầm đầu là quá rõ ràng và áp đảo – dấu vân tay, hình ảnh camera an ninh và hai nhân chứng đã nhận diện được hắn.","explanation":"<b>Overwhelming evidence</b> is the collocation for proof too strong to resist, and the list <b>fingerprints, CCTV footage and two eyewitnesses</b> shows exactly that. ✗ <b>overpowering</b> — used of smells, heat or emotions that are physically too strong; ✗ <b>overriding</b> — 'more important than everything else' (an overriding priority), not strength of proof; ✗ <b>overbearing</b> — describes a bossy, domineering person, not evidence."},{"id":"gv-ch-22-12","level":"ch","focus":"gerund-infinitive","q":"The accountant admitted ______ the invoices but denied knowing that they had been forged.","options":["to sign","having signed","to have signed","sign"],"correct":1,"answer":"having signed","vi":"Kế toán viên thừa nhận đã ký các hóa đơn nhưng phủ nhận việc biết chúng là giả.","explanation":"<b>Admit</b> takes a gerund, and the clue <b>but denied knowing that they had been forged</b> puts the signing before the admission, so the perfect gerund <b>having signed</b> fits. ✗ <b>to sign</b> — admit is never followed by a to-infinitive; ✗ <b>to have signed</b> — a perfect infinitive is still an infinitive, so it fails after admit; ✗ <b>sign</b> — a bare verb cannot be the object of admit."},{"id":"gv-ch-22-13","level":"ch","focus":"word-choice","q":"The new sentencing guidelines give judges very little ______ to shorten a term for a first-time offender.","options":["allowance","clearance","tolerance","leeway"],"correct":3,"answer":"leeway","vi":"Hướng dẫn tuyên án mới cho các thẩm phán rất ít khoảng linh hoạt để rút ngắn mức án đối với người phạm tội lần đầu.","explanation":"The clue <b>very little ______ to shorten a term</b> means very little freedom to act within the rules, which is <b>leeway</b>. ✗ <b>allowance</b> — money paid regularly, or a permitted amount (a baggage allowance); ✗ <b>clearance</b> — official permission (security clearance) or physical space (bridge clearance); ✗ <b>tolerance</b> — willingness to accept behaviour or opinions you dislike, not room to vary a sentence."},{"id":"gv-ch-22-14","level":"ch","focus":"phrasal-verb","q":"Give me a couple of days to ______ your offer before I hand in my notice at the bank.","options":["mull over","glaze over","hand over","take over"],"correct":0,"answer":"mull over","vi":"Hãy cho tôi vài ngày để cân nhắc kỹ lời đề nghị của anh trước khi tôi nộp đơn xin nghỉ việc ở ngân hàng.","explanation":"The clue <b>give me a couple of days to ______ your offer before I hand in my notice</b> means 'think about it carefully' = <b>mull over</b>. ✗ <b>glaze over</b> — (of eyes) show boredom or tiredness; it takes no object; ✗ <b>hand over</b> — give something to someone else, which makes no sense with an offer you received; ✗ <b>take over</b> — take control of a company or job, not consider an offer."},{"id":"gv-ch-22-15","level":"ch","focus":"linking","q":"The tannery was fined twice last year; ______, it continues to discharge untreated waste into the river.","options":["whereas","therefore","nevertheless","otherwise"],"correct":2,"answer":"nevertheless","vi":"Xưởng thuộc da đã bị phạt hai lần vào năm ngoái; tuy vậy, nó vẫn tiếp tục xả chất thải chưa qua xử lý ra sông.","explanation":"The tannery <b>was fined twice</b> yet <b>continues to discharge</b> waste, so the second clause contradicts what the fines should have achieved: the concessive adverb <b>nevertheless</b>, which can stand between a semicolon and a comma. ✗ <b>whereas</b> — a conjunction that joins two clauses directly, so it cannot sit between ';' and ','; ✗ <b>therefore</b> — 'as a result', but continued pollution is not a result of the fines; ✗ <b>otherwise</b> — 'if not', which would need the first clause to be a condition."},{"id":"gv-ch-22-16","level":"ch","focus":"participle","q":"______ afford the rising licence fees, the small radio station switched to streaming its programmes online.","options":["Been unable to","Be unable to","Having unable to","Being unable to"],"correct":3,"answer":"Being unable to","vi":"Vì không thể trả nổi phí bản quyền ngày càng tăng, đài phát thanh nhỏ đã chuyển sang phát trực tuyến các chương trình của mình.","explanation":"A present-participle clause gives the reason for the main clause: <b>Being unable to afford</b> = because it was unable to afford. ✗ <b>Been unable to</b> — a past participle cannot open a participle clause without 'having'; ✗ <b>Be unable to</b> — a bare infinitive cannot start a clause of reason; ✗ <b>Having unable to</b> — 'having' must be followed by a past participle (having been unable), not by the adjective 'unable' alone."},{"id":"gv-ch-22-17","level":"ch","focus":"idiom","q":"Companies that delay investing in wind power now may well ______ when the government subsidies are withdrawn next year.","options":["miss the boat","miss the mark","miss the point","miss a beat"],"correct":0,"answer":"miss the boat","vi":"Những công ty trì hoãn đầu tư vào điện gió lúc này rất có thể sẽ bỏ lỡ cơ hội khi trợ cấp của chính phủ bị rút vào năm tới.","explanation":"The clue <b>delay investing now … when the subsidies are withdrawn next year</b> describes losing an opportunity by being too slow = <b>miss the boat</b>. ✗ <b>miss the mark</b> — fail to hit the target or achieve the intended result; ✗ <b>miss the point</b> — fail to understand what really matters; ✗ <b>miss a beat</b> — hesitate for a moment, usually in 'without missing a beat'."},{"id":"gv-ch-22-18","level":"ch","focus":"agreement","q":"A number of senior engineers ______ resigned since the merger was announced, leaving the department badly understaffed.","options":["has","have","is","was"],"correct":1,"answer":"have","vi":"Nhiều kỹ sư cấp cao đã từ chức kể từ khi vụ sáp nhập được công bố, khiến bộ phận này thiếu nhân lực trầm trọng.","explanation":"<b>A number of</b> + plural noun means 'several' and takes a plural verb, and <b>since the merger was announced</b> calls for the present perfect: <b>have resigned</b>. ✗ <b>has</b> — singular; that goes with 'the number of' (the number of engineers has fallen); ✗ <b>is</b> — makes a passive 'is resigned', which does not exist; ✗ <b>was</b> — singular and a past passive, wrong on both counts."},{"id":"gv-ch-22-19","level":"ch","focus":"word-choice","q":"Global coal consumption reached its ______ in 2013 and has been drifting downwards ever since.","options":["summit","climax","peak","crest"],"correct":2,"answer":"peak","vi":"Mức tiêu thụ than toàn cầu đạt đỉnh vào năm 2013 và đã giảm dần kể từ đó.","explanation":"A quantity <b>reaches its peak</b> (highest level), and <b>drifting downwards ever since</b> confirms we mean the highest point of a figure. ✗ <b>summit</b> — the top of a mountain, or a meeting of leaders; ✗ <b>climax</b> — the most exciting or decisive moment of a story or event; ✗ <b>crest</b> — the top of a wave or a hill, not a level of consumption."},{"id":"gv-ch-22-20","level":"ch","focus":"passive","q":"The suspect is believed ______ the country on a false passport within hours of the robbery.","options":["to have left","to leave","having left","to be left"],"correct":0,"answer":"to have left","vi":"Nghi phạm được cho là đã rời khỏi đất nước bằng hộ chiếu giả chỉ vài giờ sau vụ cướp.","explanation":"After <b>is believed / thought / said + infinitive</b>, an action earlier than the belief takes the perfect infinitive, and <b>within hours of the robbery</b> is past, so <b>to have left</b>. ✗ <b>to leave</b> — a simple infinitive refers to the present or future; ✗ <b>having left</b> — a gerund, but this passive reporting pattern requires a to-infinitive; ✗ <b>to be left</b> — a passive, so the suspect would be 'left' by someone."},{"id":"gv-ch-22-21","level":"ch","focus":"comparison","q":"Recycling aluminium uses ______ energy than smelting it from raw ore, which is why scrap cans are so valuable.","options":["far less","much fewer","very less","the least"],"correct":0,"answer":"far less","vi":"Tái chế nhôm tiêu tốn ít năng lượng hơn nhiều so với luyện từ quặng thô, đó là lý do lon nhôm phế liệu có giá trị đến vậy.","explanation":"<b>Energy</b> is uncountable, so the comparative before <b>than</b> is <b>less</b>, strengthened by <b>far</b>. ✗ <b>much fewer</b> — fewer is for countable plurals (fewer cans); ✗ <b>very less</b> — very cannot modify a comparative; use much / far / a lot; ✗ <b>the least</b> — a superlative cannot be followed by than."},{"id":"gv-ch-22-22","level":"ch","focus":"idiom","q":"When my manager announced that the whole department would be relocating to Iceland, I assumed she was ______.","options":["pulling strings","pulling my leg","pulling her weight","pulling her punches"],"correct":1,"answer":"pulling my leg","vi":"Khi quản lý của tôi thông báo rằng cả phòng sẽ chuyển tới Iceland, tôi cứ tưởng chị ấy đang trêu tôi.","explanation":"The clue <b>I assumed she was</b> after an unbelievable announcement (relocating to Iceland) means I thought she was joking = <b>pulling my leg</b>. ✗ <b>pulling strings</b> — using secret influence to get something done; ✗ <b>pulling her weight</b> — doing her fair share of the work; ✗ <b>pulling her punches</b> — being gentler or less critical than she could be."},{"id":"gv-ch-22-23","level":"ch","focus":"collocation","q":"An independent laboratory has ______ doubt on the company's claim that the leak was contained within hours.","options":["shed","laid","cast","drawn"],"correct":2,"answer":"cast","vi":"Một phòng thí nghiệm độc lập đã đặt nghi vấn về tuyên bố của công ty rằng vụ rò rỉ đã được khống chế trong vài giờ.","explanation":"The fixed collocation is <b>cast doubt on</b> something = make people question it, and the lab is challenging the company's claim. ✗ <b>shed</b> — you shed light on a matter (make it clearer), the opposite idea; ✗ <b>laid</b> — you lay blame on someone, not doubt; ✗ <b>drawn</b> — you draw attention to something, not doubt."},{"id":"gv-ch-22-24","level":"ch","focus":"double-blank","q":"After weeks of haggling, the delegates finally ______ down the wording of the treaty, ______ that the wealthiest nations would fund the adaptation programme.","options":["pinned / unless","boiled / in case","narrowed / as long as","nailed / provided"],"correct":3,"answer":"nailed / provided","vi":"Sau nhiều tuần mặc cả, các đại biểu cuối cùng cũng chốt được câu chữ của hiệp ước, với điều kiện các quốc gia giàu nhất sẽ tài trợ cho chương trình thích ứng.","explanation":"<b>Nail down</b> = settle something definitely, and the condition that follows is introduced by <b>provided (that)</b> – the only one of the four conjunctions that can be followed by <b>that</b>. ✗ <b>pinned / unless</b> — 'pin down the wording' is fine, but 'unless that' does not exist; ✗ <b>boiled / in case</b> — 'in case that' is not English, and boil down means reduce to essentials; ✗ <b>narrowed / as long as</b> — 'as long as that' does not exist, and you narrow down a list of choices, not wording."},{"id":"gv-ch-22-25","level":"ch","focus":"word-choice","q":"Even a minute ______ of the pesticide is enough to kill the bees that pollinate the orchard.","options":["portion","ration","serving","dose"],"correct":3,"answer":"dose","vi":"Chỉ một liều thuốc trừ sâu rất nhỏ cũng đủ để giết chết những con ong thụ phấn cho vườn cây.","explanation":"A <b>dose</b> is a measured quantity of a drug or chemical, and <b>of the pesticide … enough to kill</b> confirms that sense. ✗ <b>portion</b> — a part of something, especially an amount of food served; ✗ <b>serving</b> — a helping of food or drink for one person; ✗ <b>ration</b> — a fixed allowance of food or fuel in times of shortage."},{"id":"gv-ch-23-1","level":"ch","focus":"word-choice","q":"The board has appointed an independent auditor to ______ how the foundation spends its grant money.","options":["overlook","oversee","overhaul","overdo"],"correct":1,"answer":"oversee","vi":"Hội đồng đã bổ nhiệm một kiểm toán viên độc lập để giám sát cách quỹ chi tiêu tiền tài trợ.","explanation":"<b>Oversee</b> = supervise or watch over; the auditor is appointed to check <b>how the foundation spends</b> its money. ✗ <b>overlook</b> — fail to notice, or ignore a fault: the opposite of checking; ✗ <b>overhaul</b> — rebuild or reform completely: an auditor inspects, not reforms; ✗ <b>overdo</b> — do to excess, and it cannot take a <b>how</b>-clause as its object."},{"id":"gv-ch-23-2","level":"ch","focus":"idiom","q":"Although they belong to the same party, the two ministers seldom ______ on how tuition fees should be set.","options":["see eye to eye","go hand in hand","stand shoulder to shoulder","play cat and mouse"],"correct":0,"answer":"see eye to eye","vi":"Dù cùng một đảng, hai vị bộ trưởng hiếm khi đồng quan điểm về cách ấn định học phí.","explanation":"<b>See eye to eye (on something)</b> = agree completely; <b>seldom</b> plus <b>on how tuition fees should be set</b> shows disagreement about an issue. ✗ <b>go hand in hand</b> — two things occur together; used of things, not people's opinions; ✗ <b>stand shoulder to shoulder</b> — support one another in a struggle; not about agreeing on a question; ✗ <b>play cat and mouse</b> — toy with or tease someone; no sense of agreement."},{"id":"gv-ch-23-3","level":"ch","focus":"collocation","q":"Sociologists describe the rush to buy the latest phone as a form of ______ consumption, a way of displaying wealth rather than meeting a need.","options":["obvious","visible","conspicuous","noticeable"],"correct":2,"answer":"conspicuous","vi":"Các nhà xã hội học mô tả cơn sốt mua điện thoại đời mới nhất là một dạng tiêu dùng phô trương, một cách khoe của cải hơn là đáp ứng nhu cầu.","explanation":"<b>Conspicuous consumption</b> is the fixed sociological term for buying expensive goods to show off wealth, which the gloss <b>displaying wealth rather than meeting a need</b> spells out. ✗ <b>obvious</b> — clear, easy to see; not the set phrase; ✗ <b>visible</b> — able to be seen; no collocation with <b>consumption</b>; ✗ <b>noticeable</b> — easy to notice; again not the term."},{"id":"gv-ch-23-4","level":"ch","focus":"linking","q":"______ the sharp rise in university tuition, enrolment has continued to climb for the fifth year running.","options":["Although","Whereas","However","Despite"],"correct":3,"answer":"Despite","vi":"Bất chấp học phí đại học tăng mạnh, số sinh viên nhập học vẫn tiếp tục tăng năm thứ năm liên tiếp.","explanation":"Contrast + noun phrase: the blank is followed by <b>the sharp rise</b>, a noun phrase with no verb, so the preposition <b>despite</b> is needed. ✗ <b>Although</b> — a conjunction that needs a subject and verb (although tuition rose…); ✗ <b>Whereas</b> — also needs a clause, and it contrasts two facts rather than showing an unexpected result; ✗ <b>However</b> — an adverb that links two sentences and cannot govern a noun phrase."},{"id":"gv-ch-23-5","level":"ch","focus":"phrasal-verb","q":"Parents who do not want their children's test scores shared with private companies may ______ of the scheme by returning a signed form.","options":["rule out","opt out","leave out","sort out"],"correct":1,"answer":"opt out","vi":"Phụ huynh không muốn điểm thi của con bị chia sẻ với các công ty tư nhân có thể rút khỏi chương trình bằng cách nộp lại mẫu đơn có chữ ký.","explanation":"<b>Opt out of</b> = choose not to take part in something; the clue is <b>of the scheme</b> after the blank, which only <b>opt out</b> takes. ✗ <b>rule out</b> — exclude as a possibility; needs a direct object, not <b>of</b>; ✗ <b>leave out</b> — omit, not include; also takes an object, and the parents are not omitting the scheme; ✗ <b>sort out</b> — solve or organise; takes an object and gives no sense of withdrawing."},{"id":"gv-ch-23-6","level":"ch","focus":"modal","q":"The donors ______ have known that the funds were being misused; the accounts were never shown to them.","options":["can't","must","should","needn't"],"correct":0,"answer":"can't","vi":"Các nhà tài trợ không thể nào biết được rằng tiền đang bị sử dụng sai mục đích; họ chưa từng được xem sổ sách.","explanation":"<b>Can't have + past participle</b> = it is impossible that something happened; the clue is <b>the accounts were never shown to them</b>, so the donors could not have known. ✗ <b>must have known</b> — near-certainty that they DID know, contradicting the second clause; ✗ <b>should have known</b> — criticises them for failing to know, but the sentence excuses them; ✗ <b>needn't have known</b> — says knowing was unnecessary, which makes no sense."},{"id":"gv-ch-23-7","level":"ch","focus":"word-choice","q":"Frequent reversals of exam policy ______ public trust in the ministry far more than any single unpopular decision.","options":["underpin","underlie","undergo","undermine"],"correct":3,"answer":"undermine","vi":"Việc liên tục đảo ngược chính sách thi cử làm xói mòn lòng tin của công chúng vào bộ nhiều hơn bất kỳ quyết định không được lòng dân nào.","explanation":"<b>Undermine</b> = gradually weaken; <b>frequent reversals</b> damage <b>public trust</b>, and the comparison with an <b>unpopular decision</b> confirms a harmful effect. ✗ <b>underpin</b> — support or strengthen; the opposite meaning; ✗ <b>underlie</b> — be the hidden cause or basis of; reversals are not the basis of trust; ✗ <b>undergo</b> — experience a process (undergo surgery); trust is not something reversals go through."},{"id":"gv-ch-23-8","level":"ch","focus":"double-blank","q":"The ministry intends to ______ out printed textbooks ______ 2030, replacing them with tablets in every classroom.","options":["fade / until","wipe / at","phase / by","wear / in"],"correct":2,"answer":"phase / by","vi":"Bộ dự định loại bỏ dần sách giáo khoa in trước năm 2030, thay bằng máy tính bảng ở mọi lớp học.","explanation":"<b>Phase out</b> = withdraw something gradually in stages (<b>replacing them with tablets</b>), and a deadline takes <b>by</b> = no later than 2030. ✗ <b>fade / until</b> — <b>fade out</b> is intransitive (things fade out by themselves) and <b>until</b> marks how long something lasts, not a deadline; ✗ <b>wipe / at</b> — <b>wipe out</b> means destroy completely, and <b>at</b> is not used with a year; ✗ <b>wear / in</b> — <b>wear out</b> means use until unusable; <b>in 2030</b> is fine but the verb fails."},{"id":"gv-ch-23-9","level":"ch","focus":"inversion","q":"______ should laboratory staff attempt to dispose of chemical waste without wearing protective gloves.","options":["Only after","Not until","Under no circumstances","No sooner"],"correct":2,"answer":"Under no circumstances","vi":"Trong bất kỳ trường hợp nào, nhân viên phòng thí nghiệm cũng không được cố xử lý chất thải hóa học mà không đeo găng tay bảo hộ.","explanation":"Negative-adverbial inversion: the inverted <b>should laboratory staff attempt</b> comes straight after the blank, so the phrase must stand alone, and <b>under no circumstances</b> = never, in no case. ✗ <b>Only after</b> — needs a time noun or clause before the inversion (Only after training should…); ✗ <b>Not until</b> — likewise needs a time phrase or clause (Not until 6 pm should…); ✗ <b>No sooner</b> — needs <b>had</b> + past participle and a following <b>than</b>."},{"id":"gv-ch-23-10","level":"ch","focus":"idiom","q":"A: Has the sponsor replied to our proposal yet? B: Not yet. Oh, ______ - here she comes now.","options":["hold your horses","the talk of the town","bite your tongue","speak of the devil"],"correct":3,"answer":"speak of the devil","vi":"A: Nhà tài trợ đã trả lời đề xuất của chúng ta chưa? B: Chưa. Ồ, vừa nhắc đã tới - cô ấy đang đến kìa.","explanation":"<b>Speak of the devil</b> is said when the person you were just talking about appears; the clue is <b>here she comes now</b> right after mentioning the sponsor. ✗ <b>hold your horses</b> — wait, slow down; not a reaction to someone appearing; ✗ <b>the talk of the town</b> — a noun phrase for something everyone is discussing; cannot stand as an exclamation here; ✗ <b>bite your tongue</b> — stop yourself from saying something; no link to arrival."},{"id":"gv-ch-23-11","level":"ch","focus":"collocation","q":"Regulators must ______ a balance between protecting consumers and allowing online retailers to innovate.","options":["strike","hit","beat","knock"],"correct":0,"answer":"strike","vi":"Các cơ quan quản lý phải tìm được sự cân bằng giữa bảo vệ người tiêu dùng và cho phép các nhà bán lẻ trực tuyến đổi mới.","explanation":"<b>Strike a balance</b> is the fixed collocation for finding a fair compromise, and <b>between protecting… and allowing…</b> names the two sides being balanced. ✗ <b>hit</b> — reach a level (hit a target) or strike with force; not used with <b>balance</b>; ✗ <b>beat</b> — defeat, or hit repeatedly; no collocation with <b>balance</b>; ✗ <b>knock</b> — hit with a sharp blow; also does not pair with <b>balance</b>."},{"id":"gv-ch-23-12","level":"ch","focus":"reported","q":"In her speech the minister said that the new grading system ______ nationwide the following year.","options":["will be introduced","is introduced","would be introduced","had introduced"],"correct":2,"answer":"would be introduced","vi":"Trong bài phát biểu, bộ trưởng nói rằng hệ thống chấm điểm mới sẽ được áp dụng trên toàn quốc vào năm sau.","explanation":"Reported speech: after past <b>said that</b>, the minister's original <b>will be introduced</b> backshifts to <b>would be introduced</b>, and <b>the following year</b> (the reported form of <b>next year</b>) confirms the shift. ✗ <b>will be introduced</b> — no backshift after a past reporting verb; ✗ <b>is introduced</b> — present tense, neither backshifted nor future; ✗ <b>had introduced</b> — active, so it needs an object (had introduced what?); the system is introduced, it does not introduce."},{"id":"gv-ch-23-13","level":"ch","focus":"word-choice","q":"Critics argue that the report ______ the benefits of private tutoring while ignoring the pressure it puts on families.","options":["overrules","overstates","overrides","overshadows"],"correct":1,"answer":"overstates","vi":"Giới phê bình cho rằng báo cáo thổi phồng lợi ích của việc học thêm trong khi phớt lờ áp lực mà nó gây ra cho các gia đình.","explanation":"<b>Overstate</b> = describe as bigger or better than it really is; the contrast <b>while ignoring the pressure</b> shows the report exaggerates one side. ✗ <b>overrules</b> — reject a decision using authority (a judge overrules an objection); benefits cannot be overruled; ✗ <b>overrides</b> — cancel or take priority over (override a veto); ✗ <b>overshadows</b> — make something seem less important by comparison; the report is praising the benefits, not eclipsing them."},{"id":"gv-ch-23-14","level":"ch","focus":"subjunctive","q":"The auditor recommended that the foundation ______ its full list of donors public before the next fundraising drive.","options":["make","makes","made","will make"],"correct":0,"answer":"make","vi":"Kiểm toán viên khuyến nghị quỹ công khai toàn bộ danh sách nhà tài trợ trước đợt gây quỹ tiếp theo.","explanation":"Subjunctive after a verb of advice: <b>recommended that</b> + subject + base form, so <b>that the foundation make</b>. ✗ <b>makes</b> — third-person <b>-s</b> is the ordinary present, not the subjunctive; ✗ <b>made</b> — past tense; the subjunctive never backshifts, even after past <b>recommended</b>; ✗ <b>will make</b> — no modal is used in the that-clause after <b>recommend</b>."},{"id":"gv-ch-23-15","level":"ch","focus":"idiom","q":"We have submitted our final offer for the sponsorship deal, so now ______.","options":["the shoe is on the other foot","the coast is clear","the ball is in your court","the sky is the limit"],"correct":2,"answer":"the ball is in your court","vi":"Chúng tôi đã gửi đề nghị cuối cùng cho hợp đồng tài trợ, nên giờ quyền quyết định thuộc về các bạn.","explanation":"<b>The ball is in your court</b> = it is now your turn to act or decide; the clue is <b>we have submitted our final offer, so now</b> — the next move belongs to the other side. ✗ <b>the shoe is on the other foot</b> — the situation has reversed and the roles have swapped; ✗ <b>the coast is clear</b> — there is no danger of being seen or caught; ✗ <b>the sky is the limit</b> — there is no upper limit to what can be achieved."},{"id":"gv-ch-23-16","level":"ch","focus":"gerund-infinitive","q":"Shoppers who are used to ______ discounts every weekend seldom notice when prices quietly rise.","options":["see","have seen","being seen","seeing"],"correct":3,"answer":"seeing","vi":"Những người mua sắm đã quen với việc thấy giảm giá mỗi cuối tuần hiếm khi để ý khi giá âm thầm tăng lên.","explanation":"<b>Be used to</b> + gerund = be accustomed to; <b>are used to</b> (with the verb <b>be</b>) shows the habit meaning, so <b>seeing</b>. ✗ <b>see</b> — the bare infinitive belongs to past-habit <b>used to see</b>, but <b>are</b> before it rules that out; ✗ <b>have seen</b> — a perfect infinitive cannot follow the preposition <b>to</b> here; ✗ <b>being seen</b> — passive: the shoppers do the seeing, they are not seen."},{"id":"gv-ch-23-17","level":"ch","focus":"phrasal-verb","q":"The plan to fund a library in every rural district did not ______ as hoped, and half the donated money was returned.","options":["pan out","pass out","hand out","peter out"],"correct":0,"answer":"pan out","vi":"Kế hoạch tài trợ một thư viện cho mỗi huyện nông thôn đã không thành công như mong đợi, và một nửa số tiền quyên góp bị trả lại.","explanation":"<b>Pan out</b> = develop or turn out (successfully); <b>did not… as hoped</b> and <b>money was returned</b> show a plan that failed. ✗ <b>pass out</b> — faint, lose consciousness; ✗ <b>hand out</b> — distribute; needs an object (hand out books), and a plan cannot hand out; ✗ <b>peter out</b> — fade away gradually; close in meaning, but it cannot take <b>as hoped</b> — nobody hopes a plan peters out."},{"id":"gv-ch-23-18","level":"ch","focus":"participle","q":"______ a sudden shortage of nurses, the hospital has begun recruiting from overseas for the first time in its history.","options":["Facing with","Having faced with","To face with","Faced with"],"correct":3,"answer":"Faced with","vi":"Đứng trước tình trạng thiếu y tá đột ngột, bệnh viện lần đầu tiên trong lịch sử đã bắt đầu tuyển dụng từ nước ngoài.","explanation":"Participle clause: the hospital is the one confronted by the shortage, so the passive participle <b>faced with</b> (= confronted by) opens the sentence; the clue is the <b>with</b> that only the passive form takes. ✗ <b>Facing with</b> — active <b>face</b> takes a direct object with no preposition (facing a shortage); ✗ <b>Having faced with</b> — same error, and the perfect form wrongly puts the shortage before the recruiting; ✗ <b>To face with</b> — an infinitive of purpose makes no sense, and again <b>with</b> is wrong."},{"id":"gv-ch-23-19","level":"ch","focus":"word-choice","q":"Investing in teacher training rather than new buildings was a ______ decision whose benefits are only now becoming visible.","options":["far-flung","far-off","far-sighted","far-out"],"correct":2,"answer":"far-sighted","vi":"Đầu tư vào đào tạo giáo viên thay vì xây dựng mới là một quyết định có tầm nhìn xa mà lợi ích chỉ giờ đây mới dần lộ rõ.","explanation":"<b>Far-sighted</b> = showing wise judgement about the future; the clue is <b>benefits are only now becoming visible</b>, i.e. the decision paid off later. ✗ <b>far-flung</b> — distant and widely scattered (far-flung villages); not used of decisions; ✗ <b>far-off</b> — remote in place or time (a far-off land); ✗ <b>far-out</b> — informal for strange or unconventional; the decision is praised, not called odd."},{"id":"gv-ch-23-20","level":"ch","focus":"idiom","q":"Every speaker praised the new curriculum, but nobody mentioned ______: the chronic shortage of qualified teachers.","options":["the skeleton in the cupboard","the elephant in the room","the black sheep of the family","the last straw"],"correct":1,"answer":"the elephant in the room","vi":"Diễn giả nào cũng ca ngợi chương trình mới, nhưng không ai nhắc đến vấn đề hiển nhiên mà mọi người đều né tránh: tình trạng thiếu giáo viên có trình độ kéo dài.","explanation":"<b>The elephant in the room</b> = an obvious problem that everyone avoids discussing; <b>nobody mentioned</b> the <b>chronic shortage</b> although it is plain to all. ✗ <b>the skeleton in the cupboard</b> — a hidden shameful secret; the shortage is public, not secret; ✗ <b>the black sheep of the family</b> — a person who embarrasses the group, not a problem; ✗ <b>the last straw</b> — the final problem that makes a situation unbearable."},{"id":"gv-ch-23-21","level":"ch","focus":"pronoun","q":"Rival fashion retailers now copy ______ so quickly that a new design rarely stays exclusive for more than a week.","options":["themselves","each","another","one another"],"correct":3,"answer":"one another","vi":"Các nhà bán lẻ thời trang đối thủ giờ sao chép lẫn nhau nhanh đến mức một mẫu thiết kế mới hiếm khi giữ được tính độc quyền quá một tuần.","explanation":"Reciprocal pronoun: <b>rival retailers</b> copy each other's designs, so <b>one another</b> (= each other). ✗ <b>themselves</b> — reflexive: each retailer would copy its own designs, which makes no sense; ✗ <b>each</b> — cannot stand alone as the object of <b>copy</b> (each what?); ✗ <b>another</b> — means a different one, not the mutual action; the pair <b>one another</b> is needed."},{"id":"gv-ch-23-22","level":"ch","focus":"double-blank","q":"Rather than ______ on the fence any longer, the school board must ______ a clear stance on mobile phones in class.","options":["sit / take","stand / make","lean / hold","stay / do"],"correct":0,"answer":"sit / take","vi":"Thay vì tiếp tục lưỡng lự không quyết, hội đồng trường phải có lập trường rõ ràng về điện thoại di động trong lớp.","explanation":"<b>Sit on the fence</b> = avoid choosing a side (clue: <b>any longer</b> + <b>must… a clear stance</b>), and the verb that collocates with <b>stance</b> is <b>take</b>. ✗ <b>stand / make</b> — <b>stand on the fence</b> is not the idiom, and one does not <b>make a stance</b>; ✗ <b>lean / hold</b> — <b>lean on the fence</b> is literal, and <b>hold a stance</b> is not the standard collocation; ✗ <b>stay / do</b> — <b>stay on the fence</b> is not the idiom and <b>do a stance</b> is impossible."},{"id":"gv-ch-23-23","level":"ch","focus":"collocation","q":"Since the scandal broke, the charity's spending has come under ______ scrutiny from journalists and regulators alike.","options":["near","tight","thick","close"],"correct":3,"answer":"close","vi":"Từ khi vụ bê bối bị phanh phui, chi tiêu của tổ chức từ thiện này đã bị cả nhà báo lẫn cơ quan quản lý xem xét kỹ lưỡng.","explanation":"<b>Close scrutiny</b> is the standard collocation for very careful examination; <b>come under… scrutiny from journalists and regulators</b> describes intense inspection. ✗ <b>near</b> — close in distance or time only, never in the sense of careful; ✗ <b>tight</b> — pairs with <b>control</b> or <b>security</b>, not <b>scrutiny</b>; ✗ <b>thick</b> — physical thickness (thick fog); no collocation with <b>scrutiny</b>."},{"id":"gv-ch-23-24","level":"ch","focus":"question-tag","q":"Nobody really expects the cap on private-school fees to survive the next budget, ______?","options":["don't they","does it","do they","doesn't it"],"correct":2,"answer":"do they","vi":"Thật ra chẳng ai mong mức trần học phí trường tư sẽ tồn tại qua kỳ ngân sách tới, phải không?","explanation":"Question tag after a negative subject: <b>nobody</b> is already negative, so the tag is positive, and the pronoun for <b>nobody</b> is plural <b>they</b>: <b>do they</b>. ✗ <b>don't they</b> — a negative tag after a negative statement; ✗ <b>does it</b> — <b>it</b> would refer to the cap, but the subject of the sentence is <b>nobody</b>; ✗ <b>doesn't it</b> — wrong pronoun and wrong polarity."},{"id":"gv-ch-23-25","level":"ch","focus":"word-choice","q":"The fund offers full scholarships to ______ students who would otherwise have no chance of attending a specialist high school.","options":["underlying","underprivileged","understaffed","undervalued"],"correct":1,"answer":"underprivileged","vi":"Quỹ cấp học bổng toàn phần cho những học sinh có hoàn cảnh khó khăn, những em nếu không sẽ chẳng có cơ hội vào trường chuyên.","explanation":"<b>Underprivileged</b> = lacking the money and advantages others have; the clue is <b>who would otherwise have no chance</b> — the scholarships help disadvantaged students. ✗ <b>underlying</b> — basic, or hidden beneath the surface (an underlying cause); ✗ <b>understaffed</b> — having too few workers; describes organisations, not students; ✗ <b>undervalued</b> — not appreciated as much as deserved; the sentence is about lack of opportunity, not appreciation."},{"id":"gv-ch-24-1","level":"ch","focus":"idiom","q":"Small family firms often weather a recession because their staff stand by them ______, even when wages are paid late.","options":["through thick and thin","by hook or by crook","by leaps and bounds","at sixes and sevens"],"correct":0,"answer":"through thick and thin","vi":"Các doanh nghiệp gia đình nhỏ thường vượt qua suy thoái vì nhân viên sát cánh cùng họ dù sướng hay khổ, ngay cả khi lương bị trả chậm.","explanation":"Idiom of loyalty: <b>stand by them … even when wages are paid late</b> means staying loyal in good times and bad, so <b>through thick and thin</b> (= loyally, whatever happens) fits. ✗ <b>by hook or by crook</b> — by any means possible; ✗ <b>by leaps and bounds</b> — very quickly (of progress); ✗ <b>at sixes and sevens</b> — in total confusion."},{"id":"gv-ch-24-2","level":"ch","focus":"idiom","q":"Setting up two-factor authentication turned out to be ______ — the whole process took less than a minute.","options":["a hard nut to crack","a piece of cake","a storm in a teacup","a drop in the ocean"],"correct":1,"answer":"a piece of cake","vi":"Hóa ra việc cài đặt xác thực hai lớp dễ như ăn kẹo — toàn bộ quá trình chưa đến một phút.","explanation":"Idiom for ease: <b>took less than a minute</b> shows the task was very easy, so <b>a piece of cake</b> (= something very easy) fits. ✗ <b>a hard nut to crack</b> — a difficult problem, the opposite; ✗ <b>a storm in a teacup</b> — a big fuss about nothing; ✗ <b>a drop in the ocean</b> — a tiny, unimportant amount."},{"id":"gv-ch-24-3","level":"ch","focus":"word-choice","q":"Data brokers can ______ a user's home address from nothing more than a handful of location pings.","options":["overlook","survey","pinpoint","browse"],"correct":2,"answer":"pinpoint","vi":"Các công ty môi giới dữ liệu có thể xác định chính xác địa chỉ nhà của người dùng chỉ từ vài tín hiệu định vị.","explanation":"Word choice: finding <b>a user's home address from … a handful of location pings</b> is locating something exactly, so <b>pinpoint</b> (= identify precisely) fits. ✗ <b>overlook</b> — fail to notice, the opposite; ✗ <b>survey</b> — look over a wide area generally; ✗ <b>browse</b> — look through casually, without a target."},{"id":"gv-ch-24-4","level":"ch","focus":"idiom","q":"When the regulator rejected the trial data, the research team found itself ______, with three years of work to repeat.","options":["on the same page","out of the woods","in the same boat","back to square one"],"correct":3,"answer":"back to square one","vi":"Khi cơ quan quản lý bác bỏ dữ liệu thử nghiệm, nhóm nghiên cứu thấy mình phải bắt đầu lại từ đầu, với ba năm công sức phải làm lại.","explanation":"Idiom for lost progress: <b>three years of work to repeat</b> means starting again from the beginning, so <b>back to square one</b> fits. ✗ <b>on the same page</b> — in agreement with others; ✗ <b>out of the woods</b> — safe, past the danger; ✗ <b>in the same boat</b> — in the same difficult situation as someone else."},{"id":"gv-ch-24-5","level":"ch","focus":"word-choice","q":"The auditors spent three weeks ______ over the bank's ledgers before the missing transfers came to light.","options":["poring","peering","gazing","squinting"],"correct":0,"answer":"poring","vi":"Các kiểm toán viên mất ba tuần nghiền ngẫm sổ sách của ngân hàng trước khi các khoản chuyển tiền thất thoát bị phát hiện.","explanation":"Word choice with <b>over</b>: <b>three weeks … over the bank's ledgers</b> is careful, lengthy study, so <b>poring over</b> (= studying closely) fits. ✗ <b>peering</b> — looking with difficulty, takes <b>at</b>, not <b>over</b>; ✗ <b>gazing</b> — looking steadily for a long time, takes <b>at</b>; ✗ <b>squinting</b> — narrowing the eyes to see, takes <b>at</b>."},{"id":"gv-ch-24-6","level":"ch","focus":"double-blank","q":"The surgeon was confident the patient would pull ______, though recovery ______ such an operation can take months.","options":["over / of","through / from","out / in","off / to"],"correct":1,"answer":"through / from","vi":"Bác sĩ phẫu thuật tin rằng bệnh nhân sẽ qua khỏi, dù việc hồi phục sau một ca mổ như vậy có thể mất nhiều tháng.","explanation":"Phrasal verb + preposition: <b>the patient would pull through</b> = survive a serious operation, and the noun <b>recovery</b> takes <b>from</b> (recovery from an operation). ✗ <b>over / of</b> — pull over = stop a car; recovery of = getting something back; ✗ <b>out / in</b> — pull out = withdraw; recovery in = improvement in a market; ✗ <b>off / to</b> — pull off = succeed in something difficult; recovery to is not used."},{"id":"gv-ch-24-7","level":"ch","focus":"phrasal-verb","q":"Company spokespeople tried to ______ the scale of the breach, insisting only a handful of accounts had been exposed.","options":["play up","play off","play down","play along"],"correct":2,"answer":"play down","vi":"Người phát ngôn của công ty cố giảm nhẹ mức độ của vụ rò rỉ, khăng khăng rằng chỉ một số ít tài khoản bị lộ.","explanation":"Phrasal verb: <b>insisting only a handful of accounts had been exposed</b> shows they made the breach seem smaller, so <b>play down</b> (= minimise) fits. ✗ <b>play up</b> — exaggerate, the opposite; ✗ <b>play off</b> — set two people against each other; ✗ <b>play along</b> — pretend to agree or cooperate."},{"id":"gv-ch-24-8","level":"ch","focus":"phrasal-verb","q":"Despite objections from privacy groups, the ministry has decided to ______ with the facial-recognition scheme in every station.","options":["press for","get ahead","press upon","press ahead"],"correct":3,"answer":"press ahead","vi":"Bất chấp sự phản đối của các nhóm bảo vệ quyền riêng tư, bộ đã quyết định xúc tiến kế hoạch nhận diện khuôn mặt ở mọi nhà ga.","explanation":"Phrasal verb with <b>with</b>: <b>Despite objections … has decided to … with the scheme</b> means continuing regardless, so <b>press ahead with</b> (= go on determinedly) fits. ✗ <b>press for</b> — demand something, and cannot take <b>with</b>; ✗ <b>press upon</b> — force something on someone; ✗ <b>get ahead</b> — advance in a career, not used with a plan."},{"id":"gv-ch-24-9","level":"ch","focus":"double-blank","q":"The merger is still ______ in the air, so the bank has put its hiring plans ______ hold.","options":["up / on","out / in","off / at","over / under"],"correct":0,"answer":"up / on","vi":"Vụ sáp nhập vẫn còn chưa ngã ngũ, nên ngân hàng đã tạm hoãn kế hoạch tuyển dụng.","explanation":"Two fixed expressions: <b>up in the air</b> = still undecided, and <b>put … on hold</b> = postponed. ✗ <b>out / in</b> — out in the air and in hold are not expressions; ✗ <b>off / at</b> — off in the air is not an expression, and at hold does not exist; ✗ <b>over / under</b> — over in the air is not an expression; under hold is not used for postponing."},{"id":"gv-ch-24-10","level":"ch","focus":"collocation","q":"Economists warn that ______ inflation is quietly eroding the value of household savings.","options":["insistent","persistent","resistant","consistent"],"correct":1,"answer":"persistent","vi":"Các nhà kinh tế cảnh báo rằng lạm phát dai dẳng đang âm thầm bào mòn giá trị tiền tiết kiệm của các hộ gia đình.","explanation":"Collocation: inflation that is <b>quietly eroding … savings</b> over time is <b>persistent inflation</b> (= continuing stubbornly). ✗ <b>insistent</b> — demanding attention, used of people or voices; ✗ <b>resistant</b> — needs <b>to</b> (resistant to change) and describes what resists, not what continues; ✗ <b>consistent</b> — steady and unchanging, not stubbornly lasting."},{"id":"gv-ch-24-11","level":"ch","focus":"idiom","q":"The two governments reached a tariff deal ______, only minutes before the new duties were due to take effect.","options":["at the end of the day","around the clock","at the eleventh hour","in the long run"],"correct":2,"answer":"at the eleventh hour","vi":"Hai chính phủ đạt được thỏa thuận thuế quan vào phút chót, chỉ vài phút trước khi các mức thuế mới có hiệu lực.","explanation":"Idiom of time: <b>only minutes before the new duties were due to take effect</b> means at the last possible moment, so <b>at the eleventh hour</b> fits. ✗ <b>at the end of the day</b> — ultimately, when everything is considered; ✗ <b>around the clock</b> — all day and all night; ✗ <b>in the long run</b> — over a long period, eventually."},{"id":"gv-ch-24-12","level":"ch","focus":"collocation","q":"The health ministry has ______ a thorough investigation into hygiene standards at the private clinic.","options":["made","done","taken","conducted"],"correct":3,"answer":"conducted","vi":"Bộ Y tế đã tiến hành một cuộc điều tra kỹ lưỡng về tiêu chuẩn vệ sinh tại phòng khám tư đó.","explanation":"Verb + noun collocation: with <b>a thorough investigation</b> the verb is <b>conduct</b> (also carry out / hold). ✗ <b>made</b> — make goes with a decision or an effort, not an investigation; ✗ <b>done</b> — do goes with research or homework, not an investigation; ✗ <b>taken</b> — take goes with action or a decision, not an investigation."},{"id":"gv-ch-24-13","level":"ch","focus":"collocation","q":"Regulators fined the platform for failing to obtain ______ consent before selling users' browsing histories to advertisers.","options":["informed","knowing","advised","aware"],"correct":0,"answer":"informed","vi":"Cơ quan quản lý đã phạt nền tảng này vì không xin được sự đồng ý có hiểu biết của người dùng trước khi bán lịch sử duyệt web của họ cho các nhà quảng cáo.","explanation":"Fixed collocation: <b>consent before selling users' browsing histories</b> is the legal idea of agreement given with full knowledge, so <b>informed consent</b> fits. ✗ <b>knowing</b> — describes a person or look (a knowing smile), not consent; ✗ <b>advised</b> — means recommended and does not pair with consent; ✗ <b>aware</b> — describes a person (aware of), never a noun like consent."},{"id":"gv-ch-24-14","level":"ch","focus":"linking","q":"Ministers insist the economy is recovering, ______ most households report that their real incomes have fallen.","options":["despite","whereas","otherwise","so that"],"correct":1,"answer":"whereas","vi":"Các bộ trưởng khẳng định nền kinh tế đang hồi phục, trong khi hầu hết các hộ gia đình cho biết thu nhập thực tế của họ đã giảm.","explanation":"Linking word: <b>Ministers insist … recovering</b> versus <b>most households report … fallen</b> are two contrasting clauses, so <b>whereas</b> (= while, by contrast) fits. ✗ <b>despite</b> — a preposition, needs a noun or -ing form, not a full clause; ✗ <b>otherwise</b> — means if not, which makes no sense here; ✗ <b>so that</b> — expresses purpose, but falling incomes are not the ministers' aim."},{"id":"gv-ch-24-15","level":"ch","focus":"gerund-infinitive","q":"After a decade in investment banking, she found it hard to get used to ______ on a researcher's salary.","options":["live","to live","living","having lived"],"correct":2,"answer":"living","vi":"Sau mười năm làm ngân hàng đầu tư, cô thấy khó mà quen được với việc sống bằng đồng lương của một nhà nghiên cứu.","explanation":"Gerund after a preposition: in <b>get used to</b>, <b>to</b> is a preposition, so the verb takes -ing: <b>living</b>. ✗ <b>live</b> — a bare infinitive cannot follow a preposition; ✗ <b>to live</b> — doubles the <b>to</b> (used to to live); ✗ <b>having lived</b> — a perfect gerund refers to a finished past action, but she is adjusting to a present situation."},{"id":"gv-ch-24-16","level":"ch","focus":"subjunctive","q":"The board recommended that the chief executive ______ from any decision involving her family's shareholding.","options":["abstains","abstained","will abstain","abstain"],"correct":3,"answer":"abstain","vi":"Hội đồng quản trị đề nghị giám đốc điều hành không tham gia bất kỳ quyết định nào liên quan đến cổ phần của gia đình bà.","explanation":"Subjunctive: after <b>recommended that</b>, the verb takes the base form: <b>abstain</b>, regardless of the subject or the past tense of the main clause. ✗ <b>abstains</b> — present -s form, not the subjunctive; ✗ <b>abstained</b> — past tense describes what happened, not what was recommended; ✗ <b>will abstain</b> — future form is not used in a that-clause after recommend."},{"id":"gv-ch-24-17","level":"ch","focus":"inversion","q":"______ for the central bank's emergency intervention, the currency would have collapsed within days.","options":["Had it not been","Had not it been","It had not been","Not had it been"],"correct":0,"answer":"Had it not been","vi":"Nếu không có sự can thiệp khẩn cấp của ngân hàng trung ương, đồng tiền này đã sụp đổ chỉ trong vài ngày.","explanation":"Inverted third conditional: <b>would have collapsed</b> marks an unreal past, and <b>Had it not been for</b> = If it had not been for; the auxiliary <b>had</b> moves before the subject and <b>not</b> stays after it. ✗ <b>Had not it been</b> — <b>not</b> cannot come between the auxiliary and the subject when uncontracted; ✗ <b>It had not been</b> — no inversion and no <b>if</b>, so it is not a condition; ✗ <b>Not had it been</b> — <b>not</b> cannot begin the inversion."},{"id":"gv-ch-24-18","level":"ch","focus":"inversion","q":"Only after the second wave of infections ______ the true cost of years of underfunding the health service.","options":["the public realised","did the public realise","the public did realise","realised the public"],"correct":1,"answer":"did the public realise","vi":"Chỉ sau làn sóng lây nhiễm thứ hai công chúng mới nhận ra cái giá thực sự của nhiều năm cắt giảm ngân sách y tế.","explanation":"Inversion after a negative/restrictive opener: <b>Only after</b> + phrase at the start forces auxiliary + subject + bare verb in the main clause: <b>did the public realise</b>. ✗ <b>the public realised</b> — normal word order is not allowed after Only after; ✗ <b>the public did realise</b> — <b>did</b> must come before the subject, not after; ✗ <b>realised the public</b> — the full verb cannot invert; an auxiliary is needed."},{"id":"gv-ch-24-19","level":"ch","focus":"word-choice","q":"Without her glasses, the pharmacist had to ______ at the tiny print on the label to read the dosage.","options":["gaze","glare","peer","observe"],"correct":2,"answer":"peer","vi":"Không có kính, dược sĩ phải nheo mắt nhìn kỹ dòng chữ li ti trên nhãn để đọc liều dùng.","explanation":"Word choice with <b>at</b>: <b>Without her glasses … the tiny print</b> means looking closely at something hard to see, so <b>peer at</b> fits. ✗ <b>gaze</b> — look steadily and dreamily, not with effort; ✗ <b>glare</b> — look angrily at someone; ✗ <b>observe</b> — watch carefully, takes a direct object without <b>at</b>."},{"id":"gv-ch-24-20","level":"ch","focus":"word-choice","q":"Journalists eventually ______ the leaked memo to a contractor working for the health ministry.","options":["spotted","sighted","located","traced"],"correct":3,"answer":"traced","vi":"Cuối cùng các nhà báo đã lần ra bản ghi nhớ bị rò rỉ xuất phát từ một nhà thầu làm việc cho Bộ Y tế.","explanation":"Word choice with <b>to</b>: following the memo <b>to a contractor</b> means finding its source, so <b>traced … to</b> (= followed evidence back to its origin) fits. ✗ <b>spotted</b> — noticed suddenly, not followed to a source; ✗ <b>sighted</b> — saw with the eyes, used of ships or animals; ✗ <b>located</b> — found the position of, does not take <b>to</b> a source."},{"id":"gv-ch-24-21","level":"ch","focus":"subjunctive","q":"It's high time regulators ______ a clear line between targeted advertising and outright surveillance.","options":["drew","draw","will draw","have drawn"],"correct":0,"answer":"drew","vi":"Đã đến lúc các cơ quan quản lý phải vạch ra ranh giới rõ ràng giữa quảng cáo nhắm mục tiêu và giám sát trắng trợn.","explanation":"Past subjunctive after <b>It's high time</b>: the expression takes a past form to say something should already be happening: <b>drew</b>. ✗ <b>draw</b> — present or base form is not used after It's high time + subject; ✗ <b>will draw</b> — future form is not used after this expression; ✗ <b>have drawn</b> — a perfect form describes a completed action, but the line has not been drawn yet."},{"id":"gv-ch-24-22","level":"ch","focus":"article-quantifier","q":"______ research has been done on how late-night scrolling affects teenagers' sleep, so no one can yet say whether the harm is real.","options":["A little","Little","Few","A few"],"correct":1,"answer":"Little","vi":"Rất ít nghiên cứu được thực hiện về việc lướt điện thoại khuya ảnh hưởng thế nào đến giấc ngủ của thanh thiếu niên, nên chưa ai dám nói tác hại đó là có thật.","explanation":"Quantifier with an uncountable noun: <b>research</b> is uncountable and <b>no one can yet say</b> shows the amount is almost none, so <b>Little</b> (= hardly any) fits. ✗ <b>A little</b> — means some, enough to matter, which clashes with no one can yet say; ✗ <b>Few</b> — used only with plural countable nouns; ✗ <b>A few</b> — also for plural countable nouns, and means some."},{"id":"gv-ch-24-23","level":"ch","focus":"modal","q":"The patient ______ the wrong dose — the pharmacy's records show every prescription that day was filled correctly.","options":["shouldn't have been given","needn't have been given","can't have been given","mustn't have been given"],"correct":2,"answer":"can't have been given","vi":"Bệnh nhân không thể nào đã bị đưa sai liều — hồ sơ nhà thuốc cho thấy mọi đơn thuốc hôm đó đều được cấp phát đúng.","explanation":"Modal of deduction: <b>records show every prescription … was filled correctly</b> is evidence that it did NOT happen, so <b>can't have been given</b> (= I am sure it did not happen) fits. ✗ <b>shouldn't have been given</b> — criticises something that did happen; ✗ <b>needn't have been given</b> — says it happened but was unnecessary; ✗ <b>mustn't have been given</b> — must have is used for positive deduction only; the negative deduction is can't have."},{"id":"gv-ch-24-24","level":"ch","focus":"participle","q":"______ the sheer volume of records exposed in the breach, investigators expect the inquiry to take at least a year.","options":["Giving","Give","Given","To give"],"correct":2,"answer":"Given","vi":"Xét đến khối lượng hồ sơ bị lộ quá lớn trong vụ rò rỉ, các điều tra viên dự đoán cuộc điều tra sẽ kéo dài ít nhất một năm.","explanation":"Participle preposition: <b>Given</b> + noun phrase means considering, taking into account, so <b>Given the sheer volume of records</b> introduces the reason for the year-long inquiry. ✗ <b>Giving</b> — a present participle would mean the investigators are giving the records; ✗ <b>Give</b> — a bare imperative cannot introduce a noun phrase as a reason; ✗ <b>To give</b> — an infinitive of purpose, but expecting a long inquiry is not done in order to give records."},{"id":"gv-ch-24-25","level":"ch","focus":"word-choice","q":"Most users simply ______ the headlines in their news feed rather than read a single article to the end.","options":["stare","skim","gaze","squint"],"correct":1,"answer":"skim","vi":"Hầu hết người dùng chỉ lướt qua các tiêu đề trong bảng tin thay vì đọc trọn vẹn dù chỉ một bài báo.","explanation":"Word choice with a direct object: <b>the headlines … rather than read a single article to the end</b> means reading quickly for the gist, so <b>skim</b> fits and takes the object directly. ✗ <b>stare</b> — look fixedly, needs <b>at</b>; ✗ <b>gaze</b> — look steadily and admiringly, needs <b>at</b>; ✗ <b>squint</b> — narrow the eyes to see, needs <b>at</b>."},{"id":"gv-ch-25-1","level":"ch","focus":"tense","q":"By the end of this decade, the orbiting telescope ______ data for longer than any of its predecessors.","options":["will collect","is collecting","has been collecting","will have been collecting"],"correct":3,"answer":"will have been collecting","vi":"Đến cuối thập kỷ này, kính viễn vọng trên quỹ đạo sẽ đã thu thập dữ liệu lâu hơn bất kỳ kính tiền nhiệm nào.","explanation":"<b>By the end of this decade</b> sets a future deadline and <b>for longer than</b> stresses duration up to it, so the future perfect continuous <b>will have been collecting</b> is required. ✗ <b>will collect</b> — simple future cannot show duration up to a deadline; ✗ <b>is collecting</b> — present continuous describes now, not a future point; ✗ <b>has been collecting</b> — present perfect measures duration up to now, not up to a future date."},{"id":"gv-ch-25-2","level":"ch","focus":"idiom","q":"The minister spent ten minutes ______ before finally admitting that the excavation had been cancelled.","options":["beating around the bush","barking up the wrong tree","jumping the gun","burning her bridges"],"correct":0,"answer":"beating around the bush","vi":"Bà bộ trưởng vòng vo mất mười phút rồi cuối cùng mới thừa nhận rằng cuộc khai quật đã bị hủy.","explanation":"<b>Beat around the bush</b> = avoid saying something directly, which matches <b>before finally admitting</b> after ten minutes of talk. ✗ <b>barking up the wrong tree</b> — pursuing a mistaken idea, not delaying an admission; ✗ <b>jumping the gun</b> — acting too soon, the opposite of stalling; ✗ <b>burning her bridges</b> — destroying any way back, unrelated to avoiding a topic."},{"id":"gv-ch-25-3","level":"ch","focus":"word-choice","q":"Insurers were reluctant to ______ the deep-sea expedition, since nobody could put a price on the risk of losing the submersible.","options":["undercut","outbid","underwrite","overcharge"],"correct":2,"answer":"underwrite","vi":"Các hãng bảo hiểm ngần ngại bảo lãnh cho chuyến thám hiểm biển sâu, vì không ai định giá nổi rủi ro mất chiếc tàu lặn.","explanation":"<b>Underwrite</b> = accept financial responsibility for a risk, which is what <b>insurers</b> do and why the <b>risk of losing the submersible</b> makes them reluctant. ✗ <b>undercut</b> — sell cheaper than a rival, not insure; ✗ <b>outbid</b> — offer more money than others at a sale; ✗ <b>overcharge</b> — ask too high a price, and insurers here are not selling."},{"id":"gv-ch-25-4","level":"ch","focus":"phrasal-verb","q":"The launch has been ______ to October after engineers found a hairline crack in a fuel line.","options":["pushed for","pushed back","pulled back","pushed on"],"correct":1,"answer":"pushed back","vi":"Vụ phóng đã bị lùi sang tháng Mười sau khi các kỹ sư phát hiện một vết nứt li ti trên đường ống nhiên liệu.","explanation":"<b>Push back</b> = postpone to a later date, so <b>to October after engineers found a crack</b> means the launch was delayed. ✗ <b>pushed for</b> — campaign for something, not move a date; ✗ <b>pulled back</b> — withdraw or retreat, does not take a new date; ✗ <b>pushed on</b> — continue despite difficulty, the opposite of a delay."},{"id":"gv-ch-25-5","level":"ch","focus":"collocation","q":"The eroding cliff poses a ______ threat to the Roman fort perched on top of it.","options":["heavy","high","deep","grave"],"correct":3,"answer":"grave","vi":"Vách đá đang xói mòn là một mối đe dọa nghiêm trọng đối với pháo đài La Mã nằm chênh vênh bên trên.","explanation":"<b>Grave threat</b> (like serious threat) is the fixed collocation for a threat that could cause great harm, fitting an <b>eroding cliff</b> under a fort. ✗ <b>heavy</b> — collocates with rain, traffic or losses, not threat; ✗ <b>high</b> — goes with risk or price, but we do not say 'a high threat to'; ✗ <b>deep</b> — goes with concern or trouble, never with threat."},{"id":"gv-ch-25-6","level":"ch","focus":"subjunctive","q":"The safety board recommended that the airline ______ every aircraft of that type until the fault was traced.","options":["ground","grounds","grounded","would ground"],"correct":0,"answer":"ground","vi":"Ủy ban an toàn khuyến nghị rằng hãng hàng không đình bay mọi máy bay loại đó cho tới khi tìm ra lỗi.","explanation":"After <b>recommended that</b>, the verb is in the subjunctive base form <b>ground</b>, whatever the subject or the tense of the main verb. ✗ <b>grounds</b> — third-person -s is dropped in the subjunctive; ✗ <b>grounded</b> — the past tense of 'recommended' is not copied into the that-clause; ✗ <b>would ground</b> — 'would' is not used after recommend that (only 'should' or the base form)."},{"id":"gv-ch-25-7","level":"ch","focus":"word-choice","q":"Cruise lines expect to ______ the cost of the new terminals within a decade through higher berthing fees.","options":["refund","recoup","redeem","reimburse"],"correct":1,"answer":"recoup","vi":"Các hãng du thuyền dự kiến thu hồi chi phí xây các bến cảng mới trong vòng một thập kỷ nhờ phí neo đậu cao hơn.","explanation":"<b>Recoup</b> = get back money you have spent, so the cruise lines recover <b>the cost of the new terminals</b> themselves. ✗ <b>refund</b> — give money back to a customer, paying out not taking in; ✗ <b>reimburse</b> — pay someone back for their expenses, again money going out; ✗ <b>redeem</b> — exchange a voucher or pay off a debt, not recover a cost."},{"id":"gv-ch-25-8","level":"ch","focus":"idiom","q":"The hotel staff ______ to make the stranded passengers comfortable, even lending out their own phone chargers.","options":["turned over a new leaf","got cold feet","bent over backwards","let their hair down"],"correct":2,"answer":"bent over backwards","vi":"Nhân viên khách sạn đã hết lòng hết sức để hành khách bị mắc kẹt được thoải mái, thậm chí cho mượn cả sạc điện thoại của mình.","explanation":"<b>Bend over backwards</b> = try extremely hard to help, and <b>even lending out their own chargers</b> shows that effort. ✗ <b>turned over a new leaf</b> — started behaving better, not helping others; ✗ <b>got cold feet</b> — lost their nerve, which does not fit making guests comfortable; ✗ <b>let their hair down</b> — relaxed and had fun, not worked hard for passengers."},{"id":"gv-ch-25-9","level":"ch","focus":"modal","q":"These bones ______ to a child; the growth plates had already fused when the person died.","options":["can't have belonged","mustn't have belonged","needn't have belonged","shouldn't have belonged"],"correct":0,"answer":"can't have belonged","vi":"Những mẩu xương này không thể là của một đứa trẻ; các đĩa sụn tăng trưởng đã liền hẳn khi người đó qua đời.","explanation":"The fused <b>growth plates</b> are evidence, so this is a confident deduction that something was impossible: <b>can't have + past participle</b>. ✗ <b>mustn't have belonged</b> — 'must have' is used only for positive deduction; its negative is 'can't have'; ✗ <b>needn't have belonged</b> — means it was unnecessary, not impossible; ✗ <b>shouldn't have belonged</b> — means it was wrong to, a judgement not a deduction."},{"id":"gv-ch-25-10","level":"ch","focus":"double-blank","q":"The museum ______ several retired teachers ______ leading the weekend tours when its own guides fell ill.","options":["tied / into","roped / on","hauled / in","roped / into"],"correct":3,"answer":"roped / into","vi":"Bảo tàng đã lôi kéo mấy giáo viên về hưu vào việc dẫn các tour cuối tuần khi hướng dẫn viên của họ ngã bệnh.","explanation":"<b>Rope someone into doing something</b> = persuade them to take on a task they had not planned, and the -ing form <b>leading</b> confirms the preposition <b>into</b>. ✗ <b>tied / into</b> — tie into = connect one thing to another, not persuade; ✗ <b>roped / on</b> — rope takes 'in' or 'into', never 'on'; ✗ <b>hauled / in</b> — haul in = drag or arrest, and 'in' cannot precede 'leading'."},{"id":"gv-ch-25-11","level":"ch","focus":"inversion","q":"Not until the ice cores had been analysed ______ how abruptly the climate had shifted.","options":["scientists realised","did scientists realise","had scientists realised","scientists did realise"],"correct":1,"answer":"did scientists realise","vi":"Mãi đến khi các lõi băng được phân tích, các nhà khoa học mới nhận ra khí hậu đã thay đổi đột ngột đến mức nào.","explanation":"A sentence opening with <b>Not until…</b> inverts the main clause: auxiliary + subject + base verb, so <b>did scientists realise</b>. ✗ <b>scientists realised</b> — no inversion after a fronted negative; ✗ <b>had scientists realised</b> — the realising came after the analysis, so past perfect puts it at the wrong, earlier time; ✗ <b>scientists did realise</b> — the auxiliary must come before the subject."},{"id":"gv-ch-25-12","level":"ch","focus":"word-choice","q":"The council will ______ a small charge on every hotel night to pay for repairs to the medieval walls.","options":["impose","inflict","exert","instil"],"correct":0,"answer":"impose","vi":"Hội đồng thành phố sẽ áp một khoản phí nhỏ lên mỗi đêm lưu trú khách sạn để trả cho việc sửa chữa tường thành thời trung cổ.","explanation":"You <b>impose</b> a tax, charge or fine on people, so <b>a small charge on every hotel night</b> is imposed. ✗ <b>inflict</b> — goes with pain, damage or a defeat, not a fee; ✗ <b>exert</b> — goes with pressure, influence or force; ✗ <b>instil</b> — put values or feelings into someone, never a charge."},{"id":"gv-ch-25-13","level":"ch","focus":"participle","q":"______ from the same volcanic rock as the temple, the statues have weathered surprisingly little.","options":["Carving","Having carved","Carved","To carve"],"correct":2,"answer":"Carved","vi":"Được tạc từ cùng loại đá núi lửa với ngôi đền, các bức tượng phong hóa ít đến ngạc nhiên.","explanation":"The statues <b>were carved</b> by someone, so the reduced clause needs the past participle <b>Carved</b> with passive meaning. ✗ <b>Carving</b> — active, would make the statues the ones doing the carving; ✗ <b>Having carved</b> — active perfect, same wrong doer; ✗ <b>To carve</b> — an infinitive of purpose, which says nothing about where the statues came from."},{"id":"gv-ch-25-14","level":"ch","focus":"idiom","q":"The probe's landing sequence worked, but engineers admitted it had survived the descent ______.","options":["by leaps and bounds","by word of mouth","by the book","by the skin of its teeth"],"correct":3,"answer":"by the skin of its teeth","vi":"Chuỗi thao tác hạ cánh của tàu thăm dò đã thành công, nhưng các kỹ sư thừa nhận nó đã sống sót qua pha hạ cánh trong gang tấc.","explanation":"<b>By the skin of its teeth</b> = only just, narrowly, fitting <b>worked, but … admitted</b> — success that was nearly failure. ✗ <b>by leaps and bounds</b> — very quickly, used of progress; ✗ <b>by word of mouth</b> — through people telling each other; ✗ <b>by the book</b> — strictly following the rules, which says nothing about a narrow escape."},{"id":"gv-ch-25-15","level":"ch","focus":"collocation","q":"Pollen trapped in the lake bed has ______ new light on how the harbour silted up.","options":["given","shed","put","set"],"correct":1,"answer":"shed","vi":"Phấn hoa mắc kẹt dưới đáy hồ đã soi rọi thêm về cách cảng biển bị bồi lấp.","explanation":"<b>Shed light on</b> (also throw or cast light on) = help explain something, and <b>how the harbour silted up</b> is the mystery explained. ✗ <b>given</b> — a lamp gives light literally, but 'give light on' is not an idiom; ✗ <b>put</b> — 'put light on' does not exist; ✗ <b>set</b> — 'set light to' means ignite, and takes 'to' not 'on'."},{"id":"gv-ch-25-16","level":"ch","focus":"linking","q":"______ carefully a mission is planned, the launch still depends on the weather on the day.","options":["Even though","Whatever","No matter how","Despite"],"correct":2,"answer":"No matter how","vi":"Dù một sứ mệnh được lên kế hoạch kỹ lưỡng đến đâu, vụ phóng vẫn phụ thuộc vào thời tiết trong ngày.","explanation":"<b>No matter how + adverb + clause</b> = however carefully, and the adverb <b>carefully</b> right after the blank decides it. ✗ <b>Even though</b> — must be followed by a subject, not an adverb; ✗ <b>Whatever</b> — takes a noun (whatever the plan); ✗ <b>Despite</b> — a preposition needing a noun or -ing form, not a clause."},{"id":"gv-ch-25-17","level":"ch","focus":"word-choice","q":"The bronze helmet ______ a record price at auction, three times the estimate printed in the catalogue.","options":["charged","spent","afforded","fetched"],"correct":3,"answer":"fetched","vi":"Chiếc mũ trụ bằng đồng đã được bán với giá kỷ lục tại phiên đấu giá, gấp ba lần mức ước tính in trong catalogue.","explanation":"An object <b>fetches</b> a price = is sold for that amount, so <b>the helmet … a record price at auction</b> is the clue. ✗ <b>charged</b> — a seller charges a buyer; a helmet cannot; ✗ <b>spent</b> — a person spends money; an object does not; ✗ <b>afforded</b> — afford = have enough money to buy, again only for people."},{"id":"gv-ch-25-18","level":"ch","focus":"gerund-infinitive","q":"Having lived at the desert camp for months, the team had grown used ______ without running water.","options":["to living","to live","living","live"],"correct":0,"answer":"to living","vi":"Sau nhiều tháng sống ở trại giữa sa mạc, cả đội đã quen với việc không có nước máy.","explanation":"In <b>grow used to</b>, 'to' is a preposition, so it takes the -ing form: <b>used to living</b>. ✗ <b>to live</b> — 'used to + base verb' means a past habit (formerly lived) and does not follow 'grow'; ✗ <b>living</b> — the 'to' after 'used' is missing; ✗ <b>live</b> — a bare verb cannot follow 'used'."},{"id":"gv-ch-25-19","level":"ch","focus":"phrasal-verb","q":"The guide ______ the tangled history of the temple so clearly that even the youngest visitors could follow it.","options":["put off","put across","put down","put up"],"correct":1,"answer":"put across","vi":"Hướng dẫn viên trình bày lịch sử rối rắm của ngôi đền rõ ràng đến mức ngay cả những du khách nhỏ tuổi nhất cũng theo dõi được.","explanation":"<b>Put across</b> = communicate an idea so people understand it, and <b>so clearly that … could follow it</b> confirms this. ✗ <b>put off</b> — postpone or discourage; ✗ <b>put down</b> — criticise someone or write something down; ✗ <b>put up</b> — build something or give someone a bed."},{"id":"gv-ch-25-20","level":"ch","focus":"relative","q":"The tools, only half of ______ have been catalogued so far, date from the early Bronze Age.","options":["them","whom","which","whose"],"correct":2,"answer":"which","vi":"Những công cụ này, mà mới chỉ một nửa được lập danh mục, có niên đại từ đầu thời đại đồ đồng.","explanation":"Quantifier + <b>of which</b> starts a non-defining relative clause about things, and <b>the tools</b> are things. ✗ <b>them</b> — a pronoun cannot join two clauses with only a comma; it would need 'and'; ✗ <b>whom</b> — used for people; ✗ <b>whose</b> — shows possession and is followed by a noun, so it cannot come after 'of'."},{"id":"gv-ch-25-21","level":"ch","focus":"idiom","q":"With the conference paper due on Monday, the two researchers ______ all weekend.","options":["burned the midnight oil","hit the sack","threw in the towel","got the sack"],"correct":0,"answer":"burned the midnight oil","vi":"Bài báo hội nghị phải nộp vào thứ Hai nên hai nhà nghiên cứu đã thức trắng làm việc suốt cả cuối tuần.","explanation":"<b>Burn the midnight oil</b> = work late into the night, fitting <b>paper due on Monday</b> and <b>all weekend</b>. ✗ <b>hit the sack</b> — go to bed, the opposite of working late; ✗ <b>threw in the towel</b> — gave up, which does not fit meeting a deadline; ✗ <b>got the sack</b> — were dismissed from a job."},{"id":"gv-ch-25-22","level":"ch","focus":"word-choice","q":"Entrance fees help to ______ the cost of conserving the mosaics, but they never cover it entirely.","options":["deduct","defray","deplete","default"],"correct":1,"answer":"defray","vi":"Tiền vé vào cửa giúp bù đắp một phần chi phí bảo tồn các bức tranh khảm, nhưng không bao giờ trang trải được toàn bộ.","explanation":"<b>Defray</b> a cost = provide money to pay part or all of it, matching <b>help to … but never cover it entirely</b>. ✗ <b>deduct</b> — subtract an amount from a total, not pay a cost; ✗ <b>deplete</b> — use up a supply, which fees do not do to a cost; ✗ <b>default</b> — fail to pay a debt, and it takes 'on', not an object."},{"id":"gv-ch-25-23","level":"ch","focus":"conditional","q":"The tourism board now wishes it ______ its marketing budget just before the pandemic struck.","options":["didn't cut","wouldn't cut","hasn't cut","hadn't cut"],"correct":3,"answer":"hadn't cut","vi":"Giờ đây cơ quan du lịch ước gì họ đã không cắt ngân sách quảng bá ngay trước khi đại dịch ập đến.","explanation":"A regret about a <b>past</b> action after <b>wish</b> takes the past perfect, and <b>just before the pandemic struck</b> puts the cut in the past: <b>hadn't cut</b>. ✗ <b>didn't cut</b> — past simple after wish is a wish about the present; ✗ <b>wouldn't cut</b> — wish + would complains about someone's future or repeated behaviour; ✗ <b>hasn't cut</b> — the present perfect is never used after wish."},{"id":"gv-ch-25-24","level":"ch","focus":"double-blank","q":"Restoring the mosaic ______ the city an arm and a ______, but visitor numbers have doubled since it reopened.","options":["paid / foot","charged / hand","cost / leg","spent / leg"],"correct":2,"answer":"cost / leg","vi":"Việc phục chế bức tranh khảm khiến thành phố tốn một khoản tiền khổng lồ, nhưng lượng khách tham quan đã tăng gấp đôi từ khi mở cửa lại.","explanation":"The idiom is <b>cost (someone) an arm and a leg</b> = be extremely expensive; both verb and final noun are fixed. ✗ <b>paid / foot</b> — the restoration does not pay anything, and 'an arm and a foot' is not the idiom; ✗ <b>charged / hand</b> — charge takes a price, and 'hand' breaks the phrase; ✗ <b>spent / leg</b> — spending is done by the city, not by 'restoring the mosaic'."},{"id":"gv-ch-25-25","level":"ch","focus":"collocation","q":"The authorities have ______ the ban on photography inside the tomb, to the delight of tour groups.","options":["lifted","raised","risen","elevated"],"correct":0,"answer":"lifted","vi":"Nhà chức trách đã dỡ bỏ lệnh cấm chụp ảnh bên trong lăng mộ, khiến các đoàn du khách vui mừng.","explanation":"You <b>lift</b> a ban, restriction or sanction = end it, and <b>to the delight of tour groups</b> shows the ban was removed. ✗ <b>raised</b> — raise means move higher or increase, so a raised ban would be stricter, not gone; ✗ <b>risen</b> — intransitive, cannot take the object 'the ban'; ✗ <b>elevated</b> — move to a higher position or rank, not end."},{"id":"gv-ch-26-1","level":"ch","focus":"word-choice","q":"Having spent a decade on the novel, she was ______ when every publisher rejected it and did not write another word for years.","options":["complacent","disconsolate","nonchalant","euphoric"],"correct":1,"answer":"disconsolate","vi":"Sau khi dành cả một thập kỷ cho cuốn tiểu thuyết, bà đã vô cùng đau khổ khi mọi nhà xuất bản đều từ chối nó và suốt nhiều năm không viết thêm một chữ nào.","explanation":"Meaning: every publisher <b>rejected</b> it and she <b>did not write another word for years</b> — deep, lasting unhappiness, so <b>disconsolate</b> (too sad to be comforted). ✗ <b>complacent</b> — smugly satisfied, the opposite of crushed; ✗ <b>nonchalant</b> — calmly unconcerned, but she stopped writing for years; ✗ <b>euphoric</b> — intensely happy, impossible after total rejection."},{"id":"gv-ch-26-2","level":"ch","focus":"collocation","q":"Wind and solar now ______ almost a third of the country's demand for electricity on a typical summer afternoon.","options":["meet","reach","fill","answer"],"correct":0,"answer":"meet","vi":"Điện gió và điện mặt trời hiện đáp ứng gần một phần ba nhu cầu điện của cả nước vào một buổi chiều mùa hè điển hình.","explanation":"Collocation: the object is <b>demand for electricity</b>, and the verb that goes with demand is <b>meet</b> (meet the demand = supply what is needed). ✗ <b>reach</b> — you reach a target, a level or a figure, not a demand; ✗ <b>fill</b> — you fill a gap, a vacancy or an order, not a demand; ✗ <b>answer</b> — you answer a question, a call or a need; 'answer demand for electricity' is not standard."},{"id":"gv-ch-26-3","level":"ch","focus":"idiom","q":"The festival lost money this year, but as its director put it, there is no use ______ when next summer's programme still has to be planned.","options":["beating about the bush","burning the midnight oil","crying over spilt milk","sitting on the fence"],"correct":2,"answer":"crying over spilt milk","vi":"Liên hoan năm nay bị lỗ, nhưng như giám đốc nói, than khóc chuyện đã rồi cũng chẳng ích gì khi chương trình mùa hè năm sau vẫn còn phải lên kế hoạch.","explanation":"Idiom: the festival <b>lost money</b> (done, cannot be changed) and next year <b>still has to be planned</b>, so regretting the past is pointless — <b>crying over spilt milk</b> (wasting time on what cannot be undone). ✗ <b>beating about the bush</b> — avoiding the main point; ✗ <b>burning the midnight oil</b> — working very late; ✗ <b>sitting on the fence</b> — refusing to take sides."},{"id":"gv-ch-26-4","level":"ch","focus":"inversion","q":"______ the engineers suspect that the bridge's cables had been corroding for years when they signed off the routine inspection report.","options":["Hardly had","Not until","Only when","Little did"],"correct":3,"answer":"Little did","vi":"Các kỹ sư hầu như không hề ngờ rằng dây cáp của cây cầu đã bị ăn mòn suốt nhiều năm khi họ ký duyệt báo cáo kiểm tra định kỳ.","explanation":"Inversion after a fronted negative: <b>Little</b> (= not at all) is followed by auxiliary + subject + bare verb, and the bare verb <b>suspect</b> fits <b>Little did</b> the engineers suspect. ✗ <b>Hardly had</b> — needs a past participle (had suspected) and a later 'when' for the next event; ✗ <b>Not until</b> — opens a time clause in normal order and puts the inversion in a main clause, which this sentence lacks; ✗ <b>Only when</b> — same problem: the inversion belongs in the main clause, not right after it."},{"id":"gv-ch-26-5","level":"ch","focus":"phrasal-verb","q":"With borrowing costs rising sharply, the utility has ______ its plans for a second offshore wind farm to a fraction of the original size.","options":["scaled back","scaled up","brought back","fallen back"],"correct":0,"answer":"scaled back","vi":"Do chi phí vay tăng mạnh, công ty điện lực đã thu hẹp kế hoạch xây trang trại điện gió ngoài khơi thứ hai xuống chỉ còn một phần nhỏ so với quy mô ban đầu.","explanation":"Phrasal verb: the clue is <b>to a fraction of the original size</b> — the plans were reduced, so <b>scaled back</b> (cut down in size or scope). ✗ <b>scaled up</b> — increased, the opposite of the clue; ✗ <b>brought back</b> — reintroduced or returned; nothing is being revived here; ✗ <b>fallen back</b> — retreated or dropped behind, and it takes no direct object, but 'its plans' follows the blank."},{"id":"gv-ch-26-6","level":"ch","focus":"modal","q":"The reviewer ______ the whole novel; her summary gets the ending completely wrong.","options":["needn't have read","can't have read","shouldn't have read","mustn't have read"],"correct":1,"answer":"can't have read","vi":"Nhà phê bình chắc chắn đã không đọc hết cuốn tiểu thuyết; bản tóm tắt của bà ấy sai hoàn toàn về đoạn kết.","explanation":"Modal deduction about the past: the summary <b>gets the ending completely wrong</b>, so the speaker is sure she did NOT read it all — a confident negative deduction is <b>can't have</b> + past participle. ✗ <b>needn't have read</b> — she read it but it was unnecessary, not the point; ✗ <b>shouldn't have read</b> — a criticism of something she did, not a deduction; ✗ <b>mustn't have read</b> — must have is used for positive deduction only; its negative is can't have."},{"id":"gv-ch-26-7","level":"ch","focus":"word-choice","q":"Local investors remain ______ about the new pipeline, fearing that a single leak could wipe out years of returns.","options":["jubilant","nostalgic","resentful","apprehensive"],"correct":3,"answer":"apprehensive","vi":"Các nhà đầu tư địa phương vẫn lo ngại về đường ống mới, e rằng chỉ một vụ rò rỉ cũng có thể xóa sạch lợi nhuận của nhiều năm.","explanation":"Meaning: <b>fearing that a single leak could wipe out years of returns</b> is worry about a possible future harm, so <b>apprehensive</b> (anxious that something bad may happen). ✗ <b>jubilant</b> — triumphantly happy, clashing with 'fearing'; ✗ <b>nostalgic</b> — longing for the past, nothing to do with a future leak; ✗ <b>resentful</b> — bitter about a wrong already done, but no harm has happened yet."},{"id":"gv-ch-26-8","level":"ch","focus":"double-blank","q":"The conductor was determined to ______ the restoration of the concert hall ______, however long the fundraising took.","options":["look / through","see / off","see / through","see / into"],"correct":2,"answer":"see / through","vi":"Vị nhạc trưởng quyết tâm theo đuổi việc trùng tu nhà hát hòa nhạc đến cùng, dù việc gây quỹ có kéo dài bao lâu.","explanation":"Phrasal verb: <b>determined</b> and <b>however long the fundraising took</b> mean continuing until the restoration is finished — <b>see something through</b>. ✗ <b>look / through</b> — look through means examine or read quickly, not persist; ✗ <b>see / off</b> — see off means say goodbye to someone or chase away, not complete a project; ✗ <b>see / into</b> — see into means look inside or perceive (see into the future), not finish."},{"id":"gv-ch-26-9","level":"ch","focus":"subjunctive","q":"The safety board recommended that the ageing reactor ______ offline until every crack in the cooling system had been examined.","options":["be taken","was taken","is taken","would be taken"],"correct":0,"answer":"be taken","vi":"Ủy ban an toàn khuyến nghị rằng lò phản ứng cũ kỹ phải được ngừng hoạt động cho đến khi mọi vết nứt trong hệ thống làm mát được kiểm tra.","explanation":"Subjunctive after a verb of recommending: <b>recommended that</b> is followed by the base form, with no tense or agreement, so <b>be taken</b>. ✗ <b>was taken</b> — past indicative; a recommendation says what should happen, not what happened; ✗ <b>is taken</b> — present indicative, and it also clashes with past 'recommended'; ✗ <b>would be taken</b> — would belongs to predictions and conditionals, not the that-clause after recommend."},{"id":"gv-ch-26-10","level":"ch","focus":"idiom","q":"When the boy insisted he had not meant to break the vase, his mother chose to ______ rather than punish him.","options":["give him a piece of her mind","give him the benefit of the doubt","give him the cold shoulder","give him a run for his money"],"correct":1,"answer":"give him the benefit of the doubt","vi":"Khi cậu bé khăng khăng rằng mình không cố ý làm vỡ bình hoa, mẹ cậu quyết định tin lời cậu thay vì phạt cậu.","explanation":"Idiom: the mother <b>chose to</b> believe him <b>rather than punish him</b>, so she <b>gave him the benefit of the doubt</b> (accepted his word without proof). ✗ <b>give him a piece of her mind</b> — an angry telling-off, the opposite of not punishing; ✗ <b>give him the cold shoulder</b> — deliberate unfriendliness, itself a punishment; ✗ <b>give him a run for his money</b> — strong competition, meaningless between a mother and a small boy."},{"id":"gv-ch-26-11","level":"ch","focus":"collocation","q":"Several critics ______ the charge of plagiarism at the young novelist, though none produced a single copied sentence.","options":["threw","pointed","sent","levelled"],"correct":3,"answer":"levelled","vi":"Nhiều nhà phê bình đã buộc tội nhà tiểu thuyết trẻ đạo văn, dù không ai đưa ra được một câu sao chép nào.","explanation":"Collocation: the noun is <b>the charge of plagiarism</b>, and the verb for aiming an accusation at someone is <b>level</b> (level a charge / an accusation / criticism at). ✗ <b>threw</b> — you throw a ball or a punch; 'throw a charge at' is not standard; ✗ <b>pointed</b> — you point a finger or a gun at someone, not a charge; ✗ <b>sent</b> — you send a letter or a message, and send does not take 'at'."},{"id":"gv-ch-26-12","level":"ch","focus":"participle","q":"______, the rescue helicopters will resume their search of the northern slopes at first light tomorrow.","options":["Weather permitted","Weather to permit","Weather permitting","Weather having permitted"],"correct":2,"answer":"Weather permitting","vi":"Nếu thời tiết cho phép, các trực thăng cứu hộ sẽ nối lại việc tìm kiếm trên các sườn núi phía bắc vào lúc rạng sáng mai.","explanation":"Absolute participle clause: <b>Weather permitting</b> = if the weather permits; the weather is the doer of 'permit', so the present (active) participle is needed. ✗ <b>Weather permitted</b> — a past participle is passive, making the weather the thing permitted; ✗ <b>Weather to permit</b> — an infinitive does not form an absolute clause; ✗ <b>Weather having permitted</b> — the perfect participle describes a condition already met, but the search is <b>tomorrow</b>."},{"id":"gv-ch-26-13","level":"ch","focus":"word-choice","q":"After the fourth blackout in a single week, residents were ______, and dozens wrote to the newspapers demanding that the grid operator resign.","options":["exasperated","serene","gratified","apathetic"],"correct":0,"answer":"exasperated","vi":"Sau lần mất điện thứ tư chỉ trong một tuần, cư dân vô cùng bực tức, và hàng chục người đã viết thư cho báo chí yêu cầu đơn vị vận hành lưới điện từ chức.","explanation":"Meaning: the <b>fourth blackout in a single week</b> and letters <b>demanding that the grid operator resign</b> show anger after repeated annoyance — <b>exasperated</b> (extremely irritated). ✗ <b>serene</b> — calm and peaceful, contradicting the angry letters; ✗ <b>gratified</b> — pleased and satisfied; nobody is pleased by four blackouts; ✗ <b>apathetic</b> — uninterested, but dozens bothered to write and demand a resignation."},{"id":"gv-ch-26-14","level":"ch","focus":"gerund-infinitive","q":"Most participants denied ______ the instructions, even though the recording showed them reading the page twice.","options":["to read","having read","to have read","read"],"correct":1,"answer":"having read","vi":"Hầu hết người tham gia phủ nhận đã đọc hướng dẫn, dù đoạn ghi hình cho thấy họ đọc trang đó hai lần.","explanation":"Verb pattern: <b>deny</b> takes a gerund (-ing), never a to-infinitive, and the perfect gerund <b>having read</b> marks the reading as earlier than the denying (the recording shows it already happened). ✗ <b>to read</b> — a to-infinitive, not used after deny; ✗ <b>to have read</b> — a perfect infinitive, still an infinitive, so not used after deny; ✗ <b>read</b> — a bare verb cannot follow deny; 'denied read' is ungrammatical."},{"id":"gv-ch-26-15","level":"ch","focus":"phrasal-verb","q":"The appeal court ______ the verdict after new evidence showed that the key witness had lied under oath.","options":["set about","set out","set aside","set off"],"correct":2,"answer":"set aside","vi":"Tòa phúc thẩm đã hủy bản án sau khi bằng chứng mới cho thấy nhân chứng chủ chốt đã khai man khi tuyên thệ.","explanation":"Phrasal verb: an <b>appeal court</b> acting on <b>new evidence</b> cancels an earlier <b>verdict</b> — the legal term is <b>set aside</b> (annul, declare invalid). ✗ <b>set about</b> — begin a task or attack someone; a court does not begin a verdict; ✗ <b>set out</b> — start a journey or state something clearly; ✗ <b>set off</b> — depart or trigger (an alarm, an explosion), not cancel."},{"id":"gv-ch-26-16","level":"ch","focus":"linking","q":"The city's grid was designed for half its present population; ______, blackouts have become a routine feature of every heatwave.","options":["nevertheless","otherwise","moreover","consequently"],"correct":3,"answer":"consequently","vi":"Lưới điện của thành phố được thiết kế cho một nửa dân số hiện tại; do đó, mất điện đã trở thành chuyện thường lệ trong mỗi đợt nắng nóng.","explanation":"Linking adverb: the grid was built <b>for half its present population</b>, and routine blackouts are the <b>result</b>, so <b>consequently</b>. ✗ <b>nevertheless</b> — signals contrast ('despite that'), but the second clause follows from the first, not against it; ✗ <b>otherwise</b> — means 'if not', describing what would happen if the first clause were untrue; ✗ <b>moreover</b> — simply adds another point, without showing that the blackouts are caused by the undersized grid."},{"id":"gv-ch-26-17","level":"ch","focus":"idiom","q":"Nurses who ______ for their patients report higher job satisfaction, the study found, even though they work longer hours.","options":["go the extra mile","go through the roof","go with the flow","go round in circles"],"correct":0,"answer":"go the extra mile","vi":"Nghiên cứu cho thấy những y tá nỗ lực hết mình vì bệnh nhân có mức độ hài lòng với công việc cao hơn, dù họ làm việc nhiều giờ hơn.","explanation":"Idiom: <b>higher job satisfaction... even though they work longer hours</b> describes nurses who make extra effort — <b>go the extra mile</b> (do more than is expected). ✗ <b>go through the roof</b> — rise very fast (prices) or lose one's temper; ✗ <b>go with the flow</b> — accept whatever happens without effort, the opposite of extra effort; ✗ <b>go round in circles</b> — make no progress, and it cannot take 'for their patients'."},{"id":"gv-ch-26-18","level":"ch","focus":"agreement","q":"Neither the playwright nor the actors ______ willing to comment on the cancelled tour when the press arrived.","options":["was","were","is","has been"],"correct":1,"answer":"were","vi":"Cả nhà viết kịch lẫn các diễn viên đều không muốn bình luận về chuyến lưu diễn bị hủy khi báo chí đến.","explanation":"Agreement with <b>neither... nor</b>: the verb agrees with the nearer subject, <b>the actors</b> (plural), and <b>when the press arrived</b> sets the time in the past, so <b>were</b>. ✗ <b>was</b> — singular, agreeing with 'the playwright', the further subject; ✗ <b>is</b> — singular and present, wrong on both counts; ✗ <b>has been</b> — singular and present perfect, while the sentence describes one past moment."},{"id":"gv-ch-26-19","level":"ch","focus":"word-choice","q":"He was ______ to discover that he had sent the unfinished draft, complete with his private notes, to the entire faculty.","options":["overjoyed","appeased","mortified","vindicated"],"correct":2,"answer":"mortified","vi":"Anh ta vô cùng xấu hổ khi phát hiện ra mình đã gửi bản thảo chưa hoàn thành, kèm cả những ghi chú riêng tư, cho toàn bộ khoa.","explanation":"Meaning: sending an unfinished draft <b>complete with his private notes</b> to <b>the entire faculty</b> is a humiliating mistake, so <b>mortified</b> (extremely embarrassed). ✗ <b>overjoyed</b> — delighted, the opposite reaction; ✗ <b>appeased</b> — calmed after being angry, but nothing had made him angry; ✗ <b>vindicated</b> — proved right after doubt, but the discovery proves a blunder, not a point."},{"id":"gv-ch-26-20","level":"ch","focus":"double-blank","q":"To ______ the ball ______, the moderator asked each panellist to name one film that had changed their mind about something.","options":["put / rolling","get / running","make / turning","get / rolling"],"correct":3,"answer":"get / rolling","vi":"Để khởi động buổi thảo luận, người điều phối đề nghị mỗi khách mời kể tên một bộ phim đã làm thay đổi suy nghĩ của họ về điều gì đó.","explanation":"Fixed idiom: <b>get the ball rolling</b> = start something happening, matching the moderator's opening question. ✗ <b>put / rolling</b> — put is not the verb of this idiom (get or set the ball rolling); ✗ <b>get / running</b> — 'get something running' works for an engine, but the ball idiom needs rolling; ✗ <b>make / turning</b> — neither word belongs to the idiom, and 'make the ball turning' is ungrammatical (make takes a bare infinitive, not -ing)."},{"id":"gv-ch-26-21","level":"ch","focus":"comparison","q":"______ a community feels about the reliability of its power supply, the less willing it is to oppose new pylons nearby.","options":["The more anxious","The most anxious","More anxious","The much anxious"],"correct":0,"answer":"The more anxious","vi":"Một cộng đồng càng lo lắng về độ tin cậy của nguồn điện thì càng ít muốn phản đối việc dựng cột điện mới gần đó.","explanation":"Double comparative: <b>the less willing</b> in the second half signals the pattern 'the + comparative..., the + comparative...', so the first half must be <b>The more anxious</b>. ✗ <b>The most anxious</b> — a superlative; the pattern needs a comparative; ✗ <b>More anxious</b> — a comparative without 'the', which the paired structure requires; ✗ <b>The much anxious</b> — 'much anxious' is not a comparative at all (much modifies comparatives: much more anxious)."},{"id":"gv-ch-26-22","level":"ch","focus":"collocation","q":"Researchers are careful to ______ a distinction between a habit, which is automatic, and an addiction, which persists despite harm.","options":["put","take","draw","set"],"correct":2,"answer":"draw","vi":"Các nhà nghiên cứu cẩn thận phân biệt giữa thói quen, vốn mang tính tự động, và chứng nghiện, vốn tồn tại dai dẳng bất chấp tác hại.","explanation":"Collocation: the noun is <b>a distinction between</b> two things, and the verbs that go with it are draw or make; only <b>draw</b> is offered. ✗ <b>put</b> — put goes with 'a question' or 'a case', not a distinction; ✗ <b>take</b> — take goes with 'a decision' or 'a view', not a distinction; ✗ <b>set</b> — set goes with 'a limit' or 'a standard'; 'set a distinction' is not English."},{"id":"gv-ch-26-23","level":"ch","focus":"idiom","q":"'What if the grant runs out before the survey is finished?' 'It may never happen, so let's ______.'","options":["burn our bridges","cross that bridge when we come to it","bite the bullet","let sleeping dogs lie"],"correct":1,"answer":"cross that bridge when we come to it","vi":"'Nếu khoản tài trợ cạn trước khi cuộc khảo sát hoàn thành thì sao?' 'Chuyện đó có thể chẳng bao giờ xảy ra, nên đến lúc đó rồi tính.'","explanation":"Idiom: <b>It may never happen</b> — the problem is only possible, so deal with it if and when it arises: <b>cross that bridge when we come to it</b>. ✗ <b>burn our bridges</b> — destroy any way back, an irreversible act; ✗ <b>bite the bullet</b> — face something unpleasant now, the opposite of waiting; ✗ <b>let sleeping dogs lie</b> — avoid stirring up an old problem, but this problem lies in the future, not the past."},{"id":"gv-ch-26-24","level":"ch","focus":"passive","q":"By the time the new dam is completed, an estimated forty villages ______ to higher ground by the authorities.","options":["will have moved","will be moving","have been moving","will have been moved"],"correct":3,"answer":"will have been moved","vi":"Đến khi con đập mới hoàn thành, ước tính khoảng bốn mươi ngôi làng sẽ đã được chính quyền di dời lên vùng đất cao hơn.","explanation":"Tense and voice: <b>By the time the new dam is completed</b> points to an action finished before a future moment (future perfect), and <b>by the authorities</b> names the agent, so the passive is needed: <b>will have been moved</b>. ✗ <b>will have moved</b> — future perfect but active, so the villages would be doing the moving, clashing with 'by the authorities'; ✗ <b>will be moving</b> — future continuous, an action in progress, not completed; ✗ <b>have been moving</b> — present perfect continuous, active and not future."},{"id":"gv-ch-26-25","level":"ch","focus":"word-choice","q":"The finding that participants who were paid more performed worse left the psychologists ______, as it contradicted every existing model of motivation.","options":["reassured","perplexed","smug","remorseful"],"correct":1,"answer":"perplexed","vi":"Phát hiện rằng những người tham gia được trả nhiều tiền hơn lại làm việc kém hơn khiến các nhà tâm lý học bối rối, vì nó mâu thuẫn với mọi mô hình động lực hiện có.","explanation":"Meaning: the result <b>contradicted every existing model</b>, so the psychologists could not explain it — <b>perplexed</b> (confused, puzzled). ✗ <b>reassured</b> — comforted, feeling less worried; an unexplained result does the opposite; ✗ <b>smug</b> — self-satisfied, which fits confirmed models, not overturned ones; ✗ <b>remorseful</b> — sorry for a wrong done, but the psychologists did nothing wrong."},{"id":"gv-ch-27-1","level":"ch","focus":"word-choice","q":"The gap between gold and silver in the 100 metres was ______ — three hundredths of a second — but in elite sprinting that is the difference between a medal and obscurity.","options":["meagre","trivial","minute","petty"],"correct":2,"answer":"minute","vi":"Khoảng cách giữa huy chương vàng và bạc ở cự ly 100 mét là cực kỳ nhỏ — ba phần trăm giây — nhưng trong môn chạy nước rút đỉnh cao, đó là khác biệt giữa một tấm huy chương và sự vô danh.","explanation":"Word choice: <b>three hundredths of a second</b> is a tiny measurement, so the gap is <b>minute</b> (/maɪˈnjuːt/) = extremely small. ✗ <b>trivial</b> — unimportant, which the sentence denies (it decides a medal); ✗ <b>meagre</b> — too small in quantity to be enough (a meagre salary), not a measured gap; ✗ <b>petty</b> — small-minded, mean behaviour, never a measurement."},{"id":"gv-ch-27-2","level":"ch","focus":"idiom","q":"Ever since his boyhood club released him at sixteen, the striker has ______, treating every question about his past as a personal insult.","options":["had a chip on his shoulder","had a bee in his bonnet","had an axe to grind","had a finger in every pie"],"correct":0,"answer":"had a chip on his shoulder","vi":"Kể từ khi câu lạc bộ thời niên thiếu cho anh ra đi năm mười sáu tuổi, tiền đạo này luôn mang nỗi hậm hực trong lòng, coi mọi câu hỏi về quá khứ như một sự xúc phạm cá nhân.","explanation":"Idiom: <b>treating every question as a personal insult</b> years after being released shows lasting resentment — <b>had a chip on his shoulder</b> = stays bitter about a past injustice and takes offence easily. ✗ <b>had a bee in his bonnet</b> — obsessed with one idea; ✗ <b>had an axe to grind</b> — has a hidden selfish motive; ✗ <b>had a finger in every pie</b> — involved in many activities."},{"id":"gv-ch-27-3","level":"ch","focus":"collocation","q":"After nine hours of deliberation, the jury in the data-fraud trial ______ a unanimous verdict of guilty on all three counts.","options":["arrived","reached","achieved","came"],"correct":1,"answer":"reached","vi":"Sau chín giờ nghị án, bồi thẩm đoàn trong phiên tòa xét xử vụ gian lận dữ liệu đã đi đến phán quyết nhất trí là có tội ở cả ba tội danh.","explanation":"Collocation: a jury <b>reaches a verdict</b> — the fixed verb for deciding its answer, and the blank is followed directly by <b>a unanimous verdict</b> with no preposition. ✗ <b>arrived</b> — needs <b>at</b> (arrive at a verdict); ✗ <b>came</b> — needs <b>to</b> (come to a verdict); ✗ <b>achieved</b> — goes with goals, results and success, not verdicts."},{"id":"gv-ch-27-4","level":"ch","focus":"modal","q":"The striker ______ offside when the pass was played; the freeze-frame clearly shows two defenders standing goal-side of him.","options":["shouldn't have been","needn't have been","mustn't have been","can't have been"],"correct":3,"answer":"can't have been","vi":"Tiền đạo không thể nào đã việt vị lúc đường chuyền được thực hiện; hình dừng cho thấy rõ hai hậu vệ đứng gần khung thành hơn anh ta.","explanation":"Modal deduction about the past: the <b>freeze-frame clearly shows</b> two defenders goal-side, so the speaker is sure offside was impossible — <b>can't have been</b>. ✗ <b>mustn't have been</b> — <b>mustn't</b> is prohibition, not deduction; the negative of <b>must have</b> is <b>can't have</b>; ✗ <b>needn't have been</b> — 'it was unnecessary', not a judgement about a fact; ✗ <b>shouldn't have been</b> — criticises a choice, but being offside is not a decision."},{"id":"gv-ch-27-5","level":"ch","focus":"phrasal-verb","q":"The world number one ______ the first-round defeat as a blip and was back on the practice court within hours.","options":["called off","shrugged off","put off","fended off"],"correct":1,"answer":"shrugged off","vi":"Tay vợt số một thế giới gạt phăng trận thua vòng một, coi đó chỉ là một sự cố nhỏ, và quay lại sân tập chỉ vài giờ sau.","explanation":"Phrasal verb: <b>as a blip</b> (something unimportant) and <b>back on the practice court within hours</b> show she dismissed the defeat — <b>shrugged off</b> = treated as unimportant. ✗ <b>called off</b> — cancelled (an event); ✗ <b>put off</b> — postponed, or discouraged someone; ✗ <b>fended off</b> — kept away an attacker or awkward questions; a defeat already suffered cannot be fended off."},{"id":"gv-ch-27-6","level":"ch","focus":"word-choice","q":"Abolishing the offside rule would be a ______ decision, one that historians of the game would still be arguing about a century from now.","options":["momentous","eminent","imposing","colossal"],"correct":0,"answer":"momentous","vi":"Bãi bỏ luật việt vị sẽ là một quyết định trọng đại, mà các nhà sử học bóng đá vẫn còn tranh cãi cả trăm năm sau.","explanation":"Word choice: a decision still <b>argued about a century from now</b> is one of great, lasting importance — <b>momentous</b>. ✗ <b>eminent</b> — distinguished, famous; used of people (an eminent scientist), not decisions; ✗ <b>imposing</b> — impressive in size or appearance, of buildings or figures; ✗ <b>colossal</b> — enormous in physical size or amount (a colossal debt), not in significance."},{"id":"gv-ch-27-7","level":"ch","focus":"inversion","q":"Rarely ______ dominated a single Olympic programme so completely, winning all seven of her events by clear water.","options":["a swimmer has","does a swimmer","has a swimmer","a swimmer had"],"correct":2,"answer":"has a swimmer","vi":"Hiếm khi có một vận động viên bơi lội nào thống trị trọn vẹn một kỳ Olympic đến thế, thắng cả bảy nội dung với khoảng cách rõ rệt.","explanation":"Inversion: a negative adverb at the front (<b>Rarely</b>) forces auxiliary + subject, and the past participle <b>dominated</b> needs <b>has</b>: Rarely <b>has a swimmer</b> dominated. ✗ <b>a swimmer has</b> — normal order; no inversion after Rarely; ✗ <b>a swimmer had</b> — no inversion, and past perfect has no earlier point to refer to; ✗ <b>does a swimmer</b> — inverted, but <b>does</b> must be followed by the base form <b>dominate</b>, not <b>dominated</b>."},{"id":"gv-ch-27-8","level":"ch","focus":"idiom","q":"The anchor found himself ______ after a live microphone picked him up mocking a guest during the commercial break.","options":["in the red","in the doldrums","in the dark","in hot water"],"correct":3,"answer":"in hot water","vi":"Người dẫn chương trình rơi vào rắc rối sau khi micro đang bật thu được cảnh anh ta chế giễu một vị khách trong lúc nghỉ quảng cáo.","explanation":"Idiom: being <b>picked up mocking a guest</b> on a live microphone lands him in trouble — <b>in hot water</b> = in trouble for something you did. ✗ <b>in the red</b> — owing money, in debt; ✗ <b>in the doldrums</b> — inactive, stagnant or gloomy; ✗ <b>in the dark</b> — not told, uninformed."},{"id":"gv-ch-27-9","level":"ch","focus":"double-blank","q":"Many freelance reporters, ______ fees have fallen by a third in real terms, can barely make ends ______ on what online outlets pay per article.","options":["whose / meet","who / meet","whose / match","whom / met"],"correct":0,"answer":"whose / meet","vi":"Nhiều phóng viên tự do, những người có nhuận bút đã giảm một phần ba theo giá trị thực, hầu như không đủ sống với mức các trang tin trực tuyến trả cho mỗi bài.","explanation":"Double blank: the first gap links <b>reporters</b> to <b>fees</b> as owner and thing owned, so the possessive relative <b>whose</b> (their fees); the second completes the idiom <b>make ends meet</b> = earn just enough to live on. ✗ <b>who / meet</b> — <b>who fees have fallen</b> is ungrammatical: <b>who</b> cannot show possession; ✗ <b>whose / match</b> — <b>match</b> breaks the fixed idiom; ✗ <b>whom / met</b> — <b>whom</b> is an object form, and <b>met</b> is the wrong form in the idiom."},{"id":"gv-ch-27-10","level":"ch","focus":"linking","q":"The public broadcaster's audience has grown steadily over the past two years, ______ its commercial rivals' has shrunk for six quarters in a row.","options":["despite","whereas","otherwise","nevertheless"],"correct":1,"answer":"whereas","vi":"Lượng khán giả của đài truyền hình công đã tăng đều trong hai năm qua, trong khi lượng khán giả của các đối thủ thương mại lại giảm sáu quý liên tiếp.","explanation":"Linking words: two full clauses with opposite facts (<b>audience has grown</b> … <b>rivals' has shrunk</b>) need a contrast conjunction — <b>whereas</b>. ✗ <b>despite</b> — a preposition, takes a noun or -ing, not subject + verb; ✗ <b>otherwise</b> — an adverb meaning 'if not', and cannot join two clauses with only a comma; ✗ <b>nevertheless</b> — an adverb ('however') that needs a full stop or semicolon before it, not a comma."},{"id":"gv-ch-27-11","level":"ch","focus":"word-choice","q":"Despite the scale of the doping scandal, the story received only ______ attention from the national broadcasters, which were busy covering the election.","options":["sparse","scarce","slender","scant"],"correct":3,"answer":"scant","vi":"Dù vụ bê bối doping có quy mô lớn, câu chuyện chỉ nhận được rất ít sự chú ý từ các đài truyền hình quốc gia, vốn đang bận đưa tin về cuộc bầu cử.","explanation":"Word choice: <b>only ______ attention</b> = very little attention, and <b>scant</b> is the adjective that pairs with attention/regard. ✗ <b>scarce</b> — in short supply, of resources (water, jobs), not attention; ✗ <b>sparse</b> — thinly spread over an area (sparse hair, a sparse population); ✗ <b>slender</b> — thin in build, or a narrow margin (a slender majority)."},{"id":"gv-ch-27-12","level":"ch","focus":"subjunctive","q":"The press ombudsman recommended that the correction ______ on the same page and in the same type size as the original error.","options":["was printed","would be printed","be printed","is printed"],"correct":2,"answer":"be printed","vi":"Thanh tra báo chí khuyến nghị rằng đính chính phải được đăng trên cùng trang và với cùng cỡ chữ như lỗi ban đầu.","explanation":"Subjunctive: after <b>recommended that</b>, the that-clause takes the base form, so the passive is <b>be printed</b>. ✗ <b>was printed</b> — past indicative; a recommendation is not a report of what happened; ✗ <b>is printed</b> — present indicative; after recommend/suggest/insist the verb loses its -s and tense; ✗ <b>would be printed</b> — <b>would</b> is not used in a that-clause after recommend."},{"id":"gv-ch-27-13","level":"ch","focus":"phrasal-verb","q":"Before announcing her candidacy for the federation presidency, she quietly ______ several national coaches to gauge how much support she could count on.","options":["sounded out","spoke out","sounded off","spelled out"],"correct":0,"answer":"sounded out","vi":"Trước khi tuyên bố ứng cử chức chủ tịch liên đoàn, bà đã âm thầm thăm dò ý kiến vài huấn luyện viên đội tuyển quốc gia để xem mình có thể trông cậy vào bao nhiêu sự ủng hộ.","explanation":"Phrasal verb: she <b>quietly</b> approached coaches <b>to gauge support</b> — <b>sounded out</b> = discreetly found out someone's opinion. ✗ <b>spoke out</b> — stated views publicly, and takes no object; ✗ <b>sounded off</b> — complained loudly, no object; ✗ <b>spelled out</b> — explained in detail; you spell out a plan or rules, not people."},{"id":"gv-ch-27-14","level":"ch","focus":"idiom","q":"\"______,\" the coach told the gymnast, who was close to tears after her fall; \"the all-around final is still two days away.\"","options":["Keep your hair on","Keep your chin up","Keep your head down","Keep your shirt on"],"correct":1,"answer":"Keep your chin up","vi":"\"Cứ ngẩng cao đầu lên,\" huấn luyện viên nói với cô vận động viên thể dục dụng cụ đang rưng rưng nước mắt sau cú ngã; \"chung kết toàn năng vẫn còn hai ngày nữa.\"","explanation":"Idiom: the gymnast is <b>close to tears</b> and the coach reminds her the final is <b>still two days away</b> — encouragement: <b>Keep your chin up</b> = stay cheerful and hopeful. ✗ <b>Keep your hair on</b> — calm down, don't get angry; ✗ <b>Keep your shirt on</b> — also 'don't lose your temper'; ✗ <b>Keep your head down</b> — stay quiet and avoid attention."},{"id":"gv-ch-27-15","level":"ch","focus":"collocation","q":"The documentary ______ a furious debate about the ethics of secretly filming athletes in their changing rooms.","options":["lit","flared","blazed","sparked"],"correct":3,"answer":"sparked","vi":"Bộ phim tài liệu đã châm ngòi cho một cuộc tranh luận dữ dội về đạo đức của việc quay lén vận động viên trong phòng thay đồ.","explanation":"Collocation: causing a discussion to start is <b>spark a debate</b> (also spark controversy / a row), and the verb needs the object <b>a furious debate</b>. ✗ <b>lit</b> — you light a fire or a cigarette, not a debate; ✗ <b>flared</b> — intransitive: a debate flares (up) by itself, it cannot flare something; ✗ <b>blazed</b> — also intransitive (a fire blazes), takes no object."},{"id":"gv-ch-27-16","level":"ch","focus":"gerund-infinitive","q":"The club now regrets ______ the young winger a longer contract before its wealthier rivals came calling.","options":["not to offer","to not offer","not offering","not offer"],"correct":2,"answer":"not offering","vi":"Câu lạc bộ giờ hối tiếc vì đã không đề nghị cầu thủ chạy cánh trẻ một hợp đồng dài hạn hơn trước khi các đối thủ giàu có hơn tìm đến.","explanation":"Gerund vs infinitive: <b>regret + -ing</b> looks back at something done or not done in the past — the club <b>now regrets not offering</b> the contract <b>before</b> rivals came. ✗ <b>not to offer</b> — regret + to-infinitive only announces bad news now (we regret to inform you); ✗ <b>to not offer</b> — same problem, plus a split infinitive; ✗ <b>not offer</b> — a bare verb cannot follow <b>regret</b>."},{"id":"gv-ch-27-17","level":"ch","focus":"word-choice","q":"The proposal to expand the tournament to 48 teams was approved by an ______ majority of member associations, with only four voting against.","options":["overriding","overwhelming","overpowering","overbearing"],"correct":1,"answer":"overwhelming","vi":"Đề xuất mở rộng giải đấu lên 48 đội đã được đa số áp đảo các liên đoàn thành viên thông qua, chỉ có bốn phiếu chống.","explanation":"Word choice: approved with <b>only four voting against</b> = a very large majority — <b>overwhelming majority</b> is the fixed pairing. ✗ <b>overriding</b> — more important than everything else (an overriding concern), not 'large'; ✗ <b>overpowering</b> — too strong to resist, of smells or feelings; ✗ <b>overbearing</b> — bossy, domineering, of people."},{"id":"gv-ch-27-18","level":"ch","focus":"reported","q":"The club's spokesman told reporters on Sunday evening that the board ______ the allegations at a press conference the following morning.","options":["would address","will address","addresses","had addressed"],"correct":0,"answer":"would address","vi":"Người phát ngôn câu lạc bộ nói với các phóng viên tối Chủ nhật rằng ban lãnh đạo sẽ trả lời các cáo buộc tại cuộc họp báo vào sáng hôm sau.","explanation":"Reported speech: after the past reporting verb <b>told</b>, <b>will</b> backshifts to <b>would</b>, and <b>the following morning</b> shows the event was still future for the speaker. ✗ <b>will address</b> — no backshift after <b>told</b> on a past Sunday; ✗ <b>addresses</b> — present simple reports a general fact, not a planned event; ✗ <b>had addressed</b> — past perfect puts the press conference before Sunday, contradicting <b>the following morning</b>."},{"id":"gv-ch-27-19","level":"ch","focus":"idiom","q":"The editor promised to ______ in tracing the source of the leaked memo, even if it meant reviewing every email sent from the building that week.","options":["leave well alone","leave it at that","leave no stone unturned","leave a lot to be desired"],"correct":2,"answer":"leave no stone unturned","vi":"Tổng biên tập hứa sẽ không bỏ sót bất cứ manh mối nào trong việc truy tìm nguồn của bản ghi nhớ bị rò rỉ, kể cả khi phải rà soát mọi email gửi đi từ tòa nhà trong tuần đó.","explanation":"Idiom: reviewing <b>every email sent from the building</b> means trying every possible way — <b>leave no stone unturned</b>. ✗ <b>leave well alone</b> — not interfere with something that is fine as it is; ✗ <b>leave it at that</b> — say or do nothing more; ✗ <b>leave a lot to be desired</b> — be far from satisfactory."},{"id":"gv-ch-27-20","level":"ch","focus":"participle","q":"______ how long the power cut would last, the laboratory staff moved the vaccine samples into a backup freezer running on a generator.","options":["Not known","Not to know","Not having known","Not knowing"],"correct":3,"answer":"Not knowing","vi":"Không biết sự cố mất điện sẽ kéo dài bao lâu, nhân viên phòng thí nghiệm đã chuyển các mẫu vắc-xin sang tủ đông dự phòng chạy bằng máy phát.","explanation":"Participle clause: the opening clause gives the reason the staff acted, and the staff are the ones not knowing, so an active -ing form with <b>not</b> in front: <b>Not knowing</b>. ✗ <b>Not known</b> — past participle is passive: the staff were not known; ✗ <b>Not to know</b> — an infinitive cannot open a reason clause; ✗ <b>Not having known</b> — the perfect form says the ignorance ended before they moved the samples, but they still didn't know."},{"id":"gv-ch-27-21","level":"ch","focus":"double-blank","q":"Instead of ______ any one player ______ for blame, the coach said the whole squad had underperformed in the second half.","options":["single / out","singling / out","singling / up","singled / out"],"correct":1,"answer":"singling / out","vi":"Thay vì chỉ trích riêng một cầu thủ nào, huấn luyện viên nói rằng cả đội đã thi đấu dưới sức trong hiệp hai.","explanation":"Double blank: <b>Instead of</b> is a preposition, so the verb after it takes -ing; the phrasal verb <b>single somebody out</b> = pick one person from a group for blame or praise. ✗ <b>single / out</b> — a bare verb cannot follow a preposition; ✗ <b>singled / out</b> — a past form cannot follow <b>of</b>; ✗ <b>singling / up</b> — <b>single up</b> does not exist."},{"id":"gv-ch-27-22","level":"ch","focus":"pronoun","q":"With the two sides level after extra time, the semi-final will be decided by ______ keeps their nerve in the penalty shoot-out.","options":["who","whom","whomever","whoever"],"correct":3,"answer":"whoever","vi":"Với hai đội hòa nhau sau hiệp phụ, trận bán kết sẽ được định đoạt bởi bất cứ ai giữ được bình tĩnh trong loạt sút luân lưu.","explanation":"Pronoun: the blank is the subject of <b>keeps</b> and means 'the person who', so <b>whoever</b>; <b>by</b> governs the whole clause <b>whoever keeps their nerve</b>, not the pronoun alone. ✗ <b>whomever</b> — object form, but the word is the subject of <b>keeps</b>; ✗ <b>who</b> — needs a noun before it (the side who…) and cannot mean 'anyone who' in standard usage; ✗ <b>whom</b> — object form, and also needs an antecedent."},{"id":"gv-ch-27-23","level":"ch","focus":"word-choice","q":"For four decades he was a ______ figure in sports broadcasting, whose commentary shaped how a whole generation heard the game.","options":["towering","lofty","soaring","elevated"],"correct":0,"answer":"towering","vi":"Trong bốn thập kỷ, ông là một tượng đài của ngành bình luận thể thao, người mà lời bình đã định hình cách cả một thế hệ nghe trận đấu.","explanation":"Word choice: a person of outstanding importance whose commentary <b>shaped a whole generation</b> is a <b>towering figure</b> (fixed pairing). ✗ <b>lofty</b> — high-minded (lofty ideals) or arrogant (a lofty manner), not 'important'; ✗ <b>soaring</b> — rising fast, of prices, temperatures or birds; ✗ <b>elevated</b> — physically raised (an elevated railway) or high in rank, not said of a figure."},{"id":"gv-ch-27-24","level":"ch","focus":"collocation","q":"Unregulated betting apps ______ a serious threat to the integrity of lower-league football, the inquiry concluded.","options":["put","make","pose","set"],"correct":2,"answer":"pose","vi":"Các ứng dụng cá cược không được quản lý đặt ra mối đe dọa nghiêm trọng đối với sự trong sạch của bóng đá hạng dưới, cuộc điều tra kết luận.","explanation":"Collocation: <b>pose a threat to</b> something is the fixed verb + noun for being a danger — apps <b>pose a serious threat to the integrity</b>. ✗ <b>put</b> — you put something <b>at risk</b> or <b>under threat</b>, never put a threat; ✗ <b>make</b> — make a threat = say threatening words, not be a danger; ✗ <b>set</b> — sets a record, a target or a trap, not a threat."},{"id":"gv-ch-27-25","level":"ch","focus":"question-tag","q":"Nobody in the press room expected the manager to announce his resignation that afternoon, ______?","options":["didn't they","did they","didn't he","did he"],"correct":1,"answer":"did they","vi":"Không ai trong phòng họp báo ngờ rằng huấn luyện viên sẽ tuyên bố từ chức chiều hôm đó, phải không?","explanation":"Question tag: <b>Nobody</b> makes the statement negative, so the tag is positive; indefinite pronouns (nobody, everyone) take <b>they</b>, and past simple <b>expected</b> takes <b>did</b>: <b>did they</b>. ✗ <b>didn't they</b> — a negative tag after an already negative statement; ✗ <b>didn't he</b> — negative, and <b>he</b> points to the manager (the object), not the subject <b>nobody</b>; ✗ <b>did he</b> — right polarity, but <b>he</b> is the wrong pronoun for <b>nobody</b>."},{"id":"gv-ch-28-1","level":"ch","focus":"word-choice","q":"After years of complaints from tenants, the city council finally voted to ______ the by-law that let landlords evict without notice.","options":["retract","repeal","cancel","dismiss"],"correct":1,"answer":"repeal","vi":"Sau nhiều năm bị người thuê nhà phàn nàn, hội đồng thành phố cuối cùng đã bỏ phiếu bãi bỏ quy định cho phép chủ nhà đuổi người thuê mà không cần báo trước.","explanation":"Word choice: a <b>by-law</b> (a law) is officially cancelled by a vote — <b>repeal</b> = cancel a law. ✗ <b>retract</b> — take back a statement or offer, not a law; ✗ <b>cancel</b> — call off an event, order or booking, not the verb used for legislation; ✗ <b>dismiss</b> — reject a case, idea or employee."},{"id":"gv-ch-28-2","level":"ch","focus":"idiom","q":"Having already been cautioned twice for leaking to the press, the junior minister knew he was ______.","options":["on thin ice","on the fence","on the rocks","on cloud nine"],"correct":0,"answer":"on thin ice","vi":"Đã hai lần bị cảnh cáo vì để lộ tin cho báo chí, vị thứ trưởng trẻ biết mình đang ở thế ngàn cân treo sợi tóc.","explanation":"Idiom: <b>cautioned twice</b> means one more mistake will finish him — <b>on thin ice</b> = in a risky position. ✗ <b>on the fence</b> — undecided between two sides; ✗ <b>on the rocks</b> — failing (a marriage, a business); ✗ <b>on cloud nine</b> — extremely happy."},{"id":"gv-ch-28-3","level":"ch","focus":"inversion","q":"______ has a single online rumour wiped so much value off a listed company as the one that circulated on Monday.","options":["Not only","Seldom","Not until","Only when"],"correct":1,"answer":"Seldom","vi":"Hiếm khi một tin đồn trên mạng lại làm bốc hơi nhiều giá trị của một công ty niêm yết đến vậy như tin đồn lan truyền hôm thứ Hai.","explanation":"Inversion after a negative adverb: <b>has a single online rumour wiped</b> (auxiliary before subject) needs a fronted word like <b>Seldom</b> (= rarely). ✗ <b>Not only</b> — needs a matching <i>but (also)</i> clause, which the sentence lacks; ✗ <b>Not until</b> — must be followed by a time clause (<i>Not until Monday did…</i>) before the inverted clause; ✗ <b>Only when</b> — same: needs a clause (<i>Only when it spread did…</i>) first."},{"id":"gv-ch-28-4","level":"ch","focus":"collocation","q":"Residents complained that the unlit stairwells had turned the estate into a ______ ground for petty crime.","options":["feeding","growing","nursing","breeding"],"correct":3,"answer":"breeding","vi":"Cư dân than phiền rằng những cầu thang không có đèn đã biến khu chung cư thành mảnh đất màu mỡ cho tội phạm vặt.","explanation":"Collocation: a place where something bad develops is a <b>breeding ground</b> (for crime, disease, ideas) — clue: <b>unlit stairwells … petty crime</b>. ✗ <b>feeding ground</b> — where animals feed, not where crime develops; ✗ <b>growing ground</b> — not a fixed phrase; ✗ <b>nursing ground</b> — not a fixed phrase (nursing = caring for the sick)."},{"id":"gv-ch-28-5","level":"ch","focus":"phrasal-verb","q":"The commissioner announced that she would ______ at the end of the year rather than face a vote of no confidence.","options":["step down","step in","step up","stand by"],"correct":0,"answer":"step down","vi":"Bà cảnh sát trưởng tuyên bố sẽ từ chức vào cuối năm thay vì đối mặt với cuộc bỏ phiếu bất tín nhiệm.","explanation":"Phrasal verb: <b>rather than face a vote of no confidence</b> means she will leave her post — <b>step down</b> = resign. ✗ <b>step in</b> — intervene to help or take control; ✗ <b>step up</b> — increase (efforts) or take on more responsibility, the opposite here; ✗ <b>stand by</b> — wait ready, or support someone."},{"id":"gv-ch-28-6","level":"ch","focus":"subjunctive","q":"The tribunal recommended that the landlord ______ the deposit in full within fourteen days.","options":["returns","return","returned","will return"],"correct":1,"answer":"return","vi":"Toà án đã khuyến nghị rằng chủ nhà phải hoàn trả toàn bộ tiền đặt cọc trong vòng mười bốn ngày.","explanation":"Mandative subjunctive: after <b>recommended that</b> (also suggest, insist, demand) the verb is the base form <b>return</b>, whatever the subject or tense. ✗ <b>returns</b> — present -s is an ordinary indicative, not used after a recommendation; ✗ <b>returned</b> — past tense does not follow <i>recommended that</i>; the base form stays even after a past reporting verb; ✗ <b>will return</b> — a future modal is not used in a <i>that</i>-clause of recommendation."},{"id":"gv-ch-28-7","level":"ch","focus":"word-choice","q":"The Court of Appeal ______ the conviction after DNA evidence showed the defendant had been elsewhere that night.","options":["abolished","suspended","quashed","terminated"],"correct":2,"answer":"quashed","vi":"Toà phúc thẩm đã huỷ bản án sau khi bằng chứng ADN cho thấy bị cáo ở nơi khác vào đêm hôm đó.","explanation":"Word choice: a court declares a <b>conviction</b> invalid — <b>quash</b> = cancel a legal decision. ✗ <b>abolished</b> — ends a law, system or institution, not a single verdict; ✗ <b>suspended</b> — puts a sentence or rule on hold temporarily; the DNA evidence cancels it outright; ✗ <b>terminated</b> — ends a contract or employment."},{"id":"gv-ch-28-8","level":"ch","focus":"double-blank","q":"The ombudsman insisted that the council ______ its reasons in full, ______ residents assume the decision had been arbitrary.","options":["spill out / lest","spell out / unless","spill over / so that","spell out / lest"],"correct":3,"answer":"spell out / lest","vi":"Thanh tra viên yêu cầu hội đồng phải giải thích rõ ràng đầy đủ lý do, kẻo người dân cho rằng quyết định đó là tuỳ tiện.","explanation":"Double blank: <b>spell out</b> = explain clearly and in detail (<b>its reasons in full</b>); <b>lest</b> = for fear that, followed by a base-form verb (<i>residents assume</i>). ✗ <b>spill out / lest</b> — <i>spill out</i> means pour or flow out, not explain; ✗ <b>spell out / unless</b> — <i>unless</i> (= if not) reverses the logic: the reasons are given so residents will NOT assume; ✗ <b>spill over / so that</b> — <i>spill over</i> means spread beyond a limit, wrong meaning."},{"id":"gv-ch-28-9","level":"ch","focus":"idiom","q":"With no way of knowing how many people would turn up to the housing consultation, the planning officers decided to ______.","options":["play for time","play it by ear","play the field","play with fire"],"correct":1,"answer":"play it by ear","vi":"Không thể biết sẽ có bao nhiêu người đến buổi tham vấn về nhà ở, các cán bộ quy hoạch quyết định tuỳ cơ ứng biến.","explanation":"Idiom: <b>no way of knowing how many people would turn up</b> means they cannot plan — <b>play it by ear</b> = decide as things happen. ✗ <b>play for time</b> — delay deliberately to gain an advantage; ✗ <b>play the field</b> — date many people, not commit to one; ✗ <b>play with fire</b> — take a dangerous risk."},{"id":"gv-ch-28-10","level":"ch","focus":"modal","q":"The defendant ______ been at the scene; his phone records place him fifty miles away at the time.","options":["can't have","mustn't have","needn't have","shouldn't have"],"correct":0,"answer":"can't have","vi":"Bị cáo không thể nào có mặt ở hiện trường được; dữ liệu điện thoại cho thấy anh ta ở cách đó năm mươi dặm vào thời điểm đó.","explanation":"Modal deduction: <b>phone records place him fifty miles away</b> is proof, so <b>can't have + past participle</b> = it is impossible that he was there. ✗ <b>mustn't have</b> — <i>must have</i> deduces that something DID happen; its negative is <i>can't have</i>, not <i>mustn't have</i>; ✗ <b>needn't have</b> — it was unnecessary (but he did it), wrong meaning; ✗ <b>shouldn't have</b> — criticism of something he did, not a deduction."},{"id":"gv-ch-28-11","level":"ch","focus":"collocation","q":"The judge ______ a heavy fine on the developer for ignoring the safety order.","options":["inflicted","charged","imposed","delivered"],"correct":2,"answer":"imposed","vi":"Thẩm phán đã áp mức phạt nặng lên chủ đầu tư vì phớt lờ lệnh an toàn.","explanation":"Collocation: a judge <b>imposes a fine/penalty/sentence on</b> someone — clue: <b>a heavy fine on</b>. ✗ <b>inflicted</b> — you inflict pain, damage or a defeat, and it is not the legal verb for a fine; ✗ <b>charged</b> — you charge a fee or a price, or charge someone with a crime; ✗ <b>delivered</b> — you deliver a verdict or a speech, not a fine."},{"id":"gv-ch-28-12","level":"ch","focus":"word-choice","q":"The housing charity was forced to ______ its night-shelter programme when the council grant ran out.","options":["disband","dissolve","dispel","discontinue"],"correct":3,"answer":"discontinue","vi":"Tổ chức từ thiện về nhà ở buộc phải ngừng chương trình nhà tạm trú ban đêm khi khoản tài trợ của hội đồng cạn kiệt.","explanation":"Word choice: a <b>programme</b> or service that stops is <b>discontinued</b>. ✗ <b>disband</b> — break up a group of people (a band, a committee); ✗ <b>dissolve</b> — formally end a parliament, marriage or company; ✗ <b>dispel</b> — drive away doubts, fears or myths."},{"id":"gv-ch-28-13","level":"ch","focus":"linking","q":"______ loudly residents object, the developer has the legal right to proceed once planning permission is granted.","options":["However","Whatever","Although","Despite"],"correct":0,"answer":"However","vi":"Dù người dân phản đối lớn tiếng đến đâu, chủ đầu tư vẫn có quyền hợp pháp tiến hành một khi đã được cấp phép quy hoạch.","explanation":"Concession: <b>However + adverb</b> (<b>However loudly</b> = no matter how loudly) heads a clause with its own subject and verb (<i>residents object</i>). ✗ <b>Whatever</b> — must be followed by a noun (<i>Whatever objections…</i>), not the adverb <i>loudly</i>; ✗ <b>Although</b> — takes a full clause directly (<i>Although residents object…</i>), it cannot be followed by <i>loudly</i>; ✗ <b>Despite</b> — a preposition, needs a noun phrase or -ing, never a clause."},{"id":"gv-ch-28-14","level":"ch","focus":"idiom","q":"Faced with spiralling costs and a hostile audit, the ministry finally decided to ______ the new stadium.","options":["pull the wool over","pull the plug on","pull the strings behind","pull rank on"],"correct":1,"answer":"pull the plug on","vi":"Đối mặt với chi phí leo thang và một cuộc kiểm toán bất lợi, bộ cuối cùng quyết định ngừng hẳn dự án sân vận động mới.","explanation":"Idiom: <b>spiralling costs and a hostile audit</b> lead the ministry to stop funding the project — <b>pull the plug on</b> = end something by withdrawing support. ✗ <b>pull the wool over</b> — deceive someone (…<i>someone's eyes</i>), wrong meaning and incomplete; ✗ <b>pull the strings behind</b> — secretly control something, not stop it; ✗ <b>pull rank on</b> — use your seniority over a person, not a stadium."},{"id":"gv-ch-28-15","level":"ch","focus":"gerund-infinitive","q":"After years of rising rents, many young graduates have been reduced to ______ in converted garages on the edge of town.","options":["live","be living","living","have lived"],"correct":2,"answer":"living","vi":"Sau nhiều năm giá thuê tăng, nhiều cử nhân trẻ đã rơi vào cảnh phải sống trong những gara cải tạo ở rìa thành phố.","explanation":"Gerund after a preposition: in <b>be reduced to</b> (= be forced into a worse state) the <b>to</b> is a preposition, so the verb takes -ing: <b>reduced to living</b>. ✗ <b>live</b> — a bare infinitive; <i>to</i> here is not the infinitive marker; ✗ <b>be living</b> — same error, an infinitive form after prepositional <i>to</i>; ✗ <b>have lived</b> — a perfect infinitive, also impossible after a preposition."},{"id":"gv-ch-28-16","level":"ch","focus":"word-choice","q":"Police believe the riots were ______ by a rumour that an officer had shot an unarmed teenager.","options":["instigated","inaugurated","instituted","installed"],"correct":0,"answer":"instigated","vi":"Cảnh sát tin rằng cuộc bạo loạn đã bị kích động bởi tin đồn rằng một sĩ quan đã bắn một thiếu niên không vũ trang.","explanation":"Word choice: riots are <b>instigated</b> (= provoked, stirred up) by a rumour. ✗ <b>inaugurated</b> — formally open a building or start a president's term; ✗ <b>instituted</b> — set up a system, policy or procedure; ✗ <b>installed</b> — put equipment in place or put a person into a post."},{"id":"gv-ch-28-17","level":"ch","focus":"participle","q":"______ orbit, the delta’s patchwork of shrimp farms looks like a sheet of shattered glass.","options":["Seeing from","To see from","Seen from","Having seen from"],"correct":2,"answer":"Seen from","vi":"Nhìn từ quỹ đạo, mạng lưới đầm nuôi tôm chằng chịt của vùng châu thổ trông như một tấm kính vỡ.","explanation":"Reduced clause: the subject <b>the delta’s patchwork of shrimp farms</b> is what is seen, not what sees, so the passive participle is needed: <b>Seen from orbit</b> (= when it is seen from orbit). ✗ <b>Seeing from</b> — active participle would make the shrimp farms the viewer; ✗ <b>To see from</b> — an infinitive states a purpose (in order to see), not a viewpoint; ✗ <b>Having seen from</b> — active and perfect, again makes the farms the viewer."},{"id":"gv-ch-28-18","level":"ch","focus":"double-blank","q":"The minister's resignation came ______ the ______, catching even his closest aides unawares.","options":["off / cuff","out of / blue","under / radar","out of / ordinary"],"correct":1,"answer":"out of / blue","vi":"Việc bộ trưởng từ chức diễn ra hoàn toàn bất ngờ, khiến ngay cả các trợ lý thân cận nhất của ông cũng trở tay không kịp.","explanation":"Double blank: <b>catching even his closest aides unawares</b> means the resignation was unexpected — <b>came out of the blue</b> = happened without warning. ✗ <b>off / cuff</b> — <i>off the cuff</i> = without preparation (a remark, a speech), not a sudden event; ✗ <b>under / radar</b> — <i>under the radar</i> = unnoticed, but the resignation was noticed, just unexpected; ✗ <b>out of / ordinary</b> — <i>out of the ordinary</i> = unusual, an adjective phrase that does not go with <i>came</i>."},{"id":"gv-ch-28-19","level":"ch","focus":"subjunctive","q":"It is high time the government ______ something about the chronic shortage of social housing.","options":["does","do","did","will do"],"correct":2,"answer":"did","vi":"Đã đến lúc chính phủ phải làm gì đó về tình trạng thiếu nhà ở xã hội kinh niên.","explanation":"Past subjunctive: <b>It is high time + past form</b> means the action is overdue but refers to now: <b>the government did</b>. ✗ <b>does</b> — present tense is not used after <i>it's (high) time</i>; ✗ <b>do</b> — the base subjunctive belongs after <i>suggest/insist that</i>, not after <i>it's time</i>; ✗ <b>will do</b> — a future form is not used in this pattern."},{"id":"gv-ch-28-20","level":"ch","focus":"phrasal-verb","q":"The new chief constable has vowed to ______ bribery in the traffic division once and for all.","options":["stamp out","rule out","wear out","phase out"],"correct":0,"answer":"stamp out","vi":"Tân cảnh sát trưởng đã thề sẽ dẹp tận gốc nạn hối lộ trong đội cảnh sát giao thông một lần và mãi mãi.","explanation":"Phrasal verb: <b>bribery … once and for all</b> means getting rid of it completely — <b>stamp out</b> = eliminate something bad. ✗ <b>rule out</b> — exclude a possibility or option; ✗ <b>wear out</b> — make something exhausted or worn by use; ✗ <b>phase out</b> — withdraw gradually in stages, which clashes with <i>once and for all</i>."},{"id":"gv-ch-28-21","level":"ch","focus":"article-quantifier","q":"______ tenants had even heard of the compensation scheme, so turnout at the meeting was poor.","options":["A few","Little","A little","Few"],"correct":3,"answer":"Few","vi":"Rất ít người thuê nhà từng nghe nói đến chương trình bồi thường, nên số người đến dự họp rất thưa thớt.","explanation":"Quantifier: <b>tenants</b> is a plural countable noun and <b>turnout … was poor</b> shows a negative sense, so <b>Few</b> (= hardly any). ✗ <b>A few</b> — positive (= some, enough), which would not explain a poor turnout; ✗ <b>Little</b> — used only with uncountable nouns (<i>little money</i>); ✗ <b>A little</b> — uncountable and positive, doubly wrong."},{"id":"gv-ch-28-22","level":"ch","focus":"idiom","q":"Economists warned the city not to ______ by tying its entire budget to tourism revenue.","options":["put the cart before the horse","walk on eggshells","put all its eggs in one basket","count its chickens before they hatch"],"correct":2,"answer":"put all its eggs in one basket","vi":"Các nhà kinh tế cảnh báo thành phố không nên dồn hết trứng vào một giỏ bằng cách gắn toàn bộ ngân sách vào nguồn thu từ du lịch.","explanation":"Idiom: <b>tying its entire budget to tourism revenue</b> = relying on one source — <b>put all its eggs in one basket</b> = depend entirely on one thing. ✗ <b>put the cart before the horse</b> — do things in the wrong order; ✗ <b>walk on eggshells</b> — act very carefully to avoid upsetting someone; ✗ <b>count its chickens before they hatch</b> — assume success before it is certain."},{"id":"gv-ch-28-23","level":"ch","focus":"inversion","q":"Only after the third burglary in a single month ______ to install cameras on the estate.","options":["the council agreed","did the council agree","the council did agree","the council had agreed"],"correct":1,"answer":"did the council agree","vi":"Chỉ sau vụ trộm thứ ba trong vòng một tháng, hội đồng mới đồng ý lắp camera trong khu chung cư.","explanation":"Inversion: a fronted <b>Only after + phrase</b> forces the auxiliary before the subject in the main clause: <b>did the council agree</b>. ✗ <b>the council agreed</b> — normal order, no inversion; ✗ <b>the council did agree</b> — the auxiliary <i>did</i> must come BEFORE <i>the council</i>, not after; ✗ <b>the council had agreed</b> — no inversion, and the past perfect needs an earlier event to precede, which the sentence does not give."},{"id":"gv-ch-28-24","level":"ch","focus":"word-choice","q":"The licensing board ______ the nightclub's licence after a third stabbing on its premises in a year.","options":["revoked","refuted","retrieved","repelled"],"correct":0,"answer":"revoked","vi":"Ban cấp phép đã thu hồi giấy phép của hộp đêm sau vụ đâm chém thứ ba trong khuôn viên trong vòng một năm.","explanation":"Word choice: a <b>licence</b> or permit is officially withdrawn — <b>revoke</b> = cancel an official permission. ✗ <b>refuted</b> — prove a claim or argument false; ✗ <b>retrieved</b> — get something back that was lost or left somewhere; ✗ <b>repelled</b> — drive away an attack or an enemy."},{"id":"gv-ch-28-25","level":"ch","focus":"collocation","q":"Prosecutors ______ doubt on the alibi after CCTV placed the defendant near the scene an hour before the robbery.","options":["placed","laid","set","cast"],"correct":3,"answer":"cast","vi":"Các công tố viên đã gieo nghi ngờ lên bằng chứng ngoại phạm sau khi camera an ninh cho thấy bị cáo ở gần hiện trường một giờ trước vụ cướp.","explanation":"Collocation: <b>cast doubt on</b> something = make people question it — clue: <b>doubt on the alibi</b>. ✗ <b>placed</b> — you place trust/emphasis on, not doubt; ✗ <b>laid</b> — you lay blame on someone, not doubt; ✗ <b>set</b> — you set a date or a record; it does not combine with <i>doubt</i>."},{"id":"gv-ch-29-1","level":"ch","focus":"word-choice","q":"Years of broken promises have gradually ______ public confidence in the government's climate pledges.","options":["collapsed","eroded","dissolved","decayed"],"correct":1,"answer":"eroded","vi":"Nhiều năm thất hứa đã dần dần bào mòn niềm tin của công chúng vào những cam kết khí hậu của chính phủ.","explanation":"Word choice: <b>gradually</b> + an object (<b>public confidence</b>) needs a transitive verb meaning wear away slowly, so <b>eroded</b> fits (erode confidence/trust/support). ✗ <b>collapsed</b> — intransitive, fall down suddenly; cannot take confidence as its object; ✗ <b>dissolved</b> — melt into liquid or end a partnership/parliament, not a feeling; ✗ <b>decayed</b> — intransitive, rot or decline; takes no object."},{"id":"gv-ch-29-2","level":"ch","focus":"tense","q":"By the end of this decade, the logistics firm ______ its entire delivery fleet with electric vehicles.","options":["will replace","has replaced","will have replaced","will be replacing"],"correct":2,"answer":"will have replaced","vi":"Đến cuối thập kỷ này, công ty logistics sẽ thay thế xong toàn bộ đội xe giao hàng bằng xe điện.","explanation":"Tense: <b>By the end of this decade</b> is a future deadline, and the action will be finished before it, so the future perfect <b>will have replaced</b> is needed. ✗ <b>will replace</b> — simple future only predicts the action; it does not show completion before the deadline; ✗ <b>has replaced</b> — present perfect links past to now, not to a future point; ✗ <b>will be replacing</b> — future continuous shows the work still in progress then."},{"id":"gv-ch-29-3","level":"ch","focus":"idiom","q":"I hate to ______, but the grant you have been promised is far from guaranteed.","options":["rain on your parade","throw in the towel","bite the bullet","jump the gun"],"correct":0,"answer":"rain on your parade","vi":"Tôi không muốn làm bạn mất hứng, nhưng khoản tài trợ mà bạn được hứa hẹn còn lâu mới chắc chắn.","explanation":"Idiom: the speaker apologises (<b>I hate to</b>) before giving disappointing news that spoils a hope, so <b>rain on your parade</b> = spoil someone's excitement. ✗ <b>throw in the towel</b> — give up a fight; ✗ <b>bite the bullet</b> — face something painful bravely; ✗ <b>jump the gun</b> — act before the proper time. None describes bringing bad news."},{"id":"gv-ch-29-4","level":"ch","focus":"collocation","q":"Rising sea levels ______ a grave threat to low-lying island nations such as the Maldives.","options":["put","place","set","pose"],"correct":3,"answer":"pose","vi":"Mực nước biển dâng gây ra mối đe dọa nghiêm trọng cho các quốc đảo thấp như Maldives.","explanation":"Collocation: the verb that goes with <b>a grave threat</b> (also a risk, a danger, a problem) is <b>pose</b>, meaning present or cause. ✗ <b>put</b> — put someone at risk / under threat, but never put a threat; ✗ <b>place</b> — place someone in danger, again not with threat as object; ✗ <b>set</b> — set a record, a target, a trap, not a threat."},{"id":"gv-ch-29-5","level":"ch","focus":"phrasal-verb","q":"The documentary ______ fresh anger over the dumping of toxic waste near the village.","options":["brought up","took up","stirred up","set up"],"correct":2,"answer":"stirred up","vi":"Bộ phim tài liệu đã khơi dậy làn sóng phẫn nộ mới về việc đổ chất thải độc hại gần ngôi làng.","explanation":"Phrasal verb: the object <b>fresh anger over</b> a scandal needs a verb meaning provoke strong feelings, so <b>stirred up</b> (stir up anger/trouble/controversy). ✗ <b>brought up</b> — mention a topic or raise a child; ✗ <b>took up</b> — start a hobby, or occupy time/space; ✗ <b>set up</b> — establish a company or arrange equipment. Only stir up collocates with anger."},{"id":"gv-ch-29-6","level":"ch","focus":"modal","q":"The samples ______ contaminated in the laboratory; they were sealed the moment they were collected.","options":["mustn't have been","can't have been","needn't have been","shouldn't have been"],"correct":1,"answer":"can't have been","vi":"Các mẫu không thể nào bị nhiễm bẩn trong phòng thí nghiệm được; chúng đã được niêm phong ngay lúc thu thập.","explanation":"Modal deduction: the second clause (<b>sealed the moment they were collected</b>) proves contamination was impossible, and a confident past deduction of impossibility is <b>can't have been</b>. ✗ <b>mustn't have been</b> — must is used for positive deduction only; its negative is not used for deduction; ✗ <b>needn't have been</b> — it happened but was unnecessary; ✗ <b>shouldn't have been</b> — it happened and was wrong."},{"id":"gv-ch-29-7","level":"ch","focus":"word-choice","q":"The appeal court ______ the original verdict, rejecting all three grounds of appeal.","options":["sustained","retained","preserved","upheld"],"correct":3,"answer":"upheld","vi":"Tòa phúc thẩm giữ nguyên phán quyết ban đầu, bác bỏ cả ba căn cứ kháng cáo.","explanation":"Word choice: an <b>appeal court</b> that <b>rejects the grounds of appeal</b> confirms the lower court's decision, and the legal verb for that is <b>upheld</b> (uphold a verdict/ruling/conviction). ✗ <b>sustained</b> — in court, a judge sustains an objection, not a verdict; ✗ <b>retained</b> — keep possession of something; ✗ <b>preserved</b> — keep from damage or decay. Neither is a legal confirmation."},{"id":"gv-ch-29-8","level":"ch","focus":"inversion","q":"______ did the new tram line cut journey times across the city, but it also reduced traffic on the ring road by a fifth.","options":["Not only","Hardly","Only after","Not until"],"correct":0,"answer":"Not only","vi":"Tuyến tàu điện mới không những rút ngắn thời gian đi lại trong thành phố mà còn giảm một phần năm lượng xe cộ trên đường vành đai.","explanation":"Inversion: the second half <b>but it also reduced</b> completes the pair <b>Not only … but also</b>, and the fronted negative triggers <b>did the tram line cut</b>. ✗ <b>Hardly</b> — pairs with when (Hardly had … when); ✗ <b>Only after</b> — needs a time phrase or clause before the inversion (Only after the line opened did …); ✗ <b>Not until</b> — likewise needs a time expression first."},{"id":"gv-ch-29-9","level":"ch","focus":"idiom","q":"Junior staff are often reluctant to ______ by questioning decisions made higher up.","options":["spill the beans","break the ice","rock the boat","hold the fort"],"correct":2,"answer":"rock the boat","vi":"Nhân viên cấp dưới thường ngại gây xáo trộn bằng cách chất vấn những quyết định từ cấp trên.","explanation":"Idiom: <b>questioning decisions made higher up</b> disturbs a settled situation, so <b>rock the boat</b> = upset the status quo. ✗ <b>spill the beans</b> — reveal a secret; ✗ <b>break the ice</b> — ease the awkwardness at a first meeting; ✗ <b>hold the fort</b> — take charge while others are away. Only rock the boat means causing trouble by challenging things."},{"id":"gv-ch-29-10","level":"ch","focus":"double-blank","q":"The missing funds uncovered so far are only the ______ of the ______; investigators believe far more was diverted.","options":["tip / iceberg","top / mountain","edge / cliff","peak / glacier"],"correct":0,"answer":"tip / iceberg","vi":"Số tiền thất thoát được phát hiện cho đến nay chỉ là phần nổi của tảng băng chìm; các điều tra viên tin rằng còn nhiều hơn thế đã bị chuyển đi.","explanation":"Idiom: <b>only the … of the …; far more was diverted</b> means a small visible part of a much larger hidden problem, which is <b>the tip of the iceberg</b>. ✗ <b>top / mountain</b> — literal words, not an idiom for a hidden problem; ✗ <b>edge / cliff</b> — on the edge of a cliff means near disaster, not a small part; ✗ <b>peak / glacier</b> — not an English expression at all."},{"id":"gv-ch-29-11","level":"ch","focus":"relative","q":"The researchers, most of ______ had spent years in the Arctic, warned that the ice was thinning faster than predicted.","options":["which","whom","them","whose"],"correct":1,"answer":"whom","vi":"Các nhà nghiên cứu, mà phần lớn trong số họ đã dành nhiều năm ở Bắc Cực, cảnh báo rằng băng đang mỏng đi nhanh hơn dự đoán.","explanation":"Relative pronoun: after a quantifier + <b>of</b> in a non-defining clause about people (<b>the researchers, most of ___</b>), the object form <b>whom</b> is required. ✗ <b>which</b> — for things, not people; ✗ <b>them</b> — a personal pronoun cannot join two clauses without and (most of them had would be a run-on); ✗ <b>whose</b> — possessive, must be followed by a noun."},{"id":"gv-ch-29-12","level":"ch","focus":"word-choice","q":"The report ______ that roughly a third of the region's wells are contaminated with pesticides.","options":["assesses","evaluates","appraises","estimates"],"correct":3,"answer":"estimates","vi":"Báo cáo ước tính rằng khoảng một phần ba số giếng trong khu vực bị nhiễm thuốc trừ sâu.","explanation":"Word choice: <b>roughly a third</b> is an approximate figure, and the verb that gives one, followed by a <b>that</b>-clause, is <b>estimates</b>. ✗ <b>assesses</b> — judge the level or importance of something; takes a noun object, not that + figure; ✗ <b>evaluates</b> — judge quality or value; also object only; ✗ <b>appraises</b> — formally value property or performance; same problem."},{"id":"gv-ch-29-13","level":"ch","focus":"collocation","q":"The airline ______ a loss of forty million dollars in the final quarter of the year.","options":["posted","noted","marked","scored"],"correct":0,"answer":"posted","vi":"Hãng hàng không ghi nhận khoản lỗ bốn mươi triệu đô la trong quý cuối năm.","explanation":"Collocation: in financial reporting a company <b>posts</b> a profit or <b>a loss</b>, meaning it officially announces the result. ✗ <b>noted</b> — observe or write down; a company notes a trend, not its own loss; ✗ <b>marked</b> — mark an anniversary or a change, not a financial result; ✗ <b>scored</b> — score goals, points or a success, never a loss."},{"id":"gv-ch-29-14","level":"ch","focus":"subjunctive","q":"The auditor recommended that the foundation ______ an independent trustee before the next funding round.","options":["appoints","appointed","would appoint","appoint"],"correct":3,"answer":"appoint","vi":"Kiểm toán viên khuyến nghị quỹ bổ nhiệm một ủy viên quản trị độc lập trước vòng tài trợ tiếp theo.","explanation":"Subjunctive: after <b>recommended that</b> (also suggest, insist, demand), the that-clause verb is the bare base form for any subject: <b>the foundation appoint</b>. ✗ <b>appoints</b> — ordinary present with -s; wrong after a recommendation verb; ✗ <b>appointed</b> — past tense; the appointment has not happened yet; ✗ <b>would appoint</b> — would is not used in this pattern (British English allows should appoint, never would)."},{"id":"gv-ch-29-15","level":"ch","focus":"idiom","q":"By unveiling its own electric van a day early, the rival firm ______ at the trade fair.","options":["pulled the company's leg","stole the company's thunder","twisted the company's arm","got the company's goat"],"correct":1,"answer":"stole the company's thunder","vi":"Bằng cách ra mắt chiếc xe tải điện của mình sớm một ngày, hãng đối thủ đã cướp mất sự chú ý của công ty tại hội chợ thương mại.","explanation":"Idiom: <b>unveiling its own van a day early</b> grabbed the attention the company expected at the fair, so <b>stole the company's thunder</b> = take someone's expected praise by acting first. ✗ <b>pulled the company's leg</b> — tease or joke with someone; ✗ <b>twisted the company's arm</b> — pressure someone into doing something; ✗ <b>got the company's goat</b> — annoy someone."},{"id":"gv-ch-29-16","level":"ch","focus":"linking","q":"______ generous the pension scheme may seem, few employees stay long enough to benefit from it.","options":["Whatever","No matter","However","Although"],"correct":2,"answer":"However","vi":"Dù chương trình hưu trí có vẻ hào phóng đến đâu, ít nhân viên ở lại đủ lâu để được hưởng lợi từ nó.","explanation":"Concession: the blank is followed directly by an adjective (<b>generous</b>) and then subject + verb (<b>the pension scheme may seem</b>), so <b>However</b> + adjective = no matter how. ✗ <b>Whatever</b> — must be followed by a noun (Whatever its generosity); ✗ <b>No matter</b> — needs how before an adjective (No matter how generous); ✗ <b>Although</b> — introduces a full clause, not a bare adjective."},{"id":"gv-ch-29-17","level":"ch","focus":"phrasal-verb","q":"Before accepting the overseas posting, she wanted to ______ the decision with her family.","options":["talk back","talk down","talk into","talk over"],"correct":3,"answer":"talk over","vi":"Trước khi nhận nhiệm vụ ở nước ngoài, cô ấy muốn bàn bạc kỹ quyết định đó với gia đình.","explanation":"Phrasal verb: <b>the decision with her family</b> before deciding means discuss it fully, so <b>talk over</b> (talk something over with someone). ✗ <b>talk back</b> — reply rudely to authority; takes no object; ✗ <b>talk down</b> — talk down to someone = speak condescendingly, or talk down a price; ✗ <b>talk into</b> — talk someone into doing = persuade; needs a person, not a decision, as object."},{"id":"gv-ch-29-18","level":"ch","focus":"word-choice","q":"Several studies have ______ a direct link between air pollution and premature births.","options":["founded","established","instituted","formulated"],"correct":1,"answer":"established","vi":"Nhiều nghiên cứu đã xác lập được mối liên hệ trực tiếp giữa ô nhiễm không khí và sinh non.","explanation":"Word choice: <b>studies</b> that prove <b>a direct link</b> exists are said to <b>establish</b> it (establish a link/fact/connection). ✗ <b>founded</b> — start an organisation or a city; ✗ <b>instituted</b> — introduce a system, policy or procedure; ✗ <b>formulated</b> — work out a plan, theory or formula in words. None means proving a connection by evidence."},{"id":"gv-ch-29-19","level":"ch","focus":"conditional","q":"______ for the anonymous donation, the hospice would have closed last winter.","options":["Were it not","If it were not","Had it not been","Unless it were"],"correct":2,"answer":"Had it not been","vi":"Nếu không nhờ khoản quyên góp ẩn danh, nhà chăm sóc cuối đời đã phải đóng cửa vào mùa đông năm ngoái.","explanation":"Conditional: the result <b>would have closed last winter</b> is past and unreal, so the condition must be third-conditional, inverted: <b>Had it not been for</b>. ✗ <b>Were it not</b> — second conditional; present or future unreal, clashing with last winter; ✗ <b>If it were not</b> — same present meaning; ✗ <b>Unless it were</b> — unless does not combine with for + noun in this pattern."},{"id":"gv-ch-29-20","level":"ch","focus":"participle","q":"______ how little rain has fallen this year, the region's reservoirs are in surprisingly good shape.","options":["Considered","To consider","Considering","Having considered"],"correct":2,"answer":"Considering","vi":"Xét đến việc năm nay mưa quá ít, các hồ chứa của khu vực đang ở trong tình trạng tốt đến bất ngờ.","explanation":"Participle: <b>how little rain has fallen</b> is a fact taken into account, and <b>Considering</b> (how / that / + noun) is a fixed form meaning in view of, needing no subject of its own. ✗ <b>Considered</b> — passive, would mean the reservoirs are being considered; ✗ <b>To consider</b> — an infinitive of purpose; reservoirs cannot consider; ✗ <b>Having considered</b> — needs a thinking subject, not reservoirs."},{"id":"gv-ch-29-21","level":"ch","focus":"idiom","q":"Figures released by the lobby group should be ______, since it is funded by the very industry it defends.","options":["swept under the carpet","kept under wraps","taken with a pinch of salt","put on the back burner"],"correct":2,"answer":"taken with a pinch of salt","vi":"Những số liệu do nhóm vận động hành lang công bố nên được tiếp nhận một cách dè dặt, vì nhóm này được tài trợ bởi chính ngành mà nó bênh vực.","explanation":"Idiom: figures from a group <b>funded by the very industry it defends</b> should be doubted, so <b>taken with a pinch of salt</b> = not believed entirely. ✗ <b>swept under the carpet</b> — hide a problem from view; ✗ <b>kept under wraps</b> — keep something secret; ✗ <b>put on the back burner</b> — postpone until later. Only pinch of salt is about believing a claim."},{"id":"gv-ch-29-22","level":"ch","focus":"gerund-infinitive","q":"After a decade in banking, she has finally got used ______ far less than her former colleagues.","options":["to earning","to earn","earning","for earning"],"correct":0,"answer":"to earning","vi":"Sau một thập kỷ làm trong ngành ngân hàng, cuối cùng cô ấy đã quen với việc kiếm được ít hơn nhiều so với các đồng nghiệp cũ.","explanation":"Gerund after preposition: in <b>get used to</b>, the <b>to</b> is a preposition, so it takes the <b>-ing</b> form: <b>get used to earning</b>. ✗ <b>to earn</b> — bare infinitive belongs to used to + verb (past habit), a different structure with no get; ✗ <b>earning</b> — drops the required to; ✗ <b>for earning</b> — used takes to, not for."},{"id":"gv-ch-29-23","level":"ch","focus":"double-blank","q":"The foundation has agreed to ______ on the running costs of the shelter ______ the council pays for the repairs.","options":["put / unless","bring / in case","carry / whereas","take / provided"],"correct":3,"answer":"take / provided","vi":"Quỹ đã đồng ý gánh vác chi phí vận hành của nhà tạm trú với điều kiện hội đồng thành phố chi trả cho việc sửa chữa.","explanation":"Double blank: <b>agreed to ___ on the running costs</b> means accept a burden, so <b>take on</b>; the council paying is the condition, so <b>provided (that)</b>. ✗ <b>put / unless</b> — put on = wear or gain weight; unless = except if, the wrong logic; ✗ <b>bring / in case</b> — bring on = cause; in case = as a precaution; ✗ <b>carry / whereas</b> — carry on = continue; whereas = contrast, not condition."},{"id":"gv-ch-29-24","level":"ch","focus":"word-choice","q":"The retraining scheme ______ of three phases, the first of which begins next spring.","options":["consists","comprises","composes","constitutes"],"correct":0,"answer":"consists","vi":"Chương trình đào tạo lại gồm ba giai đoạn, giai đoạn đầu tiên bắt đầu vào mùa xuân tới.","explanation":"Word choice: the blank is followed by <b>of</b>, and the only verb that takes of in this meaning is <b>consists</b>: the scheme consists of three phases. ✗ <b>comprises</b> — takes a direct object with no preposition (comprises three phases); ✗ <b>composes</b> — works the other way round: three phases compose the scheme; ✗ <b>constitutes</b> — likewise the parts constitute the whole, and no of."},{"id":"gv-ch-29-25","level":"ch","focus":"collocation","q":"Small manufacturers often struggle to ______ the strict new emissions standards.","options":["reach","meet","fill","match"],"correct":1,"answer":"meet","vi":"Các nhà sản xuất nhỏ thường chật vật để đáp ứng các tiêu chuẩn khí thải nghiêm ngặt mới.","explanation":"Collocation: the verb for satisfying <b>standards</b> (also requirements, targets, deadlines) is <b>meet</b>. ✗ <b>reach</b> — reach a level, a goal or an agreement; a standard is satisfied, not arrived at; ✗ <b>fill</b> — fill a gap, a post or an order, never a standard; ✗ <b>match</b> — be equal to something; matching a standard is not the phrase for complying with it."},{"id":"gv-ch-30-1","level":"ch","focus":"inversion","q":"______ the swift response of local volunteers, last month's flood would have swept away the entire rice harvest.","options":["Were it not for","Hadn't it been for","Had it not been for","If it had not been"],"correct":2,"answer":"Had it not been for","vi":"Nếu không nhờ phản ứng nhanh chóng của các tình nguyện viên địa phương, trận lũ tháng trước đã cuốn trôi toàn bộ vụ lúa.","explanation":"A past unreal condition — the main clause has <b>would have swept</b> — inverts as <b>Had it not been for</b> + noun phrase (= If it had not been for). ✗ <b>Were it not for</b> — present/future unreal, would need <b>would sweep</b>; ✗ <b>Hadn't it been for</b> — a contracted negative cannot be inverted this way; ✗ <b>If it had not been</b> — the noun phrase <b>the swift response</b> needs <b>for</b> after <b>been</b>."},{"id":"gv-ch-30-2","level":"ch","focus":"word-choice","q":"Consumer watchdogs warned that the ______ workmanship of the imported toys — loose seams, sharp edges, paint that flaked at a touch — made them unsafe for toddlers.","options":["scanty","meagre","substandard","negligible"],"correct":2,"answer":"substandard","vi":"Các tổ chức bảo vệ người tiêu dùng cảnh báo rằng tay nghề gia công kém chất lượng của lô đồ chơi nhập khẩu — đường may lỏng, cạnh sắc, sơn bong chỉ chạm nhẹ — khiến chúng không an toàn cho trẻ nhỏ.","explanation":"The dash lists faults in quality — <b>loose seams, sharp edges, paint that flaked</b> — so the workmanship is <b>substandard</b> = below the accepted standard. ✗ <b>scanty</b> — too small in amount (scanty evidence); ✗ <b>meagre</b> — small and insufficient in quantity (a meagre salary); ✗ <b>negligible</b> — so small it can be ignored (a negligible risk); none of the three describes bad quality."},{"id":"gv-ch-30-3","level":"ch","focus":"idiom","q":"Regulators were accused of ______ the misleading price tags that supermarkets displayed all season, even after shoppers complained.","options":["keeping an eye on","turning a blind eye to","seeing eye to eye with","catching the eye of"],"correct":1,"answer":"turning a blind eye to","vi":"Cơ quan quản lý bị cáo buộc làm ngơ trước những nhãn giá gây hiểu lầm mà các siêu thị trưng bày suốt cả mùa, ngay cả sau khi người mua đã khiếu nại.","explanation":"Regulators ignored the misleading tags <b>even after shoppers complained</b>: deliberately ignoring wrongdoing = <b>turn a blind eye to</b>. ✗ <b>keeping an eye on</b> — watching carefully, the opposite of neglect; ✗ <b>seeing eye to eye with</b> — agreeing with a person, not with price tags; ✗ <b>catching the eye of</b> — attracting someone's attention, which tags might do to shoppers, not regulators to tags."},{"id":"gv-ch-30-4","level":"ch","focus":"collocation","q":"The supermarket chain ______ a record profit last year despite the squeeze on household budgets.","options":["placed","put","stood","posted"],"correct":3,"answer":"posted","vi":"Chuỗi siêu thị đã công bố mức lợi nhuận kỷ lục năm ngoái bất chấp ngân sách các hộ gia đình bị thắt chặt.","explanation":"In financial English a company <b>posts</b> a profit or loss = officially reports its results, the fixed verb with <b>a record profit</b>. ✗ <b>placed</b> — you place an order or a bet, not a profit; ✗ <b>put</b> — needs a place after it (put money into shares), it cannot take <b>a profit</b> alone; ✗ <b>stood</b> — intransitive with figures (profits stood at $2m), so it cannot have <b>a profit</b> as object."},{"id":"gv-ch-30-5","level":"ch","focus":"phrasal-verb","q":"The minister's speech only briefly ______ the shortage of maths teachers before moving on to school buildings.","options":["touched on","touched up","touched down","touched off"],"correct":0,"answer":"touched on","vi":"Bài phát biểu của bộ trưởng chỉ đề cập lướt qua tình trạng thiếu giáo viên toán rồi chuyển sang chuyện cơ sở vật chất trường học.","explanation":"<b>Only briefly … before moving on</b> means the speech mentioned the shortage in passing = <b>touched on</b> (mention a subject briefly). ✗ <b>touched up</b> — improve small details of a photo or paintwork; ✗ <b>touched down</b> — land, of a plane; ✗ <b>touched off</b> — trigger a reaction or crisis, not what a brief mention in a speech does."},{"id":"gv-ch-30-6","level":"ch","focus":"modal","q":"The retailer ______ its Christmas stock months in advance — the shelves were already full the day the holiday season opened.","options":["should have ordered","needn't have ordered","must have ordered","can't have ordered"],"correct":2,"answer":"must have ordered","vi":"Nhà bán lẻ hẳn đã đặt hàng Giáng sinh từ nhiều tháng trước — các kệ hàng đã đầy ắp ngay ngày mùa lễ hội bắt đầu.","explanation":"The full shelves are evidence for a confident deduction about the past, so <b>must have ordered</b> (= I'm sure they ordered). ✗ <b>should have ordered</b> — criticises a past failure to order, but the shelves prove they did; ✗ <b>needn't have ordered</b> — they ordered but it was unnecessary, which nothing suggests; ✗ <b>can't have ordered</b> — the opposite deduction, contradicted by the full shelves."},{"id":"gv-ch-30-7","level":"ch","focus":"word-choice","q":"The auditors described the company's accounts as ______: not a single figure out of place across three years of trading.","options":["faulty","faultless","fault-finding","faulted"],"correct":1,"answer":"faultless","vi":"Các kiểm toán viên mô tả sổ sách của công ty là hoàn hảo không tì vết: không một con số nào sai lệch trong suốt ba năm kinh doanh.","explanation":"<b>Not a single figure out of place</b> after the colon means no errors at all = <b>faultless</b> (perfect). ✗ <b>faulty</b> — containing faults, the opposite meaning; ✗ <b>fault-finding</b> — describes a person who looks for things to criticise, not accounts; ✗ <b>faulted</b> — past participle 'criticised' (cannot be faulted), not an adjective describing quality."},{"id":"gv-ch-30-8","level":"ch","focus":"double-blank","q":"Engineers worked ______ the ______ to patch the payment system before the Black Friday rush began.","options":["against / time","before / clock","behind / time","against / clock"],"correct":3,"answer":"against / clock","vi":"Các kỹ sư chạy đua với thời gian để vá hệ thống thanh toán trước khi đợt mua sắm Black Friday bắt đầu.","explanation":"<b>Work against the clock</b> = work as fast as possible to beat a deadline, here <b>before the Black Friday rush began</b>. ✗ <b>against / time</b> — English has <b>a race against time</b> (no article), but <b>against the time</b> is not an idiom; ✗ <b>before / clock</b> — no such expression; ✗ <b>behind / time</b> — <b>behind the times</b> means old-fashioned, and <b>behind the time</b> does not exist."},{"id":"gv-ch-30-9","level":"ch","focus":"idiom","q":"Thanks to its low debt, the retailer managed to ______ that drove several rivals into bankruptcy.","options":["weather the storm","take by storm","go down a storm","storm the barricades"],"correct":0,"answer":"weather the storm","vi":"Nhờ nợ thấp, nhà bán lẻ đã vượt qua được cơn bão khủng hoảng vốn đẩy nhiều đối thủ vào cảnh phá sản.","explanation":"<b>Weather the storm</b> = survive a difficult period, and <b>the storm</b> then supplies the noun that <b>that drove rivals into bankruptcy</b> describes; <b>low debt</b> explains the survival. ✗ <b>take by storm</b> — conquer or impress suddenly, and needs an object after <b>take</b>; ✗ <b>go down a storm</b> — be received enthusiastically, of a show; ✗ <b>storm the barricades</b> — attack a defended position, not survive a crisis."},{"id":"gv-ch-30-10","level":"ch","focus":"linking","q":"______ the sharp rise in tuition fees, applications to the most selective universities have continued to climb.","options":["Nevertheless","Nonetheless","Notwithstanding","Albeit"],"correct":2,"answer":"Notwithstanding","vi":"Bất chấp học phí tăng mạnh, số đơn xin vào các trường đại học chọn lọc nhất vẫn tiếp tục tăng.","explanation":"The blank is followed by a noun phrase, <b>the sharp rise in tuition fees</b>, so it needs a preposition: <b>Notwithstanding</b> = despite. ✗ <b>Nevertheless</b> — an adverb contrasting two clauses, not a preposition before a noun; ✗ <b>Nonetheless</b> — the same adverb use, so it fails for the same reason; ✗ <b>Albeit</b> — 'although', used before an adjective or reduced clause (albeit slowly), not a full noun phrase."},{"id":"gv-ch-30-11","level":"ch","focus":"word-choice","q":"Critics dismissed the new curriculum as ______, arguing that it recycled old material and offered nothing that would stretch the brightest pupils.","options":["lukewarm","luminous","lucrative","lacklustre"],"correct":3,"answer":"lacklustre","vi":"Giới phê bình gạt bỏ chương trình học mới là nhạt nhẽo thiếu sức sống, cho rằng nó xào lại nội dung cũ và chẳng có gì để thử thách những học sinh giỏi nhất.","explanation":"<b>Recycled old material … nothing that would stretch</b> describes something dull and uninspired = <b>lacklustre</b>. ✗ <b>lukewarm</b> — unenthusiastic, used of a response or reception, not of the curriculum itself; ✗ <b>luminous</b> — giving off light, or brilliantly clear; ✗ <b>lucrative</b> — producing a lot of money, irrelevant to a syllabus."},{"id":"gv-ch-30-12","level":"ch","focus":"subjunctive","q":"The audit committee recommended that the chief executive ______ from the bonus scheme until the accounts had been restated.","options":["was removed","be removed","is removed","would be removed"],"correct":1,"answer":"be removed","vi":"Ủy ban kiểm toán đề nghị rằng tổng giám đốc bị loại khỏi chương trình thưởng cho đến khi báo cáo tài chính được lập lại.","explanation":"<b>Recommended that</b> triggers the subjunctive: the base form (or should + base) whatever the tense of the reporting verb, so <b>be removed</b>. ✗ <b>was removed</b> — past indicative, reports a fact rather than a proposal; ✗ <b>is removed</b> — present indicative, same problem, and clashes with past <b>recommended</b>; ✗ <b>would be removed</b> — conditional, not used after verbs of recommendation."},{"id":"gv-ch-30-13","level":"ch","focus":"collocation","q":"Online retailers face ______ competition from overseas platforms that undercut them on price.","options":["stiff","rigid","firm","solid"],"correct":0,"answer":"stiff","vi":"Các nhà bán lẻ trực tuyến đối mặt với sự cạnh tranh gay gắt từ những nền tảng nước ngoài bán phá giá họ.","explanation":"<b>Stiff competition</b> is the fixed collocation for strong, intense competition, which <b>undercut them on price</b> shows. ✗ <b>rigid</b> — inflexible rules or structures, not competition; ✗ <b>firm</b> — a firm grip, decision or offer; ✗ <b>solid</b> — a solid performance or foundation; all three mean 'not easily bent', not 'intense'."},{"id":"gv-ch-30-14","level":"ch","focus":"idiom","q":"Economists dismissed the furious row over the 2p rise in the price of bread as ______ — a great deal of noise about something that hardly mattered.","options":["a drop in the ocean","a shot in the dark","a storm in a teacup","a blessing in disguise"],"correct":2,"answer":"a storm in a teacup","vi":"Các nhà kinh tế gạt bỏ cuộc tranh cãi dữ dội về việc giá bánh mì tăng 2 xu, coi đó chỉ là chuyện bé xé ra to — ồn ào rất nhiều về một điều chẳng đáng kể.","explanation":"The gloss after the dash — <b>a great deal of noise about something that hardly mattered</b> — defines <b>a storm in a teacup</b>: a big fuss about a trivial matter. ✗ <b>a drop in the ocean</b> — a tiny amount compared with what is needed; ✗ <b>a shot in the dark</b> — a wild guess; ✗ <b>a blessing in disguise</b> — something that seems bad but turns out well."},{"id":"gv-ch-30-15","level":"ch","focus":"participle","q":"______ for even a few minutes, a charging e-scooter battery can overheat and set an entire flat alight, fire officers warned.","options":["Leaving unattended","Having left unattended","To leave unattended","Left unattended"],"correct":3,"answer":"Left unattended","vi":"Nếu bị bỏ mặc không ai trông chừng dù chỉ vài phút, pin xe điện đang sạc có thể quá nóng và thiêu rụi cả căn hộ, lực lượng cứu hỏa cảnh báo.","explanation":"The main-clause subject, <b>a charging e-scooter battery</b>, is what gets left, so the reduced conditional needs the passive past participle <b>Left unattended</b> (= if it is left unattended). ✗ <b>Leaving unattended</b> — active, makes the battery the one leaving something; ✗ <b>Having left unattended</b> — active perfect, same wrong doer and no object; ✗ <b>To leave unattended</b> — an infinitive of purpose, which makes no sense here."},{"id":"gv-ch-30-16","level":"ch","focus":"phrasal-verb","q":"It took investigators three months to ______ the owner of the website that had been selling counterfeit trainers.","options":["turn down","tone down","tie down","track down"],"correct":3,"answer":"track down","vi":"Các điều tra viên mất ba tháng mới lần ra được chủ nhân trang web bán giày thể thao giả.","explanation":"<b>Three months</b> of investigation to find <b>the owner</b> = <b>track down</b> (find after a long search). ✗ <b>turn down</b> — reject an offer or applicant; ✗ <b>tone down</b> — make language or colours less extreme; ✗ <b>tie down</b> — restrict someone's freedom or fix to one place; none means 'find'."},{"id":"gv-ch-30-17","level":"ch","focus":"word-choice","q":"For thirty years the firm has enjoyed an ______ reputation for customer service, which is why shoppers tolerate its higher prices.","options":["unblemished","unbalanced","unbounded","unbiased"],"correct":0,"answer":"unblemished","vi":"Suốt ba mươi năm, công ty đã có được danh tiếng không tì vết về dịch vụ khách hàng, và đó là lý do người mua chấp nhận giá cao hơn.","explanation":"A reputation <b>enjoyed for thirty years</b> that justifies higher prices is <b>unblemished</b> = without a single stain or fault (an unblemished record). ✗ <b>unbalanced</b> — mentally unstable, or one-sided (an unbalanced report); ✗ <b>unbounded</b> — without limits, used of joy or enthusiasm; ✗ <b>unbiased</b> — impartial, describes a judge or opinion, not a reputation for service."},{"id":"gv-ch-30-18","level":"ch","focus":"gerund-infinitive","q":"Many parents told the survey they would rather pay for private tutors ______ their children fall behind.","options":["than letting","than to let","than let","rather than let"],"correct":2,"answer":"than let","vi":"Nhiều phụ huynh cho biết trong khảo sát rằng họ thà trả tiền thuê gia sư còn hơn để con mình tụt lại phía sau.","explanation":"<b>Would rather + bare infinitive … than + bare infinitive</b>: the parallel is <b>pay … than let</b>. ✗ <b>than letting</b> — the <b>-ing</b> form breaks the parallel with <b>pay</b>; ✗ <b>than to let</b> — <b>would rather</b> never takes a <b>to</b>-infinitive; ✗ <b>rather than let</b> — repeats <b>rather</b>, which <b>would rather</b> has already supplied."},{"id":"gv-ch-30-19","level":"ch","focus":"comparison","q":"Households in the capital spend nearly ______ on private tuition as those in rural provinces.","options":["twice more","twice as much","as twice much","twice as many"],"correct":1,"answer":"twice as much","vi":"Các hộ gia đình ở thủ đô chi cho học thêm gần gấp đôi so với các hộ ở nông thôn.","explanation":"Multiples use <b>twice as much/many … as</b>, and the second <b>as</b> (<b>as those in rural provinces</b>) confirms the pattern; money spent is uncountable, so <b>twice as much</b>. ✗ <b>twice more</b> — <b>more</b> pairs with <b>than</b>, not with <b>as</b>; ✗ <b>as twice much</b> — wrong order, the multiplier goes before <b>as</b>; ✗ <b>twice as many</b> — <b>many</b> is for countable nouns, but the amount spent is uncountable."},{"id":"gv-ch-30-20","level":"ch","focus":"idiom","q":"The delivery firm broke the sofa and then, ______, billed the customer for the return journey.","options":["to add fuel to the fire","to add another string to its bow","to add its two cents","to add insult to injury"],"correct":3,"answer":"to add insult to injury","vi":"Công ty giao hàng làm hỏng chiếc ghế sofa rồi, như xát muối vào vết thương, còn tính phí khách hàng cho chuyến chở trả lại.","explanation":"The firm broke the sofa and then charged for it — a second unfairness on top of the first = <b>to add insult to injury</b>. ✗ <b>to add fuel to the fire</b> — make an argument or anger worse, but no quarrel is described; ✗ <b>to add another string to its bow</b> — gain an extra skill; ✗ <b>to add its two cents</b> — give an unasked-for opinion."},{"id":"gv-ch-30-21","level":"ch","focus":"agreement","q":"Neither the minister nor her advisers ______ willing to say when the revised syllabus would be published.","options":["were","was","is","has been"],"correct":0,"answer":"were","vi":"Cả bộ trưởng lẫn các cố vấn của bà đều không sẵn lòng cho biết khi nào chương trình học sửa đổi sẽ được công bố.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, the plural <b>her advisers</b>, and the frame is past (<b>would be published</b>), so <b>were</b>. ✗ <b>was</b> — singular, agrees with <b>the minister</b>, the farther subject; ✗ <b>is</b> — singular and present tense in a past frame; ✗ <b>has been</b> — singular present perfect, breaks both agreement and time."},{"id":"gv-ch-30-22","level":"ch","focus":"double-blank","q":"A small loan from her brother ______ the bakery ______ until the tourists returned in June.","options":["took / over","tied / up","tided / over","turned / over"],"correct":2,"answer":"tided / over","vi":"Một khoản vay nhỏ từ anh trai đã giúp tiệm bánh cầm cự qua giai đoạn khó khăn cho đến khi khách du lịch quay lại vào tháng Sáu.","explanation":"<b>Tide somebody/something over</b> = help through a short period of difficulty, which fits a loan and <b>until the tourists returned</b>. ✗ <b>took / over</b> — take over = seize control of, a loan does not control a bakery; ✗ <b>tied / up</b> — tie up = occupy or immobilise (money tied up in property); ✗ <b>turned / over</b> — turn over = generate revenue, with the business as subject, not object."},{"id":"gv-ch-30-23","level":"ch","focus":"collocation","q":"From the survey data, researchers ______ the conclusion that free school meals improve attendance.","options":["took","drew","made","brought"],"correct":1,"answer":"drew","vi":"Từ dữ liệu khảo sát, các nhà nghiên cứu rút ra kết luận rằng bữa ăn miễn phí ở trường giúp cải thiện tỷ lệ đi học.","explanation":"The fixed collocation is <b>draw a conclusion</b> (also reach a conclusion), and <b>from the survey data</b> shows the conclusion being derived. ✗ <b>took</b> — you take a decision or a view, not a conclusion; ✗ <b>made</b> — you make a decision or an assumption; ✗ <b>brought</b> — you bring something <b>to</b> a conclusion, a different structure."},{"id":"gv-ch-30-24","level":"ch","focus":"passive","q":"The new consumer-protection rules ______ to have been drafted in a hurry, with several clauses contradicting one another.","options":["are saying","say","have said","are said"],"correct":3,"answer":"are said","vi":"Bộ quy định bảo vệ người tiêu dùng mới được cho là đã được soạn thảo vội vàng, với nhiều điều khoản mâu thuẫn nhau.","explanation":"The impersonal passive <b>be said to + perfect infinitive</b> reports what people claim about a past action: <b>are said to have been drafted</b>. ✗ <b>are saying</b> — active, rules cannot say anything; ✗ <b>say</b> — same problem, and <b>say to have been</b> is not a structure; ✗ <b>have said</b> — active perfect, but the rules are the object of the claim, not its author."},{"id":"gv-ch-30-25","level":"ch","focus":"word-choice","q":"Shoppers who bought the discounted laptops soon found them ______: they worked, but the screens were dim and the batteries barely lasted an hour.","options":["second-hand","second-rate","second-best","secondary"],"correct":1,"answer":"second-rate","vi":"Những người mua laptop giảm giá sớm nhận ra chúng thuộc hạng xoàng: máy vẫn chạy, nhưng màn hình tối và pin chỉ trụ được chưa đầy một tiếng.","explanation":"<b>They worked, but the screens were dim and the batteries barely lasted</b> = functioning but of poor quality = <b>second-rate</b>. ✗ <b>second-hand</b> — previously owned, but nothing says the laptops were used; ✗ <b>second-best</b> — the next choice after the best, not a quality judgment; ✗ <b>secondary</b> — less important or coming second in order (secondary school, secondary concern)."},{"id":"gv-ch-31-1","level":"ch","focus":"word-choice","q":"Sales of home blood-pressure monitors ______ after the ministry's warning about undiagnosed hypertension, rising fivefold in a single month.","options":["dwindled","skyrocketed","fluctuated","stagnated"],"correct":1,"answer":"skyrocketed","vi":"Doanh số máy đo huyết áp tại nhà tăng vọt sau cảnh báo của bộ y tế về tình trạng cao huyết áp chưa được chẩn đoán, tăng gấp năm lần chỉ trong một tháng.","explanation":"<b>Skyrocket</b> = rise extremely fast, the only verb that matches <b>rising fivefold in a single month</b>. ✗ <b>dwindled</b> — shrink slowly, the opposite direction; ✗ <b>fluctuated</b> — rise and fall repeatedly, not one steady jump; ✗ <b>stagnated</b> — stop growing, contradicted by a fivefold rise."},{"id":"gv-ch-31-2","level":"ch","focus":"idiom","q":"Persuading teenagers to switch off location sharing has proved ______ for privacy campaigners, who report that fewer than one in ten has done so.","options":["an uphill battle","a foregone conclusion","a blessing in disguise","a red herring"],"correct":0,"answer":"an uphill battle","vi":"Việc thuyết phục thanh thiếu niên tắt chia sẻ vị trí đã tỏ ra là một cuộc chiến gian nan đối với các nhà vận động về quyền riêng tư, những người cho biết chưa tới một phần mười các em làm vậy.","explanation":"<b>An uphill battle</b> = a struggle that is very hard to win, which <b>fewer than one in ten has done so</b> shows. ✗ <b>a foregone conclusion</b> — a result certain in advance, but the campaign is failing; ✗ <b>a blessing in disguise</b> — hidden good luck, yet nothing good has come of it; ✗ <b>a red herring</b> — a misleading clue, which a persuasion effort cannot be."},{"id":"gv-ch-31-3","level":"ch","focus":"collocation","q":"Facial recognition in shopping centres ______ a serious threat to the anonymity that city life once guaranteed.","options":["makes","does","poses","puts"],"correct":2,"answer":"poses","vi":"Công nghệ nhận diện khuôn mặt ở các trung tâm mua sắm đặt ra mối đe dọa nghiêm trọng đối với sự ẩn danh mà đời sống đô thị từng bảo đảm.","explanation":"The verb that goes with <b>threat</b> (and risk, danger, problem) is <b>pose</b>: 'pose a serious threat' = be a danger to something. ✗ <b>makes</b> — 'make a threat' = say you will harm someone, not be a danger; ✗ <b>does</b> — never collocates with 'threat'; ✗ <b>puts</b> — needs a place ('put at risk'), not 'a threat'."},{"id":"gv-ch-31-4","level":"ch","focus":"inversion","q":"Not until a journalist published the leaked database ______ that millions of accounts had been exposed.","options":["the company admitted","had the company admitted","the company did admit","did the company admit"],"correct":3,"answer":"did the company admit","vi":"Mãi đến khi một nhà báo công bố cơ sở dữ liệu bị rò rỉ, công ty mới thừa nhận rằng hàng triệu tài khoản đã bị lộ.","explanation":"A fronted <b>Not until</b> clause forces inversion in the main clause: auxiliary + subject + bare verb, <b>did the company admit</b>. ✗ <b>the company admitted</b> — no inversion after the negative opener; ✗ <b>had the company admitted</b> — inverted, but past perfect puts the admission before the publishing, the wrong order; ✗ <b>the company did admit</b> — 'did' is there but the subject must follow it."},{"id":"gv-ch-31-5","level":"ch","focus":"phrasal-verb","q":"The laboratory will gradually ______ its vaccine production over the next six months rather than halt it overnight.","options":["wind down","wind up","wear down","tone down"],"correct":0,"answer":"wind down","vi":"Phòng thí nghiệm sẽ dần thu hẹp hoạt động sản xuất vắc-xin trong sáu tháng tới thay vì dừng đột ngột.","explanation":"<b>Wind down</b> = reduce an activity gradually before ending it, contrasted with <b>rather than halt it overnight</b>. ✗ <b>wind up</b> — bring to a complete end / close a company, the sudden halt the sentence rejects; ✗ <b>wear down</b> — exhaust or erode (resistance, patience), not scale back production; ✗ <b>tone down</b> — make less forceful (language, colours), not reduce output."},{"id":"gv-ch-31-6","level":"ch","focus":"word-choice","q":"Public enthusiasm for the fitness app began to ______ once users discovered how much location data it had been collecting.","options":["accelerate","rebound","escalate","wane"],"correct":3,"answer":"wane","vi":"Sự hào hứng của công chúng với ứng dụng thể dục bắt đầu nguội dần khi người dùng phát hiện nó đã thu thập bao nhiêu dữ liệu vị trí.","explanation":"<b>Wane</b> = decrease gradually in strength, the natural result of <b>discovered how much location data it had been collecting</b>. ✗ <b>accelerate</b> — speed up or increase, the wrong direction after a scandal; ✗ <b>rebound</b> — recover after a fall, but there has been no fall yet; ✗ <b>escalate</b> — grow more intense (conflicts, prices), not lose strength."},{"id":"gv-ch-31-7","level":"ch","focus":"double-blank","q":"After a decade of lawsuits, the two chip makers agreed to ______ the ______ and pool their patents on medical sensors.","options":["bite / bullet","bury / hatchet","break / ice","call / shots"],"correct":1,"answer":"bury / hatchet","vi":"Sau một thập kỷ kiện tụng, hai hãng sản xuất chip đồng ý gác lại hiềm khích và gộp chung các bằng sáng chế về cảm biến y tế.","explanation":"<b>Bury the hatchet</b> = end a long quarrel and make peace, the meaning behind <b>a decade of lawsuits</b> ending in pooled patents. ✗ <b>bite the bullet</b> — accept something painful bravely, no peace-making; ✗ <b>break the ice</b> — ease awkwardness at a first meeting, not after ten years of conflict; ✗ <b>call the shots</b> — be the one in control, not agree with a rival."},{"id":"gv-ch-31-8","level":"ch","focus":"modal","q":"The patient ______ the tablets on an empty stomach, or she would not be feeling this nauseous now.","options":["should have taken","needn't have taken","must have taken","can't have taken"],"correct":2,"answer":"must have taken","vi":"Bệnh nhân hẳn đã uống thuốc lúc bụng đói, nếu không thì giờ cô ấy đã không buồn nôn đến thế.","explanation":"<b>Would not be feeling this nauseous now</b> is present evidence, so the speaker draws a confident deduction about the past: <b>must have taken</b>. ✗ <b>can't have taken</b> — the opposite deduction ('surely did not'), which could not cause the nausea; ✗ <b>should have taken</b> — criticism of a failure to act, but she did take them; ✗ <b>needn't have taken</b> — it was unnecessary, which explains no cause."},{"id":"gv-ch-31-9","level":"ch","focus":"idiom","q":"Researchers who blame screen time alone for teenage insomnia may be ______, since the latest data point to caffeine as the stronger factor.","options":["beating around the bush","barking up the wrong tree","jumping on the bandwagon","putting the cart before the horse"],"correct":1,"answer":"barking up the wrong tree","vi":"Các nhà nghiên cứu chỉ đổ lỗi cho thời gian dùng màn hình gây mất ngủ ở tuổi teen có lẽ đang nhắm sai hướng, vì dữ liệu mới nhất cho thấy caffeine là yếu tố mạnh hơn.","explanation":"<b>Bark up the wrong tree</b> = pursue a mistaken explanation or target, which <b>caffeine as the stronger factor</b> implies about blaming screens. ✗ <b>beat around the bush</b> — avoid saying something directly, but the researchers state their view plainly; ✗ <b>jump on the bandwagon</b> — follow a popular trend, no fashion is mentioned; ✗ <b>put the cart before the horse</b> — do things in the wrong order, not blame the wrong cause."},{"id":"gv-ch-31-10","level":"ch","focus":"collocation","q":"Rural clinics have been left to ______ the burden of the vaccination drive while city hospitals receive most of the extra funding.","options":["foot","head","hand","shoulder"],"correct":3,"answer":"shoulder","vi":"Các phòng khám nông thôn bị bỏ mặc gánh vác gánh nặng của chiến dịch tiêm chủng, trong khi các bệnh viện thành phố nhận phần lớn khoản kinh phí bổ sung.","explanation":"Taking on a heavy responsibility is <b>shoulder the burden</b> (also shoulder the cost / the blame), so the clinics carry the load alone. ✗ <b>foot</b> — only 'foot the bill' (pay); ✗ <b>head</b> — lead a committee, a list or a team, not carry a burden; ✗ <b>hand</b> — needs a particle ('hand over / out') and means give, not carry."},{"id":"gv-ch-31-11","level":"ch","focus":"subjunctive","q":"It is vital that the lead researcher ______ the safety briefing in person before the trial resumes.","options":["attended","attending","attend","will attend"],"correct":2,"answer":"attend","vi":"Điều thiết yếu là trưởng nhóm nghiên cứu phải trực tiếp tham dự buổi phổ biến an toàn trước khi thử nghiệm được nối lại.","explanation":"After <b>It is vital that</b> (also essential, important, necessary) the that-clause takes the base-form subjunctive whatever the subject: <b>the researcher attend</b>. ✗ <b>attended</b> — past tense, but the briefing is a future requirement; ✗ <b>attending</b> — not a finite verb, so the clause has no main verb; ✗ <b>will attend</b> — a plain future prediction, which the subjunctive pattern does not allow."},{"id":"gv-ch-31-12","level":"ch","focus":"word-choice","q":"Shares in the social network ______ by a fifth in a single afternoon after regulators announced a privacy investigation.","options":["dwindled","crept","tumbled","hovered"],"correct":2,"answer":"tumbled","vi":"Cổ phiếu của mạng xã hội này lao dốc một phần năm chỉ trong một buổi chiều sau khi cơ quan quản lý công bố cuộc điều tra về quyền riêng tư.","explanation":"<b>Tumble</b> = fall suddenly and steeply, matching <b>by a fifth in a single afternoon</b>. ✗ <b>dwindled</b> — a slow, gradual shrinking, not a one-afternoon crash; ✗ <b>crept</b> — moved very slowly, the opposite of a sudden drop; ✗ <b>hovered</b> — stayed roughly level, so it cannot take 'by a fifth'."},{"id":"gv-ch-31-13","level":"ch","focus":"linking","q":"______ carefully a hospital encrypts its records, a single careless password can undo the whole effort.","options":["Whatever","No matter how","Even though","In spite of"],"correct":1,"answer":"No matter how","vi":"Dù một bệnh viện mã hóa hồ sơ cẩn thận đến đâu, chỉ một mật khẩu bất cẩn cũng có thể làm đổ sông đổ biển toàn bộ nỗ lực.","explanation":"The blank is followed directly by the adverb <b>carefully</b>, so the concessive opener must be <b>No matter how</b> (= however carefully). ✗ <b>Whatever</b> — must be followed by a noun ('whatever precautions'), not an adverb; ✗ <b>Even though</b> — introduces a full clause beginning with the subject ('even though a hospital encrypts'); ✗ <b>In spite of</b> — a preposition, so it needs a noun phrase, not 'carefully ... encrypts'."},{"id":"gv-ch-31-14","level":"ch","focus":"phrasal-verb","q":"Using the phone's metadata, investigators were able to ______ the exact building from which the stolen files had been uploaded.","options":["zoom in at","home in to","close in at","zero in on"],"correct":3,"answer":"zero in on","vi":"Nhờ siêu dữ liệu của chiếc điện thoại, các điều tra viên đã khoanh vùng được chính xác tòa nhà nơi các tệp bị đánh cắp đã được tải lên.","explanation":"<b>Zero in on</b> = identify and focus precisely on a target, the only option with the correct particle. ✗ <b>zoom in at</b> — the phrase is 'zoom in on'; ✗ <b>home in to</b> — the phrase is 'home in on'; ✗ <b>close in at</b> — the phrase is 'close in on'. All three verbs would fit in meaning, but each pairs only with 'on'."},{"id":"gv-ch-31-15","level":"ch","focus":"reported","q":"At the hearing, the journalist asked the chief executive ______ the company had ever sold its users' location history to advertisers.","options":["whether","that","what","did"],"correct":0,"answer":"whether","vi":"Tại phiên điều trần, nhà báo hỏi vị tổng giám đốc liệu công ty có bao giờ bán lịch sử vị trí của người dùng cho các nhà quảng cáo hay không.","explanation":"<b>Asked ... the company had ever sold</b> is a reported yes/no question, so it is introduced by <b>whether</b> (or 'if') with statement word order. ✗ <b>that</b> — reports a statement, not a question; ✗ <b>what</b> — would need a missing object, but 'sold its users' location history' is already complete; ✗ <b>did</b> — direct-question order, impossible inside reported speech."},{"id":"gv-ch-31-16","level":"ch","focus":"idiom","q":"The surgeon is not one to ______, but her transplant team's survival figures speak for themselves.","options":["blow hot and cold","blow the whistle","blow her own trumpet","blow her top"],"correct":2,"answer":"blow her own trumpet","vi":"Vị bác sĩ phẫu thuật không phải người thích khoe khoang, nhưng con số tỷ lệ sống sót của đội ghép tạng của bà đã tự nói lên tất cả.","explanation":"<b>Blow your own trumpet</b> = boast about your achievements, which contrasts with the figures that <b>speak for themselves</b>. ✗ <b>blow hot and cold</b> — keep changing your mind, nothing to do with modesty; ✗ <b>blow the whistle</b> — expose wrongdoing, none is mentioned; ✗ <b>blow her top</b> — lose her temper, unrelated to praise."},{"id":"gv-ch-31-17","level":"ch","focus":"gerund-infinitive","q":"Older users seem resigned to ______ tracked wherever they go online, whereas teenagers are increasingly fighting back.","options":["be","being","to be","been"],"correct":1,"answer":"being","vi":"Người dùng lớn tuổi dường như cam chịu việc bị theo dõi ở bất cứ đâu họ lên mạng, trong khi thanh thiếu niên ngày càng phản kháng.","explanation":"In <b>resigned to</b> the 'to' is a preposition (like 'used to', 'look forward to', 'object to'), so it is followed by a gerund: <b>being tracked</b>. ✗ <b>be</b> — a bare infinitive cannot follow a preposition; ✗ <b>to be</b> — would give 'to to be', a doubled 'to'; ✗ <b>been</b> — a past participle needs 'have / has' before it."},{"id":"gv-ch-31-18","level":"ch","focus":"word-choice","q":"The probe is now ______ towards Jupiter at almost 200,000 kilometres an hour, faster than any craft before it.","options":["hurtling","drifting","dawdling","meandering"],"correct":0,"answer":"hurtling","vi":"Tàu thăm dò hiện đang lao về phía Sao Mộc với tốc độ gần 200.000 km/giờ, nhanh hơn bất kỳ con tàu nào trước đó.","explanation":"<b>Hurtle</b> = move at very great speed, often out of control, fitting <b>almost 200,000 kilometres an hour</b>. ✗ <b>drifting</b> — moving slowly with no power or direction; ✗ <b>dawdling</b> — moving slowly and lazily, wasting time; ✗ <b>meandering</b> — following a slow, winding path. All three describe slowness, the opposite of the clue."},{"id":"gv-ch-31-19","level":"ch","focus":"participle","q":"______ a surge in counterfeit medicines, the health ministry has ordered every pharmacy to scan a barcode on each pack it sells.","options":["Prompted by","Prompting by","Having prompted by","To prompt by"],"correct":0,"answer":"Prompted by","vi":"Trước tình trạng thuốc giả gia tăng, bộ y tế đã yêu cầu mọi hiệu thuốc quét mã vạch trên từng hộp thuốc bán ra.","explanation":"The ministry was moved to act <b>by</b> the surge, so a past participle with passive meaning is needed: <b>Prompted by</b> a surge = because it was prompted by one. ✗ <b>Prompting by</b> — an active participle makes the ministry the cause, leaving 'by' with nothing to attach to; ✗ <b>Having prompted by</b> — an active perfect participle, the same wrong direction; ✗ <b>To prompt by</b> — an infinitive of purpose, not a participle clause, and the ministry did not act in order to prompt."},{"id":"gv-ch-31-20","level":"ch","focus":"collocation","q":"Even a ______ smoker who quits at fifty regains several years of life expectancy, the study concludes.","options":["strong","heavy","hard","big"],"correct":1,"answer":"heavy","vi":"Ngay cả một người nghiện thuốc nặng bỏ thuốc ở tuổi năm mươi cũng lấy lại được vài năm tuổi thọ, nghiên cứu kết luận.","explanation":"Someone who smokes a great deal is a <b>heavy smoker</b> (likewise a heavy drinker, heavy traffic, heavy rain): 'heavy' marks large quantity. ✗ <b>strong</b> — describes the cigarette or its taste, not the person; ✗ <b>hard</b> — 'a hard worker' exists, but 'hard smoker' is not a collocation; ✗ <b>big</b> — used in 'a big eater / big spender', not with 'smoker'."},{"id":"gv-ch-31-21","level":"ch","focus":"double-blank","q":"It ______ out that the clinic had been ______ patient records on an unsecured server for almost three years.","options":["ended / to store","worked / stored","turned / storing","made / storing"],"correct":2,"answer":"turned / storing","vi":"Hóa ra phòng khám đã lưu trữ hồ sơ bệnh nhân trên một máy chủ không được bảo mật trong gần ba năm.","explanation":"<b>It turned out that</b> = it was discovered that; and after <b>had been</b> the past perfect continuous needs the -ing form, <b>storing</b>. ✗ <b>ended / to store</b> — 'end out' does not exist and 'had been to store' is meaningless; ✗ <b>worked / stored</b> — 'it worked out that' is not used for discovering a fact, and 'had been stored patient records' leaves no object slot; ✗ <b>made / storing</b> — 'make out that' means to pretend, not to discover."},{"id":"gv-ch-31-22","level":"ch","focus":"idiom","q":"The telehealth start-up expects to ______ by next spring, once subscription income finally covers its server costs.","options":["break ground","break ranks","break the bank","break even"],"correct":3,"answer":"break even","vi":"Công ty khởi nghiệp y tế từ xa dự kiến sẽ hòa vốn vào mùa xuân tới, khi thu nhập từ thuê bao cuối cùng bù đắp được chi phí máy chủ.","explanation":"<b>Break even</b> = make neither a profit nor a loss, exactly what <b>income finally covers its server costs</b> describes. ✗ <b>break ground</b> — start building on a site, unrelated to money; ✗ <b>break ranks</b> — stop supporting your own group; ✗ <b>break the bank</b> — cost far too much, the opposite of covering costs."},{"id":"gv-ch-31-23","level":"ch","focus":"pronoun","q":"______ leaks a patient's records, even unintentionally, now faces a fine of up to a year's salary under the new law.","options":["Whoever","Whomever","Whichever","Whom"],"correct":0,"answer":"Whoever","vi":"Bất kỳ ai làm rò rỉ hồ sơ bệnh nhân, dù vô ý, giờ đây đều đối mặt với khoản phạt lên tới một năm lương theo luật mới.","explanation":"<b>Whoever</b> = any person who; it is the subject of <b>leaks</b> (and of 'faces'), so the subject form is needed. ✗ <b>Whomever</b> — object form, but the pronoun performs the verb 'leaks'; ✗ <b>Whichever</b> — a choice among a known set of things, not an unknown person; ✗ <b>Whom</b> — object form, and a plain relative cannot open a sentence with no antecedent."},{"id":"gv-ch-31-24","level":"ch","focus":"word-choice","q":"Life expectancy in the region has ______ at around 72 for a decade, despite heavy investment in new hospitals.","options":["rocketed","rebounded","plateaued","dipped"],"correct":2,"answer":"plateaued","vi":"Tuổi thọ trung bình ở khu vực này đã chững lại ở mức khoảng 72 suốt một thập kỷ, bất chấp đầu tư mạnh vào các bệnh viện mới.","explanation":"<b>Plateau</b> = stop rising and stay level, which <b>at around 72 for a decade</b> and 'despite heavy investment' both signal. ✗ <b>rocketed</b> — shot up fast, but the figure has not moved; ✗ <b>rebounded</b> — recovered after a fall, and no fall is mentioned; ✗ <b>dipped</b> — fell briefly, which cannot be followed by 'at around 72 for a decade'."},{"id":"gv-ch-31-25","level":"ch","focus":"question-tag","q":"Nobody expected the vaccine to clear the regulator's review this quickly, ______?","options":["didn't they","did they","did it","wasn't it"],"correct":1,"answer":"did they","vi":"Không ai ngờ vắc-xin lại vượt qua đợt xét duyệt của cơ quan quản lý nhanh đến thế, phải không?","explanation":"<b>Nobody</b> makes the statement negative, so the tag is positive, and indefinite person subjects (nobody, everyone, someone) take <b>they</b>: <b>did they</b>. ✗ <b>didn't they</b> — a negative tag after a negative statement; ✗ <b>did it</b> — 'it' would refer to the vaccine, but the subject is 'nobody'; ✗ <b>wasn't it</b> — wrong auxiliary ('expected' needs 'did') and wrong pronoun."},{"id":"gv-ch-32-1","level":"ch","focus":"word-choice","q":"Many long-term backpackers pride themselves on being ______, stretching a modest budget over months on the road without ever feeling deprived.","options":["thrifty","stingy","miserly","tight-fisted"],"correct":0,"answer":"thrifty","vi":"Nhiều người đi du lịch bụi dài ngày tự hào vì mình tiết kiệm, kéo dài một ngân sách khiêm tốn qua nhiều tháng trên đường mà chưa bao giờ thấy thiếu thốn.","explanation":"Word choice: the clue <b>pride themselves on</b> needs an approving word, and <b>thrifty</b> = spending carefully and wisely, a virtue. ✗ <b>stingy</b> — meanly unwilling to spend, an insult, not a point of pride; ✗ <b>miserly</b> — hoarding money like a miser, also an insult; ✗ <b>tight-fisted</b> — refusing to part with money, again disapproving, and the sentence says the backpackers never feel deprived."},{"id":"gv-ch-32-2","level":"ch","focus":"idiom","q":"When the exhibition's visitor figures were queried, it was the junior curator who was left to ______, although every decision had been taken far above her.","options":["carry the day","carry the can","carry the torch","carry the weight"],"correct":1,"answer":"carry the can","vi":"Khi số liệu khách tham quan của triển lãm bị chất vấn, chính cô phụ trách trưng bày trẻ tuổi phải đứng ra gánh trách nhiệm, dù mọi quyết định đều do cấp trên đưa ra.","explanation":"Idiom: <b>carry the can</b> = take the blame for something others did, which fits <b>every decision had been taken far above her</b>. ✗ <b>carry the day</b> — win the argument or contest, nothing about blame; ✗ <b>carry the torch</b> — keep a cause (or an old love) alive; ✗ <b>carry the weight</b> — bear a heavy load or responsibility, not a fixed idiom for being made the scapegoat."},{"id":"gv-ch-32-3","level":"ch","focus":"collocation","q":"Under mounting pressure from residents, the council has ______ strict limits on the number of cruise ships allowed to dock each day.","options":["installed","inflicted","imposed","instilled"],"correct":2,"answer":"imposed","vi":"Trước sức ép ngày càng lớn từ cư dân, hội đồng thành phố đã áp đặt giới hạn nghiêm ngặt về số tàu du lịch được phép cập cảng mỗi ngày.","explanation":"Collocation: a council <b>imposes</b> limits, rules, fines or taxes on people, and the clue <b>strict limits</b> is exactly what <b>impose</b> takes. ✗ <b>installed</b> — collocates with equipment, software or an official, not limits; ✗ <b>inflicted</b> — you inflict pain, damage or a defeat, not a rule; ✗ <b>instilled</b> — you instil values, fear or confidence in a person, not a numerical cap on ships."},{"id":"gv-ch-32-4","level":"ch","focus":"phrasal-verb","q":"Visitors from a single neighbouring country ______ nearly half of all overnight stays recorded in the province last year.","options":["answer for","allow for","stand for","account for"],"correct":3,"answer":"account for","vi":"Du khách từ một nước láng giềng duy nhất chiếm gần một nửa tổng số đêm lưu trú được ghi nhận ở tỉnh này năm ngoái.","explanation":"Phrasal verb: <b>account for</b> = make up a stated share of a total, and the clue <b>nearly half of all overnight stays</b> is a share. ✗ <b>answer for</b> — be held responsible for a fault or crime, so visitors would be being blamed; ✗ <b>allow for</b> — take something into consideration when planning, which needs a person as subject; ✗ <b>stand for</b> — represent or tolerate, neither of which works with a percentage."},{"id":"gv-ch-32-5","level":"ch","focus":"inversion","q":"Only when the last tour bus has pulled away ______ the village square return to its usual silence.","options":["does","do","did","has"],"correct":0,"answer":"does","vi":"Chỉ khi chiếc xe du lịch cuối cùng đã rời đi, quảng trường làng mới trở lại sự tĩnh lặng thường ngày.","explanation":"Inversion: after a fronted <b>Only when…</b> clause the main clause inverts with an auxiliary, and the singular subject <b>the village square</b> plus the present-habit clue <b>has pulled away</b> give <b>does the square return</b>. ✗ <b>do</b> — plural auxiliary, but the subject is singular; ✗ <b>did</b> — past tense, but the time clause is present perfect describing a routine; ✗ <b>has</b> — would need a past participle (<b>returned</b>), not the base form <b>return</b>."},{"id":"gv-ch-32-6","level":"ch","focus":"word-choice","q":"Reviewers described the resort's manager as ______, brushing aside complaints about the flooded rooms with a shrug and a joke.","options":["impartial","disinterested","indifferent","unbiased"],"correct":2,"answer":"indifferent","vi":"Người đánh giá mô tả quản lý khu nghỉ dưỡng là kẻ thờ ơ, gạt phăng những lời phàn nàn về các phòng bị ngập bằng cái nhún vai và một câu đùa.","explanation":"Word choice: <b>indifferent</b> = not caring at all, which matches the clue <b>brushing aside complaints with a shrug</b>. ✗ <b>impartial</b> — fair, not favouring either side, a virtue in a judge, not a fault in a manager; ✗ <b>disinterested</b> — having no personal stake, so able to judge fairly, again a good quality; ✗ <b>unbiased</b> — free from prejudice, also praise, and none of the three describe ignoring flooded rooms."},{"id":"gv-ch-32-7","level":"ch","focus":"subjunctive","q":"The tribunal recommended that the operator ______ every guide in emergency first aid before the trekking season resumes.","options":["trains","train","trained","would train"],"correct":1,"answer":"train","vi":"Hội đồng xét xử khuyến nghị nhà điều hành đào tạo sơ cứu khẩn cấp cho mọi hướng dẫn viên trước khi mùa leo núi bắt đầu lại.","explanation":"Subjunctive: after <b>recommend / suggest / insist that</b> the verb takes the base-form subjunctive, so <b>that the operator train</b>, with no <b>-s</b> even for a singular subject. ✗ <b>trains</b> — ordinary present tense, but the that-clause after <b>recommended</b> is a proposal, not a fact; ✗ <b>trained</b> — past tense would report what already happened, yet the training is still to come <b>before the season resumes</b>; ✗ <b>would train</b> — <b>would</b> is not used in the subjunctive clause after <b>recommend</b>."},{"id":"gv-ch-32-8","level":"ch","focus":"idiom","q":"Scholars who explain the missing layer by an earthquake that no chronicle records are merely ______, the reviewer argued.","options":["splitting hairs","beating about the bush","sitting on the fence","clutching at straws"],"correct":3,"answer":"clutching at straws","vi":"Những học giả giải thích tầng địa chất bị thiếu bằng một trận động đất mà không biên niên sử nào ghi lại chỉ đang bám víu vào hy vọng mong manh, nhà phê bình lập luận.","explanation":"Idiom: <b>clutch at straws</b> = rely on a hopeless explanation because nothing better exists, and the clue is an earthquake <b>that no chronicle records</b>, evidence-free guesswork. ✗ <b>splitting hairs</b> — arguing over tiny, unimportant differences; ✗ <b>beating about the bush</b> — avoiding the main point, talking indirectly; ✗ <b>sitting on the fence</b> — refusing to take sides, whereas these scholars have firmly chosen a theory."},{"id":"gv-ch-32-9","level":"ch","focus":"double-blank","q":"Reluctant to ______ corners on safety, the operator insisted that every raft ______ inspected before the river reopened to tourists.","options":["clip / be","cut / be","cut / to be","trim / being"],"correct":1,"answer":"cut / be","vi":"Không muốn làm ẩu về an toàn, nhà điều hành yêu cầu mọi chiếc bè phải được kiểm tra trước khi con sông mở cửa lại cho du khách.","explanation":"Double blank: the idiom is <b>cut corners</b> = do a job cheaply and carelessly, and <b>insisted that</b> takes the base-form subjunctive <b>be inspected</b>. ✗ <b>clip / be</b> — <b>clip corners</b> is not the idiom, even though the second half is right; ✗ <b>cut / to be</b> — after <b>insisted that every raft</b> a <b>to</b>-infinitive cannot follow the subject; ✗ <b>trim / being</b> — <b>trim corners</b> is not the idiom, and <b>being</b> gives the that-clause no finite verb."},{"id":"gv-ch-32-10","level":"ch","focus":"linking","q":"______ the lure of overseas travel, most trips taken in the region are still to places within three hours' drive of home.","options":["Notwithstanding","Nevertheless","Whereas","Albeit"],"correct":0,"answer":"Notwithstanding","vi":"Bất chấp sức hút của du lịch nước ngoài, phần lớn các chuyến đi trong khu vực vẫn là tới những nơi cách nhà không quá ba giờ lái xe.","explanation":"Linking word: the blank is followed by a noun phrase, <b>the lure of overseas travel</b>, so it needs a preposition, and <b>notwithstanding</b> = despite. ✗ <b>Nevertheless</b> — an adverb that joins two sentences; it cannot govern a noun; ✗ <b>Whereas</b> — a conjunction contrasting two full clauses, but here there is no verb after it; ✗ <b>Albeit</b> — means <b>although</b> and introduces an adjective or reduced clause (<b>albeit slowly</b>), not a noun phrase."},{"id":"gv-ch-32-11","level":"ch","focus":"word-choice","q":"The dig director was ______ to a fault, insisting that every shard be photographed in place before anyone lifted it.","options":["unscrupulous","sceptical","secretive","scrupulous"],"correct":3,"answer":"scrupulous","vi":"Người chỉ đạo khai quật cẩn trọng đến mức thái quá, yêu cầu mọi mảnh gốm phải được chụp ảnh tại chỗ trước khi ai đó nhấc lên.","explanation":"Word choice: <b>scrupulous</b> = extremely careful and exact, and the clue <b>insisting that every shard be photographed in place</b> shows that care; <b>to a fault</b> means excessively so. ✗ <b>unscrupulous</b> — without morals, willing to cheat, the opposite idea; ✗ <b>sceptical</b> — doubting or unconvinced, nothing to do with careful method; ✗ <b>secretive</b> — hiding information, but the director is documenting everything."},{"id":"gv-ch-32-12","level":"ch","focus":"modal","q":"The pottery ______ locally, since its clay contains minerals found nowhere in the valley.","options":["needn't have been made","mustn't have been made","can't have been made","shouldn't have been made"],"correct":2,"answer":"can't have been made","vi":"Số gốm này không thể được làm tại địa phương, vì đất sét của nó chứa những khoáng chất không hề có trong thung lũng.","explanation":"Modal deduction: <b>can't have + past participle</b> = a confident conclusion that something was impossible, and the clue <b>minerals found nowhere in the valley</b> is the proof. ✗ <b>needn't have been made</b> — it was made but that was unnecessary, not a deduction; ✗ <b>mustn't have been made</b> — <b>mustn't</b> expresses prohibition, not impossibility; the negative deduction is <b>can't</b>; ✗ <b>shouldn't have been made</b> — it was wrong to make it, a criticism rather than a conclusion about origin."},{"id":"gv-ch-32-13","level":"ch","focus":"phrasal-verb","q":"The traveller's timeline simply does not ______: she claims to have crossed the border twice in a single afternoon.","options":["add on","add up","add in","sum up"],"correct":1,"answer":"add up","vi":"Mốc thời gian của nữ du khách đơn giản là không hợp lý: cô ta khai đã qua biên giới hai lần chỉ trong một buổi chiều.","explanation":"Phrasal verb: <b>add up</b> (intransitive) = make sense, be consistent, and the clue <b>crossed the border twice in a single afternoon</b> is a claim that does not make sense. ✗ <b>add on</b> — attach something extra (a fee, a room), needs an object; ✗ <b>add in</b> — include an item in a total, also needs an object; ✗ <b>sum up</b> — summarise or give the main points, a different meaning entirely."},{"id":"gv-ch-32-14","level":"ch","focus":"collocation","q":"The hoard of foreign coins ______ new light on trade routes that no written source ever mentions.","options":["sheds","pours","spreads","spills"],"correct":0,"answer":"sheds","vi":"Kho tiền xu nước ngoài đã làm sáng tỏ thêm những tuyến thương mại mà không tài liệu thành văn nào từng nhắc tới.","explanation":"Collocation: the fixed phrase is <b>shed light on</b> = make something clearer, and the clue <b>trade routes that no source mentions</b> shows the coins are revealing information. ✗ <b>pours</b> — you pour a liquid or money into something; <b>pour light on</b> is not the idiom; ✗ <b>spreads</b> — news, disease or butter spreads; ✗ <b>spills</b> — liquid spills; neither collocates with <b>light on</b> in the sense of explaining."},{"id":"gv-ch-32-15","level":"ch","focus":"idiom","q":"Tension over overcrowding on the island finally ______ last August, when residents blockaded the ferry terminal.","options":["came to light","came to grief","came to a head","came to nothing"],"correct":2,"answer":"came to a head","vi":"Căng thẳng về tình trạng quá tải trên đảo cuối cùng đã lên đến đỉnh điểm vào tháng Tám năm ngoái, khi cư dân phong toả bến phà.","explanation":"Idiom: <b>come to a head</b> = reach a crisis point that forces action, and the clue <b>residents blockaded the ferry terminal</b> is that crisis. ✗ <b>came to light</b> — became known or was discovered, but the overcrowding was already obvious; ✗ <b>came to grief</b> — failed badly or had an accident; ✗ <b>came to nothing</b> — produced no result, the opposite of a blockade."},{"id":"gv-ch-32-16","level":"ch","focus":"participle","q":"______ twice about the unstable slope, the mining company nevertheless pressed ahead with blasting directly beneath the village.","options":["Having warned","Warning","Being warned","Having been warned"],"correct":3,"answer":"Having been warned","vi":"Dù đã hai lần bị cảnh báo về sườn dốc không ổn định, công ty khai mỏ vẫn tiếp tục cho nổ mìn ngay bên dưới ngôi làng.","explanation":"Participle clause: the company received the warnings (passive) and did so before pressing ahead (perfect), so <b>Having been warned</b> is the perfect passive. ✗ <b>Having warned</b> — active, would make the company give the warning to someone else; ✗ <b>Warning</b> — active and simultaneous, so the company would be issuing warnings while blasting; ✗ <b>Being warned</b> — passive but not perfect, so it does not show the two warnings came earlier, and <b>twice</b> demands completed past events."},{"id":"gv-ch-32-17","level":"ch","focus":"word-choice","q":"Psychologists find that ______ colleagues, who voice the objections others keep to themselves, are often valued more than they are liked.","options":["outspoken","outstanding","outgoing","outlandish"],"correct":0,"answer":"outspoken","vi":"Các nhà tâm lý học nhận thấy những đồng nghiệp thẳng thắn, người nói ra những phản đối mà người khác giữ trong lòng, thường được coi trọng hơn là được yêu mến.","explanation":"Word choice: <b>outspoken</b> = saying frankly what you think, and the relative clause <b>who voice the objections others keep to themselves</b> defines exactly that. ✗ <b>outstanding</b> — excellent, exceptionally good, says nothing about speaking up; ✗ <b>outgoing</b> — sociable and friendly, not the same as frank; ✗ <b>outlandish</b> — strange or bizarre, which does not fit the neutral tone."},{"id":"gv-ch-32-18","level":"ch","focus":"subjunctive","q":"It is high time the ministry ______ how many visitors the caves can safely absorb in a day.","options":["decides","decided","decide","will decide"],"correct":1,"answer":"decided","vi":"Đã đến lúc bộ phải quyết định các hang động có thể tiếp nhận an toàn bao nhiêu du khách mỗi ngày.","explanation":"Subjunctive: after <b>It is high time</b> the verb takes the past subjunctive, so <b>decided</b>, even though it refers to the present and means the action is overdue. ✗ <b>decides</b> — present simple is not used after <b>high time</b>; ✗ <b>decide</b> — the base form belongs after <b>recommend / suggest that</b>, not after <b>high time</b>; ✗ <b>will decide</b> — a future tense contradicts the point that the decision should already have been made."},{"id":"gv-ch-32-19","level":"ch","focus":"gerund-infinitive","q":"After one bad experience, the group would sooner ______ the night on the bus than trust another roadside hotel.","options":["spending","to spend","spend","spent"],"correct":2,"answer":"spend","vi":"Sau một trải nghiệm tồi tệ, cả nhóm thà qua đêm trên xe còn hơn tin thêm một khách sạn ven đường nào nữa.","explanation":"Verb pattern: <b>would sooner / would rather</b> is followed by the bare infinitive, and the clue <b>than trust</b> (also bare) confirms the parallel: <b>would sooner spend</b>. ✗ <b>spending</b> — a gerund cannot follow the modal phrase <b>would sooner</b>; ✗ <b>to spend</b> — <b>to</b> is dropped after <b>would sooner / would rather</b>; ✗ <b>spent</b> — the past form is used only with a different subject (<b>would sooner they spent</b>), not with the same subject."},{"id":"gv-ch-32-20","level":"ch","focus":"article-quantifier","q":"______ evidence survives of the ancient harbour suggests that it silted up within a single century.","options":["The few","A little","Little of","What little"],"correct":3,"answer":"What little","vi":"Chút ít bằng chứng còn sót lại về thương cảng cổ cho thấy nó đã bị bồi lấp chỉ trong vòng một thế kỷ.","explanation":"Quantifier: <b>What little evidence survives</b> = the small amount of evidence that survives, and the whole phrase is the subject of <b>suggests</b>. ✗ <b>The few</b> — <b>evidence</b> is uncountable, so <b>few</b> cannot modify it; ✗ <b>A little</b> — <b>A little evidence survives</b> would be a complete sentence, leaving <b>suggests</b> without a subject; ✗ <b>Little of</b> — <b>little of</b> must be followed by <b>the</b> (<b>little of the evidence</b>), and again <b>suggests</b> would have no subject."},{"id":"gv-ch-32-21","level":"ch","focus":"idiom","q":"Guides will cheerfully embellish a castle's ghost story, but most ______ inventing a massacre that never took place.","options":["draw the line at","draw a veil over","draw a bead on","draw a blank on"],"correct":0,"answer":"draw the line at","vi":"Hướng dẫn viên sẵn sàng thêu dệt chuyện ma ở lâu đài, nhưng phần lớn dứt khoát không bịa ra một vụ thảm sát chưa từng xảy ra.","explanation":"Idiom: <b>draw the line at</b> = refuse to go as far as something, and the contrast <b>will cheerfully embellish… but</b> shows the guides set a limit. ✗ <b>draw a veil over</b> — deliberately keep something quiet, hide it; ✗ <b>draw a bead on</b> — aim a gun at a target; ✗ <b>draw a blank on</b> — fail to find or remember something, none of which express refusal."},{"id":"gv-ch-32-22","level":"ch","focus":"inversion","q":"______ the volunteer divers who map the reef every spring, nobody would know how quickly the coral is disappearing.","options":["Had it not been for","Should it not be for","Were it not for","Were it not"],"correct":2,"answer":"Were it not for","vi":"Nếu không có những thợ lặn tình nguyện lập bản đồ rạn san hô mỗi mùa xuân, sẽ chẳng ai biết san hô đang biến mất nhanh đến mức nào.","explanation":"Inversion: <b>Were it not for + noun</b> inverts <b>If it were not for</b>, and the present result <b>nobody would know</b> marks a present unreal condition. ✗ <b>Had it not been for</b> — past unreal, needs a past result (<b>would have known</b>); ✗ <b>Should it not be for</b> — <b>Should</b> inversion replaces <b>if</b> in future conditions and never combines with <b>be for</b>; ✗ <b>Were it not</b> — the noun <b>the volunteer divers</b> requires <b>for</b>."},{"id":"gv-ch-32-23","level":"ch","focus":"double-blank","q":"Later digs ______ her hunch: a second gateway was found exactly ______ she had predicted it would be.","options":["bore up / where","bore out / where","bore out / which","bore with / that"],"correct":1,"answer":"bore out / where","vi":"Những đợt khai quật sau đó đã chứng thực linh cảm của bà: cổng thứ hai được tìm thấy đúng nơi bà đã dự đoán.","explanation":"Double blank: <b>bear out</b> = confirm a claim, and <b>exactly where she had predicted</b> shows the hunch was proved; the second blank needs the place word <b>where</b> after <b>found exactly</b>. ✗ <b>bore up / where</b> — <b>bear up</b> = stay strong under pressure; ✗ <b>bore out / which</b> — <b>which</b> needs a noun to refer to, so <b>found exactly which</b> is ungrammatical; ✗ <b>bore with / that</b> — <b>bear with</b> = be patient with someone, and <b>that</b> cannot mean <b>in the place that</b>."},{"id":"gv-ch-32-24","level":"ch","focus":"word-choice","q":"The chronicle portrays the emperor as a ______ ruler who taxed his provinces into ruin to pay for a single palace.","options":["proficient","profound","prolific","profligate"],"correct":3,"answer":"profligate","vi":"Biên niên sử khắc hoạ vị hoàng đế như một kẻ hoang phí, đánh thuế các tỉnh đến kiệt quệ chỉ để xây một cung điện.","explanation":"Word choice: <b>profligate</b> = recklessly wasteful with money, and the clue <b>taxed his provinces into ruin to pay for a single palace</b> is exactly that. ✗ <b>proficient</b> — skilled and competent, praise rather than criticism; ✗ <b>profound</b> — deep or serious in thought; ✗ <b>prolific</b> — producing a great deal (of books, goals, children), not spending a great deal."},{"id":"gv-ch-32-25","level":"ch","focus":"collocation","q":"Although they hold no formal office, the island's fishing cooperatives still ______ considerable influence over how the marine reserve is policed.","options":["brandish","wield","flex","swing"],"correct":1,"answer":"wield","vi":"Dù không nắm giữ chức vụ chính thức nào, các hợp tác xã ngư dân trên đảo vẫn có ảnh hưởng đáng kể tới cách khu bảo tồn biển được giám sát.","explanation":"Collocation: the fixed pairing is <b>wield influence / power / authority</b> = hold and use it, and the clue <b>considerable influence over how the reserve is policed</b> needs that verb. ✗ <b>brandish</b> — wave a weapon threateningly, so it takes a sword or knife, not influence; ✗ <b>flex</b> — you flex your muscles (literally or figuratively), not influence; ✗ <b>swing</b> — you swing a bat or an axe; <b>swing influence</b> is not English."},{"id":"gv-ch-33-1","level":"ch","focus":"tense","q":"By the end of next year the offshore wind farm ______ power to the island for a full decade.","options":["will supply","will have been supplying","has supplied","will be supplying"],"correct":1,"answer":"will have been supplying","vi":"Đến cuối năm sau, trang trại điện gió ngoài khơi sẽ cung cấp điện cho hòn đảo được tròn một thập kỷ.","explanation":"<b>By the end of next year</b> (a future deadline) + <b>for a full decade</b> (a duration) = an action continuing up to a future point, so the future perfect continuous <b>will have been supplying</b> is needed.<br>✗ <b>will supply</b> — simple future, cannot carry a duration up to a deadline; ✗ <b>has supplied</b> — present perfect measures up to now, not up to next year; ✗ <b>will be supplying</b> — an action in progress at that moment, not how long it will have lasted."},{"id":"gv-ch-33-2","level":"ch","focus":"word-choice","q":"The novelist's leukaemia went into ______ after a year of treatment, giving her time to finish the final volume of the trilogy.","options":["remission","relapse","recession","regression"],"correct":0,"answer":"remission","vi":"Bệnh bạch cầu của nữ tiểu thuyết gia đã thuyên giảm sau một năm điều trị, cho bà thời gian hoàn thành tập cuối của bộ ba tác phẩm.","explanation":"<b>Went into ______ after a year of treatment</b> and <b>giving her time</b> show the disease eased, so the medical term <b>remission</b> (a period when a disease stops or improves) fits.<br>✗ <b>relapse</b> — the return of an illness after improvement, the opposite meaning; ✗ <b>recession</b> — a decline in the economy, not in a disease; ✗ <b>regression</b> — going back to an earlier, less developed state; not the word for an illness easing."},{"id":"gv-ch-33-3","level":"ch","focus":"idiom","q":"The regulator ______ badly when it approved the gas pipeline without commissioning a single environmental survey.","options":["kept the ball rolling","was on the ball","dropped the ball","played ball"],"correct":2,"answer":"dropped the ball","vi":"Cơ quan quản lý đã sai sót nghiêm trọng khi phê duyệt đường ống dẫn khí mà không hề yêu cầu một cuộc khảo sát môi trường nào.","explanation":"The regulator failed in its duty (<b>approved … without commissioning a single survey</b>), and <b>badly</b> marks a mistake, so <b>dropped the ball</b> = failed to do what it was responsible for.<br>✗ <b>kept the ball rolling</b> — kept an activity going, a positive act; ✗ <b>was on the ball</b> — was alert and competent, the opposite; ✗ <b>played ball</b> — cooperated with someone, no sense of failure."},{"id":"gv-ch-33-4","level":"ch","focus":"collocation","q":"The city council has finally ______ approval for a second bridge across the estuary.","options":["allowed","permitted","admitted","granted"],"correct":3,"answer":"granted","vi":"Hội đồng thành phố cuối cùng đã cấp phép xây cây cầu thứ hai bắc qua cửa sông.","explanation":"The verb that collocates with the noun <b>approval</b> (also permission, a licence, a request) is <b>grant</b>: authorities <b>grant approval for</b> something.<br>✗ <b>allowed</b> — takes the thing permitted (allow a bridge / allow them to build), not the noun approval; ✗ <b>permitted</b> — same pattern as allow, permit + object or to-infinitive; ✗ <b>admitted</b> — means confess or let in, no sense of giving permission."},{"id":"gv-ch-33-5","level":"ch","focus":"phrasal-verb","q":"The switch to rooftop solar has ______ a sharp fall in electricity bills for rural households.","options":["brought about","brought up","brought down","brought off"],"correct":0,"answer":"brought about","vi":"Việc chuyển sang điện mặt trời áp mái đã tạo ra sự sụt giảm mạnh trong hóa đơn tiền điện của các hộ gia đình nông thôn.","explanation":"The switch <b>caused</b> a fall in bills: <b>bring about</b> = cause something to happen, and its object is a result (<b>a sharp fall</b>).<br>✗ <b>brought up</b> — raise a topic or a child; ✗ <b>brought down</b> — reduce or topple; you bring down bills, not a fall in bills; ✗ <b>brought off</b> — succeed in doing something difficult; the object is a feat, not a result."},{"id":"gv-ch-33-6","level":"ch","focus":"modal","q":"The blackout ______ have been caused by the storm, since the transmission lines went down two hours before it reached the coast.","options":["must","can't","might","should"],"correct":1,"answer":"can't","vi":"Vụ mất điện không thể do cơn bão gây ra, vì các đường dây truyền tải đã đổ hai tiếng trước khi bão vào đến bờ biển.","explanation":"<b>The lines went down two hours before</b> the storm arrived, so the storm was NOT the cause: the negative past deduction <b>can't have been</b> (= it is impossible that it was) is needed.<br>✗ <b>must</b> — must have been says it certainly was the cause; ✗ <b>might</b> — might have been leaves the storm possible; ✗ <b>should</b> — should have been means it ought to have been, an expectation, not a deduction."},{"id":"gv-ch-33-7","level":"ch","focus":"word-choice","q":"A persistent cough is often the first ______ of the lung disease that miners in the coalfield develop.","options":["syndrome","diagnosis","symptom","prognosis"],"correct":2,"answer":"symptom","vi":"Ho dai dẳng thường là triệu chứng đầu tiên của căn bệnh phổi mà các thợ mỏ ở vùng than mắc phải.","explanation":"The cough is a sign the patient notices first, so <b>symptom</b> = a sign of illness felt by the patient.<br>✗ <b>syndrome</b> — a whole group of symptoms that together form a condition, not one cough; ✗ <b>diagnosis</b> — the doctor's identification of the disease; ✗ <b>prognosis</b> — the forecast of how the disease will develop."},{"id":"gv-ch-33-8","level":"ch","focus":"inversion","q":"______ must a reporter reveal the identity of a confidential source, even when the police demand it.","options":["In any case","At all costs","On no account","Under any circumstances"],"correct":2,"answer":"On no account","vi":"Trong bất kỳ trường hợp nào, phóng viên cũng không được tiết lộ danh tính của nguồn tin bí mật, ngay cả khi cảnh sát yêu cầu.","explanation":"The inverted order <b>must a reporter reveal</b> shows a negative adverbial opens the sentence: <b>On no account</b> (= never, for no reason) is the only negative option and means revealing is forbidden.<br>✗ <b>In any case</b> — means anyway, not negative, so normal word order; ✗ <b>At all costs</b> — means whatever happens, would say the reporter must reveal; ✗ <b>Under any circumstances</b> — needs <b>no</b> (under no circumstances) to be negative and invert."},{"id":"gv-ch-33-9","level":"ch","focus":"idiom","q":"Having inflated the magazine's circulation figures for years, the publisher finally had to ______ and answer for the fraud in court.","options":["face the music","call the tune","change his tune","blow his own trumpet"],"correct":0,"answer":"face the music","vi":"Sau nhiều năm thổi phồng số lượng phát hành của tạp chí, nhà xuất bản cuối cùng phải chịu trách nhiệm và trả lời về vụ gian lận trước tòa.","explanation":"The publisher had to accept the consequences (<b>answer for the fraud in court</b>), so <b>face the music</b> = accept punishment or criticism for what you did.<br>✗ <b>call the tune</b> — be the one in control; ✗ <b>change his tune</b> — change your opinion or attitude; ✗ <b>blow his own trumpet</b> — boast about yourself."},{"id":"gv-ch-33-10","level":"ch","focus":"double-blank","q":"Unless the state broadcaster gets its ______ together, advertisers will simply take their money ______.","options":["show / away","act / elsewhere","house / out","game / off"],"correct":1,"answer":"act / elsewhere","vi":"Nếu đài truyền hình nhà nước không chấn chỉnh lại cách làm việc, các nhà quảng cáo sẽ đơn giản mang tiền đi nơi khác.","explanation":"<b>Get your act together</b> = organise yourself and start working properly, and unhappy customers <b>take their money elsewhere</b> (= to another business).<br>✗ <b>show / away</b> — the idiom is get the show on the road; take money away = remove it; ✗ <b>house / out</b> — the idiom is get your house in order; take money out = a withdrawal; ✗ <b>game / off</b> — get your game together is not an idiom; take money off = deduct."},{"id":"gv-ch-33-11","level":"ch","focus":"relative","q":"The engineer ______ the tidal barrage was designed died before its first turbine ever turned.","options":["who","whose","by whom","whom"],"correct":2,"answer":"by whom","vi":"Người kỹ sư đã thiết kế đập thủy triều ấy qua đời trước khi tua-bin đầu tiên của nó quay.","explanation":"The barrage <b>was designed</b> — a passive — so the engineer is the agent and needs <b>by</b>: <b>by whom the tidal barrage was designed</b>.<br>✗ <b>who</b> — leaves the passive with no agent preposition (the engineer who the barrage was designed ✗); ✗ <b>whom</b> — an object pronoun but still no preposition, same problem; ✗ <b>whose</b> — possessive, must be followed by a noun (whose barrage), not by the article <b>the</b>."},{"id":"gv-ch-33-12","level":"ch","focus":"word-choice","q":"The newspaper's health desk was the first to report an ______ of cholera in the flooded villages below the dam.","options":["outburst","outcome","outset","outbreak"],"correct":3,"answer":"outbreak","vi":"Ban y tế của tờ báo là nơi đầu tiên đưa tin về một đợt bùng phát dịch tả ở các làng bị ngập bên dưới con đập.","explanation":"The sudden start of a disease (also war or violence) is an <b>outbreak</b>: <b>an outbreak of cholera</b>.<br>✗ <b>outburst</b> — a sudden show of emotion (an outburst of anger); ✗ <b>outcome</b> — the result of an event; ✗ <b>outset</b> — the beginning of an activity, used in at/from the outset, not with <b>of cholera</b>."},{"id":"gv-ch-33-13","level":"ch","focus":"collocation","q":"The national grid struggles to meet ______ demand on the hottest afternoons of the year, when every air conditioner is running.","options":["peak","top","summit","climax"],"correct":0,"answer":"peak","vi":"Lưới điện quốc gia chật vật đáp ứng nhu cầu cao điểm vào những buổi chiều nóng nhất trong năm, khi mọi máy điều hòa đều chạy.","explanation":"The highest level of use is <b>peak demand</b> — a fixed collocation like peak hours, peak season; the clue is <b>the hottest afternoons … every air conditioner is running</b>.<br>✗ <b>top</b> — position or rank (top speed, top floor), not a level of demand; ✗ <b>summit</b> — the top of a mountain or a leaders' meeting, does not modify demand; ✗ <b>climax</b> — the most exciting point of a story or event."},{"id":"gv-ch-33-14","level":"ch","focus":"subjunctive","q":"The station keeps a diesel generator on standby lest the wind farm ______ to deliver on a calm day.","options":["fails","fail","failed","would fail"],"correct":1,"answer":"fail","vi":"Nhà máy luôn để sẵn một máy phát diesel đề phòng trường hợp trang trại điện gió không phát được điện vào ngày lặng gió.","explanation":"After <b>lest</b> (= for fear that) the verb takes the present subjunctive: the base form <b>fail</b> with no -s, whatever the subject (lest the wind farm <b>fail</b>; <b>should fail</b> is the other accepted form).<br>✗ <b>fails</b> — present indicative with -s, not allowed after lest; ✗ <b>failed</b> — past tense, but the sentence is present (<b>keeps</b>) and lest never takes a past form; ✗ <b>would fail</b> — conditional, not used after lest."},{"id":"gv-ch-33-15","level":"ch","focus":"idiom","q":"For three years the engineers' warnings that the spillway was cracking ______, until the flood of 2019 proved them right.","options":["turned a deaf ear","were all ears","fell on deaf ears","played it by ear"],"correct":2,"answer":"fell on deaf ears","vi":"Suốt ba năm, những cảnh báo của các kỹ sư rằng đập tràn đang nứt đều bị bỏ ngoài tai, cho đến khi trận lũ năm 2019 chứng minh họ đúng.","explanation":"The subject is <b>the engineers' warnings</b> (a thing, not a person) and they were ignored, so <b>fell on deaf ears</b> = were not listened to.<br>✗ <b>turned a deaf ear</b> — a person turns a deaf ear to advice; the ignorer is the subject; ✗ <b>were all ears</b> — listened eagerly, the opposite meaning; ✗ <b>played it by ear</b> — improvised without a plan, needs a person as subject."},{"id":"gv-ch-33-16","level":"ch","focus":"phrasal-verb","q":"The editorial ______ an independent inquiry into the grid failure, arguing that the ministry could not investigate itself.","options":["called off","called up","called out","called for"],"correct":3,"answer":"called for","vi":"Bài xã luận kêu gọi một cuộc điều tra độc lập về sự cố lưới điện, lập luận rằng bộ không thể tự điều tra chính mình.","explanation":"The editorial publicly demanded an inquiry, so <b>call for</b> = demand that something be done; the clue is <b>arguing that the ministry could not investigate itself</b>.<br>✗ <b>called off</b> — cancelled; an editorial cannot cancel an inquiry; ✗ <b>called up</b> — telephoned or summoned for military service; ✗ <b>called out</b> — criticised someone publicly or shouted; you call out a person, not an inquiry."},{"id":"gv-ch-33-17","level":"ch","focus":"word-choice","q":"The scan revealed a ______ tumour, so the poet cancelled his reading tour to begin chemotherapy at once.","options":["malignant","malicious","malevolent","malign"],"correct":0,"answer":"malignant","vi":"Kết quả chụp cho thấy một khối u ác tính, nên nhà thơ hủy chuyến lưu diễn đọc thơ để bắt đầu hóa trị ngay lập tức.","explanation":"A cancerous tumour needing <b>chemotherapy at once</b> is <b>malignant</b> (opposite: benign), the medical term.<br>✗ <b>malicious</b> — intending to hurt (malicious gossip), describes people or actions; ✗ <b>malevolent</b> — wishing evil on others, a person's character; ✗ <b>malign</b> — as an adjective means harmful in influence (a malign effect), not a medical word for a tumour."},{"id":"gv-ch-33-18","level":"ch","focus":"linking","q":"The pipeline was completed on schedule; ______, it ended up costing nearly twice the original estimate.","options":["whereas","however","despite","although"],"correct":1,"answer":"however","vi":"Đường ống được hoàn thành đúng tiến độ; tuy nhiên, chi phí cuối cùng gần gấp đôi dự toán ban đầu.","explanation":"The gap sits between a semicolon and a comma (<b>schedule; ______, it</b>), a slot only a linking adverb can fill: <b>however</b> = but, a contrast.<br>✗ <b>whereas</b> — a conjunction, must join two clauses directly (X, whereas Y), cannot follow a semicolon; ✗ <b>although</b> — also a conjunction, introduces a clause with no comma straight after it; ✗ <b>despite</b> — a preposition, needs a noun or -ing (despite the schedule), not a clause."},{"id":"gv-ch-33-19","level":"ch","focus":"participle","q":"______ entirely from recycled glass, the installation changes colour as the sun moves across the gallery.","options":["Making","Having made","Made","To make"],"correct":2,"answer":"Made","vi":"Được làm hoàn toàn từ thủy tinh tái chế, tác phẩm sắp đặt đổi màu khi mặt trời di chuyển ngang phòng trưng bày.","explanation":"The installation <b>is made</b> from glass — it does not make anything — so the reduced relative clause is passive and needs the past participle <b>Made</b>.<br>✗ <b>Making</b> — active present participle, would mean the installation makes something; ✗ <b>Having made</b> — active perfect participle, same wrong meaning plus an earlier completed action; ✗ <b>To make</b> — infinitive of purpose (in order to make), not a description."},{"id":"gv-ch-33-20","level":"ch","focus":"idiom","q":"Residents ______ to stop the coal-fired plant being built on the edge of the wetland, and in the end they won.","options":["fought shy","fought like cat and dog","picked a fight","fought tooth and nail"],"correct":3,"answer":"fought tooth and nail","vi":"Người dân đã đấu tranh quyết liệt để ngăn nhà máy nhiệt điện than được xây ở rìa vùng đất ngập nước, và cuối cùng họ đã thắng.","explanation":"The residents struggled fiercely against the plant and <b>in the end they won</b>, so <b>fought tooth and nail</b> = fought with every possible effort.<br>✗ <b>fought shy</b> — fight shy of = avoid something, the opposite; ✗ <b>fought like cat and dog</b> — two people who quarrel constantly, not a campaign; ✗ <b>picked a fight</b> — deliberately started a quarrel, and does not take <b>to stop</b>."},{"id":"gv-ch-33-21","level":"ch","focus":"double-blank","q":"The new arts centre ______ for audiences ______ tastes range from opera to hip-hop.","options":["caters / whose","calls / who","provides / which","serves / whom"],"correct":0,"answer":"caters / whose","vi":"Trung tâm nghệ thuật mới phục vụ những khán giả có gu thưởng thức trải dài từ opera đến hip-hop.","explanation":"<b>Cater for</b> = provide what a particular group wants, and the possessive relative <b>whose</b> links <b>audiences</b> to their <b>tastes</b>.<br>✗ <b>calls / who</b> — call for means demand, and who cannot be followed directly by the noun tastes; ✗ <b>provides / which</b> — provide for means support financially, and which is for things, not possession; ✗ <b>serves / whom</b> — serve takes a direct object with no <b>for</b>, and whom is an object pronoun, not possessive."},{"id":"gv-ch-33-22","level":"ch","focus":"conditional","q":"______ the emergency generators, the newsroom would have gone dark in the middle of the election broadcast.","options":["If it hadn't been","Had it not been for","Were it not for","Unless there were"],"correct":1,"answer":"Had it not been for","vi":"Nếu không nhờ các máy phát điện dự phòng, phòng tin đã chìm trong bóng tối ngay giữa buổi phát sóng bầu cử.","explanation":"The result <b>would have gone dark</b> is past unreal (third conditional), so the condition must be past too: the inverted <b>Had it not been for</b> = if the generators had not existed.<br>✗ <b>If it hadn't been</b> — right tense but missing the essential <b>for</b> before the noun; ✗ <b>Were it not for</b> — present/future unreal (second conditional), mismatches would have gone; ✗ <b>Unless there were</b> — present unreal, and unless does not pair with a would-have result."},{"id":"gv-ch-33-23","level":"ch","focus":"word-choice","q":"The condition is ______, passed from parent to child through a faulty gene, rather than caught from anyone the patient has met.","options":["contagious","congenital","hereditary","infectious"],"correct":2,"answer":"hereditary","vi":"Căn bệnh này mang tính di truyền, truyền từ cha mẹ sang con qua một gen lỗi, chứ không phải lây từ bất kỳ ai bệnh nhân từng gặp.","explanation":"The clue <b>passed from parent to child through a faulty gene</b> defines <b>hereditary</b> = inherited genetically.<br>✗ <b>contagious</b> — spread by contact with a sick person, ruled out by <b>rather than caught from anyone</b>; ✗ <b>infectious</b> — spread by germs from person to person, same problem; ✗ <b>congenital</b> — present from birth but not necessarily inherited (it can arise in the womb), so it misses the gene clue."},{"id":"gv-ch-33-24","level":"ch","focus":"gerund-infinitive","q":"The volcanologist says she will never ______ the lava fountain burst through the crater floor on her first field trip to Iceland.","options":["forget to see","forget seeing","forget to have seen","forget being seen"],"correct":1,"answer":"forget seeing","vi":"Nhà nghiên cứu núi lửa nói rằng cô sẽ không bao giờ quên cảnh cột dung nham phun trào qua đáy miệng núi lửa trong chuyến thực địa đầu tiên ở Iceland.","explanation":"<b>Forget + -ing</b> = lose the memory of something that already happened; the eruption was on <b>her first field trip</b>, a past event, so <b>forget seeing</b>.<br>✗ <b>forget to see</b> — forget + to-infinitive = fail to do something you should do, not a memory; ✗ <b>forget to have seen</b> — the perfect infinitive is not used after forget; ✗ <b>forget being seen</b> — passive: she would be the one seen, but she saw the lava."},{"id":"gv-ch-33-25","level":"ch","focus":"collocation","q":"Years of rotating night shifts at the refinery ______ a heavy toll on the workers' health.","options":["took","paid","made","had"],"correct":0,"answer":"took","vi":"Nhiều năm làm ca đêm luân phiên ở nhà máy lọc dầu đã gây tổn hại nặng nề đến sức khỏe của công nhân.","explanation":"The fixed collocation for causing serious harm is <b>take a toll on</b>: the shifts <b>took a heavy toll on</b> the workers' health.<br>✗ <b>paid</b> — you pay a toll only literally, money at a toll gate; ✗ <b>made</b> — make does not combine with toll; ✗ <b>had</b> — have a toll is not an English expression."},{"id":"gv-ch-34-1","level":"ch","focus":"word-choice","q":"Players who fail to ______ by the anti-doping code face an automatic two-year suspension.","options":["observe","abide","obey","conform"],"correct":1,"answer":"abide","vi":"Những vận động viên không tuân thủ bộ quy tắc chống doping sẽ bị treo giò tự động hai năm.","explanation":"Only <b>abide</b> takes the preposition <b>by</b> already in the sentence (abide by a rule = follow it). ✗ <b>observe</b> — observe a code takes a direct object, no by; ✗ <b>obey</b> — obey the code, also a direct object; ✗ <b>conform</b> — needs to (conform to the code), not by."},{"id":"gv-ch-34-2","level":"ch","focus":"idiom","q":"The minister's proposal to ban foreign words from state broadcasts ______ in parliament, with members of her own party voting against it.","options":["went down in flames","went through the roof","went off the rails","went under the hammer"],"correct":0,"answer":"went down in flames","vi":"Đề xuất cấm từ ngoại lai trên đài phát thanh nhà nước của bà bộ trưởng đã thất bại thảm hại ở quốc hội, khi chính các nghị sĩ đảng bà bỏ phiếu chống.","explanation":"<b>Go down in flames</b> = fail spectacularly and publicly — the clue is <b>her own party voting against it</b>. ✗ <b>went through the roof</b> — rose sharply (prices, tempers); ✗ <b>went off the rails</b> — lost control, went badly wrong (a person, a plan); ✗ <b>went under the hammer</b> — was sold at auction."},{"id":"gv-ch-34-3","level":"ch","focus":"passive","q":"The bill ______ by the president twice before a revised version finally became law.","options":["was vetoing","had vetoed","had been vetoed","has been vetoed"],"correct":2,"answer":"had been vetoed","vi":"Dự luật đã bị tổng thống phủ quyết hai lần trước khi phiên bản sửa đổi cuối cùng trở thành luật.","explanation":"The bill receives the action, so the passive is needed, and the vetoes happened before a past event (<b>before … became law</b>): past perfect passive <b>had been vetoed</b>. ✗ <b>was vetoing</b> — active, the bill would be doing the vetoing; ✗ <b>had vetoed</b> — active too, but <b>by the president</b> shows the bill is the object; ✗ <b>has been vetoed</b> — present perfect links to now, but the whole sequence is in the past."},{"id":"gv-ch-34-4","level":"ch","focus":"collocation","q":"Having promised deep tax cuts, the opposition cruised to a ______ victory in the general election.","options":["avalanche","earthquake","mudslide","landslide"],"correct":3,"answer":"landslide","vi":"Sau khi hứa cắt giảm mạnh thuế, phe đối lập đã giành chiến thắng áp đảo trong cuộc tổng tuyển cử.","explanation":"<b>Landslide victory</b> is the fixed collocation for winning by a huge margin — the clue is <b>cruised to</b>, an easy win. ✗ <b>avalanche</b> — a snow slide; figuratively only a flood of things (an avalanche of complaints); ✗ <b>earthquake</b> — a shock or upheaval, not a margin of victory; ✗ <b>mudslide</b> — purely literal, never pairs with victory."},{"id":"gv-ch-34-5","level":"ch","focus":"phrasal-verb","q":"Campaigners who try to replace legal jargon with plain English soon ______ centuries of professional tradition.","options":["come round to","come up against","come in for","come down with"],"correct":1,"answer":"come up against","vi":"Những người vận động thay thế thuật ngữ pháp lý bằng tiếng Anh giản dị sớm vấp phải truyền thống nghề nghiệp hàng thế kỷ.","explanation":"<b>Come up against</b> = meet an obstacle or opposition — <b>centuries of professional tradition</b> is what blocks them. ✗ <b>come round to</b> — gradually accept an idea; ✗ <b>come in for</b> — receive (criticism, praise); ✗ <b>come down with</b> — fall ill with (flu, a cold)."},{"id":"gv-ch-34-6","level":"ch","focus":"modal","q":"The assistant referee ______ his flag so hastily: the replay showed the striker was a yard onside.","options":["can't have raised","mustn't have raised","needn't have raised","might not have raised"],"correct":2,"answer":"needn't have raised","vi":"Trợ lý trọng tài lẽ ra không cần phất cờ vội vàng đến thế: pha quay chậm cho thấy tiền đạo đã đứng trên việt vị cả mét.","explanation":"<b>Needn't have + past participle</b> = he did it, but it was unnecessary — he did raise the flag (<b>so hastily</b>), and the replay shows it was pointless. ✗ <b>can't have raised</b> — deduction that he did not raise it, but he did; ✗ <b>mustn't have raised</b> — also a deduction that he didn't do it (and not used for past deduction in British English); ✗ <b>might not have raised</b> — doubt about whether he raised it, but we know he did."},{"id":"gv-ch-34-7","level":"ch","focus":"word-choice","q":"To encourage younger competitors, the federation agreed to ______ the entry fee for athletes under eighteen.","options":["waive","revoke","repeal","annul"],"correct":0,"answer":"waive","vi":"Để khuyến khích các vận động viên trẻ, liên đoàn đồng ý miễn lệ phí đăng ký cho những người dưới mười tám tuổi.","explanation":"<b>Waive</b> = choose not to demand a fee or right you are entitled to — the clue is <b>the entry fee</b>. ✗ <b>revoke</b> — officially take back a licence or permission; ✗ <b>repeal</b> — cancel a law; ✗ <b>annul</b> — declare a marriage or contract invalid."},{"id":"gv-ch-34-8","level":"ch","focus":"inversion","q":"______ has a scientific paper attracted so much public attention as the study linking teenagers' screen time to loss of sleep.","options":["Not until","Rarely","Only when","Little"],"correct":1,"answer":"Rarely","vi":"Hiếm khi một bài báo khoa học lại thu hút nhiều sự chú ý của công chúng đến thế như nghiên cứu liên hệ thời gian dùng màn hình của thanh thiếu niên với tình trạng mất ngủ.","explanation":"A fronted negative adverb forces subject–verb inversion (<b>has a scientific paper attracted</b>), and <b>Rarely</b> pairs with <b>so much … as</b>. ✗ <b>Not until</b> — needs a time expression first (Not until 2020 has …); ✗ <b>Only when</b> — needs a full clause before the inverted part; ✗ <b>Little</b> — inverts only with verbs of knowing (Little did they realise), not with attract."},{"id":"gv-ch-34-9","level":"ch","focus":"idiom","q":"Rather than argue with the coaching staff, the young striker decided to ______ and accept his new role on the wing.","options":["go by the book","go with the flow","go against the grain","go the extra mile"],"correct":1,"answer":"go with the flow","vi":"Thay vì tranh cãi với ban huấn luyện, tiền đạo trẻ quyết định thuận theo tình hình và chấp nhận vai trò mới ở biên.","explanation":"<b>Go with the flow</b> = accept what is happening without resisting — the clue is <b>rather than argue … accept his new role</b>. ✗ <b>go by the book</b> — follow the rules strictly; ✗ <b>go against the grain</b> — do what feels unnatural, the opposite of normal; ✗ <b>go the extra mile</b> — make extra effort."},{"id":"gv-ch-34-10","level":"ch","focus":"double-blank","q":"Once the chair had ______ with the roll call, the committee ______ straight to the vote.","options":["disposed / preceded","dispensed / preceded","dispensed / proceeded","disposed / proceeded"],"correct":2,"answer":"dispensed / proceeded","vi":"Sau khi chủ tọa bỏ qua thủ tục điểm danh, ủy ban chuyển thẳng sang bỏ phiếu.","explanation":"<b>Dispense with</b> = do without, skip (the roll call), and <b>proceed to</b> = move on to (the vote). ✗ <b>disposed / preceded</b> — dispose of = throw away, and precede = come before; ✗ <b>dispensed / preceded</b> — precede takes a direct object (precede the vote) and means come before, not move on; ✗ <b>disposed / proceeded</b> — dispose takes of, not with, and means get rid of."},{"id":"gv-ch-34-11","level":"ch","focus":"word-choice","q":"Anti-corruption laws are only as effective as the authorities' willingness to ______ them.","options":["enforce","enact","ratify","legislate"],"correct":0,"answer":"enforce","vi":"Luật chống tham nhũng chỉ hiệu quả ngang với mức độ sẵn sàng thực thi chúng của nhà chức trách.","explanation":"<b>Enforce</b> = make people obey a law that already exists — the laws <b>are</b> already in place, so the question is whether they are applied. ✗ <b>enact</b> — pass a law, make it official; ✗ <b>ratify</b> — formally approve a treaty or agreement; ✗ <b>legislate</b> — make laws, and it does not take them as an object (legislate on/for)."},{"id":"gv-ch-34-12","level":"ch","focus":"agreement","q":"Neither the head coach nor the players ______ willing to comment on the leaked dressing-room footage.","options":["was","is","has been","were"],"correct":3,"answer":"were","vi":"Cả huấn luyện viên trưởng lẫn các cầu thủ đều không muốn bình luận về đoạn phim phòng thay đồ bị rò rỉ.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, the plural <b>players</b>, so <b>were</b>. ✗ <b>was</b> — singular, would only agree with the further subject coach; ✗ <b>is</b> — singular, the nearer subject is plural; ✗ <b>has been</b> — singular as well."},{"id":"gv-ch-34-13","level":"ch","focus":"collocation","q":"The new commissioner has promised ______ reforms of the way doping cases are investigated.","options":["brushing","sweeping","wiping","mopping"],"correct":1,"answer":"sweeping","vi":"Tân cao ủy hứa hẹn những cải cách sâu rộng về cách điều tra các vụ doping.","explanation":"<b>Sweeping reforms/changes</b> = wide-ranging, affecting everything — the fixed collocation with <b>reforms</b>. ✗ <b>brushing</b> — light touching or cleaning, no figurative use; ✗ <b>wiping</b> — cleaning a surface (wipe out is a different idiom); ✗ <b>mopping</b> — cleaning a floor (mop up = finish off), never used with reforms."},{"id":"gv-ch-34-14","level":"ch","focus":"phrasal-verb","q":"It only ______ the commentators afterwards that the referee had misapplied the offside rule.","options":["dwelt on","hit on","dawned on","touched on"],"correct":2,"answer":"dawned on","vi":"Mãi sau đó các bình luận viên mới nhận ra rằng trọng tài đã áp dụng sai luật việt vị.","explanation":"<b>It dawns on someone that</b> = they gradually realise — the clue is the empty-it pattern <b>It only … afterwards that</b>. ✗ <b>dwelt on</b> — kept thinking or talking about, and needs a person as subject; ✗ <b>hit on</b> — suddenly thought of (an idea), person as subject; ✗ <b>touched on</b> — mentioned briefly, person as subject."},{"id":"gv-ch-34-15","level":"ch","focus":"linking","q":"______ the referee's lengthy explanation, the home fans remained convinced they had been robbed.","options":["Notwithstanding","Nevertheless","Although","Whereas"],"correct":0,"answer":"Notwithstanding","vi":"Bất chấp lời giải thích dài dòng của trọng tài, cổ động viên chủ nhà vẫn tin chắc họ đã bị cướp mất chiến thắng.","explanation":"A noun phrase follows (<b>the referee's lengthy explanation</b>), so a preposition is needed: <b>Notwithstanding</b> = despite. ✗ <b>Nevertheless</b> — an adverb that links two sentences, cannot govern a noun; ✗ <b>Although</b> — a conjunction, needs a subject and verb; ✗ <b>Whereas</b> — also needs a clause, and contrasts two facts rather than conceding one."},{"id":"gv-ch-34-16","level":"ch","focus":"idiom","q":"With two minutes left and the champions a goal down, their unbeaten record was ______.","options":["hanging in the air","hanging out to dry","hanging on every word","hanging by a thread"],"correct":3,"answer":"hanging by a thread","vi":"Còn hai phút, đội đương kim vô địch đang bị dẫn một bàn, thành tích bất bại của họ đang treo trên sợi tóc.","explanation":"<b>Hang by a thread</b> = be in a very precarious position — the clue is <b>two minutes left … a goal down</b>. ✗ <b>hanging in the air</b> — left unresolved, unanswered; ✗ <b>hanging out to dry</b> — abandoned to take the blame; ✗ <b>hanging on every word</b> — listening eagerly to a speaker."},{"id":"gv-ch-34-17","level":"ch","focus":"subjunctive","q":"It is high time the federation ______ its outdated rules on which nationality an athlete may represent.","options":["revise","revised","revises","has revised"],"correct":1,"answer":"revised","vi":"Đã đến lúc liên đoàn phải sửa đổi các quy định lỗi thời về việc vận động viên được đại diện cho quốc tịch nào.","explanation":"<b>It is high time</b> is followed by a past-tense form with present meaning (unreal past): <b>revised</b>. ✗ <b>revise</b> — bare form; that would follow it is time for the federation to; ✗ <b>revises</b> — present simple is not used after it is (high) time; ✗ <b>has revised</b> — present perfect, wrong form for this structure."},{"id":"gv-ch-34-18","level":"ch","focus":"word-choice","q":"Broadcasting the interview before the trial would ______ the reporting restrictions imposed by the court.","options":["offend","trespass","contravene","overrule"],"correct":2,"answer":"contravene","vi":"Phát sóng cuộc phỏng vấn trước phiên tòa sẽ vi phạm các hạn chế đưa tin do tòa án áp đặt.","explanation":"<b>Contravene</b> = act against a rule or law, and it takes a direct object (<b>the reporting restrictions</b>). ✗ <b>offend</b> — needs against (offend against the rules), or means upset a person; ✗ <b>trespass</b> — needs on/against (trespass on land); ✗ <b>overrule</b> — reverse a decision, which only a higher court can do, not a broadcaster."},{"id":"gv-ch-34-19","level":"ch","focus":"comparison","q":"The more technical the wording of a contract, ______ an ordinary citizen is to understand it.","options":["the less likely","less likely","the least likely","the less likelier"],"correct":0,"answer":"the less likely","vi":"Câu chữ hợp đồng càng chuyên môn thì người dân bình thường càng ít có khả năng hiểu được nó.","explanation":"The double comparative <b>the more …, the less …</b> needs <b>the</b> in both halves, and <b>The more technical</b> sets the pattern. ✗ <b>less likely</b> — missing the; ✗ <b>the least likely</b> — superlative, not a comparative; ✗ <b>the less likelier</b> — likelier is already comparative, so less makes a double comparative."},{"id":"gv-ch-34-20","level":"ch","focus":"collocation","q":"The club has ______ an appeal against the six-point deduction with the league's independent panel.","options":["placed","put","laid","lodged"],"correct":3,"answer":"lodged","vi":"Câu lạc bộ đã nộp đơn kháng cáo lên hội đồng độc lập của giải đấu phản đối việc bị trừ sáu điểm.","explanation":"<b>Lodge an appeal/complaint</b> is the fixed legal collocation for formally submitting one, matched by <b>with the … panel</b>. ✗ <b>placed</b> — place an order/bet, not an appeal; ✗ <b>put</b> — only works as put in an appeal, and in is missing; ✗ <b>laid</b> — lay charges/blame, not an appeal."},{"id":"gv-ch-34-21","level":"ch","focus":"gerund-infinitive","q":"The party leader is reported ______ the coalition offer at a private meeting late last night.","options":["to reject","to have rejected","rejecting","having rejected"],"correct":1,"answer":"to have rejected","vi":"Lãnh đạo đảng được cho là đã bác bỏ đề nghị liên minh tại một cuộc gặp riêng khuya qua.","explanation":"After <b>be reported/said/believed</b>, an action earlier than the report takes the perfect infinitive: <b>to have rejected</b> — the clue is <b>late last night</b>. ✗ <b>to reject</b> — present or future action, clashes with last night; ✗ <b>rejecting</b> — this passive pattern takes a to-infinitive, not -ing; ✗ <b>having rejected</b> — perfect -ing form, again not the pattern after is reported."},{"id":"gv-ch-34-22","level":"ch","focus":"idiom","q":"The press officer ______ fielding calls from reporters once the memo had been leaked.","options":["had her hands tied","had her heart in her mouth","had her hands full","had her feet on the ground"],"correct":2,"answer":"had her hands full","vi":"Nữ cán bộ báo chí bận tối mắt tối mũi trả lời các cuộc gọi từ phóng viên khi bản ghi nhớ bị rò rỉ.","explanation":"<b>Have your hands full</b> = be extremely busy — the clue is <b>fielding calls</b> nonstop. ✗ <b>had her hands tied</b> — was unable to act; ✗ <b>had her heart in her mouth</b> — was very nervous; ✗ <b>had her feet on the ground</b> — was sensible and realistic."},{"id":"gv-ch-34-23","level":"ch","focus":"participle","q":"______ in plain English rather than legal jargon, the new tenancy agreement can be understood without a lawyer.","options":["Written","Writing","Having written","To write"],"correct":0,"answer":"Written","vi":"Được viết bằng tiếng Anh giản dị thay vì thuật ngữ pháp lý, hợp đồng thuê nhà mới có thể hiểu được mà không cần luật sư.","explanation":"The agreement is written by someone, so the reduced clause is passive: past participle <b>Written</b> (= Because it is written …). ✗ <b>Writing</b> — active, would make the agreement the writer; ✗ <b>Having written</b> — active perfect, same problem; ✗ <b>To write</b> — infinitive of purpose, does not describe the agreement."},{"id":"gv-ch-34-24","level":"ch","focus":"word-choice","q":"The High Court ______ the conviction after new evidence showed the confession had been obtained under duress.","options":["squashed","crushed","smashed","quashed"],"correct":3,"answer":"quashed","vi":"Tòa án Tối cao đã hủy bản án sau khi bằng chứng mới cho thấy lời thú tội được lấy dưới sự cưỡng ép.","explanation":"<b>Quash</b> is the legal verb for officially cancelling a conviction or decision — the clue is <b>the High Court … the conviction</b>. ✗ <b>squashed</b> — flattened; informally only suppressed (a rumour); ✗ <b>crushed</b> — physically broken or defeated (crush a rebellion); ✗ <b>smashed</b> — broken into pieces."},{"id":"gv-ch-34-25","level":"ch","focus":"double-blank","q":"Small clubs and wealthy giants alike are ______ the same ______ when it comes to the new salary cap.","options":["on / ship","in / ship","in / boat","on / boat"],"correct":2,"answer":"in / boat","vi":"Các câu lạc bộ nhỏ lẫn các đại gia giàu có đều cùng chung cảnh ngộ khi nói đến mức trần lương mới.","explanation":"<b>In the same boat</b> = in the same difficult situation — the clue is <b>alike … the same</b>. ✗ <b>on / ship</b> — wrong preposition and wrong noun; ✗ <b>in / ship</b> — the idiom is fixed with boat, not ship; ✗ <b>on / boat</b> — on a boat is literal; the idiom takes in."},{"id":"gv-ch-35-1","level":"ch","focus":"word-choice","q":"Witnesses caught only a ______ glimpse of the getaway driver before the car sped off down the alley.","options":["temporary","interim","fleeting","provisional"],"correct":2,"answer":"fleeting","vi":"Các nhân chứng chỉ thoáng thấy tài xế xe tẩu thoát trong chốc lát trước khi chiếc xe lao vụt xuống con hẻm.","explanation":"Word choice: the clue is <b>only a … glimpse … before the car sped off</b> — a look lasting a split second, so <b>fleeting</b> (passing very quickly) fits. ✗ <b>temporary</b> — lasting a limited time, said of jobs or fixes, not a glimpse; ✗ <b>interim</b> — filling the gap until something permanent (an interim manager); ✗ <b>provisional</b> — arranged for now but likely to change (a provisional booking)."},{"id":"gv-ch-35-2","level":"ch","focus":"idiom","q":"New officers seldom ______ before their second year, so each is paired with a veteran detective until then.","options":["know the ropes","pull the strings","call the shots","hold the fort"],"correct":0,"answer":"know the ropes","vi":"Cảnh sát mới hiếm khi nắm vững công việc trước năm thứ hai, nên mỗi người được ghép cặp với một thám tử kỳ cựu cho đến lúc đó.","explanation":"Idiom: <b>know the ropes</b> = understand how a job is done; the clue is <b>paired with a veteran … until then</b> — the new officers still need guidance. ✗ <b>pull the strings</b> — secretly control what happens; ✗ <b>call the shots</b> — be the one who makes the decisions; ✗ <b>hold the fort</b> — look after things while the person in charge is away. None describes learning a job."},{"id":"gv-ch-35-3","level":"ch","focus":"collocation","q":"After three days of deliberation the jury was still unable to ______ a verdict.","options":["arrive","reach","make","come"],"correct":1,"answer":"reach","vi":"Sau ba ngày nghị án, bồi thẩm đoàn vẫn không thể đưa ra được phán quyết.","explanation":"Collocation: a jury <b>reaches a verdict</b>; the blank is followed directly by <b>a verdict</b> with no preposition, so the verb must be transitive. ✗ <b>arrive</b> — needs <i>at</i>: <i>arrive at a verdict</i>; ✗ <b>come</b> — needs <i>to</i>: <i>come to a verdict</i>; ✗ <b>make</b> — you <i>make a decision</i>, but a verdict is <i>reached</i>, <i>returned</i> or <i>delivered</i>, never made."},{"id":"gv-ch-35-4","level":"ch","focus":"modal","q":"The accused ______ the getaway car that night — he was already in police custody.","options":["mustn't have driven","needn't have driven","shouldn't have driven","can't have driven"],"correct":3,"answer":"can't have driven","vi":"Bị cáo không thể nào đã lái chiếc xe tẩu thoát đêm đó — lúc ấy anh ta đã bị cảnh sát tạm giữ rồi.","explanation":"Past deduction: the clue <b>he was already in police custody</b> makes the action impossible, so <b>can't have driven</b> (I am sure he did not). ✗ <b>mustn't have driven</b> — <i>must have</i> deduces that something DID happen; its negative for deduction is <i>can't have</i>, not <i>mustn't have</i>; ✗ <b>needn't have driven</b> — he drove, but it was unnecessary; ✗ <b>shouldn't have driven</b> — he drove, and it was a mistake."},{"id":"gv-ch-35-5","level":"ch","focus":"word-choice","q":"The rain was ______ all afternoon, stopping and starting so often that the flood sirens were tested three times.","options":["chronic","intermittent","perennial","interim"],"correct":1,"answer":"intermittent","vi":"Mưa rơi ngắt quãng suốt buổi chiều, ngừng rồi lại rơi thường xuyên đến mức còi báo lũ được thử tới ba lần.","explanation":"Word choice: the clue <b>stopping and starting so often</b> defines <b>intermittent</b> (happening at irregular intervals, not continuously). ✗ <b>chronic</b> — lasting a long time and hard to cure (a chronic illness, chronic unemployment); ✗ <b>perennial</b> — lasting or returning year after year (a perennial problem); ✗ <b>interim</b> — temporary until something permanent replaces it (an interim government), used of arrangements, not rain."},{"id":"gv-ch-35-6","level":"ch","focus":"inversion","q":"Only after the river had burst its banks twice ______ to fund the dredging work.","options":["the council agreed","the council did agree","did the council agree","had the council agreed"],"correct":2,"answer":"did the council agree","vi":"Chỉ sau khi con sông đã tràn bờ hai lần, hội đồng thành phố mới đồng ý cấp kinh phí nạo vét.","explanation":"Inversion: when a sentence opens with <b>Only after + clause</b>, the main clause takes question order — auxiliary before subject: <b>did the council agree</b>. ✗ <b>the council agreed</b> — normal order is not allowed after a fronted <i>Only after…</i>; ✗ <b>the council did agree</b> — has the auxiliary but no inversion (subject still first); ✗ <b>had the council agreed</b> — inverted, but past perfect belongs to the earlier action (<i>had burst</i>); the agreeing came later, so simple past."},{"id":"gv-ch-35-7","level":"ch","focus":"phrasal-verb","q":"With no savings to ______, the evicted family spent the winter sleeping in their car.","options":["fall back on","fall behind with","fall in with","fall out with"],"correct":0,"answer":"fall back on","vi":"Không có khoản tiết kiệm nào để dựa vào, gia đình bị đuổi khỏi nhà phải ngủ trong xe suốt mùa đông.","explanation":"Phrasal verb: <b>fall back on</b> = rely on something kept in reserve when nothing else is left; the clue is <b>no savings</b> as a safety net. ✗ <b>fall behind with</b> — fail to keep up with payments or work (<i>fall behind with the rent</i>); ✗ <b>fall in with</b> — start mixing with a group, or agree to a plan; ✗ <b>fall out with</b> — quarrel and stop being friends with someone."},{"id":"gv-ch-35-8","level":"ch","focus":"double-blank","q":"For decades the old seawall has ______ the rising tide ______ bay, but engineers now doubt it can survive another winter.","options":["held / in","put / to","set / from","kept / at"],"correct":3,"answer":"kept / at","vi":"Suốt hàng chục năm, bức tường chắn sóng cũ đã ngăn được thủy triều dâng, nhưng nay các kỹ sư nghi ngờ nó có thể trụ thêm một mùa đông nữa.","explanation":"Idiom: <b>keep something at bay</b> = stop something dangerous from coming closer; the clue is a <b>seawall</b> holding back the <b>rising tide</b>, and <i>has kept</i> shows a long-running effort. ✗ <b>held / in</b> — <i>hold in</i> means restrain a feeling; <i>in bay</i> is not an expression; ✗ <b>put / to</b> — <i>put to</i> pairs with <i>use</i>, <i>the test</i>, <i>bed</i>, never <i>bay</i>; ✗ <b>set / from</b> — <i>set … from bay</i> exists in no idiom."},{"id":"gv-ch-35-9","level":"ch","focus":"subjunctive","q":"It is high time the city ______ its century-old sewers instead of patching them every monsoon.","options":["replaces","replaced","will replace","has replaced"],"correct":1,"answer":"replaced","vi":"Đã đến lúc thành phố phải thay hệ thống cống trăm năm tuổi thay vì cứ vá víu mỗi mùa mưa.","explanation":"Unreal past: after <b>It is high time</b> the verb takes the past subjunctive to say something should already be happening — <b>replaced</b> refers to now, not the past; the clue <b>instead of patching them every monsoon</b> shows the change is overdue. ✗ <b>replaces</b> — present simple is not used after <i>high time</i>; ✗ <b>will replace</b> — no future form after <i>high time</i>; ✗ <b>has replaced</b> — present perfect would mean the sewers are already done, contradicting <i>patching</i>."},{"id":"gv-ch-35-10","level":"ch","focus":"word-choice","q":"Warnings of the ______ storm surge sent thousands of residents inland before nightfall.","options":["impending","eventual","forthcoming","subsequent"],"correct":0,"answer":"impending","vi":"Những cảnh báo về đợt nước dâng do bão sắp ập đến khiến hàng nghìn cư dân đổ vào đất liền trước khi trời tối.","explanation":"Word choice: <b>impending</b> = about to happen, usually something threatening; the clues are <b>warnings</b> and residents fleeing <b>before nightfall</b>. ✗ <b>eventual</b> — happening at the end of a long process (<i>the eventual winner</i>), no sense of danger; ✗ <b>forthcoming</b> — scheduled and expected (<i>the forthcoming election</i>), neutral, not threatening; ✗ <b>subsequent</b> — coming after something already mentioned, but no earlier event is given here."},{"id":"gv-ch-35-11","level":"ch","focus":"idiom","q":"Coastal towns that ignored the flood warnings ______ that a seawall costs far less than a rebuild.","options":["took a hard line","played hardball","learned the hard way","had a hard time"],"correct":2,"answer":"learned the hard way","vi":"Những thị trấn ven biển phớt lờ cảnh báo lũ đã phải trả giá đắt để hiểu rằng xây tường chắn sóng rẻ hơn nhiều so với xây dựng lại.","explanation":"Idiom: <b>learn the hard way</b> = find something out through a painful experience, and it can take a <b>that</b>-clause; the clue is towns that <b>ignored the warnings</b> and paid for it. ✗ <b>took a hard line</b> — adopted a strict, unbending attitude, and cannot be followed by <i>that…</i>; ✗ <b>played hardball</b> — acted aggressively to get their way, no <i>that</i>-clause; ✗ <b>had a hard time</b> — struggled, followed by <i>-ing</i> or <i>with</i>, not <i>that</i>."},{"id":"gv-ch-35-12","level":"ch","focus":"participle","q":"______ the sheer volume of complaints, the new bus timetable has satisfied almost no one.","options":["Judged from","Judge from","Judging from","Having been judged from"],"correct":2,"answer":"Judging from","vi":"Xét từ số lượng khiếu nại khổng lồ, lịch chạy xe buýt mới hầu như chẳng làm hài lòng ai.","explanation":"Participle phrase: <b>judging from</b> (= if one goes by) is a fixed expression whose understood subject is the speaker, who does the judging, so the active <i>-ing</i> form is used regardless of the main subject. ✗ <b>Judged from</b> — passive would make <i>the timetable</i> the thing judged; ✗ <b>Having been judged from</b> — passive and perfect, same problem; ✗ <b>Judge from</b> — a bare verb cannot open a participle clause."},{"id":"gv-ch-35-13","level":"ch","focus":"collocation","q":"The documentary set out to ______ public awareness of the smog choking the capital every winter.","options":["rise","lift","grow","raise"],"correct":3,"answer":"raise","vi":"Bộ phim tài liệu nhằm nâng cao nhận thức của công chúng về màn sương mù ô nhiễm bao trùm thủ đô mỗi mùa đông.","explanation":"Collocation: <b>raise awareness</b> is the fixed pairing; the clue is the object <b>public awareness</b> right after the blank, so a transitive verb is needed. ✗ <b>rise</b> — intransitive, cannot take an object (<i>awareness rises</i>, but you cannot <i>rise awareness</i>); ✗ <b>lift</b> — collocates with <i>a ban</i>, <i>spirits</i>, <i>restrictions</i>, not <i>awareness</i>; ✗ <b>grow</b> — you <i>grow crops</i> or <i>a business</i>; awareness is <i>raised</i>."},{"id":"gv-ch-35-14","level":"ch","focus":"reported","q":"The housing inspector asked the tenant how long ______ in the damp basement flat.","options":["she had been living","had she been living","she has been living","has she been living"],"correct":0,"answer":"she had been living","vi":"Thanh tra nhà ở hỏi người thuê rằng cô ấy đã sống trong căn hộ tầng hầm ẩm thấp đó bao lâu rồi.","explanation":"Reported question: after <b>asked … how long</b> the clause keeps statement order and the tense shifts back one step, so <b>she had been living</b> (past perfect continuous). ✗ <b>had she been living</b> — inverted; question order is only for direct questions; ✗ <b>she has been living</b> — present perfect is the direct-speech tense, not backshifted after past <i>asked</i>; ✗ <b>has she been living</b> — both inverted and unshifted."},{"id":"gv-ch-35-15","level":"ch","focus":"word-choice","q":"The judge ruled that the two prison terms would run ______ rather than one after the other.","options":["contemporarily","coincidentally","concurrently","instantaneously"],"correct":2,"answer":"concurrently","vi":"Thẩm phán phán quyết rằng hai án tù sẽ được thi hành đồng thời chứ không phải nối tiếp nhau.","explanation":"Word choice: <b>concurrently</b> = at the same time, the legal term for sentences served together; the clue is the contrast with <b>rather than one after the other</b>. ✗ <b>contemporarily</b> — belonging to the same period or the present era, not used for running sentences; ✗ <b>coincidentally</b> — by chance, at the same time by accident; ✗ <b>instantaneously</b> — immediately, in an instant, says nothing about overlap."},{"id":"gv-ch-35-16","level":"ch","focus":"idiom","q":"Once the most feared prosecutor in the city, she seems to have ______ — her last three cases collapsed within a week.","options":["lost her head","lost her voice","lost her footing","lost her touch"],"correct":3,"answer":"lost her touch","vi":"Từng là công tố viên đáng sợ nhất thành phố, giờ bà dường như đã mất đi sự sắc bén — ba vụ gần nhất của bà đều đổ vỡ trong vòng một tuần.","explanation":"Idiom: <b>lose your touch</b> = no longer have the skill you once had; the clue is <b>once the most feared … her last three cases collapsed</b>. ✗ <b>lost her head</b> — panicked and stopped thinking clearly; ✗ <b>lost her voice</b> — literal, could not speak (a sore throat); ✗ <b>lost her footing</b> — slipped and fell, or briefly lost her balance or position — not a lasting decline in skill."},{"id":"gv-ch-35-17","level":"ch","focus":"pronoun","q":"Residents of the tower block rarely speak to ______, even after years on the same floor.","options":["each other's","one another","themselves","the other"],"correct":1,"answer":"one another","vi":"Cư dân tòa chung cư hiếm khi trò chuyện với nhau, dù đã sống cùng tầng nhiều năm.","explanation":"Reciprocal pronoun: <b>one another</b> (= each other) shows that the residents act on each other; the clue is the plural subject <b>residents</b> doing something mutual. ✗ <b>each other's</b> — possessive form, needs a noun after it (<i>each other's names</i>); ✗ <b>themselves</b> — reflexive, would mean each resident talks to himself or herself; ✗ <b>the other</b> — singular, refers to one specific second person out of two."},{"id":"gv-ch-35-18","level":"ch","focus":"phrasal-verb","q":"The jury foreman refused to ______ the majority verdict until every doubt had been discussed.","options":["go in for","go down with","go along with","go off with"],"correct":2,"answer":"go along with","vi":"Chủ tịch bồi thẩm đoàn từ chối tán thành phán quyết của đa số cho đến khi mọi nghi vấn đã được thảo luận.","explanation":"Phrasal verb: <b>go along with</b> = accept or agree to a decision; the clue is <b>refused … until every doubt had been discussed</b> — he would not accept the verdict yet. ✗ <b>go in for</b> — enjoy or take part in (<i>go in for competitions</i>); ✗ <b>go down with</b> — fall ill with (<i>go down with flu</i>); ✗ <b>go off with</b> — take something away or run off with someone."},{"id":"gv-ch-35-19","level":"ch","focus":"linking","q":"The clinic now opens at six in the morning ______ shift workers can be seen before they start work.","options":["in order to","so as to","in case","so that"],"correct":3,"answer":"so that","vi":"Phòng khám nay mở cửa từ sáu giờ sáng để công nhân làm ca có thể được khám trước khi vào làm.","explanation":"Purpose clause: <b>so that</b> introduces a full clause with its own subject and verb — here <b>shift workers can be seen</b>. ✗ <b>in order to</b> — must be followed by a bare infinitive (<i>in order to see</i>), not subject + verb; ✗ <b>so as to</b> — same, infinitive only; ✗ <b>in case</b> — expresses a precaution against something that might happen, not the aim of opening early."},{"id":"gv-ch-35-20","level":"ch","focus":"collocation","q":"Small farmers along the delta will ______ the brunt of the new export tariffs, according to the ministry's own forecast.","options":["bear","carry","hold","stand"],"correct":0,"answer":"bear","vi":"Theo chính dự báo của bộ, các nông hộ nhỏ dọc vùng châu thổ sẽ phải gánh chịu nặng nề nhất từ mức thuế xuất khẩu mới.","explanation":"Collocation: <b>bear the brunt of</b> = suffer the worst part of something; the clue is the fixed noun <b>the brunt</b>, which takes only <i>bear</i>. ✗ <b>carry</b> — <i>carry the burden</i> / <i>the can</i>, but not <i>the brunt</i>; ✗ <b>hold</b> — <i>hold a grudge</i> / <i>the line</i>, no pairing with <i>brunt</i>; ✗ <b>stand</b> — <i>stand the strain</i> / <i>the pressure</i>, again not <i>brunt</i>."},{"id":"gv-ch-35-21","level":"ch","focus":"gerund-infinitive","q":"The witness admitted ______ the accused leave the warehouse, but denied having spoken to him.","options":["to see","see","to have seen","having seen"],"correct":3,"answer":"having seen","vi":"Nhân chứng thừa nhận đã thấy bị cáo rời khỏi nhà kho, nhưng phủ nhận việc đã nói chuyện với anh ta.","explanation":"Verb pattern: <b>admit</b> takes a gerund, and the perfect gerund <b>having seen</b> shows the seeing happened before the admission; the parallel clue is <b>denied having spoken</b>. ✗ <b>to see</b> — <i>admit</i> is never followed by a to-infinitive; ✗ <b>to have seen</b> — perfect infinitive, still an infinitive, so wrong after <i>admit</i>; ✗ <b>see</b> — a bare infinitive follows only modals or verbs like <i>make/let</i>."},{"id":"gv-ch-35-22","level":"ch","focus":"double-blank","q":"The residents' committee only ______ round to ______ the leaking roof after part of the ceiling had collapsed.","options":["set / repairing","got / repair","got / repairing","put / repair"],"correct":2,"answer":"got / repairing","vi":"Ban đại diện cư dân chỉ chịu bắt tay vào sửa mái dột sau khi một phần trần nhà đã sập.","explanation":"Phrasal verb: <b>get round to + -ing</b> = finally find time for something you have put off; the clue is <b>only … after part of the ceiling had collapsed</b>. ✗ <b>set / repairing</b> — <i>set round to</i> does not exist (<i>set about + -ing</i> would); ✗ <b>got / repair</b> — the <i>to</i> in <i>get round to</i> is a preposition, so a gerund must follow, not a bare verb; ✗ <b>put / repair</b> — <i>put round to</i> is not a phrasal verb."},{"id":"gv-ch-35-23","level":"ch","focus":"idiom","q":"Developers complain that the planning department keeps ______, adding fresh conditions every time a scheme is resubmitted.","options":["moving heaven and earth","moving the goalposts","moving with the times","moving mountains"],"correct":1,"answer":"moving the goalposts","vi":"Các nhà phát triển phàn nàn rằng sở quy hoạch cứ liên tục thay đổi luật chơi, thêm điều kiện mới mỗi lần hồ sơ được nộp lại.","explanation":"Idiom: <b>move the goalposts</b> = unfairly change the rules while something is already under way; the clue is <b>adding fresh conditions every time a scheme is resubmitted</b>. ✗ <b>moving heaven and earth</b> — making every possible effort to achieve something; ✗ <b>moving with the times</b> — modernising, keeping up with change; ✗ <b>moving mountains</b> — achieving something that seemed impossible."},{"id":"gv-ch-35-24","level":"ch","focus":"word-choice","q":"The inquiry published an ______ report on the landfill fire while the full investigation continues.","options":["instant","momentary","transitory","interim"],"correct":3,"answer":"interim","vi":"Ủy ban điều tra đã công bố báo cáo sơ bộ về vụ cháy bãi rác trong khi cuộc điều tra đầy đủ vẫn đang tiếp diễn.","explanation":"Word choice: an <b>interim</b> report is issued in the meantime, before the final one; the clue is <b>while the full investigation continues</b>. ✗ <b>instant</b> — happening immediately (<i>instant coffee</i>, <i>an instant reply</i>), does not describe a report; ✗ <b>momentary</b> — lasting only a moment (<i>a momentary pause</i>); ✗ <b>transitory</b> — passing, not lasting (<i>transitory fame</i>), about duration, not a stage in a process."},{"id":"gv-ch-35-25","level":"ch","focus":"question-tag","q":"Hardly anyone on the estate bothers to sort their recycling, ______?","options":["do they","don't they","does he","doesn't it"],"correct":0,"answer":"do they","vi":"Hầu như chẳng ai trong khu dân cư chịu phân loại rác tái chế, phải không?","explanation":"Question tag: <b>hardly</b> makes the statement negative, so the tag is positive; and <b>anyone</b> is referred back to with plural <i>they</i>: <b>do they</b>. ✗ <b>don't they</b> — negative tag on an already negative statement; ✗ <b>does he</b> — <i>anyone</i> takes <i>they</i>, not <i>he</i>; ✗ <b>doesn't it</b> — wrong pronoun and wrong polarity."},{"id":"gv-ch-36-1","level":"ch","focus":"inversion","q":"______ the public outcry over the data leak that the company's chief executive resigned within a week.","options":["So was","Such was","Such a","So great"],"correct":1,"answer":"Such was","vi":"Làn sóng phẫn nộ của công chúng về vụ rò rỉ dữ liệu lớn đến mức giám đốc điều hành của công ty đã từ chức trong vòng một tuần.","explanation":"Fronting <b>Such + be + noun phrase … that</b> inverts subject and verb, and the blank is followed by the noun phrase <b>the public outcry</b>: <b>Such was the public outcry that</b>. ✗ <b>So was</b> — <b>so</b> must be followed by an adjective (<b>So great was the outcry</b>), not directly by a noun; ✗ <b>Such a</b> — clashes with <b>the</b> and leaves the clause with no verb; ✗ <b>So great</b> — no verb before <b>the public outcry</b>."},{"id":"gv-ch-36-2","level":"ch","focus":"word-choice","q":"Without access to the raw figures, critics can only ______ that the charity inflated its impact numbers.","options":["ascertain","verify","surmise","discern"],"correct":2,"answer":"surmise","vi":"Không được xem số liệu gốc, giới phê bình chỉ có thể phỏng đoán rằng tổ chức từ thiện đã thổi phồng các con số về tác động.","explanation":"<b>Surmise</b> means to guess or conclude without firm evidence, which is all critics can do <b>without access to the raw figures</b>. ✗ <b>ascertain</b> — find out for certain, impossible without the data; ✗ <b>verify</b> — confirm something is true, again needing the figures; ✗ <b>discern</b> — notice or make out clearly, which implies seeing the evidence."},{"id":"gv-ch-36-3","level":"ch","focus":"idiom","q":"The claim that free tuition would bankrupt the state simply does not ______ once you look at the figures.","options":["hold water","hold the fort","hold sway","hold the line"],"correct":0,"answer":"hold water","vi":"Luận điểm rằng miễn học phí sẽ làm nhà nước phá sản đơn giản là không đứng vững khi ta nhìn vào các con số.","explanation":"A claim that <b>does not hold water</b> is unsound and collapses under examination — the clue is <b>once you look at the figures</b>. ✗ <b>hold the fort</b> — take charge while someone is away; ✗ <b>hold sway</b> — have power or influence over people; ✗ <b>hold the line</b> — refuse to change a position or price."},{"id":"gv-ch-36-4","level":"ch","focus":"collocation","q":"The survey paints a ______ picture of morale in state secondary schools, with two in five teachers planning to leave.","options":["dim","faint","pale","bleak"],"correct":3,"answer":"bleak","vi":"Cuộc khảo sát vẽ nên một bức tranh ảm đạm về tinh thần trong các trường trung học công lập, với hai phần năm giáo viên dự định bỏ nghề.","explanation":"<b>Paint a bleak/gloomy/grim picture</b> is the collocation for a pessimistic account, and <b>two in five teachers planning to leave</b> is bad news. ✗ <b>dim</b> — light that is not bright, or a poor memory; ✗ <b>faint</b> — barely visible or audible; ✗ <b>pale</b> — light in colour, as in a pale face — none describes a hopeless situation."},{"id":"gv-ch-36-5","level":"ch","focus":"subjunctive","q":"The lead author would rather her colleagues ______ the findings to the press until the peer review is complete.","options":["didn't release","don't release","wouldn't release","not to release"],"correct":0,"answer":"didn't release","vi":"Tác giả chính muốn các đồng nghiệp đừng công bố kết quả cho báo chí cho đến khi quá trình bình duyệt hoàn tất.","explanation":"<b>Would rather + another subject + past subjunctive</b> expresses a wish about the present or future, and here the subject changes to <b>her colleagues</b>: <b>would rather her colleagues didn't release</b>. ✗ <b>don't release</b> — present tense, not the required past form; ✗ <b>wouldn't release</b> — <b>would</b> cannot follow <b>would rather</b>; ✗ <b>not to release</b> — an infinitive follows <b>would rather</b> only with no second subject (<b>would rather not release</b>)."},{"id":"gv-ch-36-6","level":"ch","focus":"phrasal-verb","q":"Ministers met union leaders late into the night in an attempt to ______ a nationwide teachers' strike.","options":["head for","head off","head up","head back"],"correct":1,"answer":"head off","vi":"Các bộ trưởng đã họp với lãnh đạo công đoàn đến khuya nhằm ngăn chặn một cuộc đình công giáo viên trên toàn quốc.","explanation":"<b>Head off</b> means to prevent something before it happens, which is why ministers <b>met union leaders late into the night</b> about a strike. ✗ <b>head for</b> — move towards a place; ✗ <b>head up</b> — lead or be in charge of a team; ✗ <b>head back</b> — return to where you came from."},{"id":"gv-ch-36-7","level":"ch","focus":"word-choice","q":"The online scholarship scheme ______ that every applicant has reliable internet access, which is far from true in rural provinces.","options":["predicts","perceives","proposes","presupposes"],"correct":3,"answer":"presupposes","vi":"Chương trình học bổng trực tuyến mặc nhiên coi rằng mọi ứng viên đều có kết nối internet ổn định, điều hoàn toàn không đúng ở các tỉnh nông thôn.","explanation":"To <b>presuppose</b> is to take something for granted as a starting condition — the scheme silently assumes internet access, <b>which is far from true</b>. ✗ <b>predicts</b> — says something will happen in future; ✗ <b>perceives</b> — notices or becomes aware, which a scheme cannot do; ✗ <b>proposes</b> — suggests a plan, but the scheme is not suggesting access, it assumes it."},{"id":"gv-ch-36-8","level":"ch","focus":"double-blank","q":"Rather than ______ the buck to the previous administration, the new minister ______ full responsibility for the failed reform.","options":["push / took","throw / accepted","pass / accepted","pass / made"],"correct":2,"answer":"pass / accepted","vi":"Thay vì đổ trách nhiệm cho chính quyền tiền nhiệm, tân bộ trưởng đã nhận hoàn toàn trách nhiệm về cuộc cải cách thất bại.","explanation":"The idiom is <b>pass the buck</b> (shift blame to someone else), and one <b>accepts</b> or <b>takes</b> responsibility; <b>Rather than … the new minister</b> contrasts blaming with owning up. ✗ <b>push / took</b> — <b>took</b> works, but the idiom is never <b>push the buck</b>; ✗ <b>throw / accepted</b> — <b>throw the buck</b> is not an idiom; ✗ <b>pass / made</b> — you do not <b>make</b> responsibility."},{"id":"gv-ch-36-9","level":"ch","focus":"linking","q":"Field researchers now carry satellite phones ______ the mobile network fails in the more remote provinces.","options":["in case","unless","so that","as long as"],"correct":0,"answer":"in case","vi":"Các nhà nghiên cứu thực địa hiện mang theo điện thoại vệ tinh phòng khi mạng di động mất sóng ở những tỉnh xa xôi hơn.","explanation":"<b>In case + present simple</b> names a precaution against something that may happen: they carry phones <b>in case the network fails</b>. ✗ <b>unless</b> — 'if it does not fail', which makes no sense as a reason to carry a phone; ✗ <b>so that</b> — states a purpose, and a network failure is not the aim; ✗ <b>as long as</b> — 'provided that', a condition, not a possible risk."},{"id":"gv-ch-36-10","level":"ch","focus":"idiom","q":"The foundation deliberately works in villages that are ______, where the larger aid agencies rarely venture.","options":["off the record","off the beaten track","off the hook","off the cuff"],"correct":1,"answer":"off the beaten track","vi":"Quỹ này cố tình hoạt động ở những ngôi làng hẻo lánh ít người lui tới, nơi các tổ chức viện trợ lớn hiếm khi đặt chân đến.","explanation":"<b>Off the beaten track</b> describes a remote place few people visit — <b>where the larger aid agencies rarely venture</b>. ✗ <b>off the record</b> — said unofficially, not for publication; ✗ <b>off the hook</b> — freed from blame or a duty; ✗ <b>off the cuff</b> — said without preparation."},{"id":"gv-ch-36-11","level":"ch","focus":"modal","q":"The auditors ______ the discrepancy months earlier, yet somehow it went unnoticed until a whistle-blower came forward.","options":["must have spotted","needn't have spotted","could have spotted","can't have spotted"],"correct":2,"answer":"could have spotted","vi":"Các kiểm toán viên lẽ ra đã có thể phát hiện sai lệch từ nhiều tháng trước, vậy mà không hiểu sao nó vẫn không bị phát hiện cho đến khi một người tố giác lên tiếng.","explanation":"<b>Could have + past participle</b> describes a past possibility that did not happen, and <b>yet it went unnoticed</b> confirms nobody spotted it. ✗ <b>must have spotted</b> — a deduction that they did spot it, contradicted by the second clause; ✗ <b>can't have spotted</b> — a deduction that spotting was impossible, yet the sentence says they had the chance; ✗ <b>needn't have spotted</b> — means they spotted it unnecessarily, which never happened."},{"id":"gv-ch-36-12","level":"ch","focus":"word-choice","q":"From the guarded tone of the reference, we can ______ that her former manager was less than impressed with her work.","options":["infer","imply","insinuate","allude"],"correct":0,"answer":"infer","vi":"Từ giọng điệu dè dặt của thư giới thiệu, ta có thể suy ra rằng người quản lý cũ không mấy ấn tượng với công việc của cô ấy.","explanation":"The reader draws a conclusion, so the verb is <b>infer</b>; <b>From the guarded tone</b> shows we are working out a hidden meaning, not sending one. ✗ <b>imply</b> — the writer suggests indirectly; it is the manager, not <b>we</b>, who implies; ✗ <b>insinuate</b> — hint something unpleasant, again the writer's action; ✗ <b>allude</b> — refer indirectly, and it needs <b>to</b>, not a that-clause."},{"id":"gv-ch-36-13","level":"ch","focus":"collocation","q":"The embezzlement scandal has done ______ damage to the charity's reputation among its long-standing donors.","options":["unspoken","unsaid","unmentioned","untold"],"correct":3,"answer":"untold","vi":"Vụ bê bối biển thủ đã gây thiệt hại khôn lường cho uy tín của tổ chức từ thiện trong mắt các nhà tài trợ lâu năm.","explanation":"<b>Untold damage</b> means damage too great to be counted or described — a scandal among <b>long-standing donors</b> is that serious. ✗ <b>unspoken</b> — felt but not said aloud, as in an unspoken rule; ✗ <b>unsaid</b> — left without being said; ✗ <b>unmentioned</b> — not referred to — all three describe words, not the scale of damage."},{"id":"gv-ch-36-14","level":"ch","focus":"participle","q":"______, the three studies suggest that screen time has a far smaller effect on children's sleep than parents fear.","options":["Taking together","Taken together","Having taken together","To take together"],"correct":1,"answer":"Taken together","vi":"Gộp lại, ba nghiên cứu cho thấy thời gian dùng màn hình ảnh hưởng đến giấc ngủ của trẻ ít hơn nhiều so với những gì cha mẹ lo sợ.","explanation":"The studies are considered together by the reader, so the passive past participle <b>Taken together</b> is needed, and its subject is <b>the three studies</b>. ✗ <b>Taking together</b> — active participle makes the studies do the taking; ✗ <b>Having taken together</b> — active perfect participle, same wrong agent; ✗ <b>To take together</b> — an infinitive of purpose, but the studies have no purpose here."},{"id":"gv-ch-36-15","level":"ch","focus":"idiom","q":"With the education budget frozen, plans for a new vocational college have been put ______ until at least next year.","options":["on the front line","on the back foot","on the back burner","on the cards"],"correct":2,"answer":"on the back burner","vi":"Với ngân sách giáo dục bị đóng băng, kế hoạch xây trường cao đẳng nghề mới đã bị gác lại ít nhất đến năm sau.","explanation":"To <b>put something on the back burner</b> is to postpone it — the clue is <b>budget frozen</b> and <b>until at least next year</b>. ✗ <b>on the front line</b> — where the fighting or hardest work is; ✗ <b>on the back foot</b> — at a disadvantage, forced to defend; ✗ <b>on the cards</b> — likely to happen, the opposite of postponed."},{"id":"gv-ch-36-16","level":"ch","focus":"phrasal-verb","q":"Whether the merger goes ahead will ______ the outcome of Friday's shareholder vote.","options":["hold on","hand on","home in on","hinge on"],"correct":3,"answer":"hinge on","vi":"Việc sáp nhập có được tiến hành hay không sẽ phụ thuộc vào kết quả cuộc bỏ phiếu của cổ đông vào thứ Sáu.","explanation":"<b>Hinge on</b> means to depend entirely on, and <b>whether the merger goes ahead</b> is decided by the vote. ✗ <b>hold on</b> — wait, or grip something tightly; ✗ <b>hand on</b> — pass something to the next person; ✗ <b>home in on</b> — move straight towards a target or focus on it."},{"id":"gv-ch-36-17","level":"ch","focus":"subjunctive","q":"It is high time the government ______ teachers' pay to that of comparable graduate professions.","options":["linked","links","link","has linked"],"correct":0,"answer":"linked","vi":"Đã đến lúc chính phủ phải gắn lương giáo viên với mức lương của các ngành nghề tốt nghiệp đại học tương đương.","explanation":"<b>It is high time + subject + past subjunctive</b> says something should already have been done: <b>high time the government linked</b>. ✗ <b>links</b> — present simple, but <b>high time</b> needs the past form; ✗ <b>link</b> — a base-form subjunctive follows <b>suggest/demand</b>, not <b>high time</b>; ✗ <b>has linked</b> — present perfect would mean it is already done, the opposite of the complaint."},{"id":"gv-ch-36-18","level":"ch","focus":"word-choice","q":"The trustees ______ the proposal too risky to fund, despite the founder's enthusiasm for it.","options":["regarded","viewed","deemed","looked"],"correct":2,"answer":"deemed","vi":"Các ủy viên quản trị cho rằng đề xuất này quá rủi ro để tài trợ, bất chấp sự nhiệt tình của người sáng lập.","explanation":"<b>Deem + object + adjective</b> takes no preposition, so it fits <b>______ the proposal too risky</b> directly. ✗ <b>regarded</b> — needs <b>as</b> (regarded the proposal as too risky); ✗ <b>viewed</b> — also needs <b>as</b>; ✗ <b>looked</b> — needs <b>on/upon … as</b> to mean 'consider', and <b>looked the proposal</b> is not English."},{"id":"gv-ch-36-19","level":"ch","focus":"gerund-infinitive","q":"Having lost its final appeal, the trust had no choice but ______ the disputed funds to the donor's estate.","options":["returning","to return","return","to returning"],"correct":1,"answer":"to return","vi":"Sau khi thua kháng cáo cuối cùng, quỹ không còn lựa chọn nào khác ngoài việc trả lại số tiền tranh chấp cho di sản của nhà tài trợ.","explanation":"<b>Have no choice/alternative but + to-infinitive</b> is the fixed pattern: <b>no choice but to return</b>. ✗ <b>return</b> — the bare infinitive follows <b>cannot but</b> or <b>do nothing but</b>, not <b>have no choice but</b>; ✗ <b>returning</b> — a gerund does not follow this <b>but</b>; ✗ <b>to returning</b> — <b>to</b> here is part of the infinitive, so an -ing form cannot follow it."},{"id":"gv-ch-36-20","level":"ch","focus":"idiom","q":"A one-off retention bonus will merely ______; it will do nothing about the culture that is driving nurses out of the profession.","options":["read between the lines","clutch at straws","slip through the cracks","paper over the cracks"],"correct":3,"answer":"paper over the cracks","vi":"Một khoản thưởng giữ chân một lần chỉ che đậy tạm thời vấn đề; nó chẳng làm gì được với văn hóa đang đẩy các y tá rời bỏ nghề.","explanation":"To <b>paper over the cracks</b> is to hide a problem rather than solve it, and <b>it will do nothing about the culture</b> spells that out. ✗ <b>read between the lines</b> — find a hidden meaning in what is said; ✗ <b>clutch at straws</b> — try anything out of desperation; ✗ <b>slip through the cracks</b> — be overlooked by a system, which a bonus cannot do."},{"id":"gv-ch-36-21","level":"ch","focus":"article-quantifier","q":"______ progress has been made on narrowing the attainment gap, but far less than the ministry's press release suggests.","options":["Some","A few","Many","Several"],"correct":0,"answer":"Some","vi":"Đã có một số tiến bộ trong việc thu hẹp khoảng cách thành tích, nhưng ít hơn nhiều so với những gì thông cáo báo chí của bộ gợi ý.","explanation":"<b>Progress</b> is an uncountable noun (no plural, no <b>a</b>), so it takes <b>some</b>. ✗ <b>A few</b> — only with plural countable nouns (a few schools); ✗ <b>Many</b> — plural countable nouns only; with uncountables it would be <b>much</b>; ✗ <b>Several</b> — plural countable nouns only."},{"id":"gv-ch-36-22","level":"ch","focus":"double-blank","q":"While ______ through a decade of old survey data, the analyst ______ a pattern that nobody in the department had noticed.","options":["shifting / hit on","sorting / hit at","sifting / hit on","sifting / hit out"],"correct":2,"answer":"sifting / hit on","vi":"Trong lúc sàng lọc dữ liệu khảo sát cũ suốt một thập kỷ, nhà phân tích tình cờ phát hiện ra một quy luật mà chưa ai trong phòng để ý.","explanation":"<b>Sift through</b> is to examine a mass of material carefully, and <b>hit on</b> is to discover by chance — <b>a pattern nobody had noticed</b>. ✗ <b>shifting / hit on</b> — <b>shift</b> means to move, a spelling near-miss for <b>sift</b>; ✗ <b>sorting / hit at</b> — <b>sorting through</b> is possible, but <b>hit at</b> means to strike or attack indirectly; ✗ <b>sifting / hit out</b> — <b>hit out</b> is to attack in words."},{"id":"gv-ch-36-23","level":"ch","focus":"inversion","q":"Only after the audit was made public ______ how much of their money had gone on administration.","options":["donors realised","did donors realise","donors did realise","had donors realised"],"correct":1,"answer":"did donors realise","vi":"Chỉ sau khi báo cáo kiểm toán được công bố, các nhà tài trợ mới nhận ra bao nhiêu tiền của họ đã đi vào chi phí hành chính.","explanation":"A fronted <b>Only after + clause</b> forces subject–auxiliary inversion in the main clause: <b>did donors realise</b>. ✗ <b>donors realised</b> — no inversion after the fronted <b>Only after</b>; ✗ <b>donors did realise</b> — subject before auxiliary, so still not inverted; ✗ <b>had donors realised</b> — inverted, but the past perfect belongs to the earlier event (the audit), not the later realising."},{"id":"gv-ch-36-24","level":"ch","focus":"word-choice","q":"Few head teachers could ______ of a timetable with no standardised testing at all.","options":["perceive","contemplate","consider","conceive"],"correct":3,"answer":"conceive","vi":"Ít hiệu trưởng nào có thể hình dung nổi một thời khóa biểu hoàn toàn không có kỳ thi chuẩn hóa.","explanation":"<b>Conceive of</b> means to imagine something as possible, and it is the only option that takes <b>of</b> before <b>a timetable</b>. ✗ <b>perceive</b> — notice or see, transitive with no <b>of</b>; ✗ <b>contemplate</b> — think about seriously, takes a direct object; ✗ <b>consider</b> — think carefully about, also takes a direct object without <b>of</b>."},{"id":"gv-ch-36-25","level":"ch","focus":"collocation","q":"The central bank has raised interest rates twice this quarter in a bid to ______ inflation without tipping the economy into recession.","options":["deter","quench","curb","shrink"],"correct":2,"answer":"curb","vi":"Ngân hàng trung ương đã hai lần tăng lãi suất trong quý này nhằm kiềm chế lạm phát mà không đẩy nền kinh tế vào suy thoái.","explanation":"<b>Curb inflation/spending/emissions</b> is the collocation for keeping something under control, which is why the bank <b>raised interest rates</b>. ✗ <b>deter</b> — discourage a person or a crime, not a rate; ✗ <b>quench</b> — goes with thirst or fire; ✗ <b>shrink</b> — make a deficit or workforce smaller, not the usual verb for inflation."}];

if (typeof module !== 'undefined' && module.exports) { module.exports = { GRAMMAR_VOCAB_ITEMS }; }
